-- --------------------------------------------------------------------
-- [17/96] Migration: 20260929000006_v2_system_targets_rls_hardening.sql
-- --------------------------------------------------------------------
-- ============================================================================
-- Migration: 20260929000006_v2_system_targets_rls_hardening.sql
-- Description:
-- Harden target_versions and curriculum_nodes RLS policies so client writes
-- strictly require t.created_by = auth.uid().
-- Official/system targets with created_by IS NULL can only be modified via service_role.
-- ============================================================================

-- 1. target_versions write policies
alter table public.target_versions enable row level security;
drop policy if exists "versions_insert" on public.target_versions;
drop policy if exists "versions_update" on public.target_versions;
drop policy if exists "versions_delete" on public.target_versions;

create policy "versions_insert" on public.target_versions
  for insert with check (
    exists (
      select 1 from public.learning_targets t
      where t.id = target_versions.target_id
        and t.created_by = auth.uid()
    )
  );

create policy "versions_update" on public.target_versions
  for update using (
    target_versions.status <> 'published'
    and exists (
      select 1 from public.learning_targets t
      where t.id = target_versions.target_id
        and t.created_by = auth.uid()
    )
  )
  with check (
    exists (
      select 1 from public.learning_targets t
      where t.id = target_versions.target_id
        and t.created_by = auth.uid()
    )
  );

create policy "versions_delete" on public.target_versions
  for delete using (
    target_versions.status <> 'published'
    and exists (
      select 1 from public.learning_targets t
      where t.id = target_versions.target_id
        and t.created_by = auth.uid()
    )
  );

-- 2. curriculum_nodes write policies
alter table public.curriculum_nodes enable row level security;
drop policy if exists "nodes_write" on public.curriculum_nodes;
create policy "nodes_write" on public.curriculum_nodes
  for all using (
    exists (
      select 1 from public.target_versions v
      join public.learning_targets t on t.id = v.target_id
      where v.id = curriculum_nodes.target_version_id
        and t.created_by = auth.uid()
        and v.status <> 'published'
    )
  )
  with check (
    exists (
      select 1 from public.target_versions v
      join public.learning_targets t on t.id = v.target_id
      where v.id = curriculum_nodes.target_version_id
        and t.created_by = auth.uid()
        and v.status <> 'published'
    )
  );

INSERT INTO supabase_migrations.schema_migrations (version, name) VALUES ('20260929000006', 'v2_system_targets_rls_hardening') ON CONFLICT (version) DO NOTHING;

-- --------------------------------------------------------------------
-- [18/96] Migration: 20261001000000_lesson_visibility.sql
-- --------------------------------------------------------------------
-- Existing lessons were readable to everyone. Preserve that state explicitly,
-- then make future user-created lessons private by default.
alter table public.lessons
  add column if not exists visibility text;

update public.lessons
set visibility = 'public'
where visibility is null;

alter table public.lessons
  alter column visibility set default 'private',
  alter column visibility set not null;

alter table public.lessons
  add constraint lessons_visibility_check
  check (visibility in ('private', 'unlisted', 'public'));

alter table public.lessons
  add constraint lessons_ownerless_public_check
  check (user_id is not null or visibility = 'public');

-- Supabase anonymous-auth guests use the authenticated database role and
-- receive a distinct auth.uid(); the pre-login anon role has no owner ID.
drop policy if exists lessons_read_all on public.lessons;
create policy lessons_read_visible on public.lessons
  for select to authenticated, anon
  using (visibility = 'public' or user_id = auth.uid());

-- Every content read follows its parent lesson, including direct REST reads.
do $$
declare
  child_table text;
begin
  foreach child_table in array array['terms', 'questions', 'concepts', 'lesson_texts']
  loop
    if to_regclass('public.' || child_table) is not null then
      execute format('drop policy if exists %I on public.%I',
        child_table || '_read_all', child_table);
      execute format($policy$
        create policy %I on public.%I
          for select to authenticated, anon
          using (exists (
            select 1 from public.lessons l
            where l.id = lesson_id
              and (l.visibility = 'public' or l.user_id = auth.uid())
          ))
      $policy$, child_table || '_read_visible', child_table);
    end if;
  end loop;
end $$;

drop policy if exists lesson_concepts_read on public.lesson_concepts;
create policy lesson_concepts_read on public.lesson_concepts
  for select to authenticated, anon
  using (exists (
    select 1 from public.lessons l
    where l.id = lesson_concepts.lesson_id
      and (l.visibility = 'public' or l.user_id = auth.uid())
  ));

-- Other mapping policies already look through questions/terms, which now
-- inherit lesson visibility. These restrictive policies close junction paths
-- that otherwise expose a private lesson ID from a public course or node.
create policy course_lessons_lesson_visible on public.course_lessons
  as restrictive for select to authenticated, anon
  using (exists (
    select 1 from public.lessons l where l.id = course_lessons.lesson_id
  ));

create policy node_lessons_lesson_visible on public.curriculum_node_lessons
  as restrictive for select to authenticated, anon
  using (exists (
    select 1 from public.lessons l where l.id = curriculum_node_lessons.lesson_id
  ));

INSERT INTO supabase_migrations.schema_migrations (version, name) VALUES ('20261001000000', 'lesson_visibility') ON CONFLICT (version) DO NOTHING;

-- --------------------------------------------------------------------
-- [19/96] Migration: 20261001000001_user_curriculum_resources.sql
-- --------------------------------------------------------------------
-- User-owned supplements to exact published curriculum nodes. This table
-- never changes curriculum_node_lessons or official requirement counts.
create table public.user_curriculum_resources (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid()
    references auth.users(id) on delete cascade,
  curriculum_node_id uuid not null
    references public.curriculum_nodes(id) on delete cascade,
  lesson_id uuid not null
    references public.lessons(id) on delete cascade,
  relationship text not null default 'personal_study'
    check (relationship = 'personal_study'),
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (user_id, curriculum_node_id, lesson_id, relationship)
);

create index user_curriculum_resources_owner_node_idx
  on public.user_curriculum_resources(user_id, curriculum_node_id, sort_order, created_at);

create trigger user_curriculum_resources_touch
  before update on public.user_curriculum_resources
  for each row execute function public.touch_updated_at();

alter table public.user_curriculum_resources enable row level security;
revoke all on public.user_curriculum_resources from anon;
grant select, insert, update, delete on public.user_curriculum_resources to authenticated;

create policy user_curriculum_resources_owner_read
  on public.user_curriculum_resources
  for select to authenticated
  using (user_id = auth.uid());

create policy user_curriculum_resources_owner_insert
  on public.user_curriculum_resources
  for insert to authenticated
  with check (
    user_id = auth.uid()
    and exists (
      select 1 from public.lessons l
      where l.id = lesson_id and l.user_id = auth.uid()
    )
    and exists (
      select 1
      from public.curriculum_nodes n
      join public.target_versions v on v.id = n.target_version_id
      join public.learning_targets t on t.id = v.target_id
      where n.id = curriculum_node_id
        and t.is_official
        and t.status = 'published'
        and t.is_public
        and v.status = 'published'
    )
  );

create policy user_curriculum_resources_owner_update
  on public.user_curriculum_resources
  for update to authenticated
  using (user_id = auth.uid())
  with check (
    user_id = auth.uid()
    and exists (
      select 1 from public.lessons l
      where l.id = lesson_id and l.user_id = auth.uid()
    )
    and exists (
      select 1
      from public.curriculum_nodes n
      join public.target_versions v on v.id = n.target_version_id
      join public.learning_targets t on t.id = v.target_id
      where n.id = curriculum_node_id
        and t.is_official
        and t.status = 'published'
        and t.is_public
        and v.status = 'published'
    )
  );

create policy user_curriculum_resources_owner_delete
  on public.user_curriculum_resources
  for delete to authenticated
  using (user_id = auth.uid());

INSERT INTO supabase_migrations.schema_migrations (version, name) VALUES ('20261001000001', 'user_curriculum_resources') ON CONFLICT (version) DO NOTHING;

