-- --------------------------------------------------------------------
-- [21/96] Migration: 20261003000000_content_provenance.sql
-- --------------------------------------------------------------------
-- ============================================================================
-- Migration: 20261003000000_content_provenance.sql
-- Description: Traceable Content Provenance Layer
--              Tracks authoritative source releases (e.g. CompTIA SY0-701 blueprint,
--              NCLEX-RN Test Plan, AAMC MCAT guide) and maps curriculum nodes,
--              concepts, lessons, and questions to their exact source citations.
-- ============================================================================

-- 1. Authoritative Source Releases
create table if not exists public.content_source_releases (
  id uuid primary key default gen_random_uuid(),
  publisher text not null,
  title text not null,
  version text not null,
  source_url text,
  retrieved_at timestamptz not null default now(),
  license text,
  sha256 text,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (publisher, title, version)
);

create index if not exists content_source_releases_pub_ver_idx
  on public.content_source_releases(publisher, title, version);

create trigger trg_content_source_releases_touch
  before update on public.content_source_releases
  for each row execute function public.touch_updated_at();

-- 2. Content Source Mappings (Traceability Junction)
create table if not exists public.content_source_mappings (
  id uuid primary key default gen_random_uuid(),
  source_release_id uuid not null
    references public.content_source_releases(id) on delete cascade,
  entity_type text not null
    check (entity_type in ('target_version', 'curriculum_node', 'lesson', 'knowledge_concept', 'question', 'flashcard')),
  entity_id uuid not null,
  relationship text not null default 'derived_from'
    check (relationship in ('official_blueprint', 'primary_text', 'derived_from', 'reference_citation', 'standards_benchmark')),
  citation_location text,
  notes text,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  unique (source_release_id, entity_type, entity_id, relationship)
);

create index if not exists content_source_mappings_entity_idx
  on public.content_source_mappings(entity_type, entity_id);

create index if not exists content_source_mappings_release_idx
  on public.content_source_mappings(source_release_id);

-- 3. Row-Level Security
alter table public.content_source_releases enable row level security;
alter table public.content_source_mappings enable row level security;

-- Read policies: Published provenance citations are transparent and readable to all learners & guests
drop policy if exists "content_source_releases_read" on public.content_source_releases;
create policy "content_source_releases_read" on public.content_source_releases
  for select to authenticated, anon
  using (true);

drop policy if exists "content_source_mappings_read" on public.content_source_mappings;
create policy "content_source_mappings_read" on public.content_source_mappings
  for select to authenticated, anon
  using (true);

-- Write policies: Provenance ingestion and administrative publication via service role
drop policy if exists "content_source_releases_service_write" on public.content_source_releases;
create policy "content_source_releases_service_write" on public.content_source_releases
  for all to authenticated
  using (auth.role() = 'service_role')
  with check (auth.role() = 'service_role');

drop policy if exists "content_source_mappings_service_write" on public.content_source_mappings;
create policy "content_source_mappings_service_write" on public.content_source_mappings
  for all to authenticated
  using (auth.role() = 'service_role')
  with check (auth.role() = 'service_role');

INSERT INTO supabase_migrations.schema_migrations (version, name) VALUES ('20261003000000', 'content_provenance') ON CONFLICT (version) DO NOTHING;

-- --------------------------------------------------------------------
-- [22/96] Migration: 20261004000000_content_primitives_v2.sql
-- --------------------------------------------------------------------
-- ============================================================================
-- Migration: 20261004000000_content_primitives_v2.sql
-- Description:
-- 1. Extensible Lesson Block Document Model (lesson_blocks).
-- 2. Extensible Assessment Architecture (assessment_items, assessment_stimuli,
--    assessment_item_concepts).
-- 3. Version Migration Mapping (target_version_concept_mappings).
-- 4. TargetVersion Staging Status ('review_ready').
-- 5. Canonical Concept Alias Indexing & Resolver Function.
-- 6. Content Source Mappings extension for new primitives.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. TargetVersion Staging Status ('review_ready')
-- ----------------------------------------------------------------------------
alter table public.target_versions
  drop constraint if exists target_versions_status_check;

alter table public.target_versions
  add constraint target_versions_status_check
  check (status in ('draft', 'review_ready', 'published', 'retired'));

-- Update versions update/delete policy to treat review_ready as editable by owner
drop policy if exists "versions_update" on public.target_versions;
create policy "versions_update" on public.target_versions
  for update using (
    target_versions.status not in ('published', 'retired')
    and exists (
      select 1 from public.learning_targets t
      where t.id = target_versions.target_id
        and t.created_by = auth.uid()
    )
  )
  with check (
    exists (
      select 1 from public.learning_targets t
      where t.id = target_versions.target_id
        and t.created_by = auth.uid()
    )
  );

drop policy if exists "versions_delete" on public.target_versions;
create policy "versions_delete" on public.target_versions
  for delete using (
    target_versions.status not in ('published', 'retired')
    and exists (
      select 1 from public.learning_targets t
      where t.id = target_versions.target_id
        and t.created_by = auth.uid()
    )
  );

-- Curriculum nodes write policy: allowed when version is draft or review_ready
drop policy if exists "nodes_write" on public.curriculum_nodes;
create policy "nodes_write" on public.curriculum_nodes
  for all using (
    exists (
      select 1 from public.target_versions v
      join public.learning_targets t on t.id = v.target_id
      where v.id = curriculum_nodes.target_version_id
        and t.created_by = auth.uid()
        and v.status not in ('published', 'retired')
    )
  )
  with check (
    exists (
      select 1 from public.target_versions v
      join public.learning_targets t on t.id = v.target_id
      where v.id = curriculum_nodes.target_version_id
        and t.created_by = auth.uid()
        and v.status not in ('published', 'retired')
    )
  );

-- ----------------------------------------------------------------------------
-- 2. Ordered Lesson Block Model (lesson_blocks)
-- ----------------------------------------------------------------------------
create table if not exists public.lesson_blocks (
  id uuid primary key default gen_random_uuid(),
  lesson_id uuid not null
    references public.lessons(id) on delete cascade,
  sort_order integer not null default 0,
  block_type text not null
    check (block_type in (
      'markdown',
      'callout',
      'code',
      'table',
      'image',
      'formula',
      'example',
      'practice_prompt'
    )),
  content jsonb not null default '{}'::jsonb,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists lesson_blocks_lesson_idx
  on public.lesson_blocks(lesson_id, sort_order);

drop trigger if exists trg_lesson_blocks_touch on public.lesson_blocks;
create trigger trg_lesson_blocks_touch
  before update on public.lesson_blocks
  for each row execute function public.touch_updated_at();

alter table public.lesson_blocks enable row level security;

drop policy if exists "lesson_blocks_read_visible" on public.lesson_blocks;
create policy "lesson_blocks_read_visible" on public.lesson_blocks
  for select to authenticated, anon
  using (exists (
    select 1 from public.lessons l
    where l.id = lesson_blocks.lesson_id
      and (l.visibility = 'public' or l.user_id = auth.uid())
  ));

drop policy if exists "lesson_blocks_write_owner" on public.lesson_blocks;
create policy "lesson_blocks_write_owner" on public.lesson_blocks
  for all to authenticated
  using (exists (
    select 1 from public.lessons l
    where l.id = lesson_blocks.lesson_id
      and l.user_id = auth.uid()
  ))
  with check (exists (
    select 1 from public.lessons l
    where l.id = lesson_blocks.lesson_id
      and l.user_id = auth.uid()
  ));

-- ----------------------------------------------------------------------------
-- 3. Assessment Stimuli (Shared Vignettes, Scenarios, Diagrams)
-- ----------------------------------------------------------------------------
create table if not exists public.assessment_stimuli (
  id uuid primary key default gen_random_uuid(),
  stimulus_type text not null
    check (stimulus_type in (
      'clinical_case',
      'architecture_diagram',
      'code_snippet',
      'data_table',
      'scenario',
      'passage'
    )),
  title text not null,
  body text,
  structured_data jsonb not null default '{}'::jsonb,
  asset_refs jsonb not null default '[]'::jsonb,
  metadata jsonb not null default '{}'::jsonb,
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

drop trigger if exists trg_assessment_stimuli_touch on public.assessment_stimuli;
create trigger trg_assessment_stimuli_touch
  before update on public.assessment_stimuli
  for each row execute function public.touch_updated_at();

alter table public.assessment_stimuli enable row level security;

drop policy if exists "assessment_stimuli_read" on public.assessment_stimuli;
create policy "assessment_stimuli_read" on public.assessment_stimuli
  for select to authenticated, anon
  using (true);

drop policy if exists "assessment_stimuli_write" on public.assessment_stimuli;
create policy "assessment_stimuli_write" on public.assessment_stimuli
  for all to authenticated
  using (created_by = auth.uid())
  with check (created_by = auth.uid());

-- ----------------------------------------------------------------------------
-- 4. Extensible Assessment Items (assessment_items)
-- ----------------------------------------------------------------------------
create table if not exists public.assessment_items (
  id uuid primary key default gen_random_uuid(),
  lesson_id uuid references public.lessons(id) on delete cascade,
  stimulus_id uuid references public.assessment_stimuli(id) on delete set null,
  interaction_type text not null
    check (interaction_type in (
      'single_choice',
      'multi_select',
      'ordered_response',
      'matching',
      'matrix_grid',
      'numeric_entry',
      'cloze',
      'code_output'
    )),
  prompt text not null,
  response_spec jsonb not null default '{}'::jsonb,
  scoring_spec jsonb not null default '{}'::jsonb,
  explanation text,
  difficulty text not null default 'intermediate'
    check (difficulty in ('beginner', 'intermediate', 'advanced')),
  cognitive_level text
    check (cognitive_level in ('recall', 'comprehension', 'application', 'analysis', 'evaluation')),
  metadata jsonb not null default '{}'::jsonb,
  user_id uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists assessment_items_lesson_idx
  on public.assessment_items(lesson_id);

create index if not exists assessment_items_stimulus_idx
  on public.assessment_items(stimulus_id);

drop trigger if exists trg_assessment_items_touch on public.assessment_items;
create trigger trg_assessment_items_touch
  before update on public.assessment_items
  for each row execute function public.touch_updated_at();

alter table public.assessment_items enable row level security;

drop policy if exists "assessment_items_read" on public.assessment_items;
create policy "assessment_items_read" on public.assessment_items
  for select to authenticated, anon
  using (
    lesson_id is null
    or exists (
      select 1 from public.lessons l
      where l.id = assessment_items.lesson_id
        and (l.visibility = 'public' or l.user_id = auth.uid())
    )
  );

drop policy if exists "assessment_items_write" on public.assessment_items;
create policy "assessment_items_write" on public.assessment_items
  for all to authenticated
  using (
    user_id = auth.uid()
    or (lesson_id is not null and exists (
      select 1 from public.lessons l
      where l.id = assessment_items.lesson_id
        and l.user_id = auth.uid()
    ))
  )
  with check (
    user_id = auth.uid()
    or (lesson_id is not null and exists (
      select 1 from public.lessons l
      where l.id = assessment_items.lesson_id
        and l.user_id = auth.uid()
    ))
  );

-- ----------------------------------------------------------------------------
-- 5. Assessment Item Concept Junction (assessment_item_concepts)
-- ----------------------------------------------------------------------------
create table if not exists public.assessment_item_concepts (
  assessment_item_id uuid not null
    references public.assessment_items(id) on delete cascade,
  concept_id uuid not null
    references public.knowledge_concepts(id) on delete cascade,
  role text not null default 'primary'
    check (role in ('primary', 'supporting')),
  weight numeric(6,5) not null default 1.0
    check (weight >= 0 and weight <= 1),
  primary key(assessment_item_id, concept_id)
);

create index if not exists assessment_item_concepts_concept_idx
  on public.assessment_item_concepts(concept_id);

alter table public.assessment_item_concepts enable row level security;

drop policy if exists "assessment_item_concepts_read" on public.assessment_item_concepts;
create policy "assessment_item_concepts_read" on public.assessment_item_concepts
  for select to authenticated, anon
  using (true);

drop policy if exists "assessment_item_concepts_write" on public.assessment_item_concepts;
create policy "assessment_item_concepts_write" on public.assessment_item_concepts
  for all to authenticated
  using (exists (
    select 1 from public.assessment_items a
    where a.id = assessment_item_concepts.assessment_item_id
      and (a.user_id = auth.uid() or exists (
        select 1 from public.lessons l where l.id = a.lesson_id and l.user_id = auth.uid()
      ))
  ))
  with check (exists (
    select 1 from public.assessment_items a
    where a.id = assessment_item_concepts.assessment_item_id
      and (a.user_id = auth.uid() or exists (
        select 1 from public.lessons l where l.id = a.lesson_id and l.user_id = auth.uid()
      ))
  ));

-- ----------------------------------------------------------------------------
-- 6. TargetVersion Forward Concept Mapping (target_version_concept_mappings)
-- ----------------------------------------------------------------------------
create table if not exists public.target_version_concept_mappings (
  id uuid primary key default gen_random_uuid(),
  from_target_version_id uuid not null
    references public.target_versions(id) on delete cascade,
  from_concept_id uuid not null
    references public.knowledge_concepts(id) on delete cascade,
  to_target_version_id uuid not null
    references public.target_versions(id) on delete cascade,
  to_concept_id uuid not null
    references public.knowledge_concepts(id) on delete cascade,
  mapping_type text not null
    check (mapping_type in ('unchanged', 'renamed', 'expanded', 'narrowed', 'replaced', 'removed')),
  transfer_weight numeric(5,4) not null default 1.0
    check (transfer_weight >= 0.0 and transfer_weight <= 1.0),
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  unique (from_target_version_id, from_concept_id, to_target_version_id, to_concept_id)
);

create index if not exists tv_concept_mappings_from_idx
  on public.target_version_concept_mappings(from_target_version_id, from_concept_id);

create index if not exists tv_concept_mappings_to_idx
  on public.target_version_concept_mappings(to_target_version_id, to_concept_id);

alter table public.target_version_concept_mappings enable row level security;

drop policy if exists "tv_concept_mappings_read" on public.target_version_concept_mappings;
create policy "tv_concept_mappings_read" on public.target_version_concept_mappings
  for select to authenticated, anon
  using (true);

-- ----------------------------------------------------------------------------
-- 7. Canonical Concept Resolution & Aliases Indexing
-- ----------------------------------------------------------------------------
create index if not exists knowledge_concepts_aliases_idx
  on public.knowledge_concepts using gin (aliases);

create index if not exists knowledge_concepts_name_lower_idx
  on public.knowledge_concepts(lower(name));

create or replace function public.resolve_canonical_concept(
  p_slug text,
  p_name text default null
)
returns table (
  id uuid,
  field_id uuid,
  slug text,
  name text,
  status text,
  match_type text
) language plpgsql security definer as $$
begin
  -- 1. Exact slug match
  return query
  select c.id, c.field_id, c.slug, c.name, c.status, 'exact_slug'::text
  from public.knowledge_concepts c
  where c.slug = p_slug
  limit 1;

  if found then return; end if;

  -- 2. Slug matches an alias
  return query
  select c.id, c.field_id, c.slug, c.name, c.status, 'slug_alias'::text
  from public.knowledge_concepts c
  where p_slug = any(c.aliases)
  limit 1;

  if found then return; end if;

  -- 3. Case-insensitive name match
  if p_name is not null and trim(p_name) <> '' then
    return query
    select c.id, c.field_id, c.slug, c.name, c.status, 'exact_name'::text
    from public.knowledge_concepts c
    where lower(c.name) = lower(trim(p_name))
    limit 1;

    if found then return; end if;

    -- 4. Name matches an alias
    return query
    select c.id, c.field_id, c.slug, c.name, c.status, 'name_alias'::text
    from public.knowledge_concepts c
    where lower(trim(p_name)) = any(select lower(a) from unnest(c.aliases) a)
    limit 1;

    if found then return; end if;
  end if;

  return;
end;
$$;

-- ----------------------------------------------------------------------------
-- 8. Content Source Mappings Entity Types Extension
-- ----------------------------------------------------------------------------
alter table public.content_source_mappings
  drop constraint if exists content_source_mappings_entity_type_check;

alter table public.content_source_mappings
  add constraint content_source_mappings_entity_type_check
  check (entity_type in (
    'target_version',
    'curriculum_node',
    'lesson',
    'knowledge_concept',
    'question',
    'flashcard',
    'lesson_block',
    'assessment_item',
    'assessment_stimulus'
  ));

INSERT INTO supabase_migrations.schema_migrations (version, name) VALUES ('20261004000000', 'content_primitives_v2') ON CONFLICT (version) DO NOTHING;

-- --------------------------------------------------------------------
-- [23/96] Migration: 20261005000000_content_hardening.sql
-- --------------------------------------------------------------------
-- ============================================================================
-- Migration: 20261005000000_content_hardening.sql
-- Description:
-- 1. Tighten Assessment RLS (assessment_stimuli, assessment_items, assessment_item_concepts).
-- 2. Enforce strict draft-only writes for curriculum nodes and junctions (review_ready is frozen).
-- 3. Make target_version_concept_mappings.to_concept_id nullable for 'removed' mappings.
-- 4. Add clean_draft_target_version RPC for idempotent, repeatable ingestion.
-- 5. Harden and disambiguate resolve_canonical_concept RPC.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. Assessment Stimuli Visibility Hardening
-- ----------------------------------------------------------------------------
-- User-created stimuli must not leak publicly unless attached to a public lesson.
-- System/official stimuli (created_by is null) remain readable to all.
drop policy if exists "assessment_stimuli_read" on public.assessment_stimuli;
create policy "assessment_stimuli_read" on public.assessment_stimuli
  for select to authenticated, anon
  using (
    created_by is null
    or created_by = auth.uid()
    or exists (
      select 1 from public.assessment_items i
      join public.lessons l on l.id = i.lesson_id
      where i.stimulus_id = assessment_stimuli.id
        and (l.visibility = 'public' or l.user_id = auth.uid())
    )
  );

-- ----------------------------------------------------------------------------
-- 2. Assessment Items Visibility Hardening
-- ----------------------------------------------------------------------------
-- Standalone items (lesson_id is null) must NOT be public if user_id belongs to a private user.
drop policy if exists "assessment_items_read" on public.assessment_items;
create policy "assessment_items_read" on public.assessment_items
  for select to authenticated, anon
  using (
    (lesson_id is null and (user_id is null or user_id = auth.uid()))
    or (lesson_id is not null and exists (
      select 1 from public.lessons l
      where l.id = assessment_items.lesson_id
        and (l.visibility = 'public' or l.user_id = auth.uid())
    ))
  );

drop policy if exists "assessment_items_write" on public.assessment_items;
create policy "assessment_items_write" on public.assessment_items
  for all to authenticated
  using (
    (user_id is not null and user_id = auth.uid())
    or (lesson_id is not null and exists (
      select 1 from public.lessons l
      where l.id = assessment_items.lesson_id
        and l.user_id = auth.uid()
    ))
  )
  with check (
    (user_id is not null and user_id = auth.uid())
    or (lesson_id is not null and exists (
      select 1 from public.lessons l
      where l.id = assessment_items.lesson_id
        and l.user_id = auth.uid()
    ))
  );

-- ----------------------------------------------------------------------------
-- 3. Assessment Item Concept Junction Visibility Hardening
-- ----------------------------------------------------------------------------
-- Concepts attached to private items must not leak. Inherit item visibility.
drop policy if exists "assessment_item_concepts_read" on public.assessment_item_concepts;
create policy "assessment_item_concepts_read" on public.assessment_item_concepts
  for select to authenticated, anon
  using (exists (
    select 1 from public.assessment_items a
    where a.id = assessment_item_concepts.assessment_item_id
      and (
        (a.lesson_id is null and (a.user_id is null or a.user_id = auth.uid()))
        or (a.lesson_id is not null and exists (
          select 1 from public.lessons l
          where l.id = a.lesson_id
            and (l.visibility = 'public' or l.user_id = auth.uid())
        ))
      )
  ));

-- ----------------------------------------------------------------------------
-- 4. Coherent Frozen review_ready Staging State
-- ----------------------------------------------------------------------------
-- review_ready represents a frozen content snapshot for QA review.
-- Curriculum node edits require transitioning back to 'draft'.
drop policy if exists "nodes_write" on public.curriculum_nodes;
create policy "nodes_write" on public.curriculum_nodes
  for all using (
    exists (
      select 1 from public.target_versions v
      join public.learning_targets t on t.id = v.target_id
      where v.id = curriculum_nodes.target_version_id
        and t.created_by = auth.uid()
        and v.status = 'draft'
    )
  )
  with check (
    exists (
      select 1 from public.target_versions v
      join public.learning_targets t on t.id = v.target_id
      where v.id = curriculum_nodes.target_version_id
        and t.created_by = auth.uid()
        and v.status = 'draft'
    )
  );

-- TargetVersion updates: editable when draft, OR transitioning between draft and review_ready.
drop policy if exists "versions_update" on public.target_versions;
create policy "versions_update" on public.target_versions
  for update using (
    target_versions.status not in ('published', 'retired')
    and exists (
      select 1 from public.learning_targets t
      where t.id = target_versions.target_id
        and t.created_by = auth.uid()
    )
  )
  with check (
    exists (
      select 1 from public.learning_targets t
      where t.id = target_versions.target_id
        and t.created_by = auth.uid()
    )
  );

-- ----------------------------------------------------------------------------
-- 5. Nullable to_concept_id for Removed Concept Mappings
-- ----------------------------------------------------------------------------
alter table public.target_version_concept_mappings
  alter column to_concept_id drop not null;

alter table public.target_version_concept_mappings
  drop constraint if exists tv_concept_mappings_removed_check;

alter table public.target_version_concept_mappings
  add constraint tv_concept_mappings_removed_check
  check ( (mapping_type = 'removed') or (to_concept_id is not null) );

-- Drop and recreate unique constraint with coalesce so removed mappings are unique per from_concept
alter table public.target_version_concept_mappings
  drop constraint if exists target_version_concept_mappings_from_target_version_id_fro_key;

drop index if exists tv_concept_mappings_unique_idx;
create unique index tv_concept_mappings_unique_idx
  on public.target_version_concept_mappings (
    from_target_version_id,
    from_concept_id,
    to_target_version_id,
    coalesce(to_concept_id, '00000000-0000-0000-0000-000000000000'::uuid)
  );

-- ----------------------------------------------------------------------------
-- 6. Idempotent Draft Cleanup RPC (clean_draft_target_version)
-- ----------------------------------------------------------------------------
create or replace function public.clean_draft_target_version(
  p_version_id uuid
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_status text;
begin
  select status into v_status
  from public.target_versions
  where id = p_version_id;

  if v_status is null then
    raise exception 'TargetVersion % not found', p_version_id;
  end if;

  if v_status <> 'draft' then
    raise exception 'Cannot clean TargetVersion with status "%". Only draft versions may be reset.', v_status;
  end if;

  -- 1. Delete official flashcards linked to concepts of this draft
  delete from public.flashcards
  where user_id is null
    and id in (
      select fc.flashcard_id
      from public.flashcard_concepts fc
      join public.curriculum_node_concepts cnc on cnc.concept_id = fc.concept_id
      join public.curriculum_nodes cn on cn.id = cnc.curriculum_node_id
      where cn.target_version_id = p_version_id
    );

  -- 2. Delete official lessons bound to curriculum nodes of this draft
  delete from public.lessons
  where user_id is null
    and id in (
      select l.id
      from public.lessons l
      join public.curriculum_node_lessons cnl on cnl.lesson_id = l.id
      join public.curriculum_nodes cn on cn.id = cnl.curriculum_node_id
      where cn.target_version_id = p_version_id
    );

  -- 3. Delete content source mappings pointing to curriculum nodes of this draft
  delete from public.content_source_mappings
  where entity_type = 'curriculum_node'
    and entity_id in (
      select cn.id
      from public.curriculum_nodes cn
      where cn.target_version_id = p_version_id
    );

  -- 4. Delete curriculum nodes (cascades to curriculum_node_concepts, cnl)
  delete from public.curriculum_nodes
  where target_version_id = p_version_id;

  -- 5. Delete concept mappings involving this draft version
  delete from public.target_version_concept_mappings
  where from_target_version_id = p_version_id
     or to_target_version_id = p_version_id;

  -- 6. Delete content source mappings pointing to this version
  delete from public.content_source_mappings
  where entity_type = 'target_version'
    and entity_id = p_version_id;
end;
$$;

revoke all on function public.clean_draft_target_version(uuid) from public;
grant execute on function public.clean_draft_target_version(uuid) to authenticated, service_role;

-- ----------------------------------------------------------------------------
-- 7. Ambiguity-Safe & Hardened Canonical Concept Resolver
-- ----------------------------------------------------------------------------
drop function if exists public.resolve_canonical_concept(text, text);

create or replace function public.resolve_canonical_concept(
  p_slug text,
  p_name text default null,
  p_field_id uuid default null
)
returns table (
  id uuid,
  field_id uuid,
  slug text,
  name text,
  status text,
  match_type text,
  is_ambiguous boolean
)
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_count integer;
  v_id uuid;
  v_field_id uuid;
  v_slug text;
  v_name text;
  v_status text;
begin
  -- 1. Exact slug match (canonical unique identity)
  select c.id, c.field_id, c.slug, c.name, c.status
  into v_id, v_field_id, v_slug, v_name, v_status
  from public.knowledge_concepts c
  where c.slug = p_slug
  limit 1;

  if found then
    return query select v_id, v_field_id, v_slug, v_name, v_status, 'exact_slug'::text, false;
    return;
  end if;

  -- 2. Exact unique alias match
  select count(*) into v_count
  from public.knowledge_concepts c
  where p_slug = any(c.aliases);

  if v_count = 1 then
    select c.id, c.field_id, c.slug, c.name, c.status
    into v_id, v_field_id, v_slug, v_name, v_status
    from public.knowledge_concepts c
    where p_slug = any(c.aliases)
    limit 1;

    return query select v_id, v_field_id, v_slug, v_name, v_status, 'slug_alias'::text, false;
    return;
  elsif v_count > 1 then
    -- Multiple candidates share this alias: check if field disambiguates
    if p_field_id is not null then
      select count(*) into v_count
      from public.knowledge_concepts c
      where p_slug = any(c.aliases)
        and (c.field_id = p_field_id or exists (
          select 1 from public.concept_fields cf
          where cf.concept_id = c.id and cf.field_id = p_field_id
        ));

      if v_count = 1 then
        select c.id, c.field_id, c.slug, c.name, c.status
        into v_id, v_field_id, v_slug, v_name, v_status
        from public.knowledge_concepts c
        where p_slug = any(c.aliases)
          and (c.field_id = p_field_id or exists (
            select 1 from public.concept_fields cf
            where cf.concept_id = c.id and cf.field_id = p_field_id
          ))
        limit 1;

        return query select v_id, v_field_id, v_slug, v_name, v_status, 'field_slug_alias'::text, false;
        return;
      end if;
    end if;

    -- Ambiguous alias across multiple concepts
    return query select null::uuid, null::uuid, null::text, null::text, null::text, 'ambiguous_alias'::text, true;
    return;
  end if;

  -- 3. Case-insensitive Name Match
  if p_name is not null and trim(p_name) <> '' then
    select count(*) into v_count
    from public.knowledge_concepts c
    where lower(c.name) = lower(trim(p_name));

    if v_count = 1 then
      select c.id, c.field_id, c.slug, c.name, c.status
      into v_id, v_field_id, v_slug, v_name, v_status
      from public.knowledge_concepts c
      where lower(c.name) = lower(trim(p_name))
      limit 1;

      return query select v_id, v_field_id, v_slug, v_name, v_status, 'exact_name'::text, false;
      return;
    elsif v_count > 1 then
      if p_field_id is not null then
        select count(*) into v_count
        from public.knowledge_concepts c
        where lower(c.name) = lower(trim(p_name))
          and (c.field_id = p_field_id or exists (
            select 1 from public.concept_fields cf
            where cf.concept_id = c.id and cf.field_id = p_field_id
          ));

        if v_count = 1 then
          select c.id, c.field_id, c.slug, c.name, c.status
          into v_id, v_field_id, v_slug, v_name, v_status
          from public.knowledge_concepts c
          where lower(c.name) = lower(trim(p_name))
            and (c.field_id = p_field_id or exists (
              select 1 from public.concept_fields cf
              where cf.concept_id = c.id and cf.field_id = p_field_id
            ))
          limit 1;

          return query select v_id, v_field_id, v_slug, v_name, v_status, 'field_exact_name'::text, false;
          return;
        end if;
      end if;

      return query select null::uuid, null::uuid, null::text, null::text, null::text, 'ambiguous_name'::text, true;
      return;
    end if;

    -- 4. Name matches an alias
    select count(*) into v_count
    from public.knowledge_concepts c
    where lower(trim(p_name)) = any(select lower(a) from unnest(c.aliases) a);

    if v_count = 1 then
      select c.id, c.field_id, c.slug, c.name, c.status
      into v_id, v_field_id, v_slug, v_name, v_status
      from public.knowledge_concepts c
      where lower(trim(p_name)) = any(select lower(a) from unnest(c.aliases) a)
      limit 1;

      return query select v_id, v_field_id, v_slug, v_name, v_status, 'name_alias'::text, false;
      return;
    elsif v_count > 1 then
      if p_field_id is not null then
        select count(*) into v_count
        from public.knowledge_concepts c
        where lower(trim(p_name)) = any(select lower(a) from unnest(c.aliases) a)
          and (c.field_id = p_field_id or exists (
            select 1 from public.concept_fields cf
            where cf.concept_id = c.id and cf.field_id = p_field_id
          ));

        if v_count = 1 then
          select c.id, c.field_id, c.slug, c.name, c.status
          into v_id, v_field_id, v_slug, v_name, v_status
          from public.knowledge_concepts c
          where lower(trim(p_name)) = any(select lower(a) from unnest(c.aliases) a)
            and (c.field_id = p_field_id or exists (
              select 1 from public.concept_fields cf
              where cf.concept_id = c.id and cf.field_id = p_field_id
            ))
          limit 1;

          return query select v_id, v_field_id, v_slug, v_name, v_status, 'field_name_alias'::text, false;
          return;
        end if;
      end if;

      return query select null::uuid, null::uuid, null::text, null::text, null::text, 'ambiguous_name_alias'::text, true;
      return;
    end if;
  end if;

  return;
end;
$$;

revoke all on function public.resolve_canonical_concept(text, text, uuid) from public;
grant execute on function public.resolve_canonical_concept(text, text, uuid) to authenticated, anon, service_role;

INSERT INTO supabase_migrations.schema_migrations (version, name) VALUES ('20261005000000', 'content_hardening') ON CONFLICT (version) DO NOTHING;

-- --------------------------------------------------------------------
-- [24/96] Migration: 20261006000000_import_ownership_and_staging.sql
-- --------------------------------------------------------------------
-- ============================================================================
-- Migration: 20261006000000_import_ownership_and_staging.sql
-- Description: Phase C.5 — Import Ownership, Atomicity & Staging Visibility
--
-- Key fixes:
--   1. content_import_artifacts tracking table for strict artifact ownership.
--   2. origin_target_version_id column on lessons, assessment_stimuli,
--      assessment_items, and flashcards for target-version-bound RLS.
--   3. curriculum_reviewers table and is_target_reviewer() helper for beta previews.
--   4. Hardened RLS policies: draft and review content are strictly hidden from
--      public queries until published; review_ready can be previewed by designated reviewers.
--   5. TargetVersion lifecycle trigger enforcing frozen review_ready and state transitions.
--   6. Hardened clean_draft_target_version() restricted to service_role/owner and
--      operating strictly via content_import_artifacts (no cross-target data loss).
--   7. Atomic ingest_curriculum_manifest() transaction RPC.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. Explicit Artifact Ownership Model
-- ----------------------------------------------------------------------------

-- Add origin_target_version_id to content entities
alter table public.lessons
  add column if not exists origin_target_version_id uuid
    references public.target_versions(id) on delete set null;

create index if not exists lessons_origin_tv_idx
  on public.lessons(origin_target_version_id);

alter table public.assessment_stimuli
  add column if not exists origin_target_version_id uuid
    references public.target_versions(id) on delete set null;

create index if not exists assessment_stimuli_origin_tv_idx
  on public.assessment_stimuli(origin_target_version_id);

alter table public.assessment_items
  add column if not exists origin_target_version_id uuid
    references public.target_versions(id) on delete set null;

create index if not exists assessment_items_origin_tv_idx
  on public.assessment_items(origin_target_version_id);

alter table public.flashcards
  add column if not exists origin_target_version_id uuid
    references public.target_versions(id) on delete set null;

create index if not exists flashcards_origin_tv_idx
  on public.flashcards(origin_target_version_id);

-- Import artifact tracking table
create table if not exists public.content_import_artifacts (
  id uuid primary key default gen_random_uuid(),
  target_version_id uuid not null references public.target_versions(id) on delete cascade,
  entity_type text not null check (entity_type in (
    'lesson', 'lesson_block', 'flashcard', 'assessment_item',
    'assessment_stimulus', 'term', 'question', 'curriculum_node', 'content_source_mapping'
  )),
  entity_id uuid not null,
  manifest_key text,
  created_at timestamptz not null default now(),
  unique (target_version_id, entity_type, entity_id)
);

create index if not exists content_import_artifacts_tv_idx
  on public.content_import_artifacts(target_version_id, entity_type);

alter table public.content_import_artifacts enable row level security;
drop policy if exists "artifacts_access" on public.content_import_artifacts;
create policy "artifacts_access" on public.content_import_artifacts
  for all using (
    auth.role() = 'service_role'
    or exists (
      select 1 from public.target_versions tv
      join public.learning_targets lt on lt.id = tv.target_id
      where tv.id = content_import_artifacts.target_version_id
        and lt.created_by = auth.uid()
    )
  );

-- ----------------------------------------------------------------------------
-- 2. Designated Beta Reviewers Table & Helper
-- ----------------------------------------------------------------------------
create table if not exists public.curriculum_reviewers (
  id uuid primary key default gen_random_uuid(),
  target_id uuid references public.learning_targets(id) on delete cascade, -- null = global reviewer
  user_id uuid not null references auth.users(id) on delete cascade,
  role text not null default 'reviewer' check (role in ('reviewer', 'editor', 'admin')),
  created_at timestamptz not null default now()
);

create unique index if not exists curr_reviewers_user_target_idx
  on public.curriculum_reviewers(user_id, coalesce(target_id, '00000000-0000-0000-0000-000000000000'::uuid));

alter table public.curriculum_reviewers enable row level security;
drop policy if exists "reviewers_read" on public.curriculum_reviewers;
create policy "reviewers_read" on public.curriculum_reviewers
  for select using (auth.uid() = user_id or auth.role() = 'service_role');

-- Reviewer authorization helper
create or replace function public.is_target_reviewer(p_target_id uuid, p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1 from public.curriculum_reviewers
    where user_id = p_user_id
      and (target_id is null or target_id = p_target_id)
  );
$$;

-- ----------------------------------------------------------------------------
-- 3. Lesson Visibility Helper
-- ----------------------------------------------------------------------------
create or replace function public.is_lesson_visible(p_lesson_id uuid, p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1 from public.lessons l
    where l.id = p_lesson_id
      and (
        l.user_id = p_user_id
        or (l.origin_target_version_id is null and l.visibility = 'public')
        or (l.origin_target_version_id is not null and exists (
          select 1 from public.target_versions tv
          join public.learning_targets lt on lt.id = tv.target_id
          where tv.id = l.origin_target_version_id
            and (
              (tv.status = 'published' and lt.status = 'published' and lt.is_public = true)
              or (lt.created_by = p_user_id)
              or (tv.status = 'review_ready' and public.is_target_reviewer(lt.id, p_user_id))
            )
        ))
      )
  );
$$;

-- ----------------------------------------------------------------------------
-- 4. Staging Visibility: Secure RLS Policies
-- ----------------------------------------------------------------------------

-- Target Versions
drop policy if exists "versions_read" on public.target_versions;
create policy "versions_read" on public.target_versions
  for select using (
    exists (
      select 1 from public.learning_targets t
      where t.id = target_versions.target_id
        and (
          (t.status = 'published' and t.is_public = true and target_versions.status = 'published')
          or (t.created_by = auth.uid())
          or (target_versions.status = 'review_ready' and public.is_target_reviewer(t.id, auth.uid()))
        )
    )
  );

drop policy if exists "versions_update" on public.target_versions;
create policy "versions_update" on public.target_versions
  for update using (
    target_versions.status in ('draft', 'review_ready')
    and exists (
      select 1 from public.learning_targets t
      where t.id = target_versions.target_id
        and t.created_by = auth.uid()
    )
  )
  with check (
    exists (
      select 1 from public.learning_targets t
      where t.id = target_versions.target_id
        and t.created_by = auth.uid()
    )
  );

drop policy if exists "versions_delete" on public.target_versions;
create policy "versions_delete" on public.target_versions
  for delete using (
    target_versions.status = 'draft'
    and exists (
      select 1 from public.learning_targets t
      where t.id = target_versions.target_id
        and t.created_by = auth.uid()
    )
  );

-- Curriculum Nodes
drop policy if exists "nodes_read" on public.curriculum_nodes;
create policy "nodes_read" on public.curriculum_nodes
  for select using (
    exists (
      select 1 from public.target_versions v
      join public.learning_targets t on t.id = v.target_id
      where v.id = curriculum_nodes.target_version_id
        and (
          (t.status = 'published' and t.is_public = true and v.status = 'published')
          or (t.created_by = auth.uid())
          or (v.status = 'review_ready' and public.is_target_reviewer(t.id, auth.uid()))
        )
    )
  );

-- Lessons
drop policy if exists lessons_read_visible on public.lessons;
create policy lessons_read_visible on public.lessons
  for select to authenticated, anon
  using (
    user_id = auth.uid()
    or (origin_target_version_id is null and visibility = 'public')
    or (origin_target_version_id is not null and exists (
      select 1 from public.target_versions tv
      join public.learning_targets lt on lt.id = tv.target_id
      where tv.id = lessons.origin_target_version_id
        and (
          (tv.status = 'published' and lt.status = 'published' and lt.is_public = true)
          or (lt.created_by = auth.uid())
          or (tv.status = 'review_ready' and public.is_target_reviewer(lt.id, auth.uid()))
        )
    ))
  );

-- Lesson Blocks
drop policy if exists "lesson_blocks_read" on public.lesson_blocks;
create policy "lesson_blocks_read" on public.lesson_blocks
  for select using (public.is_lesson_visible(lesson_id, auth.uid()));

-- Terms
drop policy if exists terms_read_visible on public.terms;
create policy terms_read_visible on public.terms
  for select to authenticated, anon
  using (public.is_lesson_visible(lesson_id, auth.uid()));

-- Questions
drop policy if exists questions_read_visible on public.questions;
create policy questions_read_visible on public.questions
  for select to authenticated, anon
  using (public.is_lesson_visible(lesson_id, auth.uid()));

-- Lesson Concepts
drop policy if exists lesson_concepts_read on public.lesson_concepts;
create policy lesson_concepts_read on public.lesson_concepts
  for select to authenticated, anon
  using (public.is_lesson_visible(lesson_id, auth.uid()));

-- Assessment Stimuli
drop policy if exists "assessment_stimuli_read" on public.assessment_stimuli;
create policy "assessment_stimuli_read" on public.assessment_stimuli
  for select using (
    created_by = auth.uid()
    or (origin_target_version_id is null and created_by is null)
    or (origin_target_version_id is not null and exists (
      select 1 from public.target_versions tv
      join public.learning_targets lt on lt.id = tv.target_id
      where tv.id = assessment_stimuli.origin_target_version_id
        and (
          (tv.status = 'published' and lt.status = 'published' and lt.is_public = true)
          or (lt.created_by = auth.uid())
          or (tv.status = 'review_ready' and public.is_target_reviewer(lt.id, auth.uid()))
        )
    ))
  );

-- Assessment Items
drop policy if exists "assessment_items_read" on public.assessment_items;
create policy "assessment_items_read" on public.assessment_items
  for select using (
    user_id = auth.uid()
    or (lesson_id is not null and public.is_lesson_visible(lesson_id, auth.uid()))
    or (origin_target_version_id is not null and exists (
      select 1 from public.target_versions tv
      join public.learning_targets lt on lt.id = tv.target_id
      where tv.id = assessment_items.origin_target_version_id
        and (
          (tv.status = 'published' and lt.status = 'published' and lt.is_public = true)
          or (lt.created_by = auth.uid())
          or (tv.status = 'review_ready' and public.is_target_reviewer(lt.id, auth.uid()))
        )
    ))
  );

-- Assessment Item Concepts
drop policy if exists "assessment_item_concepts_read" on public.assessment_item_concepts;
create policy "assessment_item_concepts_read" on public.assessment_item_concepts
  for select using (
    exists (
      select 1 from public.assessment_items a
      where a.id = assessment_item_concepts.assessment_item_id
        and (
          a.user_id = auth.uid()
          or (a.lesson_id is not null and public.is_lesson_visible(a.lesson_id, auth.uid()))
          or (a.origin_target_version_id is not null and exists (
            select 1 from public.target_versions tv
            join public.learning_targets lt on lt.id = tv.target_id
            where tv.id = a.origin_target_version_id
              and (
                (tv.status = 'published' and lt.status = 'published' and lt.is_public = true)
                or (lt.created_by = auth.uid())
                or (tv.status = 'review_ready' and public.is_target_reviewer(lt.id, auth.uid()))
              )
          ))
        )
    )
  );

-- Flashcards
drop policy if exists "flashcards_read" on public.flashcards;
create policy "flashcards_read" on public.flashcards
  for select using (
    user_id = auth.uid()
    or (origin_target_version_id is not null and exists (
      select 1 from public.target_versions tv
      join public.learning_targets lt on lt.id = tv.target_id
      where tv.id = flashcards.origin_target_version_id
        and (
          (tv.status = 'published' and lt.status = 'published' and lt.is_public = true)
          or (lt.created_by = auth.uid())
          or (tv.status = 'review_ready' and public.is_target_reviewer(lt.id, auth.uid()))
        )
    ))
    or (origin_target_version_id is null and user_id is null)
  );

-- Flashcard Concepts
drop policy if exists "flashcard_concepts_read" on public.flashcard_concepts;
create policy "flashcard_concepts_read" on public.flashcard_concepts
  for select using (
    exists (
      select 1 from public.flashcards f
      where f.id = flashcard_concepts.flashcard_id
        and (
          f.user_id = auth.uid()
          or (f.origin_target_version_id is not null and exists (
            select 1 from public.target_versions tv
            join public.learning_targets lt on lt.id = tv.target_id
            where tv.id = f.origin_target_version_id
              and (
                (tv.status = 'published' and lt.status = 'published' and lt.is_public = true)
                or (lt.created_by = auth.uid())
                or (tv.status = 'review_ready' and public.is_target_reviewer(lt.id, auth.uid()))
              )
          ))
          or (f.origin_target_version_id is null and f.user_id is null)
        )
    )
  );

-- ----------------------------------------------------------------------------
-- 5. TargetVersion State Machine Trigger
-- ----------------------------------------------------------------------------
create or replace function public.trg_target_versions_lifecycle()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if tg_op = 'DELETE' then
    if old.status <> 'draft' then
      raise exception 'Cannot delete target_version with status "%". Only draft versions may be deleted.', old.status;
    end if;
    return old;
  end if;

  if tg_op = 'UPDATE' then
    -- Published versions cannot change status except to 'retired'
    if old.status = 'published' and new.status <> 'retired' and new.status <> 'published' then
      raise exception 'Published versions are immutable and can only transition to "retired".';
    end if;

    -- Retired versions are completely immutable
    if old.status = 'retired' and (new.status <> 'retired' or new.* is distinct from old.*) then
      raise exception 'Retired versions are completely immutable.';
    end if;

    -- Draft status transitions: must go through review_ready before publishing
    if old.status = 'draft' then
      if new.status not in ('draft', 'review_ready') then
        raise exception 'Invalid status transition: draft must be staged to "review_ready" before publishing.';
      end if;
    end if;

    -- review_ready status transitions
    if old.status = 'review_ready' then
      if new.status not in ('draft', 'published', 'review_ready') then
        raise exception 'Invalid status transition: review_ready can only transition to "draft" or "published".';
      end if;

      -- While in review_ready (status not changing), metadata is frozen!
      if new.status = 'review_ready' and (
        new.version_code <> old.version_code or
        new.title is distinct from old.title or
        new.description is distinct from old.description or
        new.metadata is distinct from old.metadata or
        new.target_id <> old.target_id
      ) then
        raise exception 'TargetVersion is frozen in "review_ready" status. Revert status to "draft" before making edits.';
      end if;
    end if;

    return new;
  end if;

  return new;
end;
$$;

drop trigger if exists trg_target_versions_lifecycle on public.target_versions;
create trigger trg_target_versions_lifecycle
  before update or delete on public.target_versions
  for each row execute function public.trg_target_versions_lifecycle();

-- ----------------------------------------------------------------------------
-- 6. Hardened clean_draft_target_version (Service-Role / Owner Only)
-- ----------------------------------------------------------------------------
create or replace function public.clean_draft_target_version(
  p_version_id uuid
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_status text;
  v_target_id uuid;
  v_target_owner uuid;
begin
  select tv.status, tv.target_id, lt.created_by
  into v_status, v_target_id, v_target_owner
  from public.target_versions tv
  join public.learning_targets lt on lt.id = tv.target_id
  where tv.id = p_version_id;

  if v_status is null then
    raise exception 'TargetVersion % not found', p_version_id;
  end if;

  if v_status <> 'draft' then
    raise exception 'Cannot clean TargetVersion with status "%". Only draft versions may be reset.', v_status;
  end if;

  -- Authorization check: service_role or target owner only
  if coalesce(current_setting('request.jwt.claim.role', true), '') <> 'service_role'
     and auth.role() <> 'service_role'
     and (v_target_owner is null or v_target_owner <> auth.uid()) then
    raise exception 'Unauthorized: only service_role or the target owner can clean a draft target version';
  end if;

  -- 1. Delete content_source_mappings explicitly tracked as artifacts of this draft
  delete from public.content_source_mappings
  where id in (
    select entity_id
    from public.content_import_artifacts
    where target_version_id = p_version_id
      and entity_type = 'content_source_mapping'
  )
  or (entity_type = 'target_version' and entity_id = p_version_id);

  -- Clean any orphaned content_source_mappings whose referenced entity no longer exists
  delete from public.content_source_mappings
  where (entity_type = 'lesson' and not exists (select 1 from public.lessons where id = entity_id))
     or (entity_type = 'curriculum_node' and not exists (select 1 from public.curriculum_nodes where id = entity_id))
     or (entity_type = 'assessment_stimulus' and not exists (select 1 from public.assessment_stimuli where id = entity_id))
     or (entity_type = 'assessment_item' and not exists (select 1 from public.assessment_items where id = entity_id))
     or (entity_type = 'flashcard' and not exists (select 1 from public.flashcards where id = entity_id));

  -- 2. Delete assessment_items created specifically for this draft version
  delete from public.assessment_items
  where origin_target_version_id = p_version_id
     or id in (
       select entity_id
       from public.content_import_artifacts
       where target_version_id = p_version_id
         and entity_type = 'assessment_item'
     );

  -- 3. Delete assessment_stimuli created specifically for this draft version
  delete from public.assessment_stimuli
  where origin_target_version_id = p_version_id
     or id in (
       select entity_id
       from public.content_import_artifacts
       where target_version_id = p_version_id
         and entity_type = 'assessment_stimulus'
     );

  -- 4. Delete flashcards created specifically for this draft version
  delete from public.flashcards
  where origin_target_version_id = p_version_id
     or id in (
       select entity_id
       from public.content_import_artifacts
       where target_version_id = p_version_id
         and entity_type = 'flashcard'
     );

  -- 5. Delete official lessons created specifically for this draft version
  -- (Deleting the lesson automatically cascades to lesson_blocks, terms, questions, lesson_concepts)
  delete from public.lessons
  where origin_target_version_id = p_version_id
     or id in (
       select entity_id
       from public.content_import_artifacts
       where target_version_id = p_version_id
         and entity_type = 'lesson'
     )
     or (
       user_id is null
       and origin_target_version_id is null
       and id in (
         select cnl.lesson_id
         from public.curriculum_node_lessons cnl
         join public.curriculum_nodes cn on cn.id = cnl.curriculum_node_id
         where cn.target_version_id = p_version_id
           and not exists (
             select 1
             from public.curriculum_node_lessons o_cnl
             join public.curriculum_nodes o_cn on o_cn.id = o_cnl.curriculum_node_id
             where o_cnl.lesson_id = cnl.lesson_id
               and o_cn.target_version_id <> p_version_id
           )
       )
     );

  -- 6. Delete curriculum nodes of this draft (cascades to curriculum_node_concepts, cnl)
  delete from public.curriculum_nodes
  where target_version_id = p_version_id;

  -- 7. Delete concept mappings involving this draft version
  delete from public.target_version_concept_mappings
  where from_target_version_id = p_version_id
     or to_target_version_id = p_version_id;

  -- 8. Clean all artifact tracking records for this draft version
  delete from public.content_import_artifacts
  where target_version_id = p_version_id;

end;
$$;

revoke all on function public.clean_draft_target_version(uuid) from public, anon;
grant execute on function public.clean_draft_target_version(uuid) to authenticated, service_role;

-- ----------------------------------------------------------------------------
-- 7. Fully Transactional Ingestion RPC (ingest_curriculum_manifest)
-- ----------------------------------------------------------------------------
create or replace function public.ingest_curriculum_manifest(
  payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_field_id uuid;
  v_field_slug text;
  v_target_id uuid;
  v_target_slug text;
  v_version_id uuid;
  v_version_code text;
  v_version_status text;

  -- Counters
  v_stimuli_count int := 0;
  v_domains_count int := 0;
  v_objectives_count int := 0;
  v_lessons_count int := 0;
  v_blocks_count int := 0;
  v_items_count int := 0;
  v_flashcards_count int := 0;
  v_questions_count int := 0;
  v_mappings_count int := 0;

  -- Iterators
  v_source_rel jsonb;
  v_source_artifact jsonb;
  v_rel_id uuid;
  v_stim jsonb;
  v_stim_id uuid;
  v_stim_key text;
  v_domain jsonb;
  v_domain_id uuid;
  v_obj jsonb;
  v_obj_id uuid;
  v_concept_id uuid;
  v_lesson jsonb;
  v_lesson_id uuid;
  v_block jsonb;
  v_term jsonb;
  v_question jsonb;
  v_item jsonb;
  v_item_id uuid;
  v_fc jsonb;
  v_fc_id uuid;
  v_mapping jsonb;
  v_from_concept_id uuid;
  v_to_concept_id uuid;
  v_source_mapping jsonb;
  v_mapping_id uuid;
  v_source_releases_map jsonb := '{}'::jsonb;
  v_default_rel_id uuid := null;
  v_source_rel_idx int := 0;
  v_entity_rel_id uuid;

  -- Key Maps
  v_stimuli_map jsonb := '{}'::jsonb;
begin
  -- 1. Security Check: Service role only
  if coalesce(current_setting('request.jwt.claim.role', true), '') <> 'service_role'
     and auth.role() <> 'service_role' then
    raise exception 'Unauthorized: ingest_curriculum_manifest requires service_role privilege';
  end if;

  -- 2. Extract Field
  v_field_slug := payload->'field'->>'slug';
  if v_field_slug is not null and v_field_slug <> '' then
    select id into v_field_id from public.fields where slug = v_field_slug;
    if v_field_id is null then
      insert into public.fields (slug, name, description, field_kind)
      values (
        v_field_slug,
        coalesce(payload->'field'->>'name', v_field_slug),
        payload->'field'->>'description',
        'native_field'
      )
      returning id into v_field_id;
    end if;
  end if;

  -- 3. Extract Target
  v_target_slug := payload->'target'->>'slug';
  if v_target_slug is null or v_target_slug = '' then
    raise exception 'Missing target.slug in manifest payload';
  end if;

  select id into v_target_id from public.learning_targets where slug = v_target_slug;
  if v_target_id is null then
    insert into public.learning_targets (
      slug, title, target_type, description, field_id, status, is_public
    ) values (
      v_target_slug,
      coalesce(payload->'target'->>'title', v_target_slug),
      coalesce(payload->'target'->>'target_type', coalesce(payload->'target'->>'target_kind', 'certification')),
      payload->'target'->>'description',
      v_field_id,
      'published',
      true
    )
    returning id into v_target_id;
  end if;

  -- 4. Extract TargetVersion
  v_version_code := payload->'target_version'->>'version_code';
  if v_version_code is null or v_version_code = '' then
    raise exception 'Missing target_version.version_code in manifest payload';
  end if;

  select id, status into v_version_id, v_version_status
  from public.target_versions
  where target_id = v_target_id and version_code = v_version_code;

  if v_version_id is null then
    insert into public.target_versions (
      target_id, version_code, title, description, valid_from, status, metadata
    ) values (
      v_target_id,
      v_version_code,
      payload->'target_version'->>'title',
      payload->'target_version'->>'description',
      case when payload->'target_version'->>'valid_from' is not null
           then (payload->'target_version'->>'valid_from')::date
           else null end,
      'draft',
      coalesce(payload->'target_version'->'metadata', '{}'::jsonb)
    )
    returning id, status into v_version_id, v_version_status;
  end if;

  if v_version_status <> 'draft' then
    raise exception 'Cannot ingest into TargetVersion "%" with status "%". Only draft versions may be replaced.', v_version_code, v_version_status;
  end if;

  -- 5. Atomically Clean Previous Draft Content for this TargetVersion
  perform public.clean_draft_target_version(v_version_id);

  -- 6. Ingest Source Releases & Artifacts
  if jsonb_typeof(payload->'source_releases') = 'array' then
    for v_source_rel in select * from jsonb_array_elements(payload->'source_releases')
    loop
      insert into public.content_source_releases (
        publisher, title, version, source_url, license, retrieved_at, sha256, metadata
      ) values (
        coalesce(v_source_rel->>'publisher', 'Authoritative Source'),
        coalesce(v_source_rel->>'title', 'Official Blueprint'),
        coalesce(v_source_rel->>'version', 'v1'),
        v_source_rel->>'source_url',
        coalesce(v_source_rel->>'license', v_source_rel->>'license_name'),
        case when v_source_rel->>'retrieved_at' is not null
             then (v_source_rel->>'retrieved_at')::timestamptz
             else now() end,
        v_source_rel->>'sha256',
        coalesce(v_source_rel->'metadata', '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
          'system', v_source_rel->>'system',
          'rights_note', v_source_rel->>'rights_note'
        ))
      )
      on conflict (publisher, title, version) do update
      set source_url = excluded.source_url,
          license = excluded.license,
          retrieved_at = excluded.retrieved_at,
          sha256 = excluded.sha256,
          metadata = excluded.metadata
      returning id into v_rel_id;

      v_source_rel_idx := v_source_rel_idx + 1;
      if v_default_rel_id is null then
        v_default_rel_id := v_rel_id;
      end if;

      if v_source_rel ? 'id' then
        v_source_releases_map := v_source_releases_map || jsonb_build_object(v_source_rel->>'id', v_rel_id::text);
      end if;
      v_source_releases_map := v_source_releases_map || jsonb_build_object(
        coalesce(v_source_rel->>'publisher', '') || '/' || coalesce(v_source_rel->>'version', ''), v_rel_id::text
      );
      v_source_releases_map := v_source_releases_map || jsonb_build_object(
        (v_source_rel_idx - 1)::text, v_rel_id::text
      );

      -- Link root target_version to this source release
      insert into public.content_source_mappings (
        source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
      ) values (
        v_rel_id,
        'target_version',
        v_version_id,
        'official_blueprint',
        coalesce(payload->'target_version'->>'citation', 'Root Blueprint'),
        'Root target version mapping to authoritative source release',
        '{}'::jsonb
      )
      on conflict (source_release_id, entity_type, entity_id, relationship) do update
      set citation_location = excluded.citation_location,
          notes = excluded.notes,
          metadata = excluded.metadata
      returning id into v_mapping_id;

      v_mappings_count := v_mappings_count + 1;
      insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
      values (v_version_id, 'content_source_mapping', v_mapping_id)
      on conflict do nothing;

      -- Artifacts
      if jsonb_typeof(v_source_rel->'artifacts') = 'array' then
        for v_source_artifact in select * from jsonb_array_elements(v_source_rel->'artifacts')
        loop
          insert into public.content_source_artifacts (
            source_release_id, artifact_name, source_url, sha256, file_size_bytes, retrieved_at, metadata
          ) values (
            v_rel_id,
            coalesce(v_source_artifact->>'artifact_name', 'blueprint.pdf'),
            v_source_artifact->>'source_url',
            v_source_artifact->>'sha256',
            case when v_source_artifact->>'file_size_bytes' is not null
                 then (v_source_artifact->>'file_size_bytes')::bigint
                 else null end,
            case when v_source_artifact->>'retrieved_at' is not null
                 then (v_source_artifact->>'retrieved_at')::timestamptz
                 else now() end,
            coalesce(v_source_artifact->'metadata', '{}'::jsonb)
          )
          on conflict (source_release_id, artifact_name) do update
          set source_url = excluded.source_url,
              sha256 = excluded.sha256,
              file_size_bytes = excluded.file_size_bytes,
              retrieved_at = excluded.retrieved_at,
              metadata = excluded.metadata;
        end loop;
      end if;
    end loop;
  end if;

  -- 7. Ingest Shared Stimuli (root-level & objective-level)
  if jsonb_typeof(payload->'stimuli') = 'array' then
    for v_stim in select * from jsonb_array_elements(payload->'stimuli')
    loop
      v_stim_key := v_stim->>'stimulus_key';
      insert into public.assessment_stimuli (
        title, body, stimulus_type, metadata, origin_target_version_id
      ) values (
        coalesce(v_stim->>'title', 'Exhibit'),
        coalesce(v_stim->>'body', coalesce(v_stim->>'body_markdown', '')),
        coalesce(v_stim->>'stimulus_type', 'scenario'),
        jsonb_build_object(
          'media_url', v_stim->>'media_url',
          'credit', v_stim->>'credit',
          'attribution', v_stim->>'attribution'
        ),
        v_version_id
      )
      returning id into v_stim_id;

      v_stimuli_count := v_stimuli_count + 1;
      v_stimuli_map := v_stimuli_map || jsonb_build_object(v_stim_key, v_stim_id::text);

      insert into public.content_import_artifacts (target_version_id, entity_type, entity_id, manifest_key)
      values (v_version_id, 'assessment_stimulus', v_stim_id, v_stim_key);

      -- Stimulus Source Mapping
      if v_default_rel_id is not null then
        v_entity_rel_id := null;
        if v_stim ? 'source_release_id' and v_source_releases_map ? (v_stim->>'source_release_id') then
          v_entity_rel_id := (v_source_releases_map->>(v_stim->>'source_release_id'))::uuid;
        else
          v_entity_rel_id := v_default_rel_id;
        end if;

        if v_entity_rel_id is not null then
          insert into public.content_source_mappings (
            source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
          ) values (
            v_entity_rel_id,
            'assessment_stimulus',
            v_stim_id,
            'official_blueprint',
            coalesce(v_stim->>'citation', 'Official Blueprint Stimulus'),
            'Assessment stimulus mapping',
            '{}'::jsonb
          )
          on conflict (source_release_id, entity_type, entity_id, relationship) do update
          set citation_location = excluded.citation_location,
              notes = excluded.notes,
              metadata = excluded.metadata
          returning id into v_mapping_id;

          v_mappings_count := v_mappings_count + 1;
          insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
          values (v_version_id, 'content_source_mapping', v_mapping_id)
          on conflict do nothing;
        end if;
      end if;
    end loop;
  end if;

  -- 8. Ingest Standalone Target-level Flashcards
  if jsonb_typeof(payload->'flashcards') = 'array' then
    for v_fc in select * from jsonb_array_elements(payload->'flashcards')
    loop
      insert into public.flashcards (
        front, back, explanation, origin_target_version_id
      ) values (
        v_fc->>'front',
        v_fc->>'back',
        v_fc->>'explanation',
        v_version_id
      )
      returning id into v_fc_id;

      v_flashcards_count := v_flashcards_count + 1;
      insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
      values (v_version_id, 'flashcard', v_fc_id);

      -- Link concepts
      if jsonb_typeof(v_fc->'concept_ids') = 'array' then
        for v_concept_id in select (jsonb_array_elements_text(v_fc->'concept_ids'))::uuid
        loop
          insert into public.flashcard_concepts (flashcard_id, concept_id)
          values (v_fc_id, v_concept_id)
          on conflict do nothing;
        end loop;
      end if;
    end loop;
  end if;

  -- 9. Ingest Domains, Objectives, Lessons, Blocks, Assessment Items
  if jsonb_typeof(payload->'domains') = 'array' then
    for v_domain in select * from jsonb_array_elements(payload->'domains')
    loop
      insert into public.curriculum_nodes (
        target_version_id, node_type, code, title, description, sort_order, weight, metadata
      ) values (
        v_version_id,
        'domain',
        v_domain->>'code',
        coalesce(v_domain->>'title', 'Domain'),
        v_domain->>'description',
        coalesce((v_domain->>'sort_order')::int, 0),
        case when v_domain->>'weight_percentage' is not null
             then (v_domain->>'weight_percentage')::numeric
             when v_domain->>'weight' is not null
             then (v_domain->>'weight')::numeric
             else null end,
        coalesce(v_domain->'metadata', '{}'::jsonb)
      )
      returning id into v_domain_id;

      v_domains_count := v_domains_count + 1;
      insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
      values (v_version_id, 'curriculum_node', v_domain_id);

      -- Domain Source Mapping
      if v_default_rel_id is not null then
        v_entity_rel_id := null;
        if v_domain ? 'source_release_id' and v_source_releases_map ? (v_domain->>'source_release_id') then
          v_entity_rel_id := (v_source_releases_map->>(v_domain->>'source_release_id'))::uuid;
        else
          v_entity_rel_id := v_default_rel_id;
        end if;

        if v_entity_rel_id is not null then
          insert into public.content_source_mappings (
            source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
          ) values (
            v_entity_rel_id,
            'curriculum_node',
            v_domain_id,
            'official_blueprint',
            coalesce(v_domain->>'citation', 'Domain ' || coalesce(v_domain->>'code', '')),
            'Curriculum domain node citation',
            '{}'::jsonb
          )
          on conflict (source_release_id, entity_type, entity_id, relationship) do update
          set citation_location = excluded.citation_location,
              notes = excluded.notes,
              metadata = excluded.metadata
          returning id into v_mapping_id;

          v_mappings_count := v_mappings_count + 1;
          insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
          values (v_version_id, 'content_source_mapping', v_mapping_id)
          on conflict do nothing;
        end if;
      end if;

      -- Objectives
      if jsonb_typeof(v_domain->'objectives') = 'array' then
        for v_obj in select * from jsonb_array_elements(v_domain->'objectives')
        loop
          insert into public.curriculum_nodes (
            target_version_id, parent_id, node_type, code, title, description, sort_order, metadata
          ) values (
            v_version_id,
            v_domain_id,
            'objective',
            v_obj->>'code',
            coalesce(v_obj->>'title', 'Objective'),
            v_obj->>'description',
            coalesce((v_obj->>'sort_order')::int, 0),
            jsonb_build_object('bloom_level', coalesce(v_obj->>'bloom_level', 'understand'))
          )
          returning id into v_obj_id;

          v_objectives_count := v_objectives_count + 1;
          insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
          values (v_version_id, 'curriculum_node', v_obj_id);

          -- Objective Source Mapping
          if v_default_rel_id is not null then
            v_entity_rel_id := null;
            if v_obj ? 'source_release_id' and v_source_releases_map ? (v_obj->>'source_release_id') then
              v_entity_rel_id := (v_source_releases_map->>(v_obj->>'source_release_id'))::uuid;
            else
              v_entity_rel_id := coalesce((v_source_releases_map->>(v_domain->>'source_release_id'))::uuid, v_default_rel_id);
            end if;

            if v_entity_rel_id is not null then
              insert into public.content_source_mappings (
                source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
              ) values (
                v_entity_rel_id,
                'curriculum_node',
                v_obj_id,
                'official_blueprint',
                coalesce(v_obj->>'citation', 'Objective ' || coalesce(v_obj->>'code', '')),
                'Curriculum objective node citation',
                '{}'::jsonb
              )
              on conflict (source_release_id, entity_type, entity_id, relationship) do update
              set citation_location = excluded.citation_location,
                  notes = excluded.notes,
                  metadata = excluded.metadata
              returning id into v_mapping_id;

              v_mappings_count := v_mappings_count + 1;
              insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
              values (v_version_id, 'content_source_mapping', v_mapping_id)
              on conflict do nothing;
            end if;
          end if;

          -- Link objective concepts
          if jsonb_typeof(v_obj->'concept_ids') = 'array' then
            for v_concept_id in select (jsonb_array_elements_text(v_obj->'concept_ids'))::uuid
            loop
              insert into public.curriculum_node_concepts (curriculum_node_id, concept_id)
              values (v_obj_id, v_concept_id)
              on conflict do nothing;
            end loop;
          end if;

          -- Objective Flashcards
          if jsonb_typeof(v_obj->'flashcards') = 'array' then
            for v_fc in select * from jsonb_array_elements(v_obj->'flashcards')
            loop
              insert into public.flashcards (
                front, back, explanation, origin_target_version_id
              ) values (
                v_fc->>'front',
                v_fc->>'back',
                v_fc->>'explanation',
                v_version_id
              )
              returning id into v_fc_id;

              v_flashcards_count := v_flashcards_count + 1;
              insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
              values (v_version_id, 'flashcard', v_fc_id);

              if jsonb_typeof(v_fc->'concept_ids') = 'array' then
                for v_concept_id in select (jsonb_array_elements_text(v_fc->'concept_ids'))::uuid
                loop
                  insert into public.flashcard_concepts (flashcard_id, concept_id)
                  values (v_fc_id, v_concept_id)
                  on conflict do nothing;
                end loop;
              end if;
            end loop;
          end if;

          -- Objective Assessment Items
          if jsonb_typeof(v_obj->'assessment_items') = 'array' then
            for v_item in select * from jsonb_array_elements(v_obj->'assessment_items')
            loop
              v_stim_key := v_item->>'stimulus_key';
              v_stim_id := null;
              if v_stim_key is not null and v_stimuli_map ? v_stim_key then
                v_stim_id := (v_stimuli_map->>v_stim_key)::uuid;
              end if;

              insert into public.assessment_items (
                stimulus_id, prompt, interaction_type, response_spec, scoring_spec, explanation, origin_target_version_id
              ) values (
                v_stim_id,
                v_item->>'prompt',
                coalesce(v_item->>'interaction_type', 'single_choice'),
                coalesce(v_item->'response_spec', '{}'::jsonb),
                coalesce(v_item->'scoring_spec', '{}'::jsonb),
                v_item->>'explanation',
                v_version_id
              )
              returning id into v_item_id;

              v_items_count := v_items_count + 1;
              insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
              values (v_version_id, 'assessment_item', v_item_id);

              if jsonb_typeof(v_item->'concept_ids') = 'array' then
                for v_concept_id in select (jsonb_array_elements_text(v_item->'concept_ids'))::uuid
                loop
                  insert into public.assessment_item_concepts (assessment_item_id, concept_id)
                  values (v_item_id, v_concept_id)
                  on conflict do nothing;
                end loop;
              end if;
            end loop;
          end if;

          -- Lessons
          if jsonb_typeof(v_obj->'lessons') = 'array' then
            for v_lesson in select * from jsonb_array_elements(v_obj->'lessons')
            loop
              insert into public.lessons (
                title, description, visibility, origin_target_version_id
              ) values (
                v_lesson->>'title',
                coalesce(v_lesson->>'description', v_lesson->>'summary'),
                'public',
                v_version_id
              )
              returning id into v_lesson_id;

              v_lessons_count := v_lessons_count + 1;
              insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
              values (v_version_id, 'lesson', v_lesson_id);

              -- Lesson Source Mapping
              if v_default_rel_id is not null then
                v_entity_rel_id := null;
                if v_lesson ? 'source_release_id' and v_source_releases_map ? (v_lesson->>'source_release_id') then
                  v_entity_rel_id := (v_source_releases_map->>(v_lesson->>'source_release_id'))::uuid;
                else
                  v_entity_rel_id := coalesce(
                    (v_source_releases_map->>(v_obj->>'source_release_id'))::uuid,
                    coalesce((v_source_releases_map->>(v_domain->>'source_release_id'))::uuid, v_default_rel_id)
                  );
                end if;

                if v_entity_rel_id is not null then
                  insert into public.content_source_mappings (
                    source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
                  ) values (
                    v_entity_rel_id,
                    'lesson',
                    v_lesson_id,
                    'derived_from',
                    coalesce(v_lesson->>'citation', coalesce(v_lesson->>'title', 'Lesson')),
                    'Lesson derived from authoritative source',
                    '{}'::jsonb
                  )
                  on conflict (source_release_id, entity_type, entity_id, relationship) do update
                  set citation_location = excluded.citation_location,
                      notes = excluded.notes,
                      metadata = excluded.metadata
                  returning id into v_mapping_id;

                  v_mappings_count := v_mappings_count + 1;
                  insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
                  values (v_version_id, 'content_source_mapping', v_mapping_id)
                  on conflict do nothing;
                end if;
              end if;

              -- Bind lesson to objective
              insert into public.curriculum_node_lessons (curriculum_node_id, lesson_id, sort_order)
              values (v_obj_id, v_lesson_id, coalesce((v_lesson->>'order_index')::int, 0))
              on conflict do nothing;

              -- Scoped lesson concept linking (NO global leakage!)
              if jsonb_typeof(v_lesson->'concept_ids') = 'array' then
                for v_concept_id in select (jsonb_array_elements_text(v_lesson->'concept_ids'))::uuid
                loop
                  insert into public.lesson_concepts (lesson_id, concept_id)
                  values (v_lesson_id, v_concept_id)
                  on conflict do nothing;
                end loop;
              end if;

              -- Lesson Blocks
              if jsonb_typeof(v_lesson->'blocks') = 'array' then
                for v_block in select * from jsonb_array_elements(v_lesson->'blocks')
                loop
                  insert into public.lesson_blocks (
                    lesson_id, block_type, content, sort_order
                  ) values (
                    v_lesson_id,
                    coalesce(v_block->>'block_type', 'markdown'),
                    coalesce(v_block->'content', '{}'::jsonb),
                    coalesce((v_block->>'sort_order')::int, 0)
                  );
                  v_blocks_count := v_blocks_count + 1;
                end loop;
              end if;

              -- Lesson Terms
              if jsonb_typeof(v_lesson->'terms') = 'array' then
                for v_term in select * from jsonb_array_elements(v_lesson->'terms')
                loop
                  insert into public.terms (lesson_id, term, definition)
                  values (v_lesson_id, v_term->>'term', v_term->>'definition');
                end loop;
              end if;

              -- Lesson Questions
              if jsonb_typeof(v_lesson->'questions') = 'array' then
                for v_question in select * from jsonb_array_elements(v_lesson->'questions')
                loop
                  insert into public.questions (
                    lesson_id, question_text, options, correct_answer, type, explanation
                  ) values (
                    v_lesson_id,
                    coalesce(v_question->>'question_text', v_question->>'question'),
                    coalesce(v_question->'options', '[]'::jsonb),
                    coalesce((coalesce(v_question->>'correct_answer', v_question->>'correct_index'))::int, 0),
                    coalesce(v_question->>'type', 'mcq'),
                    v_question->>'explanation'
                  );
                  v_questions_count := v_questions_count + 1;
                end loop;
              end if;

              -- Lesson Assessment Items
              if jsonb_typeof(v_lesson->'assessment_items') = 'array' then
                for v_item in select * from jsonb_array_elements(v_lesson->'assessment_items')
                loop
                  v_stim_key := v_item->>'stimulus_key';
                  v_stim_id := null;
                  if v_stim_key is not null and v_stimuli_map ? v_stim_key then
                    v_stim_id := (v_stimuli_map->>v_stim_key)::uuid;
                  end if;

                  insert into public.assessment_items (
                    lesson_id, stimulus_id, prompt, interaction_type, response_spec, scoring_spec, explanation, origin_target_version_id
                  ) values (
                    v_lesson_id,
                    v_stim_id,
                    v_item->>'prompt',
                    coalesce(v_item->>'interaction_type', 'single_choice'),
                    coalesce(v_item->'response_spec', '{}'::jsonb),
                    coalesce(v_item->'scoring_spec', '{}'::jsonb),
                    v_item->>'explanation',
                    v_version_id
                  )
                  returning id into v_item_id;

                  v_items_count := v_items_count + 1;
                  insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
                  values (v_version_id, 'assessment_item', v_item_id);

                  if jsonb_typeof(v_item->'concept_ids') = 'array' then
                    for v_concept_id in select (jsonb_array_elements_text(v_item->'concept_ids'))::uuid
                    loop
                      insert into public.assessment_item_concepts (assessment_item_id, concept_id)
                      values (v_item_id, v_concept_id)
                      on conflict do nothing;
                    end loop;
                  end if;
                end loop;
              end if;

            end loop;
          end if; -- lessons

        end loop;
      end if; -- objectives

    end loop;
  end if; -- domains

  -- 10. Ingest Source Mappings
  if jsonb_typeof(payload->'source_mappings') = 'array' then
    for v_source_mapping in select * from jsonb_array_elements(payload->'source_mappings')
    loop
      insert into public.content_source_mappings (
        source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
      ) values (
        (v_source_mapping->>'source_release_id')::uuid,
        v_source_mapping->>'entity_type',
        (v_source_mapping->>'entity_id')::uuid,
        coalesce(v_source_mapping->>'relationship', 'derived_from'),
        coalesce(v_source_mapping->>'citation_location', v_source_mapping->>'section_reference'),
        coalesce(v_source_mapping->>'notes', v_source_mapping->>'citation_text'),
        coalesce(v_source_mapping->'metadata', '{}'::jsonb)
      )
      on conflict (source_release_id, entity_type, entity_id, relationship) do update
      set citation_location = excluded.citation_location,
          notes = excluded.notes,
          metadata = excluded.metadata
      returning id into v_mapping_id;

      v_mappings_count := v_mappings_count + 1;
      insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
      values (v_version_id, 'content_source_mapping', v_mapping_id)
      on conflict do nothing;
    end loop;
  end if;

  -- 11. Ingest Concept Version Mappings
  if jsonb_typeof(payload->'target_version_concept_mappings') = 'array' then
    for v_mapping in select * from jsonb_array_elements(payload->'target_version_concept_mappings')
    loop
      v_from_concept_id := (v_mapping->>'from_concept_id')::uuid;
      v_to_concept_id := case when v_mapping->>'to_concept_id' is not null
                              then (v_mapping->>'to_concept_id')::uuid
                              else null end;

      insert into public.target_version_concept_mappings (
        from_target_version_id, from_concept_id, to_target_version_id, to_concept_id,
        mapping_type, confidence, rationale
      ) values (
        v_version_id,
        v_from_concept_id,
        case when v_mapping->>'to_target_version_id' is not null
             then (v_mapping->>'to_target_version_id')::uuid
             else null end,
        v_to_concept_id,
        coalesce(v_mapping->>'mapping_type', 'exact_match'),
        coalesce((v_mapping->>'confidence')::numeric, 1.0),
        v_mapping->>'rationale'
      )
      on conflict do nothing;
    end loop;
  end if;

  return jsonb_build_object(
    'success', true,
    'target_id', v_target_id,
    'target_slug', v_target_slug,
    'target_version_id', v_version_id,
    'version_code', v_version_code,
    'stimuli_count', v_stimuli_count,
    'domains_count', v_domains_count,
    'objectives_count', v_objectives_count,
    'lessons_count', v_lessons_count,
    'blocks_count', v_blocks_count,
    'assessment_items_count', v_items_count,
    'flashcards_count', v_flashcards_count,
    'questions_count', v_questions_count,
    'mappings_count', v_mappings_count
  );
end;
$$;

revoke all on function public.ingest_curriculum_manifest(jsonb) from public, anon, authenticated;
grant execute on function public.ingest_curriculum_manifest(jsonb) to service_role;

INSERT INTO supabase_migrations.schema_migrations (version, name) VALUES ('20261006000000', 'import_ownership_and_staging') ON CONFLICT (version) DO NOTHING;

-- --------------------------------------------------------------------
-- [25/96] Migration: 20261006000001_rpc_provenance_and_clean_fix.sql
-- --------------------------------------------------------------------
-- ============================================================================
-- Migration: 20261006000001_rpc_provenance_and_clean_fix.sql
-- Description: Ensure clean_draft_target_version and ingest_curriculum_manifest
--              include orphan mapping cleanup and automatic provenance citations.
-- ============================================================================

-- 1. Updated clean_draft_target_version
create or replace function public.clean_draft_target_version(
  p_version_id uuid
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_status text;
  v_target_owner uuid;
begin
  select tv.status, lt.created_by
  into v_status, v_target_owner
  from public.target_versions tv
  join public.learning_targets lt on lt.id = tv.target_id
  where tv.id = p_version_id;

  if v_status is null then
    raise exception 'TargetVersion % not found', p_version_id;
  end if;

  if v_status <> 'draft' then
    raise exception 'Cannot clean TargetVersion with status "%". Only draft versions may be reset.', v_status;
  end if;

  -- Authorization check: service_role or target owner only
  if coalesce(current_setting('request.jwt.claim.role', true), '') <> 'service_role'
     and auth.role() <> 'service_role'
     and (v_target_owner is null or v_target_owner <> auth.uid()) then
    raise exception 'Unauthorized: only service_role or the target owner can clean a draft target version';
  end if;

  -- 1. Delete content_source_mappings explicitly tracked as artifacts of this draft
  delete from public.content_source_mappings
  where id in (
    select entity_id
    from public.content_import_artifacts
    where target_version_id = p_version_id
      and entity_type = 'content_source_mapping'
  )
  or (entity_type = 'target_version' and entity_id = p_version_id);

  -- Clean any orphaned content_source_mappings whose referenced entity no longer exists
  delete from public.content_source_mappings
  where (entity_type = 'lesson' and not exists (select 1 from public.lessons where id = entity_id))
     or (entity_type = 'curriculum_node' and not exists (select 1 from public.curriculum_nodes where id = entity_id))
     or (entity_type = 'assessment_stimulus' and not exists (select 1 from public.assessment_stimuli where id = entity_id))
     or (entity_type = 'assessment_item' and not exists (select 1 from public.assessment_items where id = entity_id))
     or (entity_type = 'flashcard' and not exists (select 1 from public.flashcards where id = entity_id));

  -- 2. Delete assessment_items created specifically for this draft version
  delete from public.assessment_items
  where origin_target_version_id = p_version_id
     or id in (
       select entity_id
       from public.content_import_artifacts
       where target_version_id = p_version_id
         and entity_type = 'assessment_item'
     );

  -- 3. Delete assessment_stimuli created specifically for this draft version
  delete from public.assessment_stimuli
  where origin_target_version_id = p_version_id
     or id in (
       select entity_id
       from public.content_import_artifacts
       where target_version_id = p_version_id
         and entity_type = 'assessment_stimulus'
     );

  -- 4. Delete flashcards created specifically for this draft version
  delete from public.flashcards
  where origin_target_version_id = p_version_id
     or id in (
       select entity_id
       from public.content_import_artifacts
       where target_version_id = p_version_id
         and entity_type = 'flashcard'
     );

  -- 5. Delete official lessons created specifically for this draft version
  delete from public.lessons
  where origin_target_version_id = p_version_id
     or id in (
       select entity_id
       from public.content_import_artifacts
       where target_version_id = p_version_id
         and entity_type = 'lesson'
     )
     or (
       user_id is null
       and origin_target_version_id is null
       and id in (
         select cnl.lesson_id
         from public.curriculum_node_lessons cnl
         join public.curriculum_nodes cn on cn.id = cnl.curriculum_node_id
         where cn.target_version_id = p_version_id
           and not exists (
             select 1
             from public.curriculum_node_lessons o_cnl
             join public.curriculum_nodes o_cn on o_cn.id = o_cnl.curriculum_node_id
             where o_cnl.lesson_id = cnl.lesson_id
               and o_cn.target_version_id <> p_version_id
           )
       )
     );

  -- 6. Delete curriculum nodes of this draft
  delete from public.curriculum_nodes
  where target_version_id = p_version_id;

  -- 7. Delete concept mappings involving this draft version
  delete from public.target_version_concept_mappings
  where from_target_version_id = p_version_id
     or to_target_version_id = p_version_id;

  -- 8. Clean all artifact tracking records for this draft version
  delete from public.content_import_artifacts
  where target_version_id = p_version_id;

end;
$$;

revoke all on function public.clean_draft_target_version(uuid) from public, anon;
grant execute on function public.clean_draft_target_version(uuid) to authenticated, service_role;

-- 2. Updated ingest_curriculum_manifest
create or replace function public.ingest_curriculum_manifest(
  payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_field_id uuid;
  v_field_slug text;
  v_target_id uuid;
  v_target_slug text;
  v_version_id uuid;
  v_version_code text;
  v_version_status text;

  -- Counters
  v_stimuli_count int := 0;
  v_domains_count int := 0;
  v_objectives_count int := 0;
  v_lessons_count int := 0;
  v_blocks_count int := 0;
  v_items_count int := 0;
  v_flashcards_count int := 0;
  v_questions_count int := 0;
  v_mappings_count int := 0;

  -- Iterators
  v_source_rel jsonb;
  v_source_artifact jsonb;
  v_rel_id uuid;
  v_stim jsonb;
  v_stim_id uuid;
  v_stim_key text;
  v_domain jsonb;
  v_domain_id uuid;
  v_obj jsonb;
  v_obj_id uuid;
  v_concept_id uuid;
  v_lesson jsonb;
  v_lesson_id uuid;
  v_block jsonb;
  v_term jsonb;
  v_question jsonb;
  v_item jsonb;
  v_item_id uuid;
  v_fc jsonb;
  v_fc_id uuid;
  v_mapping jsonb;
  v_from_concept_id uuid;
  v_to_concept_id uuid;
  v_source_mapping jsonb;
  v_mapping_id uuid;
  v_source_releases_map jsonb := '{}'::jsonb;
  v_default_rel_id uuid := null;
  v_source_rel_idx int := 0;
  v_entity_rel_id uuid;

  -- Key Maps
  v_stimuli_map jsonb := '{}'::jsonb;
begin
  -- 1. Security Check: Service role only
  if coalesce(current_setting('request.jwt.claim.role', true), '') <> 'service_role'
     and auth.role() <> 'service_role' then
    raise exception 'Unauthorized: ingest_curriculum_manifest requires service_role privilege';
  end if;

  -- 2. Extract Field
  v_field_slug := payload->'field'->>'slug';
  if v_field_slug is not null and v_field_slug <> '' then
    select id into v_field_id from public.fields where slug = v_field_slug;
    if v_field_id is null then
      insert into public.fields (slug, name, description, field_kind)
      values (
        v_field_slug,
        coalesce(payload->'field'->>'name', v_field_slug),
        payload->'field'->>'description',
        'native_field'
      )
      returning id into v_field_id;
    end if;
  end if;

  -- 3. Extract LearningTarget
  v_target_slug := payload->'target'->>'slug';
  if v_target_slug is null or v_target_slug = '' then
    raise exception 'Missing target.slug in manifest payload';
  end if;

  select id into v_target_id from public.learning_targets where slug = v_target_slug;
  if v_target_id is null then
    insert into public.learning_targets (
      slug, title, target_type, description, field_id, status, is_public
    ) values (
      v_target_slug,
      coalesce(payload->'target'->>'title', v_target_slug),
      coalesce(payload->'target'->>'target_type', coalesce(payload->'target'->>'target_kind', 'certification')),
      payload->'target'->>'description',
      v_field_id,
      'published',
      true
    )
    returning id into v_target_id;
  end if;

  -- 4. Extract TargetVersion
  v_version_code := payload->'target_version'->>'version_code';
  if v_version_code is null or v_version_code = '' then
    raise exception 'Missing target_version.version_code in manifest payload';
  end if;

  select id, status into v_version_id, v_version_status
  from public.target_versions
  where target_id = v_target_id and version_code = v_version_code;

  if v_version_id is null then
    insert into public.target_versions (
      target_id, version_code, title, description, valid_from, status, metadata
    ) values (
      v_target_id,
      v_version_code,
      payload->'target_version'->>'title',
      payload->'target_version'->>'description',
      case when payload->'target_version'->>'valid_from' is not null
           then (payload->'target_version'->>'valid_from')::date
           else null end,
      'draft',
      coalesce(payload->'target_version'->'metadata', '{}'::jsonb)
    )
    returning id, status into v_version_id, v_version_status;
  end if;

  if v_version_status <> 'draft' then
    raise exception 'Cannot ingest into TargetVersion "%" with status "%". Only draft versions may be replaced.', v_version_code, v_version_status;
  end if;

  -- 5. Atomically Clean Previous Draft Content for this TargetVersion
  perform public.clean_draft_target_version(v_version_id);

  -- 6. Ingest Source Releases & Artifacts
  if jsonb_typeof(payload->'source_releases') = 'array' then
    for v_source_rel in select * from jsonb_array_elements(payload->'source_releases')
    loop
      insert into public.content_source_releases (
        publisher, title, version, source_url, license, retrieved_at, sha256, metadata
      ) values (
        coalesce(v_source_rel->>'publisher', 'Authoritative Source'),
        coalesce(v_source_rel->>'title', 'Official Blueprint'),
        coalesce(v_source_rel->>'version', 'v1'),
        v_source_rel->>'source_url',
        coalesce(v_source_rel->>'license', v_source_rel->>'license_name'),
        case when v_source_rel->>'retrieved_at' is not null
             then (v_source_rel->>'retrieved_at')::timestamptz
             else now() end,
        v_source_rel->>'sha256',
        coalesce(v_source_rel->'metadata', '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
          'system', v_source_rel->>'system',
          'rights_note', v_source_rel->>'rights_note'
        ))
      )
      on conflict (publisher, title, version) do update
      set source_url = excluded.source_url,
          license = excluded.license,
          retrieved_at = excluded.retrieved_at,
          sha256 = excluded.sha256,
          metadata = excluded.metadata
      returning id into v_rel_id;

      v_source_rel_idx := v_source_rel_idx + 1;
      if v_default_rel_id is null then
        v_default_rel_id := v_rel_id;
      end if;

      if v_source_rel ? 'id' then
        v_source_releases_map := v_source_releases_map || jsonb_build_object(v_source_rel->>'id', v_rel_id::text);
      end if;
      v_source_releases_map := v_source_releases_map || jsonb_build_object(
        coalesce(v_source_rel->>'publisher', '') || '/' || coalesce(v_source_rel->>'version', ''), v_rel_id::text
      );
      v_source_releases_map := v_source_releases_map || jsonb_build_object(
        (v_source_rel_idx - 1)::text, v_rel_id::text
      );

      -- Link root target_version to this source release
      insert into public.content_source_mappings (
        source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
      ) values (
        v_rel_id,
        'target_version',
        v_version_id,
        'official_blueprint',
        coalesce(payload->'target_version'->>'citation', 'Root Blueprint'),
        'Root target version mapping to authoritative source release',
        '{}'::jsonb
      )
      on conflict (source_release_id, entity_type, entity_id, relationship) do update
      set citation_location = excluded.citation_location,
          notes = excluded.notes,
          metadata = excluded.metadata
      returning id into v_mapping_id;

      v_mappings_count := v_mappings_count + 1;
      insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
      values (v_version_id, 'content_source_mapping', v_mapping_id)
      on conflict do nothing;

      -- Artifacts
      if jsonb_typeof(v_source_rel->'artifacts') = 'array' then
        for v_source_artifact in select * from jsonb_array_elements(v_source_rel->'artifacts')
        loop
          insert into public.content_source_artifacts (
            source_release_id, artifact_name, source_url, sha256, file_size_bytes, retrieved_at, metadata
          ) values (
            v_rel_id,
            coalesce(v_source_artifact->>'artifact_name', 'blueprint.pdf'),
            v_source_artifact->>'source_url',
            v_source_artifact->>'sha256',
            case when v_source_artifact->>'file_size_bytes' is not null
                 then (v_source_artifact->>'file_size_bytes')::bigint
                 else null end,
            case when v_source_artifact->>'retrieved_at' is not null
                 then (v_source_artifact->>'retrieved_at')::timestamptz
                 else now() end,
            coalesce(v_source_artifact->'metadata', '{}'::jsonb)
          )
          on conflict (source_release_id, artifact_name) do update
          set source_url = excluded.source_url,
              sha256 = excluded.sha256,
              file_size_bytes = excluded.file_size_bytes,
              retrieved_at = excluded.retrieved_at,
              metadata = excluded.metadata;
        end loop;
      end if;
    end loop;
  end if;

  -- 7. Ingest Shared Stimuli (root-level & objective-level)
  if jsonb_typeof(payload->'stimuli') = 'array' then
    for v_stim in select * from jsonb_array_elements(payload->'stimuli')
    loop
      v_stim_key := v_stim->>'stimulus_key';
      insert into public.assessment_stimuli (
        title, body, stimulus_type, metadata, origin_target_version_id
      ) values (
        coalesce(v_stim->>'title', 'Exhibit'),
        coalesce(v_stim->>'body', coalesce(v_stim->>'body_markdown', '')),
        coalesce(v_stim->>'stimulus_type', 'scenario'),
        jsonb_build_object(
          'media_url', v_stim->>'media_url',
          'credit', v_stim->>'credit',
          'attribution', v_stim->>'attribution'
        ),
        v_version_id
      )
      returning id into v_stim_id;

      v_stimuli_count := v_stimuli_count + 1;
      v_stimuli_map := v_stimuli_map || jsonb_build_object(v_stim_key, v_stim_id::text);

      insert into public.content_import_artifacts (target_version_id, entity_type, entity_id, manifest_key)
      values (v_version_id, 'assessment_stimulus', v_stim_id, v_stim_key);

      -- Stimulus Source Mapping
      if v_default_rel_id is not null then
        v_entity_rel_id := null;
        if v_stim ? 'source_release_id' and v_source_releases_map ? (v_stim->>'source_release_id') then
          v_entity_rel_id := (v_source_releases_map->>(v_stim->>'source_release_id'))::uuid;
        else
          v_entity_rel_id := v_default_rel_id;
        end if;

        if v_entity_rel_id is not null then
          insert into public.content_source_mappings (
            source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
          ) values (
            v_entity_rel_id,
            'assessment_stimulus',
            v_stim_id,
            'official_blueprint',
            coalesce(v_stim->>'citation', 'Official Blueprint Stimulus'),
            'Assessment stimulus mapping',
            '{}'::jsonb
          )
          on conflict (source_release_id, entity_type, entity_id, relationship) do update
          set citation_location = excluded.citation_location,
              notes = excluded.notes,
              metadata = excluded.metadata
          returning id into v_mapping_id;

          v_mappings_count := v_mappings_count + 1;
          insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
          values (v_version_id, 'content_source_mapping', v_mapping_id)
          on conflict do nothing;
        end if;
      end if;
    end loop;
  end if;

  -- 8. Ingest Standalone Target-level Flashcards
  if jsonb_typeof(payload->'flashcards') = 'array' then
    for v_fc in select * from jsonb_array_elements(payload->'flashcards')
    loop
      insert into public.flashcards (
        front, back, explanation, origin_target_version_id
      ) values (
        v_fc->>'front',
        v_fc->>'back',
        v_fc->>'explanation',
        v_version_id
      )
      returning id into v_fc_id;

      v_flashcards_count := v_flashcards_count + 1;
      insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
      values (v_version_id, 'flashcard', v_fc_id);

      -- Link concepts
      if jsonb_typeof(v_fc->'concept_ids') = 'array' then
        for v_concept_id in select (jsonb_array_elements_text(v_fc->'concept_ids'))::uuid
        loop
          insert into public.flashcard_concepts (flashcard_id, concept_id)
          values (v_fc_id, v_concept_id)
          on conflict do nothing;
        end loop;
      end if;
    end loop;
  end if;

  -- 9. Ingest Domains, Objectives, Lessons, Blocks, Assessment Items
  if jsonb_typeof(payload->'domains') = 'array' then
    for v_domain in select * from jsonb_array_elements(payload->'domains')
    loop
      insert into public.curriculum_nodes (
        target_version_id, node_type, code, title, description, sort_order, weight, metadata
      ) values (
        v_version_id,
        'domain',
        v_domain->>'code',
        coalesce(v_domain->>'title', 'Domain'),
        v_domain->>'description',
        coalesce((v_domain->>'sort_order')::int, 0),
        case when v_domain->>'weight_percentage' is not null
             then (v_domain->>'weight_percentage')::numeric
             when v_domain->>'weight' is not null
             then (v_domain->>'weight')::numeric
             else null end,
        coalesce(v_domain->'metadata', '{}'::jsonb)
      )
      returning id into v_domain_id;

      v_domains_count := v_domains_count + 1;
      insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
      values (v_version_id, 'curriculum_node', v_domain_id);

      -- Domain Source Mapping
      if v_default_rel_id is not null then
        v_entity_rel_id := null;
        if v_domain ? 'source_release_id' and v_source_releases_map ? (v_domain->>'source_release_id') then
          v_entity_rel_id := (v_source_releases_map->>(v_domain->>'source_release_id'))::uuid;
        else
          v_entity_rel_id := v_default_rel_id;
        end if;

        if v_entity_rel_id is not null then
          insert into public.content_source_mappings (
            source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
          ) values (
            v_entity_rel_id,
            'curriculum_node',
            v_domain_id,
            'official_blueprint',
            coalesce(v_domain->>'citation', 'Domain ' || coalesce(v_domain->>'code', '')),
            'Curriculum domain node citation',
            '{}'::jsonb
          )
          on conflict (source_release_id, entity_type, entity_id, relationship) do update
          set citation_location = excluded.citation_location,
              notes = excluded.notes,
              metadata = excluded.metadata
          returning id into v_mapping_id;

          v_mappings_count := v_mappings_count + 1;
          insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
          values (v_version_id, 'content_source_mapping', v_mapping_id)
          on conflict do nothing;
        end if;
      end if;

      -- Objectives
      if jsonb_typeof(v_domain->'objectives') = 'array' then
        for v_obj in select * from jsonb_array_elements(v_domain->'objectives')
        loop
          insert into public.curriculum_nodes (
            target_version_id, parent_id, node_type, code, title, description, sort_order, metadata
          ) values (
            v_version_id,
            v_domain_id,
            'objective',
            v_obj->>'code',
            coalesce(v_obj->>'title', 'Objective'),
            v_obj->>'description',
            coalesce((v_obj->>'sort_order')::int, 0),
            jsonb_build_object('bloom_level', coalesce(v_obj->>'bloom_level', 'understand'))
          )
          returning id into v_obj_id;

          v_objectives_count := v_objectives_count + 1;
          insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
          values (v_version_id, 'curriculum_node', v_obj_id);

          -- Objective Source Mapping
          if v_default_rel_id is not null then
            v_entity_rel_id := null;
            if v_obj ? 'source_release_id' and v_source_releases_map ? (v_obj->>'source_release_id') then
              v_entity_rel_id := (v_source_releases_map->>(v_obj->>'source_release_id'))::uuid;
            else
              v_entity_rel_id := coalesce((v_source_releases_map->>(v_domain->>'source_release_id'))::uuid, v_default_rel_id);
            end if;

            if v_entity_rel_id is not null then
              insert into public.content_source_mappings (
                source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
              ) values (
                v_entity_rel_id,
                'curriculum_node',
                v_obj_id,
                'official_blueprint',
                coalesce(v_obj->>'citation', 'Objective ' || coalesce(v_obj->>'code', '')),
                'Curriculum objective node citation',
                '{}'::jsonb
              )
              on conflict (source_release_id, entity_type, entity_id, relationship) do update
              set citation_location = excluded.citation_location,
                  notes = excluded.notes,
                  metadata = excluded.metadata
              returning id into v_mapping_id;

              v_mappings_count := v_mappings_count + 1;
              insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
              values (v_version_id, 'content_source_mapping', v_mapping_id)
              on conflict do nothing;
            end if;
          end if;

          -- Link objective concepts
          if jsonb_typeof(v_obj->'concept_ids') = 'array' then
            for v_concept_id in select (jsonb_array_elements_text(v_obj->'concept_ids'))::uuid
            loop
              insert into public.curriculum_node_concepts (curriculum_node_id, concept_id)
              values (v_obj_id, v_concept_id)
              on conflict do nothing;
            end loop;
          end if;

          -- Objective Flashcards
          if jsonb_typeof(v_obj->'flashcards') = 'array' then
            for v_fc in select * from jsonb_array_elements(v_obj->'flashcards')
            loop
              insert into public.flashcards (
                front, back, explanation, origin_target_version_id
              ) values (
                v_fc->>'front',
                v_fc->>'back',
                v_fc->>'explanation',
                v_version_id
              )
              returning id into v_fc_id;

              v_flashcards_count := v_flashcards_count + 1;
              insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
              values (v_version_id, 'flashcard', v_fc_id);

              if jsonb_typeof(v_fc->'concept_ids') = 'array' then
                for v_concept_id in select (jsonb_array_elements_text(v_fc->'concept_ids'))::uuid
                loop
                  insert into public.flashcard_concepts (flashcard_id, concept_id)
                  values (v_fc_id, v_concept_id)
                  on conflict do nothing;
                end loop;
              end if;
            end loop;
          end if;

          -- Objective Assessment Items
          if jsonb_typeof(v_obj->'assessment_items') = 'array' then
            for v_item in select * from jsonb_array_elements(v_obj->'assessment_items')
            loop
              v_stim_key := v_item->>'stimulus_key';
              v_stim_id := null;
              if v_stim_key is not null and v_stimuli_map ? v_stim_key then
                v_stim_id := (v_stimuli_map->>v_stim_key)::uuid;
              end if;

              insert into public.assessment_items (
                stimulus_id, prompt, interaction_type, response_spec, scoring_spec, explanation, origin_target_version_id
              ) values (
                v_stim_id,
                v_item->>'prompt',
                coalesce(v_item->>'interaction_type', 'single_choice'),
                coalesce(v_item->'response_spec', '{}'::jsonb),
                coalesce(v_item->'scoring_spec', '{}'::jsonb),
                v_item->>'explanation',
                v_version_id
              )
              returning id into v_item_id;

              v_items_count := v_items_count + 1;
              insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
              values (v_version_id, 'assessment_item', v_item_id);

              if jsonb_typeof(v_item->'concept_ids') = 'array' then
                for v_concept_id in select (jsonb_array_elements_text(v_item->'concept_ids'))::uuid
                loop
                  insert into public.assessment_item_concepts (assessment_item_id, concept_id)
                  values (v_item_id, v_concept_id)
                  on conflict do nothing;
                end loop;
              end if;
            end loop;
          end if;

          -- Lessons
          if jsonb_typeof(v_obj->'lessons') = 'array' then
            for v_lesson in select * from jsonb_array_elements(v_obj->'lessons')
            loop
              insert into public.lessons (
                title, description, visibility, origin_target_version_id
              ) values (
                v_lesson->>'title',
                coalesce(v_lesson->>'description', v_lesson->>'summary'),
                'public',
                v_version_id
              )
              returning id into v_lesson_id;

              v_lessons_count := v_lessons_count + 1;
              insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
              values (v_version_id, 'lesson', v_lesson_id);

              -- Lesson Source Mapping
              if v_default_rel_id is not null then
                v_entity_rel_id := null;
                if v_lesson ? 'source_release_id' and v_source_releases_map ? (v_lesson->>'source_release_id') then
                  v_entity_rel_id := (v_source_releases_map->>(v_lesson->>'source_release_id'))::uuid;
                else
                  v_entity_rel_id := coalesce(
                    (v_source_releases_map->>(v_obj->>'source_release_id'))::uuid,
                    coalesce((v_source_releases_map->>(v_domain->>'source_release_id'))::uuid, v_default_rel_id)
                  );
                end if;

                if v_entity_rel_id is not null then
                  insert into public.content_source_mappings (
                    source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
                  ) values (
                    v_entity_rel_id,
                    'lesson',
                    v_lesson_id,
                    'derived_from',
                    coalesce(v_lesson->>'citation', coalesce(v_lesson->>'title', 'Lesson')),
                    'Lesson derived from authoritative source',
                    '{}'::jsonb
                  )
                  on conflict (source_release_id, entity_type, entity_id, relationship) do update
                  set citation_location = excluded.citation_location,
                      notes = excluded.notes,
                      metadata = excluded.metadata
                  returning id into v_mapping_id;

                  v_mappings_count := v_mappings_count + 1;
                  insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
                  values (v_version_id, 'content_source_mapping', v_mapping_id)
                  on conflict do nothing;
                end if;
              end if;

              -- Bind lesson to objective
              insert into public.curriculum_node_lessons (curriculum_node_id, lesson_id, sort_order)
              values (v_obj_id, v_lesson_id, coalesce((v_lesson->>'order_index')::int, 0))
              on conflict do nothing;

              -- Scoped lesson concept linking (NO global leakage!)
              if jsonb_typeof(v_lesson->'concept_ids') = 'array' then
                for v_concept_id in select (jsonb_array_elements_text(v_lesson->'concept_ids'))::uuid
                loop
                  insert into public.lesson_concepts (lesson_id, concept_id)
                  values (v_lesson_id, v_concept_id)
                  on conflict do nothing;
                end loop;
              end if;

              -- Lesson Blocks
              if jsonb_typeof(v_lesson->'blocks') = 'array' then
                for v_block in select * from jsonb_array_elements(v_lesson->'blocks')
                loop
                  insert into public.lesson_blocks (
                    lesson_id, block_type, content, sort_order
                  ) values (
                    v_lesson_id,
                    coalesce(v_block->>'block_type', 'markdown'),
                    coalesce(v_block->'content', '{}'::jsonb),
                    coalesce((v_block->>'sort_order')::int, 0)
                  );
                  v_blocks_count := v_blocks_count + 1;
                end loop;
              end if;

              -- Lesson Terms
              if jsonb_typeof(v_lesson->'terms') = 'array' then
                for v_term in select * from jsonb_array_elements(v_lesson->'terms')
                loop
                  insert into public.terms (lesson_id, term, definition)
                  values (v_lesson_id, v_term->>'term', v_term->>'definition');
                end loop;
              end if;

              -- Lesson Questions
              if jsonb_typeof(v_lesson->'questions') = 'array' then
                for v_question in select * from jsonb_array_elements(v_lesson->'questions')
                loop
                  insert into public.questions (
                    lesson_id, question_text, options, correct_answer, type, explanation
                  ) values (
                    v_lesson_id,
                    coalesce(v_question->>'question_text', v_question->>'question'),
                    coalesce(v_question->'options', '[]'::jsonb),
                    coalesce((coalesce(v_question->>'correct_answer', v_question->>'correct_index'))::int, 0),
                    coalesce(v_question->>'type', 'mcq'),
                    v_question->>'explanation'
                  );
                  v_questions_count := v_questions_count + 1;
                end loop;
              end if;

              -- Lesson Assessment Items
              if jsonb_typeof(v_lesson->'assessment_items') = 'array' then
                for v_item in select * from jsonb_array_elements(v_lesson->'assessment_items')
                loop
                  v_stim_key := v_item->>'stimulus_key';
                  v_stim_id := null;
                  if v_stim_key is not null and v_stimuli_map ? v_stim_key then
                    v_stim_id := (v_stimuli_map->>v_stim_key)::uuid;
                  end if;

                  insert into public.assessment_items (
                    lesson_id, stimulus_id, prompt, interaction_type, response_spec, scoring_spec, explanation, origin_target_version_id
                  ) values (
                    v_lesson_id,
                    v_stim_id,
                    v_item->>'prompt',
                    coalesce(v_item->>'interaction_type', 'single_choice'),
                    coalesce(v_item->'response_spec', '{}'::jsonb),
                    coalesce(v_item->'scoring_spec', '{}'::jsonb),
                    v_item->>'explanation',
                    v_version_id
                  )
                  returning id into v_item_id;

                  v_items_count := v_items_count + 1;
                  insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
                  values (v_version_id, 'assessment_item', v_item_id);

                  if jsonb_typeof(v_item->'concept_ids') = 'array' then
                    for v_concept_id in select (jsonb_array_elements_text(v_item->'concept_ids'))::uuid
                    loop
                      insert into public.assessment_item_concepts (assessment_item_id, concept_id)
                      values (v_item_id, v_concept_id)
                      on conflict do nothing;
                    end loop;
                  end if;
                end loop;
              end if;

            end loop;
          end if; -- lessons

        end loop;
      end if; -- objectives

    end loop;
  end if; -- domains

  -- 10. Ingest Source Mappings
  if jsonb_typeof(payload->'source_mappings') = 'array' then
    for v_source_mapping in select * from jsonb_array_elements(payload->'source_mappings')
    loop
      insert into public.content_source_mappings (
        source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
      ) values (
        (v_source_mapping->>'source_release_id')::uuid,
        v_source_mapping->>'entity_type',
        (v_source_mapping->>'entity_id')::uuid,
        coalesce(v_source_mapping->>'relationship', 'derived_from'),
        coalesce(v_source_mapping->>'citation_location', v_source_mapping->>'section_reference'),
        coalesce(v_source_mapping->>'notes', v_source_mapping->>'citation_text'),
        coalesce(v_source_mapping->'metadata', '{}'::jsonb)
      )
      on conflict (source_release_id, entity_type, entity_id, relationship) do update
      set citation_location = excluded.citation_location,
          notes = excluded.notes,
          metadata = excluded.metadata
      returning id into v_mapping_id;

      v_mappings_count := v_mappings_count + 1;
      insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
      values (v_version_id, 'content_source_mapping', v_mapping_id)
      on conflict do nothing;
    end loop;
  end if;

  -- 11. Ingest Concept Version Mappings
  if jsonb_typeof(payload->'target_version_concept_mappings') = 'array' then
    for v_mapping in select * from jsonb_array_elements(payload->'target_version_concept_mappings')
    loop
      v_from_concept_id := (v_mapping->>'from_concept_id')::uuid;
      v_to_concept_id := case when v_mapping->>'to_concept_id' is not null
                              then (v_mapping->>'to_concept_id')::uuid
                              else null end;

      insert into public.target_version_concept_mappings (
        from_target_version_id, from_concept_id, to_target_version_id, to_concept_id,
        mapping_type, confidence, rationale
      ) values (
        v_version_id,
        v_from_concept_id,
        case when v_mapping->>'to_target_version_id' is not null
             then (v_mapping->>'to_target_version_id')::uuid
             else null end,
        v_to_concept_id,
        coalesce(v_mapping->>'mapping_type', 'exact_match'),
        coalesce((v_mapping->>'confidence')::numeric, 1.0),
        v_mapping->>'rationale'
      )
      on conflict do nothing;
    end loop;
  end if;

  return jsonb_build_object(
    'success', true,
    'target_id', v_target_id,
    'target_slug', v_target_slug,
    'target_version_id', v_version_id,
    'version_code', v_version_code,
    'stimuli_count', v_stimuli_count,
    'domains_count', v_domains_count,
    'objectives_count', v_objectives_count,
    'lessons_count', v_lessons_count,
    'blocks_count', v_blocks_count,
    'assessment_items_count', v_items_count,
    'flashcards_count', v_flashcards_count,
    'questions_count', v_questions_count,
    'mappings_count', v_mappings_count
  );
end;
$$;

revoke all on function public.ingest_curriculum_manifest(jsonb) from public, anon, authenticated;
grant execute on function public.ingest_curriculum_manifest(jsonb) to service_role;

INSERT INTO supabase_migrations.schema_migrations (version, name) VALUES ('20261006000001', 'rpc_provenance_and_clean_fix') ON CONFLICT (version) DO NOTHING;

-- --------------------------------------------------------------------
-- [26/96] Migration: 20261006000002_update_ingest_curriculum_manifest.sql
-- --------------------------------------------------------------------
-- ============================================================================
-- Migration: 20261006000002_update_ingest_curriculum_manifest.sql
-- Description: Ensure clean_draft_target_version and ingest_curriculum_manifest
--              include orphan mapping cleanup and automatic provenance citations.
-- ============================================================================

-- 1. Updated clean_draft_target_version
create or replace function public.clean_draft_target_version(
  p_version_id uuid
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_status text;
  v_target_owner uuid;
begin
  select tv.status, lt.created_by
  into v_status, v_target_owner
  from public.target_versions tv
  join public.learning_targets lt on lt.id = tv.target_id
  where tv.id = p_version_id;

  if v_status is null then
    raise exception 'TargetVersion % not found', p_version_id;
  end if;

  if v_status <> 'draft' then
    raise exception 'Cannot clean TargetVersion with status "%". Only draft versions may be reset.', v_status;
  end if;

  -- Authorization check: service_role or target owner only
  if coalesce(current_setting('request.jwt.claim.role', true), '') <> 'service_role'
     and auth.role() <> 'service_role'
     and (v_target_owner is null or v_target_owner <> auth.uid()) then
    raise exception 'Unauthorized: only service_role or the target owner can clean a draft target version';
  end if;

  -- 1. Delete content_source_mappings explicitly tracked as artifacts of this draft
  delete from public.content_source_mappings
  where id in (
    select entity_id
    from public.content_import_artifacts
    where target_version_id = p_version_id
      and entity_type = 'content_source_mapping'
  )
  or (entity_type = 'target_version' and entity_id = p_version_id);

  -- Clean any orphaned content_source_mappings whose referenced entity no longer exists
  delete from public.content_source_mappings
  where (entity_type = 'lesson' and not exists (select 1 from public.lessons where id = entity_id))
     or (entity_type = 'curriculum_node' and not exists (select 1 from public.curriculum_nodes where id = entity_id))
     or (entity_type = 'assessment_stimulus' and not exists (select 1 from public.assessment_stimuli where id = entity_id))
     or (entity_type = 'assessment_item' and not exists (select 1 from public.assessment_items where id = entity_id))
     or (entity_type = 'flashcard' and not exists (select 1 from public.flashcards where id = entity_id));

  -- 2. Delete assessment_items created specifically for this draft version
  delete from public.assessment_items
  where origin_target_version_id = p_version_id
     or id in (
       select entity_id
       from public.content_import_artifacts
       where target_version_id = p_version_id
         and entity_type = 'assessment_item'
     );

  -- 3. Delete assessment_stimuli created specifically for this draft version
  delete from public.assessment_stimuli
  where origin_target_version_id = p_version_id
     or id in (
       select entity_id
       from public.content_import_artifacts
       where target_version_id = p_version_id
         and entity_type = 'assessment_stimulus'
     );

  -- 4. Delete flashcards created specifically for this draft version
  delete from public.flashcards
  where origin_target_version_id = p_version_id
     or id in (
       select entity_id
       from public.content_import_artifacts
       where target_version_id = p_version_id
         and entity_type = 'flashcard'
     );

  -- 5. Delete official lessons created specifically for this draft version
  delete from public.lessons
  where origin_target_version_id = p_version_id
     or id in (
       select entity_id
       from public.content_import_artifacts
       where target_version_id = p_version_id
         and entity_type = 'lesson'
     )
     or (
       user_id is null
       and origin_target_version_id is null
       and id in (
         select cnl.lesson_id
         from public.curriculum_node_lessons cnl
         join public.curriculum_nodes cn on cn.id = cnl.curriculum_node_id
         where cn.target_version_id = p_version_id
           and not exists (
             select 1
             from public.curriculum_node_lessons o_cnl
             join public.curriculum_nodes o_cn on o_cn.id = o_cnl.curriculum_node_id
             where o_cnl.lesson_id = cnl.lesson_id
               and o_cn.target_version_id <> p_version_id
           )
       )
     );

  -- 6. Delete curriculum nodes of this draft
  delete from public.curriculum_nodes
  where target_version_id = p_version_id;

  -- 7. Delete concept mappings involving this draft version
  delete from public.target_version_concept_mappings
  where from_target_version_id = p_version_id
     or to_target_version_id = p_version_id;

  -- 8. Clean all artifact tracking records for this draft version
  delete from public.content_import_artifacts
  where target_version_id = p_version_id;

end;
$$;

revoke all on function public.clean_draft_target_version(uuid) from public, anon;
grant execute on function public.clean_draft_target_version(uuid) to authenticated, service_role;

-- 2. Updated ingest_curriculum_manifest
create or replace function public.ingest_curriculum_manifest(
  payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_field_id uuid;
  v_field_slug text;
  v_target_id uuid;
  v_target_slug text;
  v_version_id uuid;
  v_version_code text;
  v_version_status text;

  -- Counters
  v_stimuli_count int := 0;
  v_domains_count int := 0;
  v_objectives_count int := 0;
  v_lessons_count int := 0;
  v_blocks_count int := 0;
  v_items_count int := 0;
  v_flashcards_count int := 0;
  v_questions_count int := 0;
  v_mappings_count int := 0;

  -- Iterators
  v_source_rel jsonb;
  v_source_artifact jsonb;
  v_rel_id uuid;
  v_stim jsonb;
  v_stim_id uuid;
  v_stim_key text;
  v_domain jsonb;
  v_domain_id uuid;
  v_obj jsonb;
  v_obj_id uuid;
  v_concept_id uuid;
  v_lesson jsonb;
  v_lesson_id uuid;
  v_block jsonb;
  v_term jsonb;
  v_question jsonb;
  v_item jsonb;
  v_item_id uuid;
  v_fc jsonb;
  v_fc_id uuid;
  v_mapping jsonb;
  v_from_concept_id uuid;
  v_to_concept_id uuid;
  v_source_mapping jsonb;
  v_mapping_id uuid;
  v_source_releases_map jsonb := '{}'::jsonb;
  v_default_rel_id uuid := null;
  v_source_rel_idx int := 0;
  v_entity_rel_id uuid;

  -- Key Maps
  v_stimuli_map jsonb := '{}'::jsonb;
begin
  -- 1. Security Check: Service role only
  if coalesce(current_setting('request.jwt.claim.role', true), '') <> 'service_role'
     and auth.role() <> 'service_role' then
    raise exception 'Unauthorized: ingest_curriculum_manifest requires service_role privilege';
  end if;

  -- 2. Extract Field
  v_field_slug := payload->'field'->>'slug';
  if v_field_slug is not null and v_field_slug <> '' then
    select id into v_field_id from public.fields where slug = v_field_slug;
    if v_field_id is null then
      insert into public.fields (slug, name, description, field_kind)
      values (
        v_field_slug,
        coalesce(payload->'field'->>'name', v_field_slug),
        payload->'field'->>'description',
        'native_field'
      )
      returning id into v_field_id;
    end if;
  end if;

  -- 3. Extract LearningTarget
  v_target_slug := payload->'target'->>'slug';
  if v_target_slug is null or v_target_slug = '' then
    raise exception 'Missing target.slug in manifest payload';
  end if;

  select id into v_target_id from public.learning_targets where slug = v_target_slug;
  if v_target_id is null then
    insert into public.learning_targets (
      slug, title, target_type, description, field_id, status, is_public
    ) values (
      v_target_slug,
      coalesce(payload->'target'->>'title', v_target_slug),
      coalesce(payload->'target'->>'target_type', coalesce(payload->'target'->>'target_kind', 'certification')),
      payload->'target'->>'description',
      v_field_id,
      'published',
      true
    )
    returning id into v_target_id;
  end if;

  -- 4. Extract TargetVersion
  v_version_code := payload->'target_version'->>'version_code';
  if v_version_code is null or v_version_code = '' then
    raise exception 'Missing target_version.version_code in manifest payload';
  end if;

  select id, status into v_version_id, v_version_status
  from public.target_versions
  where target_id = v_target_id and version_code = v_version_code;

  if v_version_id is null then
    insert into public.target_versions (
      target_id, version_code, title, description, valid_from, status, metadata
    ) values (
      v_target_id,
      v_version_code,
      payload->'target_version'->>'title',
      payload->'target_version'->>'description',
      case when payload->'target_version'->>'valid_from' is not null
           then (payload->'target_version'->>'valid_from')::date
           else null end,
      'draft',
      coalesce(payload->'target_version'->'metadata', '{}'::jsonb)
    )
    returning id, status into v_version_id, v_version_status;
  end if;

  if v_version_status <> 'draft' then
    raise exception 'Cannot ingest into TargetVersion "%" with status "%". Only draft versions may be replaced.', v_version_code, v_version_status;
  end if;

  -- 5. Atomically Clean Previous Draft Content for this TargetVersion
  perform public.clean_draft_target_version(v_version_id);

  -- 6. Ingest Source Releases & Artifacts
  if jsonb_typeof(payload->'source_releases') = 'array' then
    for v_source_rel in select * from jsonb_array_elements(payload->'source_releases')
    loop
      insert into public.content_source_releases (
        publisher, title, version, source_url, license, retrieved_at, sha256, metadata
      ) values (
        coalesce(v_source_rel->>'publisher', 'Authoritative Source'),
        coalesce(v_source_rel->>'title', 'Official Blueprint'),
        coalesce(v_source_rel->>'version', 'v1'),
        v_source_rel->>'source_url',
        coalesce(v_source_rel->>'license', v_source_rel->>'license_name'),
        case when v_source_rel->>'retrieved_at' is not null
             then (v_source_rel->>'retrieved_at')::timestamptz
             else now() end,
        v_source_rel->>'sha256',
        coalesce(v_source_rel->'metadata', '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
          'system', v_source_rel->>'system',
          'rights_note', v_source_rel->>'rights_note'
        ))
      )
      on conflict (publisher, title, version) do update
      set source_url = excluded.source_url,
          license = excluded.license,
          retrieved_at = excluded.retrieved_at,
          sha256 = excluded.sha256,
          metadata = excluded.metadata
      returning id into v_rel_id;

      v_source_rel_idx := v_source_rel_idx + 1;
      if v_default_rel_id is null then
        v_default_rel_id := v_rel_id;
      end if;

      if v_source_rel ? 'id' then
        v_source_releases_map := v_source_releases_map || jsonb_build_object(v_source_rel->>'id', v_rel_id::text);
      end if;
      v_source_releases_map := v_source_releases_map || jsonb_build_object(
        coalesce(v_source_rel->>'publisher', '') || '/' || coalesce(v_source_rel->>'version', ''), v_rel_id::text
      );
      v_source_releases_map := v_source_releases_map || jsonb_build_object(
        (v_source_rel_idx - 1)::text, v_rel_id::text
      );

      -- Link root target_version to this source release
      insert into public.content_source_mappings (
        source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
      ) values (
        v_rel_id,
        'target_version',
        v_version_id,
        'official_blueprint',
        coalesce(payload->'target_version'->>'citation', 'Root Blueprint'),
        'Root target version mapping to authoritative source release',
        '{}'::jsonb
      )
      on conflict (source_release_id, entity_type, entity_id, relationship) do update
      set citation_location = excluded.citation_location,
          notes = excluded.notes,
          metadata = excluded.metadata
      returning id into v_mapping_id;

      v_mappings_count := v_mappings_count + 1;
      insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
      values (v_version_id, 'content_source_mapping', v_mapping_id)
      on conflict do nothing;

      -- Artifacts
      if jsonb_typeof(v_source_rel->'artifacts') = 'array' then
        for v_source_artifact in select * from jsonb_array_elements(v_source_rel->'artifacts')
        loop
          insert into public.content_source_artifacts (
            source_release_id, artifact_name, source_url, sha256, file_size_bytes, retrieved_at, metadata
          ) values (
            v_rel_id,
            coalesce(v_source_artifact->>'artifact_name', 'blueprint.pdf'),
            v_source_artifact->>'source_url',
            v_source_artifact->>'sha256',
            case when v_source_artifact->>'file_size_bytes' is not null
                 then (v_source_artifact->>'file_size_bytes')::bigint
                 else null end,
            case when v_source_artifact->>'retrieved_at' is not null
                 then (v_source_artifact->>'retrieved_at')::timestamptz
                 else now() end,
            coalesce(v_source_artifact->'metadata', '{}'::jsonb)
          )
          on conflict (source_release_id, artifact_name) do update
          set source_url = excluded.source_url,
              sha256 = excluded.sha256,
              file_size_bytes = excluded.file_size_bytes,
              retrieved_at = excluded.retrieved_at,
              metadata = excluded.metadata;
        end loop;
      end if;
    end loop;
  end if;

  -- 7. Ingest Shared Stimuli (root-level & objective-level)
  if jsonb_typeof(payload->'stimuli') = 'array' then
    for v_stim in select * from jsonb_array_elements(payload->'stimuli')
    loop
      v_stim_key := v_stim->>'stimulus_key';
      insert into public.assessment_stimuli (
        title, body, stimulus_type, metadata, origin_target_version_id
      ) values (
        coalesce(v_stim->>'title', 'Exhibit'),
        coalesce(v_stim->>'body', coalesce(v_stim->>'body_markdown', '')),
        coalesce(v_stim->>'stimulus_type', 'scenario'),
        jsonb_build_object(
          'media_url', v_stim->>'media_url',
          'credit', v_stim->>'credit',
          'attribution', v_stim->>'attribution'
        ),
        v_version_id
      )
      returning id into v_stim_id;

      v_stimuli_count := v_stimuli_count + 1;
      v_stimuli_map := v_stimuli_map || jsonb_build_object(v_stim_key, v_stim_id::text);

      insert into public.content_import_artifacts (target_version_id, entity_type, entity_id, manifest_key)
      values (v_version_id, 'assessment_stimulus', v_stim_id, v_stim_key);

      -- Stimulus Source Mapping
      if v_default_rel_id is not null then
        v_entity_rel_id := null;
        if v_stim ? 'source_release_id' and v_source_releases_map ? (v_stim->>'source_release_id') then
          v_entity_rel_id := (v_source_releases_map->>(v_stim->>'source_release_id'))::uuid;
        else
          v_entity_rel_id := v_default_rel_id;
        end if;

        if v_entity_rel_id is not null then
          insert into public.content_source_mappings (
            source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
          ) values (
            v_entity_rel_id,
            'assessment_stimulus',
            v_stim_id,
            'official_blueprint',
            coalesce(v_stim->>'citation', 'Official Blueprint Stimulus'),
            'Assessment stimulus mapping',
            '{}'::jsonb
          )
          on conflict (source_release_id, entity_type, entity_id, relationship) do update
          set citation_location = excluded.citation_location,
              notes = excluded.notes,
              metadata = excluded.metadata
          returning id into v_mapping_id;

          v_mappings_count := v_mappings_count + 1;
          insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
          values (v_version_id, 'content_source_mapping', v_mapping_id)
          on conflict do nothing;
        end if;
      end if;
    end loop;
  end if;

  -- 8. Ingest Standalone Target-level Flashcards
  if jsonb_typeof(payload->'flashcards') = 'array' then
    for v_fc in select * from jsonb_array_elements(payload->'flashcards')
    loop
      insert into public.flashcards (
        front, back, explanation, origin_target_version_id
      ) values (
        v_fc->>'front',
        v_fc->>'back',
        v_fc->>'explanation',
        v_version_id
      )
      returning id into v_fc_id;

      v_flashcards_count := v_flashcards_count + 1;
      insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
      values (v_version_id, 'flashcard', v_fc_id);

      -- Link concepts
      if jsonb_typeof(v_fc->'concept_ids') = 'array' then
        for v_concept_id in select (jsonb_array_elements_text(v_fc->'concept_ids'))::uuid
        loop
          insert into public.flashcard_concepts (flashcard_id, concept_id)
          values (v_fc_id, v_concept_id)
          on conflict do nothing;
        end loop;
      end if;
    end loop;
  end if;

  -- 9. Ingest Domains, Objectives, Lessons, Blocks, Assessment Items
  if jsonb_typeof(payload->'domains') = 'array' then
    for v_domain in select * from jsonb_array_elements(payload->'domains')
    loop
      insert into public.curriculum_nodes (
        target_version_id, node_type, code, title, description, sort_order, weight, metadata
      ) values (
        v_version_id,
        'domain',
        v_domain->>'code',
        coalesce(v_domain->>'title', 'Domain'),
        v_domain->>'description',
        coalesce((v_domain->>'sort_order')::int, 0),
        case when v_domain->>'weight_percentage' is not null
             then (v_domain->>'weight_percentage')::numeric
             when v_domain->>'weight' is not null
             then (v_domain->>'weight')::numeric
             else null end,
        coalesce(v_domain->'metadata', '{}'::jsonb)
      )
      returning id into v_domain_id;

      v_domains_count := v_domains_count + 1;
      insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
      values (v_version_id, 'curriculum_node', v_domain_id);

      -- Domain Source Mapping
      if v_default_rel_id is not null then
        v_entity_rel_id := null;
        if v_domain ? 'source_release_id' and v_source_releases_map ? (v_domain->>'source_release_id') then
          v_entity_rel_id := (v_source_releases_map->>(v_domain->>'source_release_id'))::uuid;
        else
          v_entity_rel_id := v_default_rel_id;
        end if;

        if v_entity_rel_id is not null then
          insert into public.content_source_mappings (
            source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
          ) values (
            v_entity_rel_id,
            'curriculum_node',
            v_domain_id,
            'official_blueprint',
            coalesce(v_domain->>'citation', 'Domain ' || coalesce(v_domain->>'code', '')),
            'Curriculum domain node citation',
            '{}'::jsonb
          )
          on conflict (source_release_id, entity_type, entity_id, relationship) do update
          set citation_location = excluded.citation_location,
              notes = excluded.notes,
              metadata = excluded.metadata
          returning id into v_mapping_id;

          v_mappings_count := v_mappings_count + 1;
          insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
          values (v_version_id, 'content_source_mapping', v_mapping_id)
          on conflict do nothing;
        end if;
      end if;

      -- Objectives
      if jsonb_typeof(v_domain->'objectives') = 'array' then
        for v_obj in select * from jsonb_array_elements(v_domain->'objectives')
        loop
          insert into public.curriculum_nodes (
            target_version_id, parent_id, node_type, code, title, description, sort_order, metadata
          ) values (
            v_version_id,
            v_domain_id,
            'objective',
            v_obj->>'code',
            coalesce(v_obj->>'title', 'Objective'),
            v_obj->>'description',
            coalesce((v_obj->>'sort_order')::int, 0),
            jsonb_build_object('bloom_level', coalesce(v_obj->>'bloom_level', 'understand'))
          )
          returning id into v_obj_id;

          v_objectives_count := v_objectives_count + 1;
          insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
          values (v_version_id, 'curriculum_node', v_obj_id);

          -- Objective Source Mapping
          if v_default_rel_id is not null then
            v_entity_rel_id := null;
            if v_obj ? 'source_release_id' and v_source_releases_map ? (v_obj->>'source_release_id') then
              v_entity_rel_id := (v_source_releases_map->>(v_obj->>'source_release_id'))::uuid;
            else
              v_entity_rel_id := coalesce((v_source_releases_map->>(v_domain->>'source_release_id'))::uuid, v_default_rel_id);
            end if;

            if v_entity_rel_id is not null then
              insert into public.content_source_mappings (
                source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
              ) values (
                v_entity_rel_id,
                'curriculum_node',
                v_obj_id,
                'official_blueprint',
                coalesce(v_obj->>'citation', 'Objective ' || coalesce(v_obj->>'code', '')),
                'Curriculum objective node citation',
                '{}'::jsonb
              )
              on conflict (source_release_id, entity_type, entity_id, relationship) do update
              set citation_location = excluded.citation_location,
                  notes = excluded.notes,
                  metadata = excluded.metadata
              returning id into v_mapping_id;

              v_mappings_count := v_mappings_count + 1;
              insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
              values (v_version_id, 'content_source_mapping', v_mapping_id)
              on conflict do nothing;
            end if;
          end if;

          -- Link objective concepts
          if jsonb_typeof(v_obj->'concept_ids') = 'array' then
            for v_concept_id in select (jsonb_array_elements_text(v_obj->'concept_ids'))::uuid
            loop
              insert into public.curriculum_node_concepts (curriculum_node_id, concept_id)
              values (v_obj_id, v_concept_id)
              on conflict do nothing;
            end loop;
          end if;

          -- Objective Flashcards
          if jsonb_typeof(v_obj->'flashcards') = 'array' then
            for v_fc in select * from jsonb_array_elements(v_obj->'flashcards')
            loop
              insert into public.flashcards (
                front, back, explanation, origin_target_version_id
              ) values (
                v_fc->>'front',
                v_fc->>'back',
                v_fc->>'explanation',
                v_version_id
              )
              returning id into v_fc_id;

              v_flashcards_count := v_flashcards_count + 1;
              insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
              values (v_version_id, 'flashcard', v_fc_id);

              if jsonb_typeof(v_fc->'concept_ids') = 'array' then
                for v_concept_id in select (jsonb_array_elements_text(v_fc->'concept_ids'))::uuid
                loop
                  insert into public.flashcard_concepts (flashcard_id, concept_id)
                  values (v_fc_id, v_concept_id)
                  on conflict do nothing;
                end loop;
              end if;
            end loop;
          end if;

          -- Objective Assessment Items
          if jsonb_typeof(v_obj->'assessment_items') = 'array' then
            for v_item in select * from jsonb_array_elements(v_obj->'assessment_items')
            loop
              v_stim_key := v_item->>'stimulus_key';
              v_stim_id := null;
              if v_stim_key is not null and v_stimuli_map ? v_stim_key then
                v_stim_id := (v_stimuli_map->>v_stim_key)::uuid;
              end if;

              insert into public.assessment_items (
                stimulus_id, prompt, interaction_type, response_spec, scoring_spec, explanation, origin_target_version_id
              ) values (
                v_stim_id,
                v_item->>'prompt',
                coalesce(v_item->>'interaction_type', 'single_choice'),
                coalesce(v_item->'response_spec', '{}'::jsonb),
                coalesce(v_item->'scoring_spec', '{}'::jsonb),
                v_item->>'explanation',
                v_version_id
              )
              returning id into v_item_id;

              v_items_count := v_items_count + 1;
              insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
              values (v_version_id, 'assessment_item', v_item_id);

              if jsonb_typeof(v_item->'concept_ids') = 'array' then
                for v_concept_id in select (jsonb_array_elements_text(v_item->'concept_ids'))::uuid
                loop
                  insert into public.assessment_item_concepts (assessment_item_id, concept_id)
                  values (v_item_id, v_concept_id)
                  on conflict do nothing;
                end loop;
              end if;
            end loop;
          end if;

          -- Lessons
          if jsonb_typeof(v_obj->'lessons') = 'array' then
            for v_lesson in select * from jsonb_array_elements(v_obj->'lessons')
            loop
              insert into public.lessons (
                title, description, visibility, origin_target_version_id
              ) values (
                v_lesson->>'title',
                coalesce(v_lesson->>'description', v_lesson->>'summary'),
                'public',
                v_version_id
              )
              returning id into v_lesson_id;

              v_lessons_count := v_lessons_count + 1;
              insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
              values (v_version_id, 'lesson', v_lesson_id);

              -- Lesson Source Mapping
              if v_default_rel_id is not null then
                v_entity_rel_id := null;
                if v_lesson ? 'source_release_id' and v_source_releases_map ? (v_lesson->>'source_release_id') then
                  v_entity_rel_id := (v_source_releases_map->>(v_lesson->>'source_release_id'))::uuid;
                else
                  v_entity_rel_id := coalesce(
                    (v_source_releases_map->>(v_obj->>'source_release_id'))::uuid,
                    coalesce((v_source_releases_map->>(v_domain->>'source_release_id'))::uuid, v_default_rel_id)
                  );
                end if;

                if v_entity_rel_id is not null then
                  insert into public.content_source_mappings (
                    source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
                  ) values (
                    v_entity_rel_id,
                    'lesson',
                    v_lesson_id,
                    'derived_from',
                    coalesce(v_lesson->>'citation', coalesce(v_lesson->>'title', 'Lesson')),
                    'Lesson derived from authoritative source',
                    '{}'::jsonb
                  )
                  on conflict (source_release_id, entity_type, entity_id, relationship) do update
                  set citation_location = excluded.citation_location,
                      notes = excluded.notes,
                      metadata = excluded.metadata
                  returning id into v_mapping_id;

                  v_mappings_count := v_mappings_count + 1;
                  insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
                  values (v_version_id, 'content_source_mapping', v_mapping_id)
                  on conflict do nothing;
                end if;
              end if;

              -- Bind lesson to objective
              insert into public.curriculum_node_lessons (curriculum_node_id, lesson_id, sort_order)
              values (v_obj_id, v_lesson_id, coalesce((v_lesson->>'order_index')::int, 0))
              on conflict do nothing;

              -- Scoped lesson concept linking (NO global leakage!)
              if jsonb_typeof(v_lesson->'concept_ids') = 'array' then
                for v_concept_id in select (jsonb_array_elements_text(v_lesson->'concept_ids'))::uuid
                loop
                  insert into public.lesson_concepts (lesson_id, concept_id)
                  values (v_lesson_id, v_concept_id)
                  on conflict do nothing;
                end loop;
              end if;

              -- Lesson Blocks
              if jsonb_typeof(v_lesson->'blocks') = 'array' then
                for v_block in select * from jsonb_array_elements(v_lesson->'blocks')
                loop
                  insert into public.lesson_blocks (
                    lesson_id, block_type, content, sort_order
                  ) values (
                    v_lesson_id,
                    coalesce(v_block->>'block_type', 'markdown'),
                    coalesce(v_block->'content', '{}'::jsonb),
                    coalesce((v_block->>'sort_order')::int, 0)
                  );
                  v_blocks_count := v_blocks_count + 1;
                end loop;
              end if;

              -- Lesson Terms
              if jsonb_typeof(v_lesson->'terms') = 'array' then
                for v_term in select * from jsonb_array_elements(v_lesson->'terms')
                loop
                  insert into public.terms (lesson_id, term, definition)
                  values (v_lesson_id, v_term->>'term', v_term->>'definition');
                end loop;
              end if;

              -- Lesson Questions
              if jsonb_typeof(v_lesson->'questions') = 'array' then
                for v_question in select * from jsonb_array_elements(v_lesson->'questions')
                loop
                  insert into public.questions (
                    lesson_id, question_text, options, correct_answer, type, explanation
                  ) values (
                    v_lesson_id,
                    coalesce(v_question->>'question_text', v_question->>'question'),
                    coalesce(v_question->'options', '[]'::jsonb),
                    coalesce((coalesce(v_question->>'correct_answer', v_question->>'correct_index'))::int, 0),
                    coalesce(v_question->>'type', 'mcq'),
                    v_question->>'explanation'
                  );
                  v_questions_count := v_questions_count + 1;
                end loop;
              end if;

              -- Lesson Assessment Items
              if jsonb_typeof(v_lesson->'assessment_items') = 'array' then
                for v_item in select * from jsonb_array_elements(v_lesson->'assessment_items')
                loop
                  v_stim_key := v_item->>'stimulus_key';
                  v_stim_id := null;
                  if v_stim_key is not null and v_stimuli_map ? v_stim_key then
                    v_stim_id := (v_stimuli_map->>v_stim_key)::uuid;
                  end if;

                  insert into public.assessment_items (
                    lesson_id, stimulus_id, prompt, interaction_type, response_spec, scoring_spec, explanation, origin_target_version_id
                  ) values (
                    v_lesson_id,
                    v_stim_id,
                    v_item->>'prompt',
                    coalesce(v_item->>'interaction_type', 'single_choice'),
                    coalesce(v_item->'response_spec', '{}'::jsonb),
                    coalesce(v_item->'scoring_spec', '{}'::jsonb),
                    v_item->>'explanation',
                    v_version_id
                  )
                  returning id into v_item_id;

                  v_items_count := v_items_count + 1;
                  insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
                  values (v_version_id, 'assessment_item', v_item_id);

                  if jsonb_typeof(v_item->'concept_ids') = 'array' then
                    for v_concept_id in select (jsonb_array_elements_text(v_item->'concept_ids'))::uuid
                    loop
                      insert into public.assessment_item_concepts (assessment_item_id, concept_id)
                      values (v_item_id, v_concept_id)
                      on conflict do nothing;
                    end loop;
                  end if;
                end loop;
              end if;

            end loop;
          end if; -- lessons

        end loop;
      end if; -- objectives

    end loop;
  end if; -- domains

  -- 10. Ingest Source Mappings
  if jsonb_typeof(payload->'source_mappings') = 'array' then
    for v_source_mapping in select * from jsonb_array_elements(payload->'source_mappings')
    loop
      insert into public.content_source_mappings (
        source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
      ) values (
        (v_source_mapping->>'source_release_id')::uuid,
        v_source_mapping->>'entity_type',
        (v_source_mapping->>'entity_id')::uuid,
        coalesce(v_source_mapping->>'relationship', 'derived_from'),
        coalesce(v_source_mapping->>'citation_location', v_source_mapping->>'section_reference'),
        coalesce(v_source_mapping->>'notes', v_source_mapping->>'citation_text'),
        coalesce(v_source_mapping->'metadata', '{}'::jsonb)
      )
      on conflict (source_release_id, entity_type, entity_id, relationship) do update
      set citation_location = excluded.citation_location,
          notes = excluded.notes,
          metadata = excluded.metadata
      returning id into v_mapping_id;

      v_mappings_count := v_mappings_count + 1;
      insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
      values (v_version_id, 'content_source_mapping', v_mapping_id)
      on conflict do nothing;
    end loop;
  end if;

  -- 11. Ingest Concept Version Mappings
  if jsonb_typeof(payload->'target_version_concept_mappings') = 'array' then
    for v_mapping in select * from jsonb_array_elements(payload->'target_version_concept_mappings')
    loop
      v_from_concept_id := (v_mapping->>'from_concept_id')::uuid;
      v_to_concept_id := case when v_mapping->>'to_concept_id' is not null
                              then (v_mapping->>'to_concept_id')::uuid
                              else null end;

      insert into public.target_version_concept_mappings (
        from_target_version_id, from_concept_id, to_target_version_id, to_concept_id,
        mapping_type, confidence, rationale
      ) values (
        v_version_id,
        v_from_concept_id,
        case when v_mapping->>'to_target_version_id' is not null
             then (v_mapping->>'to_target_version_id')::uuid
             else null end,
        v_to_concept_id,
        coalesce(v_mapping->>'mapping_type', 'exact_match'),
        coalesce((v_mapping->>'confidence')::numeric, 1.0),
        v_mapping->>'rationale'
      )
      on conflict do nothing;
    end loop;
  end if;

  return jsonb_build_object(
    'success', true,
    'target_id', v_target_id,
    'target_slug', v_target_slug,
    'target_version_id', v_version_id,
    'version_code', v_version_code,
    'stimuli_count', v_stimuli_count,
    'domains_count', v_domains_count,
    'objectives_count', v_objectives_count,
    'lessons_count', v_lessons_count,
    'blocks_count', v_blocks_count,
    'assessment_items_count', v_items_count,
    'flashcards_count', v_flashcards_count,
    'questions_count', v_questions_count,
    'mappings_count', v_mappings_count
  );
end;
$$;

