-- ----------------------------------------------------------------------------
-- 4. Entity-Gated Content Source Mappings RLS (No Draft Provenance Leakage)
-- ----------------------------------------------------------------------------

drop policy if exists "content_source_mappings_read" on public.content_source_mappings;
create policy "content_source_mappings_read" on public.content_source_mappings
  for select to authenticated, anon
  using (
    auth.role() = 'service_role'
    or case entity_type
      when 'target_version' then exists (
        select 1 from public.target_versions tv
        join public.learning_targets lt on lt.id = tv.target_id
        where tv.id = content_source_mappings.entity_id
          and (
            (lt.status = 'published' and lt.is_public = true and tv.status = 'published')
            or lt.created_by = auth.uid()
            or (tv.status = 'review_ready' and public.is_target_reviewer(lt.id))
          )
      )
      when 'curriculum_node' then exists (
        select 1 from public.curriculum_nodes cn
        join public.target_versions tv on tv.id = cn.target_version_id
        join public.learning_targets lt on lt.id = tv.target_id
        where cn.id = content_source_mappings.entity_id
          and (
            (lt.status = 'published' and lt.is_public = true and tv.status = 'published')
            or lt.created_by = auth.uid()
            or (tv.status = 'review_ready' and public.is_target_reviewer(lt.id))
          )
      )
      when 'lesson' then public.is_lesson_visible(content_source_mappings.entity_id)
      when 'lesson_block' then exists (
        select 1 from public.lesson_blocks lb
        where lb.id = content_source_mappings.entity_id
          and public.is_lesson_visible(lb.lesson_id)
      )
      when 'assessment_item' then exists (
        select 1 from public.assessment_items ai
        where ai.id = content_source_mappings.entity_id
          and (
            ai.user_id = auth.uid()
            or (ai.lesson_id is not null and public.is_lesson_visible(ai.lesson_id))
            or (ai.origin_target_version_id is not null and exists (
              select 1 from public.target_versions tv
              join public.learning_targets lt on lt.id = tv.target_id
              where tv.id = ai.origin_target_version_id
                and (
                  (tv.status = 'published' and lt.status = 'published' and lt.is_public = true)
                  or (lt.created_by = auth.uid())
                  or (tv.status = 'review_ready' and public.is_target_reviewer(lt.id))
                )
            ))
          )
      )
      when 'assessment_stimulus' then exists (
        select 1 from public.assessment_stimuli ast
        where ast.id = content_source_mappings.entity_id
          and (
            ast.created_by = auth.uid()
            or (ast.origin_target_version_id is null and ast.created_by is null)
            or (ast.origin_target_version_id is not null and exists (
              select 1 from public.target_versions tv
              join public.learning_targets lt on lt.id = tv.target_id
              where tv.id = ast.origin_target_version_id
                and (
                  (tv.status = 'published' and lt.status = 'published' and lt.is_public = true)
                  or (lt.created_by = auth.uid())
                  or (tv.status = 'review_ready' and public.is_target_reviewer(lt.id))
                )
            ))
          )
      )
      when 'flashcard' then exists (
        select 1 from public.flashcards f
        where f.id = content_source_mappings.entity_id
          and (
            f.user_id = auth.uid()
            or (f.origin_target_version_id is not null and exists (
              select 1 from public.target_versions tv
              join public.learning_targets lt on lt.id = tv.target_id
              where tv.id = f.origin_target_version_id
                and (
                  (tv.status = 'published' and lt.status = 'published' and lt.is_public = true)
                  or (lt.created_by = auth.uid())
                  or (tv.status = 'review_ready' and public.is_target_reviewer(lt.id))
                )
            ))
            or (f.origin_target_version_id is null and f.user_id is null)
          )
      )
      when 'knowledge_concept' then exists (
        select 1 from public.knowledge_concepts kc
        where kc.id = content_source_mappings.entity_id
          and (kc.status = 'active' or kc.created_by = auth.uid())
      )
      when 'question' then exists (
        select 1 from public.questions q
        where q.id = content_source_mappings.entity_id
          and (q.lesson_id is null or public.is_lesson_visible(q.lesson_id))
      )
      when 'term' then exists (
        select 1 from public.terms t
        where t.id = content_source_mappings.entity_id
          and (t.lesson_id is null or public.is_lesson_visible(t.lesson_id))
      )
      else false
    end
  );

-- ----------------------------------------------------------------------------
-- 5. Lock content_import_artifacts Table to service_role Only
-- ----------------------------------------------------------------------------

revoke all on public.content_import_artifacts from public, anon, authenticated;
grant all on public.content_import_artifacts to service_role;

drop policy if exists "artifacts_access" on public.content_import_artifacts;
drop policy if exists "artifacts_service_role" on public.content_import_artifacts;
create policy "artifacts_service_role" on public.content_import_artifacts
  for all using (auth.role() = 'service_role');

-- ----------------------------------------------------------------------------
-- 6. TargetVersion Lifecycle State Machine Trigger
-- ----------------------------------------------------------------------------

create or replace function public.trg_target_versions_lifecycle()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if tg_op = 'DELETE' then
    if old.status <> 'draft' then
      raise exception 'Cannot delete target_version with status "%". Only draft versions may be deleted.', old.status;
    end if;
    return old;
  end if;

  if tg_op = 'UPDATE' then
    -- 1. Published immutability: NO field changes allowed, except status transition to 'retired'
    if old.status = 'published' then
      if new.status <> 'retired' then
        raise exception 'Published versions are immutable and cannot be updated. Only transition to "retired" status is permitted.';
      end if;

      -- Even when transitioning to 'retired', no metadata/title/version_code/etc. can be changed
      if (to_jsonb(new) - 'status' - 'updated_at') is distinct from (to_jsonb(old) - 'status' - 'updated_at') then
        raise exception 'Cannot modify TargetVersion attributes when retiring a published version. It must be a status-only transition.';
      end if;
    end if;

    -- 2. Retired versions are completely immutable
    if old.status = 'retired' and (new.status <> 'retired' or new.* is distinct from old.*) then
      raise exception 'Retired versions are completely immutable.';
    end if;

    -- 3. Draft status transitions: must go through review_ready before publishing
    if old.status = 'draft' then
      if new.status not in ('draft', 'review_ready') then
        raise exception 'Invalid status transition: draft must be staged to "review_ready" before publishing.';
      end if;
    end if;

    -- 4. review_ready status transitions
    if old.status = 'review_ready' then
      if new.status not in ('draft', 'published', 'review_ready') then
        raise exception 'Invalid status transition: review_ready can only transition to "draft" or "published".';
      end if;

      -- In review_ready or when leaving review_ready (to published or draft), NO field edits allowed (status-only)!
      if (to_jsonb(new) - 'status' - 'updated_at') is distinct from (to_jsonb(old) - 'status' - 'updated_at') then
        if new.status = 'published' then
          raise exception 'Cannot modify TargetVersion attributes during publication from "review_ready". Publication must be a status-only transition.';
        elsif new.status = 'review_ready' then
          raise exception 'TargetVersion is frozen in "review_ready" status. Revert status to "draft" before making edits.';
        else
          raise exception 'Status change from "review_ready" to "draft" must be a status-only transition before edits can be made.';
        end if;
      end if;
    end if;

    return new;
  end if;

  return new;
end;
$$;

-- ----------------------------------------------------------------------------
-- 7. Defense-in-Depth & Scoped clean_draft_target_version()
-- ----------------------------------------------------------------------------

create or replace function public.clean_draft_target_version(
  p_version_id uuid
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_status text;
  v_target_owner uuid;
begin
  select tv.status, lt.created_by
  into v_status, v_target_owner
  from public.target_versions tv
  join public.learning_targets lt on lt.id = tv.target_id
  where tv.id = p_version_id;

  if v_status is null then
    raise exception 'TargetVersion % not found', p_version_id;
  end if;

  if v_status <> 'draft' then
    raise exception 'Cannot clean TargetVersion with status "%". Only draft versions may be reset.', v_status;
  end if;

  -- Authorization check: service_role or target owner only
  if coalesce(current_setting('request.jwt.claim.role', true), '') <> 'service_role'
     and auth.role() <> 'service_role'
     and (v_target_owner is null or v_target_owner <> auth.uid()) then
    raise exception 'Unauthorized: only service_role or the target owner can clean a draft target version';
  end if;

  -- 1. Scoped provenance mapping deletion (NO cross-target global orphan deletion!):
  -- Canonical concept mappings (entity_type = 'knowledge_concept') are durable global provenance and are NEVER deleted.
  delete from public.content_source_mappings
  where entity_type <> 'knowledge_concept'
    and (
      (entity_type = 'target_version' and entity_id = p_version_id)
      or (entity_type = 'curriculum_node' and entity_id in (
           select id from public.curriculum_nodes where target_version_id = p_version_id
         ))
      or (entity_type = 'lesson' and entity_id in (
           select id from public.lessons where origin_target_version_id = p_version_id
         ))
      or (entity_type = 'assessment_stimulus' and entity_id in (
           select id from public.assessment_stimuli where origin_target_version_id = p_version_id
         ))
      or (entity_type = 'assessment_item' and entity_id in (
           select id from public.assessment_items where origin_target_version_id = p_version_id
         ))
      or (entity_type = 'flashcard' and entity_id in (
           select id from public.flashcards where origin_target_version_id = p_version_id
         ))
      or (entity_type = 'lesson_block' and entity_id in (
           select lb.id from public.lesson_blocks lb
           join public.lessons l on l.id = lb.lesson_id
           where l.origin_target_version_id = p_version_id
         ))
    );

  -- 2. Delete assessment_items: defense-in-depth requires origin_target_version_id = p_version_id
  delete from public.assessment_items
  where origin_target_version_id = p_version_id;

  -- 3. Delete assessment_stimuli: defense-in-depth requires origin_target_version_id = p_version_id
  delete from public.assessment_stimuli
  where origin_target_version_id = p_version_id;

  -- 4. Delete flashcards: defense-in-depth requires origin_target_version_id = p_version_id
  delete from public.flashcards
  where origin_target_version_id = p_version_id;

  -- 5. Delete official lessons: defense-in-depth strictly requires origin_target_version_id = p_version_id
  delete from public.lessons
  where origin_target_version_id = p_version_id;

  -- 6. Delete curriculum nodes of this draft: must have target_version_id = p_version_id
  delete from public.curriculum_nodes
  where target_version_id = p_version_id;

  -- 7. Delete concept mappings involving this draft version
  delete from public.target_version_concept_mappings
  where from_target_version_id = p_version_id
     or to_target_version_id = p_version_id;

  -- 8. Clean all artifact tracking records for this draft version
  delete from public.content_import_artifacts
  where target_version_id = p_version_id;

end;
$$;

revoke all on function public.clean_draft_target_version(uuid) from public, anon;
grant execute on function public.clean_draft_target_version(uuid) to authenticated, service_role;

-- ----------------------------------------------------------------------------
-- 7b. Atomic Target Version Publication & Retirement RPC
-- ----------------------------------------------------------------------------

create or replace function public.publish_target_version(
  p_version_id uuid,
  p_retire_previous boolean default false
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_status text;
  v_target_id uuid;
  v_target_owner uuid;
  v_retired_count integer := 0;
begin
  select tv.status, tv.target_id, lt.created_by
  into v_status, v_target_id, v_target_owner
  from public.target_versions tv
  join public.learning_targets lt on lt.id = tv.target_id
  where tv.id = p_version_id;

  if v_status is null then
    raise exception 'TargetVersion % not found', p_version_id;
  end if;

  if v_status = 'published' then
    return jsonb_build_object('success', true, 'status', 'published', 'already_published', true, 'retired_previous_count', 0);
  end if;

  if v_status <> 'review_ready' then
    raise exception 'Cannot publish TargetVersion with status "%". Publication strictly requires "review_ready" staging status.', v_status;
  end if;

  -- Authorization check: service_role or target owner only
  if coalesce(current_setting('request.jwt.claim.role', true), '') <> 'service_role'
     and auth.role() <> 'service_role'
     and (v_target_owner is null or v_target_owner <> auth.uid()) then
    raise exception 'Unauthorized: only service_role or the target owner can publish a target version';
  end if;

  -- 1. Atomically retire previous published versions for this target if requested
  if p_retire_previous then
    with retired as (
      update public.target_versions
      set status = 'retired',
          updated_at = now()
      where target_id = v_target_id
        and status = 'published'
        and id <> p_version_id
      returning id
    )
    select count(*) into v_retired_count from retired;
  end if;

  -- 2. Promote target version to published
  update public.target_versions
  set status = 'published',
      updated_at = now()
  where id = p_version_id;

  return jsonb_build_object(
    'success', true,
    'status', 'published',
    'retired_previous_count', v_retired_count
  );
end;
$$;

revoke all on function public.publish_target_version(uuid, boolean) from public, anon;
grant execute on function public.publish_target_version(uuid, boolean) to authenticated, service_role;

-- ----------------------------------------------------------------------------
-- 8. Fully Transactional Ingestion RPC (ingest_curriculum_manifest)
-- ----------------------------------------------------------------------------

create or replace function public.ingest_curriculum_manifest(
  payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_field_id uuid;
  v_field_slug text;
  v_target_id uuid;
  v_target_slug text;
  v_version_id uuid;
  v_version_code text;
  v_version_status text;

  -- Counters
  v_concepts_count int := 0;
  v_stimuli_count int := 0;
  v_domains_count int := 0;
  v_objectives_count int := 0;
  v_lessons_count int := 0;
  v_blocks_count int := 0;
  v_items_count int := 0;
  v_flashcards_count int := 0;
  v_questions_count int := 0;
  v_mappings_count int := 0;

  -- Lookup Maps
  v_stimuli_map jsonb := '{}'::jsonb;         -- stimulus_key -> uuid
  v_concepts_map jsonb := '{}'::jsonb;        -- slug -> uuid
  v_source_releases_map jsonb := '{}'::jsonb; -- source_id or index -> uuid
  v_default_rel_id uuid := null;

  -- Concept processing variables
  v_concept jsonb;
  v_concept_id uuid;
  v_concept_slug text;
  v_concept_name text;
  v_explicit_canon text;
  v_matched_id uuid;
  v_matched_is_ambig boolean;
  v_concept_rel_id uuid;

  -- Content processing variables
  v_stim jsonb;
  v_stim_key text;
  v_stim_id uuid;
  v_domain jsonb;
  v_domain_id uuid;
  v_obj jsonb;
  v_obj_id uuid;
  v_lesson jsonb;
  v_lesson_id uuid;
  v_block jsonb;
  v_block_id uuid;
  v_item jsonb;
  v_item_id uuid;
  v_fc jsonb;
  v_fc_id uuid;
  v_term jsonb;
  v_question jsonb;
  v_mapping jsonb;
  v_source_rel jsonb;
  v_source_rel_idx int := 0;
  v_rel_id uuid;
  v_source_artifact jsonb;
  v_mapping_id uuid;
  v_source_mapping jsonb;
  v_from_concept_id uuid;
  v_to_concept_id uuid;

  v_entity_rel_id uuid;
  v_lesson_rel_id uuid;
  v_obj_rel_id uuid;
  v_raw_concept_ref text;
  v_resolved_cid uuid;
begin
  -- 1. Security Check: Service-role only
  if coalesce(current_setting('request.jwt.claim.role', true), '') <> 'service_role'
     and auth.role() <> 'service_role' then
    raise exception 'Unauthorized: ingest_curriculum_manifest requires service_role privilege';
  end if;

  -- 2. Extract / Upsert Field
  v_field_slug := payload->'field'->>'slug';
  if v_field_slug is not null and v_field_slug <> '' then
    select id into v_field_id from public.fields where slug = v_field_slug;
    if v_field_id is null then
      insert into public.fields (slug, name, description, field_kind)
      values (
        v_field_slug,
        coalesce(payload->'field'->>'name', v_field_slug),
        payload->'field'->>'description',
        'native_field'
      )
      returning id into v_field_id;
    end if;
  end if;

  -- 3. Extract / Upsert LearningTarget
  v_target_slug := payload->'target'->>'slug';
  if v_target_slug is null or v_target_slug = '' then
    raise exception 'Missing target.slug in manifest payload';
  end if;

  select id into v_target_id from public.learning_targets where slug = v_target_slug;
  if v_target_id is null then
    insert into public.learning_targets (
      slug, title, target_type, description, field_id, status, is_public
    ) values (
      v_target_slug,
      coalesce(payload->'target'->>'title', v_target_slug),
      coalesce(payload->'target'->>'target_type', coalesce(payload->'target'->>'target_kind', 'certification')),
      payload->'target'->>'description',
      v_field_id,
      'published',
      true
    )
    returning id into v_target_id;
  end if;

  -- 4. Extract / Upsert TargetVersion
  v_version_code := payload->'target_version'->>'version_code';
  if v_version_code is null or v_version_code = '' then
    raise exception 'Missing target_version.version_code in manifest payload';
  end if;

  select id, status into v_version_id, v_version_status
  from public.target_versions
  where target_id = v_target_id and version_code = v_version_code;

  if v_version_id is null then
    insert into public.target_versions (
      target_id, version_code, title, description, valid_from, status, metadata
    ) values (
      v_target_id,
      v_version_code,
      coalesce(payload->'target_version'->>'title', payload->'target'->>'version_title', v_version_code),
      coalesce(payload->'target_version'->>'description', payload->'target'->>'version_description'),
      case when coalesce(payload->'target_version'->>'valid_from', payload->'target'->>'valid_from') is not null
           then (coalesce(payload->'target_version'->>'valid_from', payload->'target'->>'valid_from'))::date
           else null end,
      'draft',
      coalesce(payload->'target_version'->'metadata', '{}'::jsonb)
    )
    returning id, status into v_version_id, v_version_status;
  else
    if v_version_status <> 'draft' then
      raise exception 'Cannot ingest into TargetVersion "%" with status "%". Only draft versions may be replaced.', v_version_code, v_version_status;
    end if;

    update public.target_versions
    set title = coalesce(payload->'target_version'->>'title', payload->'target'->>'version_title', title),
        description = coalesce(payload->'target_version'->>'description', payload->'target'->>'version_description', description),
        valid_from = case when coalesce(payload->'target_version'->>'valid_from', payload->'target'->>'valid_from') is not null
                          then (coalesce(payload->'target_version'->>'valid_from', payload->'target'->>'valid_from'))::date
                          else valid_from end,
        metadata = coalesce(payload->'target_version'->'metadata', metadata),
        updated_at = now()
    where id = v_version_id;
  end if;

  -- 5. Atomically Clean Previous Draft Content for this TargetVersion
  perform public.clean_draft_target_version(v_version_id);

  -- 6. Ingest Source Releases
  if jsonb_typeof(coalesce(payload->'source_releases', payload->'sources')) = 'array' then
    for v_source_rel in select * from jsonb_array_elements(coalesce(payload->'source_releases', payload->'sources'))
    loop
      insert into public.content_source_releases (
        publisher, title, version, source_url, license, retrieved_at, sha256, metadata
      ) values (
        coalesce(v_source_rel->>'publisher', 'Authoritative Source'),
        coalesce(v_source_rel->>'title', 'Official Blueprint'),
        coalesce(v_source_rel->>'version', 'v1'),
        v_source_rel->>'source_url',
        coalesce(v_source_rel->>'license', v_source_rel->>'license_name'),
        case when v_source_rel->>'retrieved_at' is not null
             then (v_source_rel->>'retrieved_at')::timestamptz
             else now() end,
        v_source_rel->>'sha256',
        coalesce(v_source_rel->'metadata', '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
          'system', v_source_rel->>'system',
          'rights_note', v_source_rel->>'rights_note'
        ))
      )
      on conflict (publisher, title, version) do update
      set source_url = excluded.source_url,
          license = excluded.license,
          retrieved_at = excluded.retrieved_at,
          sha256 = excluded.sha256,
          metadata = excluded.metadata
      returning id into v_rel_id;

      v_source_rel_idx := v_source_rel_idx + 1;
      if v_default_rel_id is null then
        v_default_rel_id := v_rel_id;
      end if;

      if v_source_rel ? 'id' then
        v_source_releases_map := v_source_releases_map || jsonb_build_object(v_source_rel->>'id', v_rel_id::text);
      end if;
      if v_source_rel ? 'source_id' then
        v_source_releases_map := v_source_releases_map || jsonb_build_object(v_source_rel->>'source_id', v_rel_id::text);
      end if;
      v_source_releases_map := v_source_releases_map || jsonb_build_object(
        coalesce(v_source_rel->>'publisher', '') || '/' || coalesce(v_source_rel->>'version', ''), v_rel_id::text
      );
      v_source_releases_map := v_source_releases_map || jsonb_build_object(
        (v_source_rel_idx - 1)::text, v_rel_id::text
      );

      -- Link root target_version to this source release
      insert into public.content_source_mappings (
        source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
      ) values (
        v_rel_id,
        'target_version',
        v_version_id,
        'official_blueprint',
        coalesce(payload->'target_version'->>'citation', 'Root Blueprint'),
        'Root target version mapping to authoritative source release',
        '{}'::jsonb
      )
      on conflict (source_release_id, entity_type, entity_id, relationship) do update
      set citation_location = excluded.citation_location,
          notes = excluded.notes,
          metadata = excluded.metadata
      returning id into v_mapping_id;

      v_mappings_count := v_mappings_count + 1;
      insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
      values (v_version_id, 'content_source_mapping', v_mapping_id)
      on conflict do nothing;

      -- Source Artifacts
      if jsonb_typeof(v_source_rel->'artifacts') = 'array' then
        for v_source_artifact in select * from jsonb_array_elements(v_source_rel->'artifacts')
        loop
          insert into public.content_source_artifacts (
            source_release_id, artifact_name, source_url, sha256, file_size_bytes, retrieved_at, metadata
          ) values (
            v_rel_id,
            coalesce(v_source_artifact->>'artifact_name', 'blueprint.pdf'),
            v_source_artifact->>'source_url',
            v_source_artifact->>'sha256',
            case when v_source_artifact->>'file_size_bytes' is not null
                 then (v_source_artifact->>'file_size_bytes')::bigint
                 else null end,
            case when v_source_artifact->>'retrieved_at' is not null
                 then (v_source_artifact->>'retrieved_at')::timestamptz
                 else now() end,
            coalesce(v_source_artifact->'metadata', '{}'::jsonb)
          )
          on conflict (source_release_id, artifact_name) do update
          set source_url = excluded.source_url,
              sha256 = excluded.sha256,
              file_size_bytes = excluded.file_size_bytes,
              retrieved_at = excluded.retrieved_at,
              metadata = excluded.metadata;
        end loop;
      end if;
    end loop;
  end if;

  -- 7. Fully Transactional Canonical Concepts Resolution & Ingestion (Option A)
  if jsonb_typeof(payload->'concepts') = 'array' then
    for v_concept in select * from jsonb_array_elements(payload->'concepts')
    loop
      v_concept_slug := v_concept->>'slug';
      v_concept_name := coalesce(v_concept->>'name', v_concept_slug);
      v_explicit_canon := v_concept->>'canonical_concept';
      v_concept_id := null;

      if v_explicit_canon is not null and trim(v_explicit_canon) <> '' then
        select id into v_concept_id
        from public.knowledge_concepts
        where slug = trim(v_explicit_canon);

        if v_concept_id is null then
          raise exception 'Explicit canonical_concept "%" declared for concept "%" (%) does not exist in knowledge_concepts. Overrides must fail closed.', v_explicit_canon, v_concept_name, v_concept_slug;
        end if;

        if v_field_id is not null then
          insert into public.concept_fields (concept_id, field_id, relationship)
          values (v_concept_id, v_field_id, 'core_concept')
          on conflict (concept_id, field_id) do nothing;
        end if;
      else
        -- Ambiguity-safe resolution RPC
        select r.id, r.is_ambiguous into v_matched_id, v_matched_is_ambig
        from public.resolve_canonical_concept(v_concept_slug, v_concept_name, v_field_id) r
        limit 1;

        if v_matched_is_ambig then
          raise exception 'Ambiguous canonical concept match for "%" (%). Multiple concepts share this name across fields and target field does not disambiguate. Declare "canonical_concept: <existing-slug>" explicitly in the manifest to resolve the ambiguity, or make the concept name specific.', v_concept_name, v_concept_slug;
        end if;

        if v_matched_id is not null then
          v_concept_id := v_matched_id;
          if v_field_id is not null then
            insert into public.concept_fields (concept_id, field_id, relationship)
            values (v_concept_id, v_field_id, 'core_concept')
            on conflict (concept_id, field_id) do nothing;
          end if;
        else
          -- Insert new canonical knowledge concept
          insert into public.knowledge_concepts (
            field_id, slug, name, short_definition, description, emoji, aliases, status
          ) values (
            v_field_id,
            v_concept_slug,
            v_concept_name,
            v_concept->>'short_definition',
            v_concept->>'description',
            coalesce(v_concept->>'emoji', '💡'),
            case when jsonb_typeof(v_concept->'aliases') = 'array'
                 then array(select jsonb_array_elements_text(v_concept->'aliases'))
                 else array[]::text[] end,
            'active'
          )
          returning id into v_concept_id;

          if v_field_id is not null then
            insert into public.concept_fields (concept_id, field_id, relationship)
            values (v_concept_id, v_field_id, 'core_concept')
            on conflict (concept_id, field_id) do nothing;
          end if;
        end if;
      end if;

      v_concepts_count := v_concepts_count + 1;
      v_concepts_map := v_concepts_map || jsonb_build_object(v_concept_slug, v_concept_id::text);

      -- Canonical Concept Provenance Mapping
      if v_default_rel_id is not null then
        v_concept_rel_id := null;
        if v_concept ? 'source_release_id' and v_source_releases_map ? (v_concept->>'source_release_id') then
          v_concept_rel_id := (v_source_releases_map->>(v_concept->>'source_release_id'))::uuid;
        elsif v_concept ? 'source_id' and v_source_releases_map ? (v_concept->>'source_id') then
          v_concept_rel_id := (v_source_releases_map->>(v_concept->>'source_id'))::uuid;
        else
          v_concept_rel_id := v_default_rel_id;
        end if;

        if v_concept_rel_id is not null then
          insert into public.content_source_mappings (
            source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
          ) values (
            v_concept_rel_id,
            'knowledge_concept',
            v_concept_id,
            coalesce(v_concept->>'relationship', 'official_blueprint'),
            coalesce(v_concept->>'citation', coalesce(v_concept->>'citation_location', 'Concept ' || v_concept_slug)),
            coalesce(v_concept->>'notes', coalesce(v_concept->>'citation_notes', 'Authoritative concept definition from blueprint')),
            '{}'::jsonb
          )
          on conflict (source_release_id, entity_type, entity_id, relationship) do update
          set citation_location = excluded.citation_location,
              notes = excluded.notes,
              metadata = excluded.metadata;

          v_mappings_count := v_mappings_count + 1;
        end if;
      end if;
    end loop;
  end if;

  -- 8. Ingest Shared Stimuli (root-level & objective-level)
  if jsonb_typeof(payload->'stimuli') = 'array' then
    for v_stim in select * from jsonb_array_elements(payload->'stimuli')
    loop
      v_stim_key := v_stim->>'stimulus_key';
      insert into public.assessment_stimuli (
        title, body, stimulus_type, metadata, origin_target_version_id
      ) values (
        coalesce(v_stim->>'title', 'Exhibit'),
        coalesce(v_stim->>'body', coalesce(v_stim->>'body_markdown', '')),
        coalesce(v_stim->>'stimulus_type', 'scenario'),
        jsonb_build_object(
          'media_url', v_stim->>'media_url',
          'credit', v_stim->>'credit',
          'attribution', v_stim->>'attribution'
        ),
        v_version_id
      )
      returning id into v_stim_id;

      v_stimuli_count := v_stimuli_count + 1;
      v_stimuli_map := v_stimuli_map || jsonb_build_object(v_stim_key, v_stim_id::text);

      insert into public.content_import_artifacts (target_version_id, entity_type, entity_id, manifest_key)
      values (v_version_id, 'assessment_stimulus', v_stim_id, v_stim_key);

      -- Stimulus Source Mapping
      if v_default_rel_id is not null then
        v_entity_rel_id := null;
        if v_stim ? 'source_release_id' and v_source_releases_map ? (v_stim->>'source_release_id') then
          v_entity_rel_id := (v_source_releases_map->>(v_stim->>'source_release_id'))::uuid;
        elsif v_stim ? 'source_id' and v_source_releases_map ? (v_stim->>'source_id') then
          v_entity_rel_id := (v_source_releases_map->>(v_stim->>'source_id'))::uuid;
        else
          v_entity_rel_id := v_default_rel_id;
        end if;

        if v_entity_rel_id is not null then
          insert into public.content_source_mappings (
            source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
          ) values (
            v_entity_rel_id,
            'assessment_stimulus',
            v_stim_id,
            'official_blueprint',
            coalesce(v_stim->>'citation', coalesce(v_stim->>'citation_location', 'Official Blueprint Stimulus')),
            coalesce(v_stim->>'notes', 'Assessment stimulus mapping'),
            '{}'::jsonb
          )
          on conflict (source_release_id, entity_type, entity_id, relationship) do update
          set citation_location = excluded.citation_location,
              notes = excluded.notes,
              metadata = excluded.metadata
          returning id into v_mapping_id;

          v_mappings_count := v_mappings_count + 1;
          insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
          values (v_version_id, 'content_source_mapping', v_mapping_id)
          on conflict do nothing;
        end if;
      end if;
    end loop;
  end if;

  -- 9. Ingest Standalone Target-level Flashcards
  if jsonb_typeof(payload->'flashcards') = 'array' then
    for v_fc in select * from jsonb_array_elements(payload->'flashcards')
    loop
      insert into public.flashcards (
        front, back, explanation, origin_target_version_id
      ) values (
        v_fc->>'front',
        v_fc->>'back',
        v_fc->>'explanation',
        v_version_id
      )
      returning id into v_fc_id;

      v_flashcards_count := v_flashcards_count + 1;
      insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
      values (v_version_id, 'flashcard', v_fc_id);

      -- Link concepts by UUID or slug lookup
      if jsonb_typeof(v_fc->'concept_ids') = 'array' then
        for v_concept_id in select (jsonb_array_elements_text(v_fc->'concept_ids'))::uuid
        loop
          insert into public.flashcard_concepts (flashcard_id, concept_id)
          values (v_fc_id, v_concept_id)
          on conflict do nothing;
        end loop;
      end if;

      if jsonb_typeof(v_fc->'concept_slugs') = 'array' then
        for v_raw_concept_ref in select jsonb_array_elements_text(v_fc->'concept_slugs')
        loop
          if v_concepts_map ? v_raw_concept_ref then
            v_resolved_cid := (v_concepts_map->>v_raw_concept_ref)::uuid;
            insert into public.flashcard_concepts (flashcard_id, concept_id)
            values (v_fc_id, v_resolved_cid)
            on conflict do nothing;
          end if;
        end loop;
      end if;

      -- Flashcard Provenance Mapping
      if v_default_rel_id is not null then
        v_entity_rel_id := null;
        if v_fc ? 'source_release_id' and v_source_releases_map ? (v_fc->>'source_release_id') then
          v_entity_rel_id := (v_source_releases_map->>(v_fc->>'source_release_id'))::uuid;
        elsif v_fc ? 'source_id' and v_source_releases_map ? (v_fc->>'source_id') then
          v_entity_rel_id := (v_source_releases_map->>(v_fc->>'source_id'))::uuid;
        else
          v_entity_rel_id := v_default_rel_id;
        end if;

        if v_entity_rel_id is not null then
          insert into public.content_source_mappings (
            source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
          ) values (
            v_entity_rel_id,
            'flashcard',
            v_fc_id,
            'derived_from',
            coalesce(v_fc->>'citation', coalesce(v_fc->>'citation_location', coalesce(v_fc->>'front', 'Flashcard'))),
            coalesce(v_fc->>'notes', 'Flashcard derived from authoritative blueprint'),
            '{}'::jsonb
          )
          on conflict (source_release_id, entity_type, entity_id, relationship) do update
          set citation_location = excluded.citation_location,
              notes = excluded.notes,
              metadata = excluded.metadata
          returning id into v_mapping_id;

          v_mappings_count := v_mappings_count + 1;
          insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
          values (v_version_id, 'content_source_mapping', v_mapping_id)
          on conflict do nothing;
        end if;
      end if;
    end loop;
  end if;

  -- 10. Ingest Domains, Objectives, Lessons, Blocks, Assessment Items
  if jsonb_typeof(payload->'domains') = 'array' then
    for v_domain in select * from jsonb_array_elements(payload->'domains')
    loop
      insert into public.curriculum_nodes (
        target_version_id, node_type, code, title, description, sort_order, weight, metadata
      ) values (
        v_version_id,
        'domain',
        v_domain->>'code',
        coalesce(v_domain->>'title', 'Domain'),
        v_domain->>'description',
        coalesce((v_domain->>'sort_order')::int, 0),
        case when v_domain->>'weight_percentage' is not null
             then (v_domain->>'weight_percentage')::numeric
             when v_domain->>'weight' is not null
             then (v_domain->>'weight')::numeric
             else null end,
        coalesce(v_domain->'metadata', '{}'::jsonb)
      )
      returning id into v_domain_id;

      v_domains_count := v_domains_count + 1;
      insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
      values (v_version_id, 'curriculum_node', v_domain_id);

      -- Domain Source Mapping
      if v_default_rel_id is not null then
        v_entity_rel_id := null;
        if v_domain ? 'source_release_id' and v_source_releases_map ? (v_domain->>'source_release_id') then
          v_entity_rel_id := (v_source_releases_map->>(v_domain->>'source_release_id'))::uuid;
        elsif v_domain ? 'source_id' and v_source_releases_map ? (v_domain->>'source_id') then
          v_entity_rel_id := (v_source_releases_map->>(v_domain->>'source_id'))::uuid;
        else
          v_entity_rel_id := v_default_rel_id;
        end if;

        if v_entity_rel_id is not null then
          insert into public.content_source_mappings (
            source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
          ) values (
            v_entity_rel_id,
            'curriculum_node',
            v_domain_id,
            'official_blueprint',
            coalesce(v_domain->>'citation', coalesce(v_domain->>'citation_location', 'Domain ' || coalesce(v_domain->>'code', ''))),
            coalesce(v_domain->>'notes', 'Curriculum domain node citation'),
            '{}'::jsonb
          )
          on conflict (source_release_id, entity_type, entity_id, relationship) do update
          set citation_location = excluded.citation_location,
              notes = excluded.notes,
              metadata = excluded.metadata
          returning id into v_mapping_id;

          v_mappings_count := v_mappings_count + 1;
          insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
          values (v_version_id, 'content_source_mapping', v_mapping_id)
          on conflict do nothing;
        end if;
      end if;

      -- Objectives
      if jsonb_typeof(v_domain->'objectives') = 'array' then
        for v_obj in select * from jsonb_array_elements(v_domain->'objectives')
        loop
          insert into public.curriculum_nodes (
            target_version_id, parent_id, node_type, code, title, description, sort_order, metadata
          ) values (
            v_version_id,
            v_domain_id,
            'objective',
            v_obj->>'code',
            coalesce(v_obj->>'title', 'Objective'),
            v_obj->>'description',
            coalesce((v_obj->>'sort_order')::int, 0),
            jsonb_build_object('bloom_level', coalesce(v_obj->>'bloom_level', 'understand'))
          )
          returning id into v_obj_id;

          v_objectives_count := v_objectives_count + 1;
          insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
          values (v_version_id, 'curriculum_node', v_obj_id);

          -- Objective Source Mapping
          if v_default_rel_id is not null then
            v_entity_rel_id := null;
            if v_obj ? 'source_release_id' and v_source_releases_map ? (v_obj->>'source_release_id') then
              v_entity_rel_id := (v_source_releases_map->>(v_obj->>'source_release_id'))::uuid;
            elsif v_obj ? 'source_id' and v_source_releases_map ? (v_obj->>'source_id') then
              v_entity_rel_id := (v_source_releases_map->>(v_obj->>'source_id'))::uuid;
            else
              v_entity_rel_id := coalesce(
                (v_source_releases_map->>(v_domain->>'source_release_id'))::uuid,
                (v_source_releases_map->>(v_domain->>'source_id'))::uuid,
                v_default_rel_id
              );
            end if;

            v_obj_rel_id := v_entity_rel_id;

            if v_entity_rel_id is not null then
              insert into public.content_source_mappings (
                source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
              ) values (
                v_entity_rel_id,
                'curriculum_node',
                v_obj_id,
                'official_blueprint',
                coalesce(v_obj->>'citation', coalesce(v_obj->>'citation_location', 'Objective ' || coalesce(v_obj->>'code', ''))),
                coalesce(v_obj->>'notes', 'Curriculum objective node citation'),
                '{}'::jsonb
              )
              on conflict (source_release_id, entity_type, entity_id, relationship) do update
              set citation_location = excluded.citation_location,
                  notes = excluded.notes,
                  metadata = excluded.metadata
              returning id into v_mapping_id;

              v_mappings_count := v_mappings_count + 1;
              insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
              values (v_version_id, 'content_source_mapping', v_mapping_id)
              on conflict do nothing;
            end if;
          end if;

          -- Link objective concepts by UUID or slug
          if jsonb_typeof(v_obj->'concept_ids') = 'array' then
            for v_concept_id in select (jsonb_array_elements_text(v_obj->'concept_ids'))::uuid
            loop
              insert into public.curriculum_node_concepts (curriculum_node_id, concept_id)
              values (v_obj_id, v_concept_id)
              on conflict do nothing;
            end loop;
          end if;

          if jsonb_typeof(v_obj->'concept_slugs') = 'array' then
            for v_raw_concept_ref in select jsonb_array_elements_text(v_obj->'concept_slugs')
            loop
              if v_concepts_map ? v_raw_concept_ref then
                v_resolved_cid := (v_concepts_map->>v_raw_concept_ref)::uuid;
                insert into public.curriculum_node_concepts (curriculum_node_id, concept_id)
                values (v_obj_id, v_resolved_cid)
                on conflict do nothing;
              end if;
            end loop;
          end if;

          -- Objective Flashcards
          if jsonb_typeof(v_obj->'flashcards') = 'array' then
            for v_fc in select * from jsonb_array_elements(v_obj->'flashcards')
            loop
              insert into public.flashcards (
                front, back, explanation, origin_target_version_id
              ) values (
                v_fc->>'front',
                v_fc->>'back',
                v_fc->>'explanation',
                v_version_id
              )
              returning id into v_fc_id;

              v_flashcards_count := v_flashcards_count + 1;
              insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
              values (v_version_id, 'flashcard', v_fc_id);

              if jsonb_typeof(v_fc->'concept_ids') = 'array' then
                for v_concept_id in select (jsonb_array_elements_text(v_fc->'concept_ids'))::uuid
                loop
                  insert into public.flashcard_concepts (flashcard_id, concept_id)
                  values (v_fc_id, v_concept_id)
                  on conflict do nothing;
                end loop;
              end if;

              if jsonb_typeof(v_fc->'concept_slugs') = 'array' then
                for v_raw_concept_ref in select jsonb_array_elements_text(v_fc->'concept_slugs')
                loop
                  if v_concepts_map ? v_raw_concept_ref then
                    v_resolved_cid := (v_concepts_map->>v_raw_concept_ref)::uuid;
                    insert into public.flashcard_concepts (flashcard_id, concept_id)
                    values (v_fc_id, v_resolved_cid)
                    on conflict do nothing;
                  end if;
                end loop;
              end if;

              -- Objective Flashcard Provenance Mapping
              if v_default_rel_id is not null then
                v_entity_rel_id := null;
                if v_fc ? 'source_release_id' and v_source_releases_map ? (v_fc->>'source_release_id') then
                  v_entity_rel_id := (v_source_releases_map->>(v_fc->>'source_release_id'))::uuid;
                elsif v_fc ? 'source_id' and v_source_releases_map ? (v_fc->>'source_id') then
                  v_entity_rel_id := (v_source_releases_map->>(v_fc->>'source_id'))::uuid;
                else
                  v_entity_rel_id := coalesce(v_obj_rel_id, v_default_rel_id);
                end if;

                if v_entity_rel_id is not null then
                  insert into public.content_source_mappings (
                    source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
                  ) values (
                    v_entity_rel_id,
                    'flashcard',
                    v_fc_id,
                    'derived_from',
                    coalesce(v_fc->>'citation', coalesce(v_fc->>'citation_location', coalesce(v_fc->>'front', 'Objective Flashcard'))),
                    coalesce(v_fc->>'notes', 'Flashcard derived from authoritative objective blueprint'),
                    '{}'::jsonb
                  )
                  on conflict (source_release_id, entity_type, entity_id, relationship) do update
                  set citation_location = excluded.citation_location,
                      notes = excluded.notes,
                      metadata = excluded.metadata
                  returning id into v_mapping_id;

                  v_mappings_count := v_mappings_count + 1;
                  insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
                  values (v_version_id, 'content_source_mapping', v_mapping_id)
                  on conflict do nothing;
                end if;
              end if;
            end loop;
          end if;

          -- Objective Assessment Items
          if jsonb_typeof(v_obj->'assessment_items') = 'array' then
            for v_item in select * from jsonb_array_elements(v_obj->'assessment_items')
            loop
              v_stim_key := v_item->>'stimulus_key';
              v_stim_id := null;
              if v_stim_key is not null and v_stimuli_map ? v_stim_key then
                v_stim_id := (v_stimuli_map->>v_stim_key)::uuid;
              end if;

              insert into public.assessment_items (
                stimulus_id, prompt, interaction_type, response_spec, scoring_spec, explanation, origin_target_version_id
              ) values (
                v_stim_id,
                v_item->>'prompt',
                coalesce(v_item->>'interaction_type', 'single_choice'),
                coalesce(v_item->'response_spec', '{}'::jsonb),
                coalesce(v_item->'scoring_spec', '{}'::jsonb),
                v_item->>'explanation',
                v_version_id
              )
              returning id into v_item_id;

              v_items_count := v_items_count + 1;
              insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
              values (v_version_id, 'assessment_item', v_item_id);

              if jsonb_typeof(v_item->'concept_ids') = 'array' then
                for v_concept_id in select (jsonb_array_elements_text(v_item->'concept_ids'))::uuid
                loop
                  insert into public.assessment_item_concepts (assessment_item_id, concept_id)
                  values (v_item_id, v_concept_id)
                  on conflict do nothing;
                end loop;
              end if;

              if jsonb_typeof(v_item->'concept_slugs') = 'array' then
                for v_raw_concept_ref in select jsonb_array_elements_text(v_item->'concept_slugs')
                loop
                  if v_concepts_map ? v_raw_concept_ref then
                    v_resolved_cid := (v_concepts_map->>v_raw_concept_ref)::uuid;
                    insert into public.assessment_item_concepts (assessment_item_id, concept_id)
                    values (v_item_id, v_resolved_cid)
                    on conflict do nothing;
                  end if;
                end loop;
              end if;

              -- Objective Assessment Item Provenance Mapping
              if v_default_rel_id is not null then
                v_entity_rel_id := null;
                if v_item ? 'source_release_id' and v_source_releases_map ? (v_item->>'source_release_id') then
                  v_entity_rel_id := (v_source_releases_map->>(v_item->>'source_release_id'))::uuid;
                elsif v_item ? 'source_id' and v_source_releases_map ? (v_item->>'source_id') then
                  v_entity_rel_id := (v_source_releases_map->>(v_item->>'source_id'))::uuid;
                else
                  v_entity_rel_id := coalesce(v_obj_rel_id, v_default_rel_id);
                end if;

                if v_entity_rel_id is not null then
                  insert into public.content_source_mappings (
                    source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
                  ) values (
                    v_entity_rel_id,
                    'assessment_item',
                    v_item_id,
                    'derived_from',
                    coalesce(v_item->>'citation', coalesce(v_item->>'citation_location', substring(coalesce(v_item->>'prompt', 'Assessment Item') from 1 for 100))),
                    coalesce(v_item->>'notes', 'Assessment item derived from authoritative blueprint'),
                    '{}'::jsonb
                  )
                  on conflict (source_release_id, entity_type, entity_id, relationship) do update
                  set citation_location = excluded.citation_location,
                      notes = excluded.notes,
                      metadata = excluded.metadata
                  returning id into v_mapping_id;

                  v_mappings_count := v_mappings_count + 1;
                  insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
                  values (v_version_id, 'content_source_mapping', v_mapping_id)
                  on conflict do nothing;
                end if;
              end if;
            end loop;
          end if;

          -- Lessons
          if jsonb_typeof(v_obj->'lessons') = 'array' then
            for v_lesson in select * from jsonb_array_elements(v_obj->'lessons')
            loop
              insert into public.lessons (
                title, description, visibility, origin_target_version_id
              ) values (
                v_lesson->>'title',
                coalesce(v_lesson->>'description', v_lesson->>'summary'),
                'public',
                v_version_id
              )
              returning id into v_lesson_id;

              v_lessons_count := v_lessons_count + 1;
              insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
              values (v_version_id, 'lesson', v_lesson_id);

              -- Lesson Source Mapping
              if v_default_rel_id is not null then
                v_entity_rel_id := null;
                if v_lesson ? 'source_release_id' and v_source_releases_map ? (v_lesson->>'source_release_id') then
                  v_entity_rel_id := (v_source_releases_map->>(v_lesson->>'source_release_id'))::uuid;
                elsif v_lesson ? 'source_id' and v_source_releases_map ? (v_lesson->>'source_id') then
                  v_entity_rel_id := (v_source_releases_map->>(v_lesson->>'source_id'))::uuid;
                else
                  v_entity_rel_id := coalesce(
                    (v_source_releases_map->>(v_obj->>'source_release_id'))::uuid,
                    (v_source_releases_map->>(v_obj->>'source_id'))::uuid,
                    coalesce(
                      (v_source_releases_map->>(v_domain->>'source_release_id'))::uuid,
                      (v_source_releases_map->>(v_domain->>'source_id'))::uuid,
                      v_default_rel_id
                    )
                  );
                end if;

                v_lesson_rel_id := v_entity_rel_id;

                if v_entity_rel_id is not null then
                  insert into public.content_source_mappings (
                    source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
                  ) values (
                    v_entity_rel_id,
                    'lesson',
                    v_lesson_id,
                    'derived_from',
                    coalesce(v_lesson->>'citation', coalesce(v_lesson->>'citation_location', coalesce(v_lesson->>'title', 'Lesson'))),
                    coalesce(v_lesson->>'notes', 'Lesson derived from authoritative source'),
                    '{}'::jsonb
                  )
                  on conflict (source_release_id, entity_type, entity_id, relationship) do update
                  set citation_location = excluded.citation_location,
                      notes = excluded.notes,
                      metadata = excluded.metadata
                  returning id into v_mapping_id;

                  v_mappings_count := v_mappings_count + 1;
                  insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
                  values (v_version_id, 'content_source_mapping', v_mapping_id)
                  on conflict do nothing;
                end if;
              end if;

              -- Bind lesson to objective
              insert into public.curriculum_node_lessons (curriculum_node_id, lesson_id, sort_order)
              values (v_obj_id, v_lesson_id, coalesce((v_lesson->>'order_index')::int, 0))
              on conflict do nothing;

              -- Scoped lesson concept linking
              if jsonb_typeof(v_lesson->'concept_ids') = 'array' then
                for v_concept_id in select (jsonb_array_elements_text(v_lesson->'concept_ids'))::uuid
                loop
                  insert into public.lesson_concepts (lesson_id, concept_id)
                  values (v_lesson_id, v_concept_id)
                  on conflict do nothing;
                end loop;
              end if;

              if jsonb_typeof(v_lesson->'concept_slugs') = 'array' then
                for v_raw_concept_ref in select jsonb_array_elements_text(v_lesson->'concept_slugs')
                loop
                  if v_concepts_map ? v_raw_concept_ref then
                    v_resolved_cid := (v_concepts_map->>v_raw_concept_ref)::uuid;
                    insert into public.lesson_concepts (lesson_id, concept_id)
                    values (v_lesson_id, v_resolved_cid)
                    on conflict do nothing;
                  end if;
                end loop;
              end if;

              -- Lesson Blocks
              if jsonb_typeof(v_lesson->'blocks') = 'array' then
                for v_block in select * from jsonb_array_elements(v_lesson->'blocks')
                loop
                  insert into public.lesson_blocks (
                    lesson_id, block_type, content, sort_order
                  ) values (
                    v_lesson_id,
                    coalesce(v_block->>'block_type', 'markdown'),
                    coalesce(v_block->'content', '{}'::jsonb),
                    coalesce((v_block->>'sort_order')::int, 0)
                  )
                  returning id into v_block_id;

                  v_blocks_count := v_blocks_count + 1;
                  insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
                  values (v_version_id, 'lesson_block', v_block_id);

                  -- Lesson Block Provenance Mapping
                  if v_default_rel_id is not null then
                    v_entity_rel_id := null;
                    if v_block ? 'source_release_id' and v_source_releases_map ? (v_block->>'source_release_id') then
                      v_entity_rel_id := (v_source_releases_map->>(v_block->>'source_release_id'))::uuid;
                    elsif v_block ? 'source_id' and v_source_releases_map ? (v_block->>'source_id') then
                      v_entity_rel_id := (v_source_releases_map->>(v_block->>'source_id'))::uuid;
                    else
                      v_entity_rel_id := coalesce(v_lesson_rel_id, v_default_rel_id);
                    end if;

                    if v_entity_rel_id is not null then
                      insert into public.content_source_mappings (
                        source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
                      ) values (
                        v_entity_rel_id,
                        'lesson_block',
                        v_block_id,
                        'derived_from',
                        coalesce(v_block->>'citation', coalesce(v_block->>'citation_location', coalesce(v_lesson->>'title', 'Lesson Block'))),
                        coalesce(v_block->>'notes', 'Lesson content block citation'),
                        '{}'::jsonb
                      )
                      on conflict (source_release_id, entity_type, entity_id, relationship) do update
                      set citation_location = excluded.citation_location,
                          notes = excluded.notes,
                          metadata = excluded.metadata
                      returning id into v_mapping_id;

                      v_mappings_count := v_mappings_count + 1;
                      insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
                      values (v_version_id, 'content_source_mapping', v_mapping_id)
                      on conflict do nothing;
                    end if;
                  end if;
                end loop;
              end if;

              -- Lesson Terms
              if jsonb_typeof(v_lesson->'terms') = 'array' then
                for v_term in select * from jsonb_array_elements(v_lesson->'terms')
                loop
                  insert into public.terms (lesson_id, term, definition)
                  values (v_lesson_id, v_term->>'term', v_term->>'definition');
                end loop;
              end if;

              -- Lesson Questions
              if jsonb_typeof(v_lesson->'questions') = 'array' then
                for v_question in select * from jsonb_array_elements(v_lesson->'questions')
                loop
                  insert into public.questions (
                    lesson_id, question_text, options, correct_answer, type, explanation
                  ) values (
                    v_lesson_id,
                    coalesce(v_question->>'question_text', v_question->>'question'),
                    coalesce(v_question->'options', '[]'::jsonb),
                    coalesce((coalesce(v_question->>'correct_answer', v_question->>'correct_index'))::int, 0),
                    coalesce(v_question->>'type', 'mcq'),
                    v_question->>'explanation'
                  );
                  v_questions_count := v_questions_count + 1;
                end loop;
              end if;

              -- Lesson Assessment Items
              if jsonb_typeof(v_lesson->'assessment_items') = 'array' then
                for v_item in select * from jsonb_array_elements(v_lesson->'assessment_items')
                loop
                  v_stim_key := v_item->>'stimulus_key';
                  v_stim_id := null;
                  if v_stim_key is not null and v_stimuli_map ? v_stim_key then
                    v_stim_id := (v_stimuli_map->>v_stim_key)::uuid;
                  end if;

                  insert into public.assessment_items (
                    lesson_id, stimulus_id, prompt, interaction_type, response_spec, scoring_spec, explanation, origin_target_version_id
                  ) values (
                    v_lesson_id,
                    v_stim_id,
                    v_item->>'prompt',
                    coalesce(v_item->>'interaction_type', 'single_choice'),
                    coalesce(v_item->'response_spec', '{}'::jsonb),
                    coalesce(v_item->'scoring_spec', '{}'::jsonb),
                    v_item->>'explanation',
                    v_version_id
                  )
                  returning id into v_item_id;

                  v_items_count := v_items_count + 1;
                  insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
                  values (v_version_id, 'assessment_item', v_item_id);

                  if jsonb_typeof(v_item->'concept_ids') = 'array' then
                    for v_concept_id in select (jsonb_array_elements_text(v_item->'concept_ids'))::uuid
                    loop
                      insert into public.assessment_item_concepts (assessment_item_id, concept_id)
                      values (v_item_id, v_concept_id)
                      on conflict do nothing;
                    end loop;
                  end if;

                  if jsonb_typeof(v_item->'concept_slugs') = 'array' then
                    for v_raw_concept_ref in select jsonb_array_elements_text(v_item->'concept_slugs')
                    loop
                      if v_concepts_map ? v_raw_concept_ref then
                        v_resolved_cid := (v_concepts_map->>v_raw_concept_ref)::uuid;
                        insert into public.assessment_item_concepts (assessment_item_id, concept_id)
                        values (v_item_id, v_resolved_cid)
                        on conflict do nothing;
                      end if;
                    end loop;
                  end if;

                  -- Lesson Assessment Item Provenance Mapping
                  if v_default_rel_id is not null then
                    v_entity_rel_id := null;
                    if v_item ? 'source_release_id' and v_source_releases_map ? (v_item->>'source_release_id') then
                      v_entity_rel_id := (v_source_releases_map->>(v_item->>'source_release_id'))::uuid;
                    elsif v_item ? 'source_id' and v_source_releases_map ? (v_item->>'source_id') then
                      v_entity_rel_id := (v_source_releases_map->>(v_item->>'source_id'))::uuid;
                    else
                      v_entity_rel_id := coalesce(v_lesson_rel_id, v_default_rel_id);
                    end if;

                    if v_entity_rel_id is not null then
                      insert into public.content_source_mappings (
                        source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
                      ) values (
                        v_entity_rel_id,
                        'assessment_item',
                        v_item_id,
                        'derived_from',
                        coalesce(v_item->>'citation', coalesce(v_item->>'citation_location', substring(coalesce(v_item->>'prompt', 'Lesson Assessment Item') from 1 for 100))),
                        coalesce(v_item->>'notes', 'Lesson assessment item derived from authoritative blueprint'),
                        '{}'::jsonb
                      )
                      on conflict (source_release_id, entity_type, entity_id, relationship) do update
                      set citation_location = excluded.citation_location,
                          notes = excluded.notes,
                          metadata = excluded.metadata
                      returning id into v_mapping_id;

                      v_mappings_count := v_mappings_count + 1;
                      insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
                      values (v_version_id, 'content_source_mapping', v_mapping_id)
                      on conflict do nothing;
                    end if;
                  end if;
                end loop;
              end if;

            end loop;
          end if; -- lessons

        end loop;
      end if; -- objectives

    end loop;
  end if; -- domains

  -- 11. Ingest Explicit Custom Source Mappings
  if jsonb_typeof(payload->'source_mappings') = 'array' then
    for v_source_mapping in select * from jsonb_array_elements(payload->'source_mappings')
    loop
      insert into public.content_source_mappings (
        source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
      ) values (
        (v_source_mapping->>'source_release_id')::uuid,
        v_source_mapping->>'entity_type',
        (v_source_mapping->>'entity_id')::uuid,
        coalesce(v_source_mapping->>'relationship', 'derived_from'),
        coalesce(v_source_mapping->>'citation_location', v_source_mapping->>'section_reference'),
        coalesce(v_source_mapping->>'notes', v_source_mapping->>'citation_text'),
        coalesce(v_source_mapping->'metadata', '{}'::jsonb)
      )
      on conflict (source_release_id, entity_type, entity_id, relationship) do update
      set citation_location = excluded.citation_location,
          notes = excluded.notes,
          metadata = excluded.metadata
      returning id into v_mapping_id;

      v_mappings_count := v_mappings_count + 1;
      insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
      values (v_version_id, 'content_source_mapping', v_mapping_id)
      on conflict do nothing;
    end loop;
  end if;

  -- 12. Ingest Concept Version Mappings
  if jsonb_typeof(payload->'target_version_concept_mappings') = 'array' then
    for v_mapping in select * from jsonb_array_elements(payload->'target_version_concept_mappings')
    loop
      v_from_concept_id := (v_mapping->>'from_concept_id')::uuid;
      v_to_concept_id := case when v_mapping->>'to_concept_id' is not null
                              then (v_mapping->>'to_concept_id')::uuid
                              else null end;

      insert into public.target_version_concept_mappings (
        from_target_version_id, from_concept_id, to_target_version_id, to_concept_id,
        mapping_type, confidence, rationale
      ) values (
        v_version_id,
        v_from_concept_id,
        (v_mapping->>'to_target_version_id')::uuid,
        v_to_concept_id,
        coalesce(v_mapping->>'mapping_type', 'equivalent'),
        case when v_mapping->>'confidence' is not null
             then (v_mapping->>'confidence')::numeric
             else 1.0 end,
        v_mapping->>'rationale'
      )
      on conflict (from_target_version_id, from_concept_id, to_target_version_id, to_concept_id) do update
      set mapping_type = excluded.mapping_type,
          confidence = excluded.confidence,
          rationale = excluded.rationale;
    end loop;
  end if;

  -- 13. Return Ingestion Summary
  return jsonb_build_object(
    'target_version_id', v_version_id,
    'concepts_count', v_concepts_count,
    'domains_count', v_domains_count,
    'objectives_count', v_objectives_count,
    'lessons_count', v_lessons_count,
    'blocks_count', v_blocks_count,
    'assessment_items_count', v_items_count,
    'flashcards_count', v_flashcards_count,
    'stimuli_count', v_stimuli_count,
    'questions_count', v_questions_count,
    'mappings_count', v_mappings_count
  );
end;
$$;

revoke all on function public.ingest_curriculum_manifest(jsonb) from public, anon, authenticated;
grant execute on function public.ingest_curriculum_manifest(jsonb) to service_role;

INSERT INTO supabase_migrations.schema_migrations (version, name) VALUES ('20261006000003', 'phase_c5_final_hardening') ON CONFLICT (version) DO NOTHING;

-- --------------------------------------------------------------------
-- [28/96] Migration: 20261007000000_phase_f_taxonomy_crosswalk.sql
-- --------------------------------------------------------------------
-- ============================================================================
-- Phase F: Full Taxonomy & Crosswalk Expansion Migration
-- Migration: 20261007000000_phase_f_taxonomy_crosswalk.sql
-- Description:
--   1. Adds convenient application view v_target_occupation_mappings joining
--      learning_target_fields to v_field_occupation_mappings.
--   2. Adds RPC resolve_taxonomy_lineage for tracing external taxonomy transitions.
--   3. Adds RPC get_target_crosswalk_occupations for high-performance UI retrieval.
--   4. Seeds representative decennial lineage data (CIP 2010 -> 2020 & SOC 2010 -> 2018).
--   5. Seeds multidisciplinary field bindings in learning_target_fields.
--   6. Seeds lateral field relations in field_relations.
--   7. Configures RLS policies and grants for the new views and RPCs.
-- ============================================================================

-- 1. TARGET OCCUPATION MAPPINGS VIEW
-- Allows direct queries connecting a LearningTarget to related labor occupations
-- through its primary and supporting fields.
create or replace view public.v_target_occupation_mappings as
  select distinct
    ltf.target_id,
    lt.slug as target_slug,
    lt.title as target_title,
    ltf.field_id,
    f.name as field_name,
    f.slug as field_slug,
    ltf.role as field_role,
    ltf.display_order as field_display_order,
    fom.occupation_id,
    fom.classification_system,
    fom.classification_version,
    fom.classification_code,
    fom.occupation_code,
    fom.occupation_title,
    fom.mapping_kind,
    fom.source_release_id
  from public.learning_target_fields ltf
  join public.learning_targets lt on lt.id = ltf.target_id
  join public.fields f on f.id = ltf.field_id
  join public.v_field_occupation_mappings fom on fom.field_id = ltf.field_id;

-- 2. TAXONOMY LINEAGE RESOLUTION RPC
-- Traverses taxonomy_node_lineage to resolve how a historical code transitioned
create or replace function public.resolve_taxonomy_lineage(
  p_source_system text,
  p_from_version text,
  p_from_code text
)
returns table (
  id uuid,
  source_system text,
  from_version text,
  from_code text,
  to_version text,
  to_code text,
  transition_type text,
  notes text,
  created_at timestamptz
) as $$
begin
  return query
  select
    l.id,
    l.source_system,
    l.from_version,
    l.from_code,
    l.to_version,
    l.to_code,
    l.transition_type,
    l.notes,
    l.created_at
  from public.taxonomy_node_lineage l
  where l.source_system = p_source_system
    and l.from_version = p_from_version
    and (l.from_code = p_from_code or (p_from_code is null and l.from_code is null))
  order by l.created_at asc;
end;
$$ language plpgsql stable security definer;

-- 3. TARGET CROSSWALK OCCUPATIONS RPC
-- Fetches enriched occupation cards for a specific learning target
create or replace function public.get_target_crosswalk_occupations(
  p_target_id uuid
)
returns table (
  occupation_id uuid,
  occupation_code text,
  occupation_title text,
  occupation_level text,
  job_zone integer,
  field_id uuid,
  field_name text,
  field_role text,
  mapping_kind text,
  classification_code text,
  classification_title text
) as $$
begin
  return query
  select distinct
    ocn.id as occupation_id,
    ocn.code as occupation_code,
    ocn.title as occupation_title,
    ocn.level as occupation_level,
    ocn.job_zone,
    ltf.field_id,
    f.name as field_name,
    ltf.role as field_role,
    ecom.mapping_kind,
    ecn.code as classification_code,
    ecn.title as classification_title
  from public.learning_target_fields ltf
  join public.fields f on f.id = ltf.field_id
  join public.field_external_classifications fec on fec.field_id = ltf.field_id
  join public.external_classification_nodes ecn on ecn.id = fec.classification_node_id
  join public.external_classification_occupation_mappings ecom on ecom.classification_node_id = ecn.id
  join public.occupation_nodes ocn on ocn.id = ecom.occupation_id
  where ltf.target_id = p_target_id
    and ocn.is_active = true
  order by ltf.role asc, ocn.code asc;
end;
$$ language plpgsql stable security definer;

-- 4. CROSS-TARGET SHARED CONCEPTS RPC
-- Identifies canonical concepts shared between learning targets
create or replace function public.get_cross_target_shared_concepts(
  p_target_a_id uuid,
  p_target_b_id uuid
)
returns table (
  concept_id uuid,
  concept_slug text,
  concept_name text,
  short_definition text,
  emoji text,
  target_a_nodes bigint,
  target_b_nodes bigint
) as $$
begin
  return query
  with target_a_concepts as (
    select distinct cnc.concept_id, count(cnc.curriculum_node_id) as node_count
    from public.curriculum_nodes cn
    join public.target_versions tv on tv.id = cn.target_version_id
    join public.curriculum_node_concepts cnc on cnc.curriculum_node_id = cn.id
    where tv.target_id = p_target_a_id
    group by cnc.concept_id
  ),
  target_b_concepts as (
    select distinct cnc.concept_id, count(cnc.curriculum_node_id) as node_count
    from public.curriculum_nodes cn
    join public.target_versions tv on tv.id = cn.target_version_id
    join public.curriculum_node_concepts cnc on cnc.curriculum_node_id = cn.id
    where tv.target_id = p_target_b_id
    group by cnc.concept_id
  )
  select
    kc.id as concept_id,
    kc.slug as concept_slug,
    kc.name as concept_name,
    kc.short_definition,
    kc.emoji,
    ta.node_count as target_a_nodes,
    tb.node_count as target_b_nodes
  from target_a_concepts ta
  join target_b_concepts tb on tb.concept_id = ta.concept_id
  join public.knowledge_concepts kc on kc.id = ta.concept_id
  order by kc.name asc;
end;
$$ language plpgsql stable security definer;

-- 5. SEED REPRESENTATIVE DECENNIAL TAXONOMY LINEAGE DATA
-- Seed CIP 2010 -> CIP 2020 transitions
insert into public.taxonomy_node_lineage (
  source_system, from_version, from_code, to_version, to_code, transition_type, notes
) values
  ('cip', '2010', '11.0101', '2020', '11.0101', 'unchanged', 'Computer and Information Sciences, General retained across decennial revisions.'),
  ('cip', '2010', '11.0701', '2020', '11.0701', 'unchanged', 'Computer Science core program classification unchanged.'),
  ('cip', '2010', '11.0801', '2020', '11.0801', 'renamed', 'Title updated to Web Page, Digital/Multimedia and Information Resources Design.'),
  ('cip', '2010', null, '2020', '11.0105', 'newly_introduced', 'Human-Centered Technology Design introduced in CIP 2020.'),
  ('cip', '2010', null, '2020', '30.7001', 'newly_introduced', 'Data Science, General introduced under Multi/Interdisciplinary Studies in CIP 2020.'),
  ('cip', '2010', '51.9999', '2020', null, 'deleted', 'Historical obsolete catchall classification sunsetted in CIP 2020.'),
  ('bls_soc', '2010', '15-1132', '2018', '15-1252', 'moved_to', 'Software Developers, Applications recoded to 15-1252 Software Developers.'),
  ('bls_soc', '2010', '15-1133', '2018', '15-1252', 'merged_into', 'Software Developers, Systems Software merged into unified 15-1252 in SOC 2018.'),
  ('bls_soc', '2010', null, '2018', '15-2051', 'newly_introduced', 'Data Scientists formally introduced as detailed occupation in SOC 2018.')
on conflict (source_system, from_version, coalesce(from_code, ''), to_version, coalesce(to_code, ''), transition_type) do nothing;

-- 6. SEED LATERAL FIELD RELATIONS (With Canonical Ordering)
-- Directional relations: interdisciplinary_parent, applied_domain_of
-- Symmetric relations: shares_foundations, cross_disciplinary_partner (requires from_field_id < to_field_id)
do $$
declare
  v_f_cs uuid;
  v_f_math uuid;
  v_f_eng uuid;
  v_f_bio uuid;
  v_f1 uuid;
  v_f2 uuid;
begin
  select id into v_f_cs from public.fields where slug in ('computer-sciences', 'computer-science') limit 1;
  select id into v_f_math from public.fields where slug in ('mathematics-statistics-series', 'mathematics-statistics') limit 1;
  select id into v_f_eng from public.fields where slug in ('engineering-disciplines', 'engineering') limit 1;
  select id into v_f_bio from public.fields where slug in ('biological-biomedical-sciences', 'biological-sciences') limit 1;

  if v_f_cs is not null and v_f_math is not null then
    -- CS & Math share foundations (symmetric: from_id < to_id)
    if v_f_cs < v_f_math then
      v_f1 := v_f_cs; v_f2 := v_f_math;
    else
      v_f1 := v_f_math; v_f2 := v_f_cs;
    end if;
    insert into public.field_relations (from_field_id, to_field_id, relation_type, notes)
    values (v_f1, v_f2, 'shares_foundations', 'Discrete mathematics, logic, and graph theory form mutual theoretical bedrock.')
    on conflict (from_field_id, to_field_id, relation_type) do nothing;
  end if;

  if v_f_cs is not null and v_f_eng is not null then
    -- CS & Engineering cross-disciplinary partners (symmetric: from_id < to_id)
    if v_f_cs < v_f_eng then
      v_f1 := v_f_cs; v_f2 := v_f_eng;
    else
      v_f1 := v_f_eng; v_f2 := v_f_cs;
    end if;
    insert into public.field_relations (from_field_id, to_field_id, relation_type, notes)
    values (v_f1, v_f2, 'cross_disciplinary_partner', 'Computer Systems Engineering bridges digital hardware synthesis and systems programming.')
    on conflict (from_field_id, to_field_id, relation_type) do nothing;
  end if;

  if v_f_bio is not null and v_f_cs is not null then
    -- Bio is an applied domain of CS algorithms in Bioinformatics
    insert into public.field_relations (from_field_id, to_field_id, relation_type, notes)
    values (v_f_bio, v_f_cs, 'applied_domain_of', 'Computational genomics and protein folding algorithms apply CS models to biological systems.')
    on conflict (from_field_id, to_field_id, relation_type) do nothing;
  end if;
end $$;

-- 7. SEED MULTIDISCIPLINARY TARGET FIELD BINDINGS
do $$
declare
  v_t_cs uuid;
  v_t_swe uuid;
  v_t_sec uuid;
  v_f_cs uuid;
  v_f_math uuid;
  v_f_eng uuid;
  v_f_sec uuid;
begin
  select id into v_t_cs from public.learning_targets where slug = 'program-bs-computer-science';
  select id into v_t_swe from public.learning_targets where slug = 'career-software-engineer';
  select id into v_t_sec from public.learning_targets where slug = 'cert-comptia-security-plus';

  select id into v_f_cs from public.fields where slug in ('computer-sciences', 'computer-science') limit 1;
  select id into v_f_math from public.fields where slug in ('mathematics-statistics-series', 'mathematics-statistics') limit 1;
  select id into v_f_eng from public.fields where slug in ('engineering-disciplines', 'engineering') limit 1;
  select id into v_f_sec from public.fields where slug in ('homeland-security-protective') limit 1;

  -- B.S. in Computer Science: Primary CS, Supporting Math
  if v_t_cs is not null and v_f_cs is not null then
    insert into public.learning_target_fields (target_id, field_id, role, display_order)
    values (v_t_cs, v_f_cs, 'primary', 1)
    on conflict (target_id, field_id) do update set role = 'primary', display_order = 1;
  end if;
  if v_t_cs is not null and v_f_math is not null then
    insert into public.learning_target_fields (target_id, field_id, role, display_order)
    values (v_t_cs, v_f_math, 'supporting', 2)
    on conflict (target_id, field_id) do update set role = 'supporting', display_order = 2;
  end if;

  -- Software Engineer Career: Primary CS, Supporting Math & Engineering
  if v_t_swe is not null and v_f_cs is not null then
    insert into public.learning_target_fields (target_id, field_id, role, display_order)
    values (v_t_swe, v_f_cs, 'primary', 1)
    on conflict (target_id, field_id) do update set role = 'primary', display_order = 1;
  end if;
  if v_t_swe is not null and v_f_math is not null then
    insert into public.learning_target_fields (target_id, field_id, role, display_order)
    values (v_t_swe, v_f_math, 'supporting', 2)
    on conflict (target_id, field_id) do update set role = 'supporting', display_order = 2;
  end if;
  if v_t_swe is not null and v_f_eng is not null then
    insert into public.learning_target_fields (target_id, field_id, role, display_order)
    values (v_t_swe, v_f_eng, 'supporting', 3)
    on conflict (target_id, field_id) do update set role = 'supporting', display_order = 3;
  end if;

  -- CompTIA Security+: Primary CS, Supporting Protective Services
  if v_t_sec is not null and v_f_cs is not null then
    insert into public.learning_target_fields (target_id, field_id, role, display_order)
    values (v_t_sec, v_f_cs, 'primary', 1)
    on conflict (target_id, field_id) do update set role = 'primary', display_order = 1;
  end if;
  if v_t_sec is not null and v_f_sec is not null then
    insert into public.learning_target_fields (target_id, field_id, role, display_order)
    values (v_t_sec, v_f_sec, 'supporting', 2)
    on conflict (target_id, field_id) do update set role = 'supporting', display_order = 2;
  end if;
end $$;

-- 8. GRANT PRIVILEGES
revoke all on function public.resolve_taxonomy_lineage(text, text, text) from public;
grant execute on function public.resolve_taxonomy_lineage(text, text, text) to authenticated, anon, service_role;

revoke all on function public.get_target_crosswalk_occupations(uuid) from public;
grant execute on function public.get_target_crosswalk_occupations(uuid) to authenticated, anon, service_role;

revoke all on function public.get_cross_target_shared_concepts(uuid, uuid) from public;
grant execute on function public.get_cross_target_shared_concepts(uuid, uuid) to authenticated, anon, service_role;

INSERT INTO supabase_migrations.schema_migrations (version, name) VALUES ('20261007000000', 'phase_f_taxonomy_crosswalk') ON CONFLICT (version) DO NOTHING;

-- --------------------------------------------------------------------
-- [29/96] Migration: 20261008000000_phase_g_version_governance.sql
-- --------------------------------------------------------------------
-- ============================================================================
-- Migration: 20261008000000_phase_g_version_governance.sql
-- Description: Phase G — Version Migration & Governance Engine
--
-- Features:
--   1. user_version_migration_logs table for audit & progress carry-forward tracking.
--   2. v_target_version_updates view identifying outdated and retired learning contexts.
--   3. evaluate_target_version_migration RPC calculating concept transfer retention.
--   4. migrate_user_context_target_version RPC safely carrying forward evidence and updating context.
--   5. audit_target_version_readiness RPC generating comprehensive QA diagnostic reports.
--   6. publish_target_version and retire_target_version RPCs managing safe lifecycle transitions.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. User Version Migration Logs
-- ----------------------------------------------------------------------------
create table if not exists public.user_version_migration_logs (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null
    references auth.users(id) on delete cascade,
  context_id uuid
    references public.learning_contexts(id) on delete set null,
  from_target_version_id uuid not null
    references public.target_versions(id) on delete cascade,
  to_target_version_id uuid not null
    references public.target_versions(id) on delete cascade,
  transferred_concepts_count integer not null default 0,
  retained_mastery_pct numeric(5,2) not null default 0.00,
  migration_metadata jsonb not null default '{}'::jsonb,
  migrated_at timestamptz not null default now()
);

create index if not exists user_version_migration_logs_user_idx
  on public.user_version_migration_logs(user_id, migrated_at desc);

create index if not exists user_version_migration_logs_context_idx
  on public.user_version_migration_logs(context_id);

alter table public.user_version_migration_logs enable row level security;

drop policy if exists "user_migration_logs_read" on public.user_version_migration_logs;
create policy "user_migration_logs_read" on public.user_version_migration_logs
  for select to authenticated
  using (user_id = auth.uid());

drop policy if exists "user_migration_logs_insert" on public.user_version_migration_logs;
create policy "user_migration_logs_insert" on public.user_version_migration_logs
  for insert to authenticated, anon
  with check (user_id = auth.uid() or auth.uid() is null);

-- ----------------------------------------------------------------------------
-- 2. Version Updates Availability View
-- ----------------------------------------------------------------------------
create or replace view public.v_target_version_updates as
select
  lc.id as context_id,
  lc.user_id,
  lt.id as target_id,
  lt.title as target_title,
  lt.slug as target_slug,
  current_tv.id as current_version_id,
  current_tv.version_code as current_version_code,
  current_tv.title as current_version_title,
  current_tv.status as current_version_status,
  latest_tv.id as latest_version_id,
  latest_tv.version_code as latest_version_code,
  latest_tv.title as latest_version_title,
  latest_tv.status as latest_version_status,
  (latest_tv.id is not null and current_tv.id <> latest_tv.id) as is_outdated,
  (current_tv.status = 'retired') as is_retired
from public.learning_contexts lc
join public.target_versions current_tv on current_tv.id = lc.target_version_id
join public.learning_targets lt on lt.id = current_tv.target_id
left join lateral (
  select tv.id, tv.version_code, tv.title, tv.status
  from public.target_versions tv
  where tv.target_id = lt.id
    and tv.status = 'published'
  order by tv.created_at desc
  limit 1
) latest_tv on true
where lc.root_type = 'target';

-- ----------------------------------------------------------------------------
-- 3. Target Version Concept Transfer Evaluation RPC
-- ----------------------------------------------------------------------------
create or replace function public.evaluate_target_version_migration(
  p_user_id uuid,
  p_from_target_version_id uuid,
  p_to_target_version_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_source_concepts_count integer;
  v_target_concepts_count integer;
  v_mapped_count integer;
  v_retained_count integer;
  v_removed_count integer;
  v_new_concepts_count integer;
  v_avg_weight numeric(5,2);
  v_user_assessed_count integer;
  v_projected_retained_assessed numeric(5,2);
  v_mappings_json jsonb;
begin
  -- Total distinct source concepts in from_target_version
  select count(distinct cnc.concept_id)
  into v_source_concepts_count
  from public.curriculum_node_concepts cnc
  join public.curriculum_nodes cn on cn.id = cnc.curriculum_node_id
  where cn.target_version_id = p_from_target_version_id;

  -- Total distinct target concepts in to_target_version
  select count(distinct cnc.concept_id)
  into v_target_concepts_count
  from public.curriculum_node_concepts cnc
  join public.curriculum_nodes cn on cn.id = cnc.curriculum_node_id
  where cn.target_version_id = p_to_target_version_id;

  -- Count mappings
  select
    count(*),
    count(*) filter (where m.transfer_weight > 0 and m.to_concept_id is not null),
    count(*) filter (where m.mapping_type = 'removed' or m.to_concept_id is null or m.transfer_weight = 0),
    coalesce(round(avg(m.transfer_weight) * 100, 2), 100.00)
  into
    v_mapped_count,
    v_retained_count,
    v_removed_count,
    v_avg_weight
  from public.target_version_concept_mappings m
  where m.from_target_version_id = p_from_target_version_id
    and m.to_target_version_id = p_to_target_version_id;

  -- If no explicit mappings table entries exist, calculate autonomous concept intersection
  if v_mapped_count = 0 and v_source_concepts_count > 0 then
    select count(distinct s.concept_id)
    into v_retained_count
    from (
      select distinct cnc.concept_id
      from public.curriculum_node_concepts cnc
      join public.curriculum_nodes cn on cn.id = cnc.curriculum_node_id
      where cn.target_version_id = p_from_target_version_id
    ) s
    where s.concept_id in (
      select distinct cnc2.concept_id
      from public.curriculum_node_concepts cnc2
      join public.curriculum_nodes cn2 on cn2.id = cnc2.curriculum_node_id
      where cn2.target_version_id = p_to_target_version_id
    );

    v_mapped_count := v_retained_count;
    v_removed_count := greatest(0, v_source_concepts_count - v_retained_count);
    if v_source_concepts_count > 0 then
      v_avg_weight := round((v_retained_count::numeric / v_source_concepts_count::numeric) * 100, 2);
    else
      v_avg_weight := 100.00;
    end if;
  end if;

  v_new_concepts_count := greatest(0, v_target_concepts_count - v_retained_count);

  -- Learner specific assessed concept stats
  if p_user_id is not null then
    select count(distinct ucs.concept_id)
    into v_user_assessed_count
    from public.user_concept_state ucs
    where ucs.user_id = p_user_id
      and ucs.evidence_count > 0
      and ucs.concept_id in (
        select distinct cnc.concept_id
        from public.curriculum_node_concepts cnc
        join public.curriculum_nodes cn on cn.id = cnc.curriculum_node_id
        where cn.target_version_id = p_from_target_version_id
      );

    v_projected_retained_assessed := round((v_user_assessed_count::numeric * (v_avg_weight / 100.0)), 1);
  else
    v_user_assessed_count := 0;
    v_projected_retained_assessed := 0;
  end if;

  -- Mappings detail list
  select coalesce(jsonb_agg(jsonb_build_object(
    'from_concept_id', m.from_concept_id,
    'to_concept_id', m.to_concept_id,
    'mapping_type', m.mapping_type,
    'transfer_weight', m.transfer_weight,
    'from_concept_name', fc.name,
    'to_concept_name', tc.name
  )), '[]'::jsonb)
  into v_mappings_json
  from public.target_version_concept_mappings m
  left join public.knowledge_concepts fc on fc.id = m.from_concept_id
  left join public.knowledge_concepts tc on tc.id = m.to_concept_id
  where m.from_target_version_id = p_from_target_version_id
    and m.to_target_version_id = p_to_target_version_id;

  return jsonb_build_object(
    'from_target_version_id', p_from_target_version_id,
    'to_target_version_id', p_to_target_version_id,
    'total_source_concepts', v_source_concepts_count,
    'total_target_concepts', v_target_concepts_count,
    'mapped_concepts_count', v_mapped_count,
    'retained_concepts_count', v_retained_count,
    'removed_concepts_count', v_removed_count,
    'new_concepts_count', v_new_concepts_count,
    'transfer_retention_pct', v_avg_weight,
    'user_assessed_concepts_count', v_user_assessed_count,
    'projected_retained_assessed_count', v_projected_retained_assessed,
    'concept_mappings', v_mappings_json
  );
end;
$$;

-- ----------------------------------------------------------------------------
-- 4. Target Version Migration Execution RPC
-- ----------------------------------------------------------------------------
create or replace function public.migrate_user_context_target_version(
  p_user_id uuid,
  p_context_id uuid,
  p_to_target_version_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_context record;
  v_from_tv record;
  v_to_tv record;
  v_mapping record;
  v_transferred_count integer := 0;
  v_evaluation jsonb;
  v_retention_pct numeric(5,2) := 100.00;
begin
  -- 1. Authorization check
  if auth.uid() is not null and auth.uid() <> p_user_id then
    raise exception 'Unauthorized: cannot migrate context for another user.';
  end if;

  -- 2. Verify context exists and belongs to user
  select * into v_context
  from public.learning_contexts
  where id = p_context_id and user_id = p_user_id;

  if not found then
    raise exception 'Learning context not found or does not belong to user.';
  end if;

  -- 3. Verify target versions
  select * into v_from_tv
  from public.target_versions
  where id = v_context.target_version_id;

  select * into v_to_tv
  from public.target_versions
  where id = p_to_target_version_id;

  if not found then
    raise exception 'Destination target version not found.';
  end if;

  -- Target versions must belong to same target
  if v_from_tv.target_id <> v_to_tv.target_id then
    raise exception 'Cannot migrate context across different learning targets.';
  end if;

  -- Destination must be published (or user is author/reviewer)
  if v_to_tv.status not in ('published', 'review_ready') then
    raise exception 'Cannot migrate to target version with status "%".', v_to_tv.status;
  end if;

  -- 4. Evaluate concept transfer
  v_evaluation := public.evaluate_target_version_migration(
    p_user_id,
    v_from_tv.id,
    v_to_tv.id
  );
  v_retention_pct := coalesce((v_evaluation->>'transfer_retention_pct')::numeric, 100.00);

  -- 5. Carry forward concept retrieval evidence according to mappings
  for v_mapping in
    select
      m.from_concept_id,
      m.to_concept_id,
      m.transfer_weight
    from public.target_version_concept_mappings m
    where m.from_target_version_id = v_from_tv.id
      and m.to_target_version_id = v_to_tv.id
      and m.to_concept_id is not null
      and m.transfer_weight > 0
  loop
    -- Scale evidence from from_concept to to_concept if different
    if v_mapping.from_concept_id <> v_mapping.to_concept_id then
      insert into public.user_concept_state (
        user_id,
        concept_id,
        retrieval_band,
        confidence,
        evidence_count,
        weighted_correct,
        weighted_total,
        last_evidence_at,
        updated_at
      )
      select
        p_user_id,
        v_mapping.to_concept_id,
        ucs.retrieval_band,
        ucs.confidence,
        round(ucs.evidence_count * v_mapping.transfer_weight)::integer,
        ucs.weighted_correct * v_mapping.transfer_weight,
        ucs.weighted_total * v_mapping.transfer_weight,
        ucs.last_evidence_at,
        now()
      from public.user_concept_state ucs
      where ucs.user_id = p_user_id
        and ucs.concept_id = v_mapping.from_concept_id
        and ucs.evidence_count > 0
      on conflict (user_id, concept_id) do update set
        evidence_count = greatest(user_concept_state.evidence_count, excluded.evidence_count),
        weighted_correct = greatest(user_concept_state.weighted_correct, excluded.weighted_correct),
        weighted_total = greatest(user_concept_state.weighted_total, excluded.weighted_total),
        last_evidence_at = coalesce(excluded.last_evidence_at, user_concept_state.last_evidence_at),
        updated_at = now();

      v_transferred_count := v_transferred_count + 1;
    else
      -- Unchanged concept: evidence is already canonical and preserved
      v_transferred_count := v_transferred_count + 1;
    end if;
  end loop;

  -- 6. Update context active target version
  update public.learning_contexts
  set
    target_version_id = v_to_tv.id,
    updated_at = now()
  where id = p_context_id;

  -- 7. Reset obsolete resume pointer if pointing to prior version node
  update public.resume_pointers
  set
    curriculum_node_id = null,
    updated_at = now()
  where context_id = p_context_id
    and curriculum_node_id is not null
    and not exists (
      select 1 from public.curriculum_nodes cn
      where cn.id = resume_pointers.curriculum_node_id
        and cn.target_version_id = v_to_tv.id
    );

  -- 8. Record audit log
  insert into public.user_version_migration_logs (
    user_id,
    context_id,
    from_target_version_id,
    to_target_version_id,
    transferred_concepts_count,
    retained_mastery_pct,
    migration_metadata
  )
  values (
    p_user_id,
    p_context_id,
    v_from_tv.id,
    v_to_tv.id,
    v_transferred_count,
    v_retention_pct,
    jsonb_build_object(
      'from_version_code', v_from_tv.version_code,
      'to_version_code', v_to_tv.version_code,
      'evaluation', v_evaluation
    )
  );

  return jsonb_build_object(
    'success', true,
    'context_id', p_context_id,
    'from_version_code', v_from_tv.version_code,
    'to_version_code', v_to_tv.version_code,
    'transferred_concepts_count', v_transferred_count,
    'retained_mastery_pct', v_retention_pct
  );
end;
$$;

-- ----------------------------------------------------------------------------
-- 5. QA Blueprint Audit RPC (audit_target_version_readiness)
-- ----------------------------------------------------------------------------
create or replace function public.audit_target_version_readiness(
  p_target_version_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_tv record;
  v_domain_count integer := 0;
  v_objective_count integer := 0;
  v_leaf_objective_count integer := 0;
  v_domain_weight_sum numeric(7,3) := 0.0;
  v_is_weight_balanced boolean := false;
  v_lesson_count integer := 0;
  v_lesson_block_count integer := 0;
  v_stimulus_count integer := 0;
  v_assessment_item_count integer := 0;
  v_empty_objectives_count integer := 0;
  v_concept_count integer := 0;
  v_unassessed_concept_count integer := 0;
  v_provenance_citations_count integer := 0;
  v_missing_provenance_count integer := 0;
  v_cross_version_mappings_count integer := 0;
  v_can_stage_review boolean := false;
  v_can_publish boolean := false;
  v_blockers text[] := '{}';
  v_warnings text[] := '{}';
begin
  select tv.*, lt.title as target_title
  into v_tv
  from public.target_versions tv
  join public.learning_targets lt on lt.id = tv.target_id
  where tv.id = p_target_version_id;

  if not found then
    raise exception 'Target version not found: %', p_target_version_id;
  end if;

  -- 1. Domain and objective counts
  select
    count(*) filter (where cn.parent_id is null),
    count(*),
    coalesce(sum(cn.weight) filter (where cn.parent_id is null), 0.0)
  into
    v_domain_count,
    v_objective_count,
    v_domain_weight_sum
  from public.curriculum_nodes cn
  where cn.target_version_id = p_target_version_id;

  -- Leaf objectives
  select count(*)
  into v_leaf_objective_count
  from public.curriculum_nodes cn
  where cn.target_version_id = p_target_version_id
    and not exists (
      select 1 from public.curriculum_nodes child
      where child.parent_id = cn.id
    );

  -- Domain weight validation (must sum to ~100.0 or ~1.0, or 0.0 if unweighted)
  if v_domain_weight_sum = 0.0 then
    v_is_weight_balanced := true;
    v_warnings := array_append(v_warnings, 'Domains are unweighted (sum is 0.0).');
  elsif abs(v_domain_weight_sum - 100.0) < 0.1 or abs(v_domain_weight_sum - 1.0) < 0.01 then
    v_is_weight_balanced := true;
  else
    v_is_weight_balanced := false;
    v_blockers := array_append(v_blockers, format('Domain weights sum to %s%% (expected 100.0%%).', v_domain_weight_sum));
  end if;

  -- 2. Lesson and Content Metrics
  select count(distinct cnl.lesson_id)
  into v_lesson_count
  from public.curriculum_node_lessons cnl
  join public.curriculum_nodes cn on cn.id = cnl.curriculum_node_id
  where cn.target_version_id = p_target_version_id;

  select count(*)
  into v_lesson_block_count
  from public.lesson_blocks lb
  where lb.lesson_id in (
    select distinct cnl.lesson_id
    from public.curriculum_node_lessons cnl
    join public.curriculum_nodes cn on cn.id = cnl.curriculum_node_id
    where cn.target_version_id = p_target_version_id
  );

  -- 3. Assessment and Stimulus Metrics
  select count(*)
  into v_stimulus_count
  from public.assessment_stimuli
  where origin_target_version_id = p_target_version_id;

  select count(*)
  into v_assessment_item_count
  from public.assessment_items ai
  where ai.origin_target_version_id = p_target_version_id
     or ai.lesson_id in (
       select distinct cnl.lesson_id
       from public.curriculum_node_lessons cnl
       join public.curriculum_nodes cn on cn.id = cnl.curriculum_node_id
       where cn.target_version_id = p_target_version_id
     );

  -- 4. Empty leaf objectives (neither lesson nor question bound)
  select count(*)
  into v_empty_objectives_count
  from public.curriculum_nodes cn
  where cn.target_version_id = p_target_version_id
    and not exists (
      select 1 from public.curriculum_nodes child where child.parent_id = cn.id
    )
    and not exists (
      select 1 from public.curriculum_node_lessons cnl where cnl.curriculum_node_id = cn.id
    )
    and not exists (
      select 1 from public.curriculum_node_concepts cnc
      join public.assessment_item_concepts aic on aic.concept_id = cnc.concept_id
      where cnc.curriculum_node_id = cn.id
    );

  if v_empty_objectives_count > 0 then
    v_warnings := array_append(v_warnings, format('%s leaf objective(s) have no lessons or assessment items bound.', v_empty_objectives_count));
  end if;

  -- 5. Concept Coverage & Assessment Gap
  select count(distinct cnc.concept_id)
  into v_concept_count
  from public.curriculum_node_concepts cnc
  join public.curriculum_nodes cn on cn.id = cnc.curriculum_node_id
  where cn.target_version_id = p_target_version_id;

  select count(distinct cnc.concept_id)
  into v_unassessed_concept_count
  from public.curriculum_node_concepts cnc
  join public.curriculum_nodes cn on cn.id = cnc.curriculum_node_id
  where cn.target_version_id = p_target_version_id
    and not exists (
      select 1 from public.assessment_item_concepts aic
      where aic.concept_id = cnc.concept_id
    );

  if v_unassessed_concept_count > 0 then
    v_warnings := array_append(v_warnings, format('%s concept(s) have no direct assessment items.', v_unassessed_concept_count));
  end if;

  -- 6. Provenance & Citations
  select count(*)
  into v_provenance_citations_count
  from public.content_source_mappings
  where target_version_id = p_target_version_id;

  select count(*)
  into v_missing_provenance_count
  from public.curriculum_nodes cn
  where cn.target_version_id = p_target_version_id
    and not exists (
      select 1 from public.content_source_mappings csm
      where csm.curriculum_node_id = cn.id
    );

  if v_missing_provenance_count > 0 then
    v_warnings := array_append(v_warnings, format('%s curriculum node(s) have no official source citation.', v_missing_provenance_count));
  end if;

  -- 7. Cross-Version Mapping Count
  select count(*)
  into v_cross_version_mappings_count
  from public.target_version_concept_mappings
  where from_target_version_id = p_target_version_id
     or to_target_version_id = p_target_version_id;

  -- 8. Gating Criteria
  if v_domain_count = 0 then
    v_blockers := array_append(v_blockers, 'Target version has no domains (root curriculum nodes).');
  end if;

  if v_objective_count = 0 then
    v_blockers := array_append(v_blockers, 'Target version has no objectives.');
  end if;

  v_can_stage_review := (v_domain_count > 0 and v_objective_count > 0 and (v_lesson_count > 0 or v_assessment_item_count > 0));
  v_can_publish := (v_tv.status = 'review_ready' and v_is_weight_balanced and array_length(v_blockers, 1) is null);

  return jsonb_build_object(
    'target_version_id', v_tv.id,
    'version_code', v_tv.version_code,
    'status', v_tv.status,
    'target_title', v_tv.target_title,
    'domain_count', v_domain_count,
    'objective_count', v_objective_count,
    'leaf_objective_count', v_leaf_objective_count,
    'domain_weight_sum', v_domain_weight_sum,
    'is_domain_weight_balanced', v_is_weight_balanced,
    'lesson_count', v_lesson_count,
    'lesson_block_count', v_lesson_block_count,
    'stimulus_count', v_stimulus_count,
    'assessment_item_count', v_assessment_item_count,
    'empty_objectives_count', v_empty_objectives_count,
    'concept_coverage_count', v_concept_count,
    'unassessed_concepts_count', v_unassessed_concept_count,
    'provenance_citations_count', v_provenance_citations_count,
    'missing_provenance_count', v_missing_provenance_count,
    'cross_version_mappings_count', v_cross_version_mappings_count,
    'can_stage_review', v_can_stage_review,
    'can_publish', v_can_publish,
    'blocking_issues', to_jsonb(v_blockers),
    'warnings', to_jsonb(v_warnings)
  );
end;
$$;

-- ----------------------------------------------------------------------------
-- 6. Target Version Publishing & Retirement RPCs
-- ----------------------------------------------------------------------------
create or replace function public.publish_target_version(
  p_version_id uuid,
  p_retire_previous boolean default false
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_tv record;
  v_retired_ids uuid[] := '{}';
  v_ret record;
begin
  select * into v_tv
  from public.target_versions
  where id = p_version_id;

  if not found then
    raise exception 'Target version not found: %', p_version_id;
  end if;

  if v_tv.status = 'published' then
    return jsonb_build_object(
      'success', true,
      'target_version_id', p_version_id,
      'status', 'published',
      'already_published', true,
      'retired_version_ids', '[]'::jsonb,
      'retired_previous_count', 0
    );
  end if;

  if v_tv.status not in ('draft', 'review_ready') then
    raise exception 'Cannot publish target version in status "%".', v_tv.status;
  end if;

  -- 1. If in draft, transition through review_ready
  if v_tv.status = 'draft' then
    update public.target_versions
    set status = 'review_ready', updated_at = now()
    where id = p_version_id;
  end if;

  -- 2. Retire prior published versions if requested
  if p_retire_previous then
    for v_ret in
      select id from public.target_versions
      where target_id = v_tv.target_id
        and status = 'published'
        and id <> p_version_id
    loop
      update public.target_versions
      set status = 'retired', updated_at = now()
      where id = v_ret.id;
      v_retired_ids := array_append(v_retired_ids, v_ret.id);
    end loop;
  end if;

  -- 3. Publish destination version
  update public.target_versions
  set status = 'published', updated_at = now()
  where id = p_version_id;

  -- 4. Ensure parent target is published and public
  update public.learning_targets
  set status = 'published', is_public = true, updated_at = now()
  where id = v_tv.target_id;

  return jsonb_build_object(
    'success', true,
    'target_version_id', p_version_id,
    'status', 'published',
    'already_published', false,
    'retired_version_ids', to_jsonb(v_retired_ids),
    'retired_previous_count', coalesce(array_length(v_retired_ids, 1), 0)
  );
end;
$$;

create or replace function public.retire_target_version(
  p_version_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_tv record;
begin
  select * into v_tv
  from public.target_versions
  where id = p_version_id;

  if not found then
    raise exception 'Target version not found: %', p_version_id;
  end if;

  if v_tv.status = 'retired' then
    return jsonb_build_object(
      'success', true,
      'target_version_id', p_version_id,
      'status', 'retired',
      'already_retired', true
    );
  end if;

  if v_tv.status <> 'published' then
    raise exception 'Cannot retire target version in status "%". Only published versions can be retired.', v_tv.status;
  end if;

  update public.target_versions
  set status = 'retired', updated_at = now()
  where id = p_version_id;

  return jsonb_build_object(
    'success', true,
    'target_version_id', p_version_id,
    'status', 'retired',
    'already_retired', false
  );
end;
$$;

INSERT INTO supabase_migrations.schema_migrations (version, name) VALUES ('20261008000000', 'phase_g_version_governance') ON CONFLICT (version) DO NOTHING;

-- --------------------------------------------------------------------
-- [30/96] Migration: 20261008000001_phase_g_security_hardening.sql
-- --------------------------------------------------------------------
-- ============================================================================
-- Phase G.5: Version Governance Security & Integrity Hardening
-- Migration: 20261008000001_phase_g_security_hardening.sql
--
-- Restores the authorization invariants established during Phase C.5 and
-- makes governance functions fail closed. This follow-up migration is
-- intentionally additive so already-migrated environments receive the fix.
-- ============================================================================

-- Governance audit rows are written only by the SECURITY DEFINER migration RPC.
drop policy if exists "user_migration_logs_insert" on public.user_version_migration_logs;
grant select on table public.user_version_migration_logs to authenticated;

-- The view must honor the RLS policies of learning_contexts/target_versions.
alter view public.v_target_version_updates set (security_invoker = true);
grant select on public.v_target_version_updates to authenticated;

-- ----------------------------------------------------------------------------
-- 1. Migration evaluation: authenticated users may inspect only their own
-- learner evidence. service_role may evaluate any user.
-- ----------------------------------------------------------------------------
create or replace function public.evaluate_target_version_migration(
  p_user_id uuid,
  p_from_target_version_id uuid,
  p_to_target_version_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_source_concepts_count integer;
  v_target_concepts_count integer;
  v_mapped_count integer;
  v_retained_count integer;
  v_removed_count integer;
  v_new_concepts_count integer;
  v_avg_weight numeric(5,2);
  v_user_assessed_count integer;
  v_projected_retained_assessed numeric(5,2);
  v_mappings_json jsonb;
  v_from_tv record;
  v_to_tv record;
  v_target_owner uuid;
  v_can_preview boolean := false;
begin
  if coalesce(auth.role(), '') <> 'service_role'
     and (auth.uid() is null or p_user_id is null or auth.uid() <> p_user_id) then
    raise exception 'Unauthorized: cannot evaluate migration evidence for another user.';
  end if;

  select * into v_from_tv
  from public.target_versions
  where id = p_from_target_version_id;

  if not found then
    raise exception 'Source target version not found.';
  end if;

  select tv.*, lt.created_by as target_owner
  into v_to_tv
  from public.target_versions tv
  join public.learning_targets lt on lt.id = tv.target_id
  where tv.id = p_to_target_version_id;

  if not found then
    raise exception 'Destination target version not found.';
  end if;

  if v_from_tv.target_id <> v_to_tv.target_id then
    raise exception 'Cannot evaluate migration across different learning targets.';
  end if;

  v_target_owner := v_to_tv.target_owner;
  if coalesce(auth.role(), '') = 'service_role' then
    v_can_preview := true;
  elsif auth.uid() is not null then
    v_can_preview :=
      v_target_owner = auth.uid()
      or public.is_target_reviewer(v_to_tv.target_id);
  end if;

  if v_to_tv.status <> 'published' and not v_can_preview then
    raise exception 'Unauthorized: destination target version is not published for this caller.';
  end if;

  select count(distinct cnc.concept_id)
  into v_source_concepts_count
  from public.curriculum_node_concepts cnc
  join public.curriculum_nodes cn on cn.id = cnc.curriculum_node_id
  where cn.target_version_id = p_from_target_version_id;

  select count(distinct cnc.concept_id)
  into v_target_concepts_count
  from public.curriculum_node_concepts cnc
  join public.curriculum_nodes cn on cn.id = cnc.curriculum_node_id
  where cn.target_version_id = p_to_target_version_id;

  select
    count(*),
    count(*) filter (where m.transfer_weight > 0 and m.to_concept_id is not null),
    count(*) filter (
      where m.mapping_type = 'removed'
         or m.to_concept_id is null
         or m.transfer_weight = 0
    ),
    coalesce(round(avg(m.transfer_weight) * 100, 2), 100.00)
  into
    v_mapped_count,
    v_retained_count,
    v_removed_count,
    v_avg_weight
  from public.target_version_concept_mappings m
  where m.from_target_version_id = p_from_target_version_id
    and m.to_target_version_id = p_to_target_version_id;

  if v_mapped_count = 0 and v_source_concepts_count > 0 then
    select count(distinct s.concept_id)
    into v_retained_count
    from (
      select distinct cnc.concept_id
      from public.curriculum_node_concepts cnc
      join public.curriculum_nodes cn on cn.id = cnc.curriculum_node_id
      where cn.target_version_id = p_from_target_version_id
    ) s
    where s.concept_id in (
      select distinct cnc2.concept_id
      from public.curriculum_node_concepts cnc2
      join public.curriculum_nodes cn2 on cn2.id = cnc2.curriculum_node_id
      where cn2.target_version_id = p_to_target_version_id
    );

    v_mapped_count := v_retained_count;
    v_removed_count := greatest(0, v_source_concepts_count - v_retained_count);
    v_avg_weight := round(
      (v_retained_count::numeric / v_source_concepts_count::numeric) * 100,
      2
    );
  end if;

  v_new_concepts_count := greatest(0, v_target_concepts_count - v_retained_count);

  select count(distinct ucs.concept_id)
  into v_user_assessed_count
  from public.user_concept_state ucs
  where ucs.user_id = p_user_id
    and ucs.evidence_count > 0
    and ucs.concept_id in (
      select distinct cnc.concept_id
      from public.curriculum_node_concepts cnc
      join public.curriculum_nodes cn on cn.id = cnc.curriculum_node_id
      where cn.target_version_id = p_from_target_version_id
    );

  v_projected_retained_assessed :=
    round((v_user_assessed_count::numeric * (v_avg_weight / 100.0)), 1);

  select coalesce(jsonb_agg(jsonb_build_object(
    'from_concept_id', m.from_concept_id,
    'to_concept_id', m.to_concept_id,
    'mapping_type', m.mapping_type,
    'transfer_weight', m.transfer_weight,
    'from_concept_name', fc.name,
    'to_concept_name', tc.name
  )), '[]'::jsonb)
  into v_mappings_json
  from public.target_version_concept_mappings m
  left join public.knowledge_concepts fc on fc.id = m.from_concept_id
  left join public.knowledge_concepts tc on tc.id = m.to_concept_id
  where m.from_target_version_id = p_from_target_version_id
    and m.to_target_version_id = p_to_target_version_id;

  return jsonb_build_object(
    'from_target_version_id', p_from_target_version_id,
    'to_target_version_id', p_to_target_version_id,
    'total_source_concepts', v_source_concepts_count,
    'total_target_concepts', v_target_concepts_count,
    'mapped_concepts_count', v_mapped_count,
    'retained_concepts_count', v_retained_count,
    'removed_concepts_count', v_removed_count,
    'new_concepts_count', v_new_concepts_count,
    'transfer_retention_pct', v_avg_weight,
    'user_assessed_concepts_count', v_user_assessed_count,
    'projected_retained_assessed_count', v_projected_retained_assessed,
    'concept_mappings', v_mappings_json
  );
end;
$$;

-- ----------------------------------------------------------------------------
-- 2. User-context migration: self only (or service_role). Review-ready
-- destinations are restricted to target owners/reviewers.
-- ----------------------------------------------------------------------------
create or replace function public.migrate_user_context_target_version(
  p_user_id uuid,
  p_context_id uuid,
  p_to_target_version_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_context record;
  v_from_tv record;
  v_to_tv record;
  v_mapping record;
  v_transferred_count integer := 0;
  v_evaluation jsonb;
  v_retention_pct numeric(5,2) := 100.00;
  v_is_privileged_editor boolean := false;
begin
  if coalesce(auth.role(), '') <> 'service_role'
     and (auth.uid() is null or auth.uid() <> p_user_id) then
    raise exception 'Unauthorized: cannot migrate context for another user.';
  end if;

  select * into v_context
  from public.learning_contexts
  where id = p_context_id and user_id = p_user_id;

  if not found then
    raise exception 'Learning context not found or does not belong to user.';
  end if;

  select * into v_from_tv
  from public.target_versions
  where id = v_context.target_version_id;

  if not found then
    raise exception 'Current target version not found.';
  end if;

  select * into v_to_tv
  from public.target_versions
  where id = p_to_target_version_id;

  if not found then
    raise exception 'Destination target version not found.';
  end if;

  if v_from_tv.target_id <> v_to_tv.target_id then
    raise exception 'Cannot migrate context across different learning targets.';
  end if;

  if coalesce(auth.role(), '') = 'service_role' then
    v_is_privileged_editor := true;
  elsif auth.uid() is not null then
    select exists (
      select 1
      from public.learning_targets lt
      where lt.id = v_to_tv.target_id
        and lt.created_by = auth.uid()
    ) or public.is_target_reviewer(v_to_tv.target_id)
    into v_is_privileged_editor;
  end if;

  if v_to_tv.status = 'published' then
    null;
  elsif v_to_tv.status = 'review_ready' and v_is_privileged_editor then
    null;
  else
    raise exception 'Cannot migrate to target version with status "%" for this caller.', v_to_tv.status;
  end if;

  v_evaluation := public.evaluate_target_version_migration(
    p_user_id,
    v_from_tv.id,
    v_to_tv.id
  );
  v_retention_pct :=
    coalesce((v_evaluation->>'transfer_retention_pct')::numeric, 100.00);

  for v_mapping in
    select
      m.from_concept_id,
      m.to_concept_id,
      m.transfer_weight
    from public.target_version_concept_mappings m
    where m.from_target_version_id = v_from_tv.id
      and m.to_target_version_id = v_to_tv.id
      and m.to_concept_id is not null
      and m.transfer_weight > 0
  loop
    if v_mapping.from_concept_id <> v_mapping.to_concept_id then
      insert into public.user_concept_state (
        user_id,
        concept_id,
        retrieval_band,
        confidence,
        evidence_count,
        weighted_correct,
        weighted_total,
        last_evidence_at,
        updated_at
      )
      select
        p_user_id,
        v_mapping.to_concept_id,
        ucs.retrieval_band,
        ucs.confidence,
        round(ucs.evidence_count * v_mapping.transfer_weight)::integer,
        ucs.weighted_correct * v_mapping.transfer_weight,
        ucs.weighted_total * v_mapping.transfer_weight,
        ucs.last_evidence_at,
        now()
      from public.user_concept_state ucs
      where ucs.user_id = p_user_id
        and ucs.concept_id = v_mapping.from_concept_id
        and ucs.evidence_count > 0
      on conflict (user_id, concept_id) do update set
        evidence_count = greatest(
          public.user_concept_state.evidence_count,
          excluded.evidence_count
        ),
        weighted_correct = greatest(
          public.user_concept_state.weighted_correct,
          excluded.weighted_correct
        ),
        weighted_total = greatest(
          public.user_concept_state.weighted_total,
          excluded.weighted_total
        ),
        last_evidence_at = coalesce(
          excluded.last_evidence_at,
          public.user_concept_state.last_evidence_at
        ),
        updated_at = now();
    end if;

    v_transferred_count := v_transferred_count + 1;
  end loop;

  update public.learning_contexts
  set
    target_version_id = v_to_tv.id,
    updated_at = now()
  where id = p_context_id;

  -- Resume pointers are disposable breadcrumbs and carry activity IDs rather
  -- than curriculum-node foreign keys. A target-version migration can make the
  -- saved lesson/study-set position stale, so clear the pointer atomically.
  delete from public.resume_pointers
  where context_id = p_context_id;

  insert into public.user_version_migration_logs (
    user_id,
    context_id,
    from_target_version_id,
    to_target_version_id,
    transferred_concepts_count,
    retained_mastery_pct,
    migration_metadata
  )
  values (
    p_user_id,
    p_context_id,
    v_from_tv.id,
    v_to_tv.id,
    v_transferred_count,
    v_retention_pct,
    jsonb_build_object(
      'from_version_code', v_from_tv.version_code,
      'to_version_code', v_to_tv.version_code,
      'evaluation', v_evaluation
    )
  );

  return jsonb_build_object(
    'success', true,
    'context_id', p_context_id,
    'from_version_code', v_from_tv.version_code,
    'to_version_code', v_to_tv.version_code,
    'transferred_concepts_count', v_transferred_count,
    'retained_mastery_pct', v_retention_pct
  );
end;
$$;

-- ----------------------------------------------------------------------------
-- 3. Audit: draft/review governance data is available only to the target owner,
-- assigned reviewers, or service_role.
-- ----------------------------------------------------------------------------
create or replace function public.audit_target_version_readiness(
  p_target_version_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_tv record;
  v_domain_count integer := 0;
  v_objective_count integer := 0;
  v_leaf_objective_count integer := 0;
  v_domain_weight_sum numeric(7,3) := 0.0;
  v_is_weight_balanced boolean := false;
  v_lesson_count integer := 0;
  v_lesson_block_count integer := 0;
  v_stimulus_count integer := 0;
  v_assessment_item_count integer := 0;
  v_empty_objectives_count integer := 0;
  v_concept_count integer := 0;
  v_unassessed_concept_count integer := 0;
  v_provenance_citations_count integer := 0;
  v_missing_provenance_count integer := 0;
  v_cross_version_mappings_count integer := 0;
  v_can_stage_review boolean := false;
  v_can_publish boolean := false;
  v_blockers text[] := '{}';
  v_warnings text[] := '{}';
begin
  select tv.*, lt.title as target_title, lt.created_by as target_owner
  into v_tv
  from public.target_versions tv
  join public.learning_targets lt on lt.id = tv.target_id
  where tv.id = p_target_version_id;

  if not found then
    raise exception 'Target version not found: %', p_target_version_id;
  end if;

  if coalesce(auth.role(), '') <> 'service_role'
     and (
       auth.uid() is null
       or (
         v_tv.target_owner is distinct from auth.uid()
         and not public.is_target_reviewer(v_tv.target_id)
       )
     ) then
    raise exception 'Unauthorized: only service_role, target owner, or assigned reviewer may audit a target version.';
  end if;

  select
    count(*) filter (where cn.parent_id is null),
    count(*),
    coalesce(sum(cn.weight) filter (where cn.parent_id is null), 0.0)
  into
    v_domain_count,
    v_objective_count,
    v_domain_weight_sum
  from public.curriculum_nodes cn
  where cn.target_version_id = p_target_version_id;

  select count(*)
  into v_leaf_objective_count
  from public.curriculum_nodes cn
  where cn.target_version_id = p_target_version_id
    and not exists (
      select 1 from public.curriculum_nodes child
      where child.parent_id = cn.id
    );

  if v_domain_weight_sum = 0.0 then
    v_is_weight_balanced := true;
    v_warnings := array_append(v_warnings, 'Domains are unweighted (sum is 0.0).');
  elsif abs(v_domain_weight_sum - 100.0) < 0.1
     or abs(v_domain_weight_sum - 1.0) < 0.01 then
    v_is_weight_balanced := true;
  else
    v_is_weight_balanced := false;
    v_blockers := array_append(
      v_blockers,
      format('Domain weights sum to %s%% (expected 100.0%%).', v_domain_weight_sum)
    );
  end if;

  select count(distinct cnl.lesson_id)
  into v_lesson_count
  from public.curriculum_node_lessons cnl
  join public.curriculum_nodes cn on cn.id = cnl.curriculum_node_id
  where cn.target_version_id = p_target_version_id;

  select count(*)
  into v_lesson_block_count
  from public.lesson_blocks lb
  where lb.lesson_id in (
    select distinct cnl.lesson_id
    from public.curriculum_node_lessons cnl
    join public.curriculum_nodes cn on cn.id = cnl.curriculum_node_id
    where cn.target_version_id = p_target_version_id
  );

  select count(*)
  into v_stimulus_count
  from public.assessment_stimuli
  where origin_target_version_id = p_target_version_id;

  select count(*)
  into v_assessment_item_count
  from public.assessment_items ai
  where ai.origin_target_version_id = p_target_version_id
     or ai.lesson_id in (
       select distinct cnl.lesson_id
       from public.curriculum_node_lessons cnl
       join public.curriculum_nodes cn on cn.id = cnl.curriculum_node_id
       where cn.target_version_id = p_target_version_id
     );

  select count(*)
  into v_empty_objectives_count
  from public.curriculum_nodes cn
  where cn.target_version_id = p_target_version_id
    and not exists (
      select 1 from public.curriculum_nodes child where child.parent_id = cn.id
    )
    and not exists (
      select 1 from public.curriculum_node_lessons cnl
      where cnl.curriculum_node_id = cn.id
    )
    and not exists (
      select 1
      from public.curriculum_node_concepts cnc
      join public.assessment_item_concepts aic
        on aic.concept_id = cnc.concept_id
      where cnc.curriculum_node_id = cn.id
    );

  if v_empty_objectives_count > 0 then
    v_warnings := array_append(
      v_warnings,
      format(
        '%s leaf objective(s) have no lessons or assessment items bound.',
        v_empty_objectives_count
      )
    );
  end if;

  select count(distinct cnc.concept_id)
  into v_concept_count
  from public.curriculum_node_concepts cnc
  join public.curriculum_nodes cn on cn.id = cnc.curriculum_node_id
  where cn.target_version_id = p_target_version_id;

  select count(distinct cnc.concept_id)
  into v_unassessed_concept_count
  from public.curriculum_node_concepts cnc
  join public.curriculum_nodes cn on cn.id = cnc.curriculum_node_id
  where cn.target_version_id = p_target_version_id
    and not exists (
      select 1 from public.assessment_item_concepts aic
      where aic.concept_id = cnc.concept_id
    );

  if v_unassessed_concept_count > 0 then
    v_warnings := array_append(
      v_warnings,
      format('%s concept(s) have no direct assessment items.', v_unassessed_concept_count)
    );
  end if;

  select count(*)
  into v_provenance_citations_count
  from public.content_source_mappings csm
  where
    (csm.entity_type = 'target_version' and csm.entity_id = p_target_version_id)
    or (
      csm.entity_type = 'curriculum_node'
      and csm.entity_id in (
        select cn.id
        from public.curriculum_nodes cn
        where cn.target_version_id = p_target_version_id
      )
    )
    or (
      csm.entity_type = 'lesson'
      and csm.entity_id in (
        select distinct cnl.lesson_id
        from public.curriculum_node_lessons cnl
        join public.curriculum_nodes cn
          on cn.id = cnl.curriculum_node_id
        where cn.target_version_id = p_target_version_id
      )
    )
    or (
      csm.entity_type = 'knowledge_concept'
      and csm.entity_id in (
        select distinct cnc.concept_id
        from public.curriculum_node_concepts cnc
        join public.curriculum_nodes cn
          on cn.id = cnc.curriculum_node_id
        where cn.target_version_id = p_target_version_id
      )
    );

  select count(*)
  into v_missing_provenance_count
  from public.curriculum_nodes cn
  where cn.target_version_id = p_target_version_id
    and not exists (
      select 1
      from public.content_source_mappings csm
      where csm.entity_type = 'curriculum_node'
        and csm.entity_id = cn.id
    );

  if v_missing_provenance_count > 0 then
    v_warnings := array_append(
      v_warnings,
      format(
        '%s curriculum node(s) have no official source citation.',
        v_missing_provenance_count
      )
    );
  end if;

  select count(*)
  into v_cross_version_mappings_count
  from public.target_version_concept_mappings
  where from_target_version_id = p_target_version_id
     or to_target_version_id = p_target_version_id;

  if v_domain_count = 0 then
    v_blockers := array_append(
      v_blockers,
      'Target version has no domains (root curriculum nodes).'
    );
  end if;

  if v_objective_count = 0 then
    v_blockers := array_append(v_blockers, 'Target version has no objectives.');
  end if;

  v_can_stage_review :=
    (v_domain_count > 0 and v_objective_count > 0
      and (v_lesson_count > 0 or v_assessment_item_count > 0));
  v_can_publish :=
    (v_tv.status = 'review_ready'
      and v_is_weight_balanced
      and array_length(v_blockers, 1) is null);

  return jsonb_build_object(
    'target_version_id', v_tv.id,
    'version_code', v_tv.version_code,
    'status', v_tv.status,
    'target_title', v_tv.target_title,
    'domain_count', v_domain_count,
    'objective_count', v_objective_count,
    'leaf_objective_count', v_leaf_objective_count,
    'domain_weight_sum', v_domain_weight_sum,
    'is_domain_weight_balanced', v_is_weight_balanced,
    'lesson_count', v_lesson_count,
    'lesson_block_count', v_lesson_block_count,
    'stimulus_count', v_stimulus_count,
    'assessment_item_count', v_assessment_item_count,
    'empty_objectives_count', v_empty_objectives_count,
    'concept_coverage_count', v_concept_count,
    'unassessed_concepts_count', v_unassessed_concept_count,
    'provenance_citations_count', v_provenance_citations_count,
    'missing_provenance_count', v_missing_provenance_count,
    'cross_version_mappings_count', v_cross_version_mappings_count,
    'can_stage_review', v_can_stage_review,
    'can_publish', v_can_publish,
    'blocking_issues', to_jsonb(v_blockers),
    'warnings', to_jsonb(v_warnings)
  );
end;
$$;

-- ----------------------------------------------------------------------------
-- 4. Publication and retirement: service_role or target owner only.
-- Publishing requires review_ready; draft -> published shortcuts are forbidden.
-- ----------------------------------------------------------------------------
create or replace function public.publish_target_version(
  p_version_id uuid,
  p_retire_previous boolean default false
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_tv record;
  v_target_owner uuid;
  v_retired_ids uuid[] := '{}';
  v_ret record;
begin
  select tv.*, lt.created_by
  into v_tv
  from public.target_versions tv
  join public.learning_targets lt on lt.id = tv.target_id
  where tv.id = p_version_id;

  if not found then
    raise exception 'Target version not found: %', p_version_id;
  end if;

  v_target_owner := v_tv.created_by;

  if coalesce(auth.role(), '') <> 'service_role'
     and (auth.uid() is null or v_target_owner is distinct from auth.uid()) then
    raise exception 'Unauthorized: only service_role or the target owner can publish a target version';
  end if;

  if v_tv.status = 'published' then
    return jsonb_build_object(
      'success', true,
      'target_version_id', p_version_id,
      'status', 'published',
      'already_published', true,
      'retired_version_ids', '[]'::jsonb,
      'retired_previous_count', 0
    );
  end if;

  if v_tv.status <> 'review_ready' then
    raise exception 'Cannot publish TargetVersion with status "%". Publication strictly requires "review_ready" staging status.', v_tv.status;
  end if;

  if p_retire_previous then
    for v_ret in
      select id
      from public.target_versions
      where target_id = v_tv.target_id
        and status = 'published'
        and id <> p_version_id
    loop
      update public.target_versions
      set status = 'retired', updated_at = now()
      where id = v_ret.id;
      v_retired_ids := array_append(v_retired_ids, v_ret.id);
    end loop;
  end if;

  update public.target_versions
  set status = 'published', updated_at = now()
  where id = p_version_id;

  update public.learning_targets
  set status = 'published', is_public = true, updated_at = now()
  where id = v_tv.target_id;

  return jsonb_build_object(
    'success', true,
    'target_version_id', p_version_id,
    'status', 'published',
    'already_published', false,
    'retired_version_ids', to_jsonb(v_retired_ids),
    'retired_previous_count', coalesce(array_length(v_retired_ids, 1), 0)
  );
end;
$$;

create or replace function public.retire_target_version(
  p_version_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_tv record;
  v_target_owner uuid;
begin
  select tv.*, lt.created_by
  into v_tv
  from public.target_versions tv
  join public.learning_targets lt on lt.id = tv.target_id
  where tv.id = p_version_id;

  if not found then
    raise exception 'Target version not found: %', p_version_id;
  end if;

  v_target_owner := v_tv.created_by;

  if coalesce(auth.role(), '') <> 'service_role'
     and (auth.uid() is null or v_target_owner is distinct from auth.uid()) then
    raise exception 'Unauthorized: only service_role or the target owner can retire a target version';
  end if;

  if v_tv.status = 'retired' then
    return jsonb_build_object(
      'success', true,
      'target_version_id', p_version_id,
      'status', 'retired',
      'already_retired', true
    );
  end if;

  if v_tv.status <> 'published' then
    raise exception 'Cannot retire target version in status "%". Only published versions can be retired.', v_tv.status;
  end if;

  update public.target_versions
  set status = 'retired', updated_at = now()
  where id = p_version_id;

  return jsonb_build_object(
    'success', true,
    'target_version_id', p_version_id,
    'status', 'retired',
    'already_retired', false
  );
end;
$$;

-- ----------------------------------------------------------------------------
-- 5. Explicit EXECUTE surface. SECURITY DEFINER functions are never left with
-- PostgreSQL's default PUBLIC execute privilege.
-- ----------------------------------------------------------------------------
revoke all on function public.evaluate_target_version_migration(uuid, uuid, uuid)
  from public, anon;
grant execute on function public.evaluate_target_version_migration(uuid, uuid, uuid)
  to authenticated, service_role;

revoke all on function public.migrate_user_context_target_version(uuid, uuid, uuid)
  from public, anon;
grant execute on function public.migrate_user_context_target_version(uuid, uuid, uuid)
  to authenticated, service_role;

revoke all on function public.audit_target_version_readiness(uuid)
  from public, anon;
grant execute on function public.audit_target_version_readiness(uuid)
  to authenticated, service_role;

revoke all on function public.publish_target_version(uuid, boolean)
  from public, anon;
grant execute on function public.publish_target_version(uuid, boolean)
  to authenticated, service_role;

revoke all on function public.retire_target_version(uuid)
  from public, anon;
grant execute on function public.retire_target_version(uuid)
  to authenticated, service_role;

INSERT INTO supabase_migrations.schema_migrations (version, name) VALUES ('20261008000001', 'phase_g_security_hardening') ON CONFLICT (version) DO NOTHING;

-- --------------------------------------------------------------------
-- [31/96] Migration: 20261008000002_phase_f1_production_taxonomy_hardening.sql
-- --------------------------------------------------------------------
-- ============================================================================
-- Phase F.1: Production Taxonomy Ingestion Hardening
-- Migration: 20261008000002_phase_f1_production_taxonomy_hardening.sql
-- Description:
--   1. Replaces occupation_nodes uniqueness with version-safe constraint
--      including data_release_version (NULLS NOT DISTINCT) to avoid O*NET
--      multi-release collision (e.g. 31.0 vs 31.1).
--   2. Adds retrieval_url column to taxonomy_source_artifacts for full provenance.
--   3. Creates service_role-only staging tables for atomic two-phase ingestion.
--   4. Adds atomic transactional RPC finalize_official_taxonomy_import() that
--      promotes staged records, reconciles absent records, and verifies exact counts.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. O*NET Version-Safe Unique Constraint on occupation_nodes
-- ----------------------------------------------------------------------------
alter table public.occupation_nodes
  drop constraint if exists occupation_nodes_taxonomy_system_taxonomy_version_code_key;

alter table public.occupation_nodes
  add constraint occupation_nodes_system_version_release_code_key
  unique nulls not distinct (taxonomy_system, taxonomy_version, data_release_version, code);

-- ----------------------------------------------------------------------------
-- 2. Artifact Retrieval URL Provenance
-- ----------------------------------------------------------------------------
alter table public.taxonomy_source_artifacts
  add column if not exists retrieval_url text;

-- Create missing content_source_artifacts table referenced by ingest_curriculum_manifest
create table if not exists public.content_source_artifacts (
  id uuid primary key default gen_random_uuid(),
  source_release_id uuid not null references public.content_source_releases(id) on delete cascade,
  artifact_name text not null,
  source_url text,
  sha256 text,
  file_size_bytes bigint,
  retrieved_at timestamptz not null default now(),
  metadata jsonb not null default '{}'::jsonb,
  unique (source_release_id, artifact_name)
);

alter table public.content_source_artifacts enable row level security;

create policy "public_read_content_source_artifacts"
  on public.content_source_artifacts for select
  using (true);

-- Align target_version_concept_mappings schema with ingest_curriculum_manifest
alter table public.target_version_concept_mappings
  add column if not exists confidence numeric,
  add column if not exists rationale text;

-- ----------------------------------------------------------------------------
-- 3. Service-Role-Only Staging Tables for Atomic Taxonomy Ingestion
-- ----------------------------------------------------------------------------
create table if not exists public.stg_taxonomy_source_artifacts (
  id uuid primary key default gen_random_uuid(),
  import_run_id uuid not null,
  source_system text not null,
  release_version text not null,
  artifact_name text not null,
  source_url text,
  retrieval_url text,
  sha256 text,
  file_size_bytes bigint,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

create table if not exists public.stg_external_classification_nodes (
  id uuid primary key default gen_random_uuid(),
  import_run_id uuid not null,
  system text not null,
  version text not null,
  code text not null,
  source_parent_code text,
  level_code text not null,
  level_depth integer not null default 1,
  title text not null,
  definition text,
  cross_references text[] not null default '{}',
  illustrative_examples text[] not null default '{}',
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

create table if not exists public.stg_occupation_nodes (
  id uuid primary key default gen_random_uuid(),
  import_run_id uuid not null,
  code text not null,
  title text not null,
  description text,
  level text not null,
  taxonomy_system text not null,
  taxonomy_version text not null,
  data_release_version text,
  job_zone integer,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

create table if not exists public.stg_external_classification_occupation_mappings (
  id uuid primary key default gen_random_uuid(),
  import_run_id uuid not null,
  classification_system text not null,
  classification_version text not null,
  classification_code text not null,
  occupation_system text not null,
  occupation_version text not null,
  occupation_code text not null,
  mapping_source text not null default 'nces_bls_crosswalk_2020',
  mapping_version text not null default '2020',
  mapping_kind text not null default 'official_qualitative',
  source_notes text,
  created_at timestamptz not null default now()
);

create table if not exists public.stg_taxonomy_node_lineage (
  id uuid primary key default gen_random_uuid(),
  import_run_id uuid not null,
  source_system text not null,
  from_version text not null,
  from_code text,
  to_version text not null,
  to_code text,
  transition_type text not null,
  notes text,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

-- Indices on import_run_id and search keys for high-performance lookup and finalization
create index if not exists stg_art_run_idx on public.stg_taxonomy_source_artifacts(import_run_id);
create index if not exists stg_cip_run_idx on public.stg_external_classification_nodes(import_run_id, system, version, code);
create index if not exists stg_occ_run_idx on public.stg_occupation_nodes(import_run_id, taxonomy_system, taxonomy_version, data_release_version, code);
create index if not exists stg_map_run_idx on public.stg_external_classification_occupation_mappings(import_run_id);
create index if not exists stg_map_join_idx on public.stg_external_classification_occupation_mappings(import_run_id, classification_system, classification_version, classification_code, occupation_system, occupation_version, occupation_code);
create index if not exists stg_lin_run_idx on public.stg_taxonomy_node_lineage(import_run_id, source_system, from_version, to_version);
create index if not exists stg_lin_reconcile_idx on public.stg_taxonomy_node_lineage(import_run_id, source_system, from_version, to_version, transition_type);

-- Enable RLS and lock down staging tables strictly to service_role
alter table public.stg_taxonomy_source_artifacts enable row level security;
alter table public.stg_external_classification_nodes enable row level security;
alter table public.stg_occupation_nodes enable row level security;
alter table public.stg_external_classification_occupation_mappings enable row level security;
alter table public.stg_taxonomy_node_lineage enable row level security;

create policy "service_role_manage_stg_artifacts"
  on public.stg_taxonomy_source_artifacts for all
  using (auth.role() = 'service_role')
  with check (auth.role() = 'service_role');

create policy "service_role_manage_stg_cip"
  on public.stg_external_classification_nodes for all
  using (auth.role() = 'service_role')
  with check (auth.role() = 'service_role');

create policy "service_role_manage_stg_occ"
  on public.stg_occupation_nodes for all
  using (auth.role() = 'service_role')
  with check (auth.role() = 'service_role');

create policy "service_role_manage_stg_map"
  on public.stg_external_classification_occupation_mappings for all
  using (auth.role() = 'service_role')
  with check (auth.role() = 'service_role');

create policy "service_role_manage_stg_lin"
  on public.stg_taxonomy_node_lineage for all
  using (auth.role() = 'service_role')
  with check (auth.role() = 'service_role');

-- ----------------------------------------------------------------------------
-- 4. Atomic Finalize RPC
-- ----------------------------------------------------------------------------
create or replace function public.finalize_official_taxonomy_import(
  p_import_run_id uuid
)
returns jsonb
language plpgsql
security definer
set statement_timeout = '120s'
as $$
declare
  v_cip_stg_count integer;
  v_soc_stg_count integer;
  v_onet_stg_count integer;
  v_map_stg_count integer;
  v_cip_lin_count integer;
  v_soc_lin_count integer;

  v_cip_active_count integer;
  v_soc_active_count integer;
  v_onet_active_count integer;
  v_map_active_count integer;
  v_orphan_cip integer;
  v_orphan_soc integer;
  v_orphan_onet integer;

  v_cip_rel_id uuid := 'a1000000-0000-0000-0000-000000000001'::uuid;
  v_soc_rel_id uuid := 'a1000000-0000-0000-0000-000000000002'::uuid;
  v_onet_rel_id uuid := 'a1000000-0000-0000-0000-000000000003'::uuid;
begin
  -- Elevate statement timeout within transaction
  perform set_config('statement_timeout', '120000', true);

  -- 1. Verify staged record counts match frozen specifications
  select count(*) into v_cip_stg_count
  from public.stg_external_classification_nodes
  where import_run_id = p_import_run_id and system = 'cip' and version = '2020';

  select count(*) into v_soc_stg_count
  from public.stg_occupation_nodes
  where import_run_id = p_import_run_id and taxonomy_system = 'bls_soc' and taxonomy_version = 'soc_2018';

  select count(*) into v_onet_stg_count
  from public.stg_occupation_nodes
  where import_run_id = p_import_run_id
    and taxonomy_system = 'onet_soc'
    and taxonomy_version = '2019'
    and data_release_version = 'onet_31_0';

  select count(*) into v_map_stg_count
  from public.stg_external_classification_occupation_mappings
  where import_run_id = p_import_run_id;

  select count(*) into v_cip_lin_count
  from public.stg_taxonomy_node_lineage
  where import_run_id = p_import_run_id and source_system = 'cip';

  select count(*) into v_soc_lin_count
  from public.stg_taxonomy_node_lineage
  where import_run_id = p_import_run_id and source_system = 'bls_soc';

  if v_cip_stg_count <> 2809 then
    raise exception 'Staged CIP 2020 nodes count (%) does not match required 2809.', v_cip_stg_count;
  end if;
  if v_soc_stg_count <> 1447 then
    raise exception 'Staged SOC 2018 nodes count (%) does not match required 1447.', v_soc_stg_count;
  end if;
  if v_onet_stg_count <> 1016 then
    raise exception 'Staged O*NET 2019 nodes count (%) does not match required 1016.', v_onet_stg_count;
  end if;
  if v_map_stg_count <> 5723 then
    raise exception 'Staged CIP-SOC mappings count (%) does not match required 5723.', v_map_stg_count;
  end if;
  if v_cip_lin_count <> 2699 then
    raise exception 'Staged CIP lineage count (%) does not match required 2699.', v_cip_lin_count;
  end if;
  if v_soc_lin_count <> 900 then
    raise exception 'Staged SOC lineage count (%) does not match required 900.', v_soc_lin_count;
  end if;

  -- 2. Upsert source releases
  insert into public.taxonomy_source_releases (
    id, source_system, release_version, release_date, source_url, license_name, license_url, attribution_text, metadata
  ) values
    (v_cip_rel_id, 'nces_cip', '2020', '2020-01-01', 'https://nces.ed.gov/ipeds/cipcode/resources.aspx?y=56', 'US_Public_Domain', 'https://www2.ed.gov/notices/copyright/index.html', 'National Center for Education Statistics, U.S. Department of Education', '{"taxonomy": "CIP 2020"}'::jsonb),
    (v_soc_rel_id, 'bls_soc', '2018', '2018-01-01', 'https://www.bls.gov/soc/2018/home.htm', 'US_Public_Domain', 'https://www.bls.gov/bls/linksite.htm', 'Bureau of Labor Statistics, U.S. Department of Labor', '{"taxonomy": "2018 Standard Occupational Classification"}'::jsonb),
    (v_onet_rel_id, 'onet', 'onet_31_0', '2026-08-01', 'https://www.onetcenter.org/db_releases.html', 'CC_BY_4_0', 'https://www.onetcenter.org/license_db.html', 'This product includes information from the O*NET 31.0 Database by the U.S. Department of Labor, Employment and Training Administration (USDOL/ETA), used under CC BY 4.0. O*NET® is a trademark of USDOL/ETA.', '{"taxonomy": "O*NET-SOC 2019", "database_release": "31.0"}'::jsonb)
  on conflict (source_system, release_version) do update set
    source_url = excluded.source_url,
    attribution_text = excluded.attribution_text,
    metadata = excluded.metadata,
    retrieved_at = now();

  -- 3. Upsert artifacts from staging
  insert into public.taxonomy_source_artifacts (
    source_release_id, artifact_name, source_url, retrieval_url, sha256, file_size_bytes, retrieved_at, metadata
  )
  select
    case
      when s.source_system = 'nces_cip' then v_cip_rel_id
      when s.source_system = 'bls_soc' then v_soc_rel_id
      else v_onet_rel_id
    end,
    s.artifact_name,
    s.source_url,
    s.retrieval_url,
    s.sha256,
    s.file_size_bytes,
    now(),
    s.metadata
  from public.stg_taxonomy_source_artifacts s
  where s.import_run_id = p_import_run_id
  on conflict (source_release_id, artifact_name) do update set
    source_url = excluded.source_url,
    retrieval_url = excluded.retrieval_url,
    sha256 = excluded.sha256,
    file_size_bytes = excluded.file_size_bytes,
    retrieved_at = now(),
    metadata = excluded.metadata;

  -- 4. Upsert CIP Nodes (external_classification_nodes)
  -- Pass 1: Upsert records
  insert into public.external_classification_nodes (
    source_release_id, system, version, code, source_parent_code, level_code, level_depth,
    title, definition, cross_references, illustrative_examples, metadata, is_active
  )
  select
    v_cip_rel_id,
    s.system,
    s.version,
    s.code,
    s.source_parent_code,
    s.level_code,
    s.level_depth,
    s.title,
    s.definition,
    s.cross_references,
    s.illustrative_examples,
    s.metadata,
    true
  from public.stg_external_classification_nodes s
  where s.import_run_id = p_import_run_id
  on conflict (system, version, code) do update set
    source_release_id = excluded.source_release_id,
    source_parent_code = excluded.source_parent_code,
    level_code = excluded.level_code,
    level_depth = excluded.level_depth,
    title = excluded.title,
    definition = excluded.definition,
    cross_references = excluded.cross_references,
    illustrative_examples = excluded.illustrative_examples,
    metadata = excluded.metadata,
    is_active = true;

  -- Pass 2: Reconstruct parent_id within CIP hierarchy
  update public.external_classification_nodes n
  set parent_id = p.id
  from public.external_classification_nodes p
  where n.system = 'cip'
    and n.version = '2020'
    and p.system = 'cip'
    and p.version = '2020'
    and n.source_parent_code is not null
    and p.code = n.source_parent_code
    and (n.parent_id is null or n.parent_id <> p.id);

  -- Pass 3: Reconcile absent CIP nodes (deactivate any old rows not present in official release)
  update public.external_classification_nodes n
  set is_active = false
  where n.system = 'cip'
    and n.version = '2020'
    and n.is_active = true
    and not exists (
      select 1 from public.stg_external_classification_nodes s
      where s.import_run_id = p_import_run_id
        and s.system = 'cip'
        and s.version = '2020'
        and s.code = n.code
    );

  -- 5. Upsert BLS SOC Nodes (occupation_nodes)
  -- Pass 1: Upsert SOC nodes
  insert into public.occupation_nodes (
    code, title, description, level, taxonomy_system, taxonomy_version, data_release_version,
    job_zone, source_release_id, metadata, is_active
  )
  select
    s.code,
    s.title,
    s.description,
    s.level,
    s.taxonomy_system,
    s.taxonomy_version,
    s.data_release_version,
    s.job_zone,
    v_soc_rel_id,
    s.metadata,
    true
  from public.stg_occupation_nodes s
  where s.import_run_id = p_import_run_id
    and s.taxonomy_system = 'bls_soc'
  on conflict (taxonomy_system, taxonomy_version, data_release_version, code) do update set
    title = excluded.title,
    description = excluded.description,
    level = excluded.level,
    job_zone = excluded.job_zone,
    source_release_id = excluded.source_release_id,
    metadata = excluded.metadata,
    is_active = true,
    updated_at = now();

  -- Pass 2: Reconstruct SOC parent_id
  -- 2a. Minor groups -> Major groups (e.g. 15-1200 -> 15-0000)
  update public.occupation_nodes o
  set parent_id = p.id
  from public.occupation_nodes p
  where o.taxonomy_system = 'bls_soc'
    and o.taxonomy_version = 'soc_2018'
    and p.taxonomy_system = 'bls_soc'
    and p.taxonomy_version = 'soc_2018'
    and o.level = 'minor_group'
    and p.level = 'major_group'
    and p.code = substring(o.code from 1 for 2) || '-0000'
    and (o.parent_id is null or o.parent_id <> p.id);

  -- 2b. Broad occupations -> Minor groups (standard 5-char e.g. 15-1250 -> 15-1200)
  update public.occupation_nodes o
  set parent_id = p.id
  from public.occupation_nodes p
  where o.taxonomy_system = 'bls_soc'
    and o.taxonomy_version = 'soc_2018'
    and p.taxonomy_system = 'bls_soc'
    and p.taxonomy_version = 'soc_2018'
    and o.level = 'broad_occupation'
    and p.level = 'minor_group'
    and p.code = substring(o.code from 1 for 5) || '00'
    and (o.parent_id is null or o.parent_id <> p.id);

  -- 2c. Broad occupations -> Minor groups (overflow 4-char e.g. 11-9110 -> 11-9000, 29-1210 -> 29-1000)
  update public.occupation_nodes o
  set parent_id = p.id
  from public.occupation_nodes p
  where o.taxonomy_system = 'bls_soc'
    and o.taxonomy_version = 'soc_2018'
    and p.taxonomy_system = 'bls_soc'
    and p.taxonomy_version = 'soc_2018'
    and o.level = 'broad_occupation'
    and o.parent_id is null
    and p.level = 'minor_group'
    and p.code = substring(o.code from 1 for 4) || '000';

  -- 2c-fallback. Broad occupations fallback -> Major groups (if minor missing)
  update public.occupation_nodes o
  set parent_id = p.id
  from public.occupation_nodes p
  where o.taxonomy_system = 'bls_soc'
    and o.taxonomy_version = 'soc_2018'
    and p.taxonomy_system = 'bls_soc'
    and p.taxonomy_version = 'soc_2018'
    and o.level = 'broad_occupation'
    and o.parent_id is null
    and p.level = 'major_group'
    and p.code = substring(o.code from 1 for 2) || '-0000';

  -- 2d. Detailed occupations -> Broad occupations (standard 6-char e.g. 15-1252 -> 15-1250)
  update public.occupation_nodes o
  set parent_id = p.id
  from public.occupation_nodes p
  where o.taxonomy_system = 'bls_soc'
    and o.taxonomy_version = 'soc_2018'
    and p.taxonomy_system = 'bls_soc'
    and p.taxonomy_version = 'soc_2018'
    and o.level = 'detailed_occupation'
    and p.level = 'broad_occupation'
    and p.code = substring(o.code from 1 for 6) || '0'
    and (o.parent_id is null or o.parent_id <> p.id);

  -- 2e. Detailed occupations -> Broad occupations (Physicians 29-1221..29-1229 -> 29-1210)
  update public.occupation_nodes o
  set parent_id = p.id
  from public.occupation_nodes p
  where o.taxonomy_system = 'bls_soc'
    and o.taxonomy_version = 'soc_2018'
    and p.taxonomy_system = 'bls_soc'
    and p.taxonomy_version = 'soc_2018'
    and o.level = 'detailed_occupation'
    and o.code in ('29-1221', '29-1222', '29-1223', '29-1224', '29-1229')
    and p.level = 'broad_occupation'
    and p.code = '29-1210'
    and (o.parent_id is null or o.parent_id <> p.id);

  -- 2f. Detailed occupations fallback -> Minor groups (if broad missing)
  update public.occupation_nodes o
  set parent_id = p.id
  from public.occupation_nodes p
  where o.taxonomy_system = 'bls_soc'
    and o.taxonomy_version = 'soc_2018'
    and p.taxonomy_system = 'bls_soc'
    and p.taxonomy_version = 'soc_2018'
    and o.level = 'detailed_occupation'
    and o.parent_id is null
    and p.level = 'minor_group'
    and (
      p.code = substring(o.code from 1 for 5) || '00' or
      p.code = substring(o.code from 1 for 4) || '000'
    );

  -- 6. Upsert O*NET Nodes (occupation_nodes)
  insert into public.occupation_nodes (
    code, title, description, level, taxonomy_system, taxonomy_version, data_release_version,
    job_zone, source_release_id, parent_id, metadata, is_active
  )
  select
    s.code,
    s.title,
    s.description,
    s.level,
    s.taxonomy_system,
    s.taxonomy_version,
    s.data_release_version,
    s.job_zone,
    v_onet_rel_id,
    p.id,
    s.metadata,
    true
  from public.stg_occupation_nodes s
  join public.occupation_nodes p
    on p.taxonomy_system = 'bls_soc'
   and p.taxonomy_version = 'soc_2018'
   and p.code = split_part(s.code, '.', 1)
  where s.import_run_id = p_import_run_id
    and s.taxonomy_system = 'onet_soc'
    and s.taxonomy_version = '2019'
    and s.data_release_version = 'onet_31_0'
  on conflict (taxonomy_system, taxonomy_version, data_release_version, code) do update set
    title = excluded.title,
    description = excluded.description,
    job_zone = excluded.job_zone,
    parent_id = excluded.parent_id,
    source_release_id = excluded.source_release_id,
    metadata = excluded.metadata,
    is_active = true,
    updated_at = now();

  -- Reconcile absent SOC/O*NET nodes
  update public.occupation_nodes o
  set is_active = false
  where o.is_active = true
    and (
      (o.taxonomy_system = 'bls_soc' and o.taxonomy_version = 'soc_2018' and not exists (
        select 1 from public.stg_occupation_nodes s
        where s.import_run_id = p_import_run_id
          and s.taxonomy_system = 'bls_soc'
          and s.taxonomy_version = 'soc_2018'
          and s.code = o.code
      )) or
      (o.taxonomy_system = 'onet_soc' and o.taxonomy_version = '2019' and o.data_release_version = 'onet_31_0' and not exists (
        select 1 from public.stg_occupation_nodes s
        where s.import_run_id = p_import_run_id
          and s.taxonomy_system = 'onet_soc'
          and s.taxonomy_version = '2019'
          and s.data_release_version = 'onet_31_0'
          and s.code = o.code
      ))
    );
  -- 7. Upsert CIP-SOC Crosswalk
  insert into public.external_classification_occupation_mappings (
    classification_node_id, occupation_id, source_release_id, mapping_source, mapping_version, mapping_kind, source_notes
  )
  select
    c.id as classification_node_id,
    o.id as occupation_id,
    v_cip_rel_id as source_release_id,
    s.mapping_source,
    s.mapping_version,
    s.mapping_kind,
    s.source_notes
  from public.stg_external_classification_occupation_mappings s
  join public.external_classification_nodes c
    on c.system = s.classification_system
   and c.version = s.classification_version
   and c.code = s.classification_code
  join public.occupation_nodes o
    on o.taxonomy_system = s.occupation_system
   and o.taxonomy_version = s.occupation_version
   and o.code = s.occupation_code
  where s.import_run_id = p_import_run_id
  on conflict (classification_node_id, occupation_id, source_release_id) do update set
    mapping_source = excluded.mapping_source,
    mapping_version = excluded.mapping_version,
    mapping_kind = excluded.mapping_kind,
    source_notes = excluded.source_notes;

  -- Reconcile deleted official crosswalk mappings for this release
  delete from public.external_classification_occupation_mappings m
  where m.source_release_id = v_cip_rel_id
    and m.mapping_source = 'nces_bls_crosswalk_2020'
    and m.mapping_version = '2020'
    and not exists (
      select 1
      from public.stg_external_classification_occupation_mappings s
      join public.external_classification_nodes c
        on c.system = s.classification_system
       and c.version = s.classification_version
       and c.code = s.classification_code
      join public.occupation_nodes o
        on o.taxonomy_system = s.occupation_system
       and o.taxonomy_version = s.occupation_version
       and o.code = s.occupation_code
      where s.import_run_id = p_import_run_id
        and c.id = m.classification_node_id
        and o.id = m.occupation_id
    );

  -- 8. Upsert Lineage from staging with exact reconciliation
  -- Reconcile absent lineage edges for official CIP 2010 -> 2020 release
  delete from public.taxonomy_node_lineage l
  where l.source_system = 'cip'
    and l.from_version = '2010'
    and l.to_version = '2020'
    and not exists (
      select 1
      from public.stg_taxonomy_node_lineage s
      where s.import_run_id = p_import_run_id
        and s.source_system = 'cip'
        and s.from_version = '2010'
        and s.to_version = '2020'
        and coalesce(s.from_code, '') = coalesce(l.from_code, '')
        and coalesce(s.to_code, '') = coalesce(l.to_code, '')
        and s.transition_type = l.transition_type
    );

  -- Reconcile absent lineage edges for official SOC 2010 -> 2018 release
  delete from public.taxonomy_node_lineage l
  where l.source_system = 'bls_soc'
    and l.from_version = '2010'
    and l.to_version = '2018'
    and not exists (
      select 1
      from public.stg_taxonomy_node_lineage s
      where s.import_run_id = p_import_run_id
        and s.source_system = 'bls_soc'
        and s.from_version = '2010'
        and s.to_version = '2018'
        and coalesce(s.from_code, '') = coalesce(l.from_code, '')
        and coalesce(s.to_code, '') = coalesce(l.to_code, '')
        and s.transition_type = l.transition_type
    );

  -- Upsert staged lineage
  insert into public.taxonomy_node_lineage (
    source_system, from_version, from_code, to_version, to_code, transition_type, notes, metadata
  )
  select
    source_system, from_version, from_code, to_version, to_code, transition_type, notes, metadata
  from public.stg_taxonomy_node_lineage s
  where s.import_run_id = p_import_run_id
  on conflict (
    source_system,
    from_version,
    coalesce(from_code, ''),
    to_version,
    coalesce(to_code, ''),
    transition_type
  ) do update set
    notes = excluded.notes,
    metadata = excluded.metadata;

  -- 9. Transactional Validation Invariants (Exact Counts & Zero Orphans)
  select count(*) into v_cip_active_count
  from public.external_classification_nodes
  where system = 'cip' and version = '2020' and is_active = true;

  select count(*) into v_soc_active_count
  from public.occupation_nodes
  where taxonomy_system = 'bls_soc' and taxonomy_version = 'soc_2018' and is_active = true;

  select count(*) into v_onet_active_count
  from public.occupation_nodes
  where taxonomy_system = 'onet_soc'
    and taxonomy_version = '2019'
    and data_release_version = 'onet_31_0'
    and is_active = true;

  select count(*) into v_map_active_count
  from public.external_classification_occupation_mappings
  where source_release_id = v_cip_rel_id
    and mapping_source = 'nces_bls_crosswalk_2020'
    and mapping_version = '2020';

  select count(*) into v_cip_lin_count
  from public.taxonomy_node_lineage
  where source_system = 'cip' and from_version = '2010' and to_version = '2020';

  select count(*) into v_soc_lin_count
  from public.taxonomy_node_lineage
  where source_system = 'bls_soc' and from_version = '2010' and to_version = '2018';

  if v_cip_active_count <> 2809 then
    raise exception 'Final active CIP count (%) does not match exact source count 2809.', v_cip_active_count;
  end if;
  if v_soc_active_count <> 1447 then
    raise exception 'Final active SOC count (%) does not match exact source count 1447.', v_soc_active_count;
  end if;
  if v_onet_active_count <> 1016 then
    raise exception 'Final active O*NET count (%) does not match exact source count 1016.', v_onet_active_count;
  end if;
  if v_map_active_count <> 5723 then
    raise exception 'Final official CIP-SOC mappings count (%) does not match exact source count 5723.', v_map_active_count;
  end if;
  if v_cip_lin_count <> 2699 then
    raise exception 'Final active CIP 2010 -> 2020 lineage count (%) does not match exact source count 2699.', v_cip_lin_count;
  end if;
  if v_soc_lin_count <> 900 then
    raise exception 'Final active SOC 2010 -> 2018 lineage count (%) does not match exact source count 900.', v_soc_lin_count;
  end if;

  select count(*) into v_orphan_cip from public.external_classification_nodes
  where system = 'cip' and version = '2020' and is_active = true and level_code <> 'series' and parent_id is null;
  if v_orphan_cip <> 0 then
    raise exception 'Integrity error: % orphan CIP non-series nodes exist after finalization.', v_orphan_cip;
  end if;

  select count(*) into v_orphan_soc from public.occupation_nodes
  where taxonomy_system = 'bls_soc' and taxonomy_version = 'soc_2018' and is_active = true and level <> 'major_group' and parent_id is null;
  if v_orphan_soc <> 0 then
    raise exception 'Integrity error: % orphan SOC non-major-group nodes exist after finalization.', v_orphan_soc;
  end if;

  select count(*) into v_orphan_onet from public.occupation_nodes
  where taxonomy_system = 'onet_soc'
    and taxonomy_version = '2019'
    and data_release_version = 'onet_31_0'
    and is_active = true
    and parent_id is null;
  if v_orphan_onet <> 0 then
    raise exception 'Integrity error: % orphan O*NET nodes exist after finalization.', v_orphan_onet;
  end if;

  -- 10. Clean up staging data for this run
  delete from public.stg_taxonomy_source_artifacts where import_run_id = p_import_run_id;
  delete from public.stg_external_classification_nodes where import_run_id = p_import_run_id;
  delete from public.stg_occupation_nodes where import_run_id = p_import_run_id;
  delete from public.stg_external_classification_occupation_mappings where import_run_id = p_import_run_id;
  delete from public.stg_taxonomy_node_lineage where import_run_id = p_import_run_id;

  return jsonb_build_object(
    'status', 'success',
    'import_run_id', p_import_run_id,
    'cip_nodes', v_cip_active_count,
    'soc_nodes', v_soc_active_count,
    'onet_nodes', v_onet_active_count,
    'cip_soc_mappings', v_map_active_count,
    'cip_lineage', v_cip_lin_count,
    'soc_lineage', v_soc_lin_count
  );
end;
$$;

-- Revoke execute from public/anon and grant to service_role
revoke execute on function public.finalize_official_taxonomy_import(uuid) from public, anon, authenticated;
grant execute on function public.finalize_official_taxonomy_import(uuid) to service_role;

-- ----------------------------------------------------------------------------
-- Hierarchical CIP Crosswalk Views & Target Occupations RPC
-- Supports arbitrary CIP hierarchy (series, group, program) joining to fields
-- ----------------------------------------------------------------------------
create or replace view public.v_field_occupation_mappings as
  select distinct
    fec.field_id,
    ecom.occupation_id,
    ecn.system as classification_system,
    ecn.version as classification_version,
    ecn.code as classification_code,
    ocn.code as occupation_code,
    ocn.title as occupation_title,
    ecom.mapping_kind,
    ecom.source_release_id
  from public.external_classification_occupation_mappings ecom
  join public.external_classification_nodes ecn on ecn.id = ecom.classification_node_id
  join public.external_classification_nodes fn
    on fn.system = ecn.system
   and fn.version = ecn.version
   and (
     fn.id = ecn.id or
     (fn.level_code = 'series' and fn.code = substring(ecn.code from 1 for 2)) or
     (fn.level_code = 'group' and fn.code = substring(ecn.code from 1 for 5))
   )
  join public.field_external_classifications fec on fec.classification_node_id = fn.id
  join public.occupation_nodes ocn on ocn.id = ecom.occupation_id;

grant select on public.v_field_occupation_mappings to anon, authenticated, service_role;

create or replace view public.v_target_occupation_mappings as
  select distinct
    ltf.target_id,
    lt.slug as target_slug,
    lt.title as target_title,
    ltf.field_id,
    f.name as field_name,
    f.slug as field_slug,
    ltf.role as field_role,
    ltf.display_order as field_display_order,
    fom.occupation_id,
    fom.classification_system,
    fom.classification_version,
    fom.classification_code,
    fom.occupation_code,
    fom.occupation_title,
    fom.mapping_kind,
    fom.source_release_id
  from public.learning_target_fields ltf
  join public.learning_targets lt on lt.id = ltf.target_id
  join public.fields f on f.id = ltf.field_id
  join public.v_field_occupation_mappings fom on fom.field_id = ltf.field_id;

grant select on public.v_target_occupation_mappings to anon, authenticated, service_role;

create or replace function public.get_target_crosswalk_occupations(
  p_target_id uuid
)
returns table (
  occupation_id uuid,
  occupation_code text,
  occupation_title text,
  occupation_level text,
  job_zone integer,
  field_id uuid,
  field_name text,
  field_role text,
  mapping_kind text,
  classification_code text,
  classification_title text
) as $$
begin
  return query
  select distinct
    ocn.id as occupation_id,
    ocn.code as occupation_code,
    ocn.title as occupation_title,
    ocn.level as occupation_level,
    ocn.job_zone,
    ltf.field_id,
    f.name as field_name,
    ltf.role as field_role,
    ecom.mapping_kind,
    ecn.code as classification_code,
    ecn.title as classification_title
  from public.learning_target_fields ltf
  join public.fields f on f.id = ltf.field_id
  join public.field_external_classifications fec on fec.field_id = ltf.field_id
  join public.external_classification_nodes fn on fn.id = fec.classification_node_id
  join public.external_classification_nodes ecn
    on ecn.system = fn.system
   and ecn.version = fn.version
   and (
     ecn.id = fn.id or
     (fn.level_code = 'series' and substring(ecn.code from 1 for 2) = fn.code) or
     (fn.level_code = 'group' and substring(ecn.code from 1 for 5) = fn.code)
   )
  join public.external_classification_occupation_mappings ecom on ecom.classification_node_id = ecn.id
  join public.occupation_nodes ocn on ocn.id = ecom.occupation_id
  where ltf.target_id = p_target_id
    and ocn.is_active = true
  order by ltf.role asc, ocn.code asc;
end;
$$ language plpgsql stable security definer;

grant execute on function public.get_target_crosswalk_occupations(uuid) to anon, authenticated, service_role;

-- ----------------------------------------------------------------------------
-- Strict Database Lint Hardening & Dynamic Resolution
-- 1. audit_target_version_readiness: Explicit array[]::text[] typing
-- 2. publish_target_version: Explicit array[]::uuid[] typing
-- ----------------------------------------------------------------------------

create or replace function public.audit_target_version_readiness(
  p_target_version_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_tv record;
  v_domain_count integer := 0;
  v_objective_count integer := 0;
  v_leaf_objective_count integer := 0;
  v_domain_weight_sum numeric(7,3) := 0.0;
  v_is_weight_balanced boolean := false;
  v_lesson_count integer := 0;
  v_lesson_block_count integer := 0;
  v_stimulus_count integer := 0;
  v_assessment_item_count integer := 0;
  v_empty_objectives_count integer := 0;
  v_concept_count integer := 0;
  v_unassessed_concept_count integer := 0;
  v_provenance_citations_count integer := 0;
  v_missing_provenance_count integer := 0;
  v_cross_version_mappings_count integer := 0;
  v_can_stage_review boolean := false;
  v_can_publish boolean := false;
  v_blockers text[] := array[]::text[];
  v_warnings text[] := array[]::text[];
begin
  select tv.*, lt.title as target_title, lt.created_by as target_owner
  into v_tv
  from public.target_versions tv
  join public.learning_targets lt on lt.id = tv.target_id
  where tv.id = p_target_version_id;

  if not found then
    raise exception 'Target version not found: %', p_target_version_id;
  end if;

  if coalesce(auth.role(), '') <> 'service_role'
     and (
       auth.uid() is null
       or (
         v_tv.target_owner is distinct from auth.uid()
         and not public.is_target_reviewer(v_tv.target_id)
       )
     ) then
    raise exception 'Unauthorized: only service_role, target owner, or assigned reviewer may audit a target version.';
  end if;

  select
    count(*) filter (where cn.parent_id is null),
    count(*),
    coalesce(sum(cn.weight) filter (where cn.parent_id is null), 0.0)
  into
    v_domain_count,
    v_objective_count,
    v_domain_weight_sum
  from public.curriculum_nodes cn
  where cn.target_version_id = p_target_version_id;

  select count(*)
  into v_leaf_objective_count
  from public.curriculum_nodes cn
  where cn.target_version_id = p_target_version_id
    and not exists (
      select 1 from public.curriculum_nodes child
      where child.parent_id = cn.id
    );

  if v_domain_weight_sum = 0.0 then
    v_is_weight_balanced := true;
    v_warnings := array_append(v_warnings, 'Domains are unweighted (sum is 0.0).');
  elsif abs(v_domain_weight_sum - 100.0) < 0.1
     or abs(v_domain_weight_sum - 1.0) < 0.01 then
    v_is_weight_balanced := true;
  else
    v_is_weight_balanced := false;
    v_blockers := array_append(
      v_blockers,
      format('Domain weights sum to %s%% (expected 100.0%%).', v_domain_weight_sum)
    );
  end if;

  select count(distinct cnl.lesson_id)
  into v_lesson_count
  from public.curriculum_node_lessons cnl
  join public.curriculum_nodes cn on cn.id = cnl.curriculum_node_id
  where cn.target_version_id = p_target_version_id;

  select count(*)
  into v_lesson_block_count
  from public.lesson_blocks lb
  where lb.lesson_id in (
    select distinct cnl.lesson_id
    from public.curriculum_node_lessons cnl
    join public.curriculum_nodes cn on cn.id = cnl.curriculum_node_id
    where cn.target_version_id = p_target_version_id
  );

  select count(*)
  into v_stimulus_count
  from public.assessment_stimuli
  where origin_target_version_id = p_target_version_id;

  select count(*)
  into v_assessment_item_count
  from public.assessment_items ai
  where ai.origin_target_version_id = p_target_version_id
     or ai.lesson_id in (
       select distinct cnl.lesson_id
       from public.curriculum_node_lessons cnl
       join public.curriculum_nodes cn on cn.id = cnl.curriculum_node_id
       where cn.target_version_id = p_target_version_id
     );

  select count(*)
  into v_empty_objectives_count
  from public.curriculum_nodes cn
  where cn.target_version_id = p_target_version_id
    and not exists (
      select 1 from public.curriculum_nodes child where child.parent_id = cn.id
    )
    and not exists (
      select 1 from public.curriculum_node_lessons cnl
      where cnl.curriculum_node_id = cn.id
    )
    and not exists (
      select 1
      from public.curriculum_node_concepts cnc
      join public.assessment_item_concepts aic
        on aic.concept_id = cnc.concept_id
      where cnc.curriculum_node_id = cn.id
    );

  if v_empty_objectives_count > 0 then
    v_warnings := array_append(
      v_warnings,
      format(
        '%s leaf objective(s) have no lessons or assessment items bound.',
        v_empty_objectives_count
      )
    );
  end if;

  select count(distinct cnc.concept_id)
  into v_concept_count
  from public.curriculum_node_concepts cnc
  join public.curriculum_nodes cn on cn.id = cnc.curriculum_node_id
  where cn.target_version_id = p_target_version_id;

  select count(distinct cnc.concept_id)
  into v_unassessed_concept_count
  from public.curriculum_node_concepts cnc
  join public.curriculum_nodes cn on cn.id = cnc.curriculum_node_id
  where cn.target_version_id = p_target_version_id
    and not exists (
      select 1 from public.assessment_item_concepts aic
      where aic.concept_id = cnc.concept_id
    );

  if v_unassessed_concept_count > 0 then
    v_warnings := array_append(
      v_warnings,
      format('%s concept(s) have no direct assessment items.', v_unassessed_concept_count)
    );
  end if;

  select count(*)
  into v_provenance_citations_count
  from public.content_source_mappings csm
  where
    (csm.entity_type = 'target_version' and csm.entity_id = p_target_version_id)
    or (
      csm.entity_type = 'curriculum_node'
      and csm.entity_id in (
        select cn.id
        from public.curriculum_nodes cn
        where cn.target_version_id = p_target_version_id
      )
    )
    or (
      csm.entity_type = 'lesson'
      and csm.entity_id in (
        select distinct cnl.lesson_id
        from public.curriculum_node_lessons cnl
        join public.curriculum_nodes cn
          on cn.id = cnl.curriculum_node_id
        where cn.target_version_id = p_target_version_id
      )
    )
    or (
      csm.entity_type = 'knowledge_concept'
      and csm.entity_id in (
        select distinct cnc.concept_id
        from public.curriculum_node_concepts cnc
        join public.curriculum_nodes cn
          on cn.id = cnc.curriculum_node_id
        where cn.target_version_id = p_target_version_id
      )
    );

  select count(*)
  into v_missing_provenance_count
  from public.curriculum_nodes cn
  where cn.target_version_id = p_target_version_id
    and not exists (
      select 1
      from public.content_source_mappings csm
      where csm.entity_type = 'curriculum_node'
        and csm.entity_id = cn.id
    );

  if v_missing_provenance_count > 0 then
    v_warnings := array_append(
      v_warnings,
      format(
        '%s curriculum node(s) have no official source citation.',
        v_missing_provenance_count
      )
    );
  end if;

  select count(*)
  into v_cross_version_mappings_count
  from public.target_version_concept_mappings
  where from_target_version_id = p_target_version_id
     or to_target_version_id = p_target_version_id;

  if v_domain_count = 0 then
    v_blockers := array_append(
      v_blockers,
      'Target version has no domains (root curriculum nodes).'
    );
  end if;

  if v_objective_count = 0 then
    v_blockers := array_append(v_blockers, 'Target version has no objectives.');
  end if;

  v_can_stage_review :=
    (v_domain_count > 0 and v_objective_count > 0
      and (v_lesson_count > 0 or v_assessment_item_count > 0));
  v_can_publish :=
    (v_tv.status = 'review_ready'
      and v_is_weight_balanced
      and array_length(v_blockers, 1) is null);

  return jsonb_build_object(
    'target_version_id', v_tv.id,
    'version_code', v_tv.version_code,
    'status', v_tv.status,
    'target_title', v_tv.target_title,
    'domain_count', v_domain_count,
    'objective_count', v_objective_count,
    'leaf_objective_count', v_leaf_objective_count,
    'domain_weight_sum', v_domain_weight_sum,
    'is_domain_weight_balanced', v_is_weight_balanced,
    'lesson_count', v_lesson_count,
    'lesson_block_count', v_lesson_block_count,
    'stimulus_count', v_stimulus_count,
    'assessment_item_count', v_assessment_item_count,
    'empty_objectives_count', v_empty_objectives_count,
    'concept_coverage_count', v_concept_count,
    'unassessed_concepts_count', v_unassessed_concept_count,
    'provenance_citations_count', v_provenance_citations_count,
    'missing_provenance_count', v_missing_provenance_count,
    'cross_version_mappings_count', v_cross_version_mappings_count,
    'can_stage_review', v_can_stage_review,
    'can_publish', v_can_publish,
    'blocking_issues', to_jsonb(v_blockers),
    'warnings', to_jsonb(v_warnings)
  );
end;
$$;

revoke all on function public.audit_target_version_readiness(uuid) from public, anon;
grant execute on function public.audit_target_version_readiness(uuid) to authenticated, service_role;

create or replace function public.publish_target_version(
  p_version_id uuid,
  p_retire_previous boolean default false
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_tv record;
  v_target_owner uuid;
  v_retired_ids uuid[] := array[]::uuid[];
  v_ret record;
begin
  select tv.*, lt.created_by
  into v_tv
  from public.target_versions tv
  join public.learning_targets lt on lt.id = tv.target_id
  where tv.id = p_version_id;

  if not found then
    raise exception 'Target version not found: %', p_version_id;
  end if;

  v_target_owner := v_tv.created_by;

  if coalesce(auth.role(), '') <> 'service_role'
     and (auth.uid() is null or v_target_owner is distinct from auth.uid()) then
    raise exception 'Unauthorized: only service_role or the target owner can publish a target version';
  end if;

  if v_tv.status = 'published' then
    return jsonb_build_object(
      'success', true,
      'target_version_id', p_version_id,
      'status', 'published',
      'already_published', true,
      'retired_version_ids', '[]'::jsonb,
      'retired_previous_count', 0
    );
  end if;

  if v_tv.status <> 'review_ready' then
    raise exception 'Cannot publish TargetVersion with status "%". Publication strictly requires "review_ready" staging status.', v_tv.status;
  end if;

  if p_retire_previous then
    for v_ret in
      select id
      from public.target_versions
      where target_id = v_tv.target_id
        and status = 'published'
        and id <> p_version_id
    loop
      update public.target_versions
      set status = 'retired', updated_at = now()
      where id = v_ret.id;
      v_retired_ids := array_append(v_retired_ids, v_ret.id);
    end loop;
  end if;

  update public.target_versions
  set status = 'published', updated_at = now()
  where id = p_version_id;

  update public.learning_targets
  set status = 'published', is_public = true, updated_at = now()
  where id = v_tv.target_id;

  return jsonb_build_object(
    'success', true,
    'target_version_id', p_version_id,
    'status', 'published',
    'already_published', false,
    'retired_version_ids', to_jsonb(v_retired_ids),
    'retired_previous_count', coalesce(array_length(v_retired_ids, 1), 0)
  );
end;
$$;

revoke all on function public.publish_target_version(uuid, boolean) from public, anon;
grant execute on function public.publish_target_version(uuid, boolean) to authenticated, service_role;

INSERT INTO supabase_migrations.schema_migrations (version, name) VALUES ('20261008000002', 'phase_f1_production_taxonomy_hardening') ON CONFLICT (version) DO NOTHING;

-- --------------------------------------------------------------------
-- [32/96] Migration: 20261009000000_manifest_concept_mappings_and_target_security.sql
-- --------------------------------------------------------------------
-- ============================================================================
-- Migration: 20261009000000_manifest_concept_mappings_and_target_security.sql
-- Description:
--   1. Reconcile Cross-Version Concept Mappings Ingestion Contract:
--      Manifest concept_mappings (from_version_code, from_concept_slug, to_concept_slug,
--      mapping_type, transfer_weight, metadata) resolved and persisted into
--      target_version_concept_mappings.
--   2. Target Visibility Security Hardening for Views & RPCs:
--      Harden get_target_crosswalk_occupations and get_cross_target_shared_concepts
--      to fail closed if requested learning target is not published+public, owned by caller,
--      or visible to reviewer.
--      Set v_target_occupation_mappings and v_field_occupation_mappings to security_invoker = true.
--   3. Content Source Artifacts Provenance Visibility:
--      Restrict content_source_artifacts to inherit visibility from mapped entities
--      via content_source_mappings rather than public read.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. Target Version Concept Mappings Schema & Index Hardening
-- ----------------------------------------------------------------------------
alter table public.target_version_concept_mappings
  alter column to_concept_id drop not null;

alter table public.target_version_concept_mappings
  drop constraint if exists tv_concept_mappings_removed_check;

alter table public.target_version_concept_mappings
  add constraint tv_concept_mappings_removed_check
  check ( (mapping_type = 'removed') or (to_concept_id is not null) );

alter table public.target_version_concept_mappings
  drop constraint if exists target_version_concept_mappings_from_target_version_id_fro_key;

drop index if exists public.tv_concept_mappings_unique_idx;
create unique index tv_concept_mappings_unique_idx
  on public.target_version_concept_mappings (
    from_target_version_id,
    from_concept_id,
    to_target_version_id,
    coalesce(to_concept_id, '00000000-0000-0000-0000-000000000000'::uuid)
  );

-- ----------------------------------------------------------------------------
-- 2. Fully Transactional Ingestion RPC (ingest_curriculum_manifest) Reconnection
-- ----------------------------------------------------------------------------
create or replace function public.ingest_curriculum_manifest(
  payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_field_id uuid;
  v_field_slug text;
  v_target_id uuid;
  v_target_slug text;
  v_version_id uuid;
  v_version_code text;
  v_version_status text;

  -- Counters
  v_concepts_count int := 0;
  v_stimuli_count int := 0;
  v_domains_count int := 0;
  v_objectives_count int := 0;
  v_lessons_count int := 0;
  v_blocks_count int := 0;
  v_items_count int := 0;
  v_flashcards_count int := 0;
  v_questions_count int := 0;
  v_mappings_count int := 0;

  -- Lookup Maps
  v_stimuli_map jsonb := '{}'::jsonb;         -- stimulus_key -> uuid
  v_concepts_map jsonb := '{}'::jsonb;        -- slug -> uuid
  v_source_releases_map jsonb := '{}'::jsonb; -- source_id or index -> uuid
  v_default_rel_id uuid := null;

  -- Concept processing variables
  v_concept jsonb;
  v_concept_id uuid;
  v_concept_slug text;
  v_concept_name text;
  v_explicit_canon text;
  v_matched_id uuid;
  v_matched_is_ambig boolean;
  v_concept_rel_id uuid;

  -- Content processing variables
  v_stim jsonb;
  v_stim_key text;
  v_stim_id uuid;
  v_domain jsonb;
  v_domain_id uuid;
  v_obj jsonb;
  v_obj_id uuid;
  v_lesson jsonb;
  v_lesson_id uuid;
  v_block jsonb;
  v_block_id uuid;
  v_item jsonb;
  v_item_id uuid;
  v_fc jsonb;
  v_fc_id uuid;
  v_term jsonb;
  v_question jsonb;
  v_mapping jsonb;
  v_source_rel jsonb;
  v_source_rel_idx int := 0;
  v_rel_id uuid;
  v_source_artifact jsonb;
  v_mapping_id uuid;
  v_source_mapping jsonb;
  v_from_concept_id uuid;
  v_to_concept_id uuid;

  v_entity_rel_id uuid;
  v_lesson_rel_id uuid;
  v_obj_rel_id uuid;
  v_raw_concept_ref text;
  v_resolved_cid uuid;

  -- Concept mapping resolution variables
  v_from_version_code text;
  v_from_concept_slug text;
  v_to_concept_slug text;
  v_mapping_type text;
  v_from_tv_id uuid;
  v_transfer_weight numeric;
  v_concept_mappings_count int := 0;
begin

  -- 1. Security Check: Service-role only
  if coalesce(current_setting('request.jwt.claim.role', true), '') <> 'service_role'
     and auth.role() <> 'service_role' then
    raise exception 'Unauthorized: ingest_curriculum_manifest requires service_role privilege';
  end if;

  -- 2. Extract / Upsert Field
  v_field_slug := payload->'field'->>'slug';
  if v_field_slug is not null and v_field_slug <> '' then
    select id into v_field_id from public.fields where slug = v_field_slug;
    if v_field_id is null then
      insert into public.fields (slug, name, description, field_kind)
      values (
        v_field_slug,
        coalesce(payload->'field'->>'name', v_field_slug),
        payload->'field'->>'description',
        'native_field'
      )
      returning id into v_field_id;
    end if;
  end if;

  -- 3. Extract / Upsert LearningTarget
  v_target_slug := payload->'target'->>'slug';
  if v_target_slug is null or v_target_slug = '' then
    raise exception 'Missing target.slug in manifest payload';
  end if;

  select id into v_target_id from public.learning_targets where slug = v_target_slug;
  if v_target_id is null then
    insert into public.learning_targets (
      slug, title, target_type, description, field_id, status, is_public
    ) values (
      v_target_slug,
      coalesce(payload->'target'->>'title', v_target_slug),
      coalesce(payload->'target'->>'target_type', coalesce(payload->'target'->>'target_kind', 'certification')),
      payload->'target'->>'description',
      v_field_id,
      'published',
      true
    )
    returning id into v_target_id;
  end if;

  -- 4. Extract / Upsert TargetVersion
  v_version_code := payload->'target_version'->>'version_code';
  if v_version_code is null or v_version_code = '' then
    raise exception 'Missing target_version.version_code in manifest payload';
  end if;

  select id, status into v_version_id, v_version_status
  from public.target_versions
  where target_id = v_target_id and version_code = v_version_code;

  if v_version_id is null then
    insert into public.target_versions (
      target_id, version_code, title, description, valid_from, status, metadata
    ) values (
      v_target_id,
      v_version_code,
      coalesce(payload->'target_version'->>'title', payload->'target'->>'version_title', v_version_code),
      coalesce(payload->'target_version'->>'description', payload->'target'->>'version_description'),
      case when coalesce(payload->'target_version'->>'valid_from', payload->'target'->>'valid_from') is not null
           then (coalesce(payload->'target_version'->>'valid_from', payload->'target'->>'valid_from'))::date
           else null end,
      'draft',
      coalesce(payload->'target_version'->'metadata', '{}'::jsonb)
    )
    returning id, status into v_version_id, v_version_status;
  else
    if v_version_status <> 'draft' then
      raise exception 'Cannot ingest into TargetVersion "%" with status "%". Only draft versions may be replaced.', v_version_code, v_version_status;
    end if;

    update public.target_versions
    set title = coalesce(payload->'target_version'->>'title', payload->'target'->>'version_title', title),
        description = coalesce(payload->'target_version'->>'description', payload->'target'->>'version_description', description),
        valid_from = case when coalesce(payload->'target_version'->>'valid_from', payload->'target'->>'valid_from') is not null
                          then (coalesce(payload->'target_version'->>'valid_from', payload->'target'->>'valid_from'))::date
                          else valid_from end,
        metadata = coalesce(payload->'target_version'->'metadata', metadata),
        updated_at = now()
    where id = v_version_id;
  end if;

  -- 5. Atomically Clean Previous Draft Content for this TargetVersion
  perform public.clean_draft_target_version(v_version_id);

  -- 6. Ingest Source Releases
  if jsonb_typeof(coalesce(payload->'source_releases', payload->'sources')) = 'array' then
    for v_source_rel in select * from jsonb_array_elements(coalesce(payload->'source_releases', payload->'sources'))
    loop
      insert into public.content_source_releases (
        publisher, title, version, source_url, license, retrieved_at, sha256, metadata
      ) values (
        coalesce(v_source_rel->>'publisher', 'Authoritative Source'),
        coalesce(v_source_rel->>'title', 'Official Blueprint'),
        coalesce(v_source_rel->>'version', 'v1'),
        v_source_rel->>'source_url',
        coalesce(v_source_rel->>'license', v_source_rel->>'license_name'),
        case when v_source_rel->>'retrieved_at' is not null
             then (v_source_rel->>'retrieved_at')::timestamptz
             else now() end,
        v_source_rel->>'sha256',
        coalesce(v_source_rel->'metadata', '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
          'system', v_source_rel->>'system',
          'rights_note', v_source_rel->>'rights_note'
        ))
      )
      on conflict (publisher, title, version) do update
      set source_url = excluded.source_url,
          license = excluded.license,
          retrieved_at = excluded.retrieved_at,
          sha256 = excluded.sha256,
          metadata = excluded.metadata
      returning id into v_rel_id;

      v_source_rel_idx := v_source_rel_idx + 1;
      if v_default_rel_id is null then
        v_default_rel_id := v_rel_id;
      end if;

      if v_source_rel ? 'id' then
        v_source_releases_map := v_source_releases_map || jsonb_build_object(v_source_rel->>'id', v_rel_id::text);
      end if;
      if v_source_rel ? 'source_id' then
        v_source_releases_map := v_source_releases_map || jsonb_build_object(v_source_rel->>'source_id', v_rel_id::text);
      end if;
      v_source_releases_map := v_source_releases_map || jsonb_build_object(
        coalesce(v_source_rel->>'publisher', '') || '/' || coalesce(v_source_rel->>'version', ''), v_rel_id::text
      );
      v_source_releases_map := v_source_releases_map || jsonb_build_object(
        (v_source_rel_idx - 1)::text, v_rel_id::text
      );

      -- Link root target_version to this source release
      insert into public.content_source_mappings (
        source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
      ) values (
        v_rel_id,
        'target_version',
        v_version_id,
        'official_blueprint',
        coalesce(payload->'target_version'->>'citation', 'Root Blueprint'),
        'Root target version mapping to authoritative source release',
        '{}'::jsonb
      )
      on conflict (source_release_id, entity_type, entity_id, relationship) do update
      set citation_location = excluded.citation_location,
          notes = excluded.notes,
          metadata = excluded.metadata
      returning id into v_mapping_id;

      v_mappings_count := v_mappings_count + 1;
      insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
      values (v_version_id, 'content_source_mapping', v_mapping_id)
      on conflict do nothing;

      -- Source Artifacts
      if jsonb_typeof(v_source_rel->'artifacts') = 'array' then
        for v_source_artifact in select * from jsonb_array_elements(v_source_rel->'artifacts')
        loop
          insert into public.content_source_artifacts (
            source_release_id, artifact_name, source_url, sha256, file_size_bytes, retrieved_at, metadata
          ) values (
            v_rel_id,
            coalesce(v_source_artifact->>'artifact_name', 'blueprint.pdf'),
            v_source_artifact->>'source_url',
            v_source_artifact->>'sha256',
            case when v_source_artifact->>'file_size_bytes' is not null
                 then (v_source_artifact->>'file_size_bytes')::bigint
                 else null end,
            case when v_source_artifact->>'retrieved_at' is not null
                 then (v_source_artifact->>'retrieved_at')::timestamptz
                 else now() end,
            coalesce(v_source_artifact->'metadata', '{}'::jsonb)
          )
          on conflict (source_release_id, artifact_name) do update
          set source_url = excluded.source_url,
              sha256 = excluded.sha256,
              file_size_bytes = excluded.file_size_bytes,
              retrieved_at = excluded.retrieved_at,
              metadata = excluded.metadata;
        end loop;
      end if;
    end loop;
  end if;

  -- 7. Fully Transactional Canonical Concepts Resolution & Ingestion (Option A)
  if jsonb_typeof(payload->'concepts') = 'array' then
    for v_concept in select * from jsonb_array_elements(payload->'concepts')
    loop
      v_concept_slug := v_concept->>'slug';
      v_concept_name := coalesce(v_concept->>'name', v_concept_slug);
      v_explicit_canon := v_concept->>'canonical_concept';
      v_concept_id := null;

      if v_explicit_canon is not null and trim(v_explicit_canon) <> '' then
        select id into v_concept_id
        from public.knowledge_concepts
        where slug = trim(v_explicit_canon);

        if v_concept_id is null then
          raise exception 'Explicit canonical_concept "%" declared for concept "%" (%) does not exist in knowledge_concepts. Overrides must fail closed.', v_explicit_canon, v_concept_name, v_concept_slug;
        end if;

        if v_field_id is not null then
          insert into public.concept_fields (concept_id, field_id, relationship)
          values (v_concept_id, v_field_id, 'core_concept')
          on conflict (concept_id, field_id) do nothing;
        end if;
      else
        -- Ambiguity-safe resolution RPC
        select r.id, r.is_ambiguous into v_matched_id, v_matched_is_ambig
        from public.resolve_canonical_concept(v_concept_slug, v_concept_name, v_field_id) r
        limit 1;

        if v_matched_is_ambig then
          raise exception 'Ambiguous canonical concept match for "%" (%). Multiple concepts share this name across fields and target field does not disambiguate. Declare "canonical_concept: <existing-slug>" explicitly in the manifest to resolve the ambiguity, or make the concept name specific.', v_concept_name, v_concept_slug;
        end if;

        if v_matched_id is not null then
          v_concept_id := v_matched_id;
          if v_field_id is not null then
            insert into public.concept_fields (concept_id, field_id, relationship)
            values (v_concept_id, v_field_id, 'core_concept')
            on conflict (concept_id, field_id) do nothing;
          end if;
        else
          -- Insert new canonical knowledge concept
          insert into public.knowledge_concepts (
            field_id, slug, name, short_definition, description, emoji, aliases, status
          ) values (
            v_field_id,
            v_concept_slug,
            v_concept_name,
            v_concept->>'short_definition',
            v_concept->>'description',
            coalesce(v_concept->>'emoji', '💡'),
            case when jsonb_typeof(v_concept->'aliases') = 'array'
                 then array(select jsonb_array_elements_text(v_concept->'aliases'))
                 else array[]::text[] end,
            'active'
          )
          returning id into v_concept_id;

          if v_field_id is not null then
            insert into public.concept_fields (concept_id, field_id, relationship)
            values (v_concept_id, v_field_id, 'core_concept')
            on conflict (concept_id, field_id) do nothing;
          end if;
        end if;
      end if;

      v_concepts_count := v_concepts_count + 1;
      v_concepts_map := v_concepts_map || jsonb_build_object(v_concept_slug, v_concept_id::text);

      -- Canonical Concept Provenance Mapping
      if v_default_rel_id is not null then
        v_concept_rel_id := null;
        if v_concept ? 'source_release_id' and v_source_releases_map ? (v_concept->>'source_release_id') then
          v_concept_rel_id := (v_source_releases_map->>(v_concept->>'source_release_id'))::uuid;
        elsif v_concept ? 'source_id' and v_source_releases_map ? (v_concept->>'source_id') then
          v_concept_rel_id := (v_source_releases_map->>(v_concept->>'source_id'))::uuid;
        else
          v_concept_rel_id := v_default_rel_id;
        end if;

        if v_concept_rel_id is not null then
          insert into public.content_source_mappings (
            source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
          ) values (
            v_concept_rel_id,
            'knowledge_concept',
            v_concept_id,
            coalesce(v_concept->>'relationship', 'official_blueprint'),
            coalesce(v_concept->>'citation', coalesce(v_concept->>'citation_location', 'Concept ' || v_concept_slug)),
            coalesce(v_concept->>'notes', coalesce(v_concept->>'citation_notes', 'Authoritative concept definition from blueprint')),
            '{}'::jsonb
          )
          on conflict (source_release_id, entity_type, entity_id, relationship) do update
          set citation_location = excluded.citation_location,
              notes = excluded.notes,
              metadata = excluded.metadata;

          v_mappings_count := v_mappings_count + 1;
        end if;
      end if;
    end loop;
  end if;

  -- 8. Ingest Shared Stimuli (root-level & objective-level)
  if jsonb_typeof(payload->'stimuli') = 'array' then
    for v_stim in select * from jsonb_array_elements(payload->'stimuli')
    loop
      v_stim_key := v_stim->>'stimulus_key';
      insert into public.assessment_stimuli (
        title, body, stimulus_type, metadata, origin_target_version_id
      ) values (
        coalesce(v_stim->>'title', 'Exhibit'),
        coalesce(v_stim->>'body', coalesce(v_stim->>'body_markdown', '')),
        coalesce(v_stim->>'stimulus_type', 'scenario'),
        jsonb_build_object(
          'media_url', v_stim->>'media_url',
          'credit', v_stim->>'credit',
          'attribution', v_stim->>'attribution'
        ),
        v_version_id
      )
      returning id into v_stim_id;

      v_stimuli_count := v_stimuli_count + 1;
      v_stimuli_map := v_stimuli_map || jsonb_build_object(v_stim_key, v_stim_id::text);

      insert into public.content_import_artifacts (target_version_id, entity_type, entity_id, manifest_key)
      values (v_version_id, 'assessment_stimulus', v_stim_id, v_stim_key);

      -- Stimulus Source Mapping
      if v_default_rel_id is not null then
        v_entity_rel_id := null;
        if v_stim ? 'source_release_id' and v_source_releases_map ? (v_stim->>'source_release_id') then
          v_entity_rel_id := (v_source_releases_map->>(v_stim->>'source_release_id'))::uuid;
        elsif v_stim ? 'source_id' and v_source_releases_map ? (v_stim->>'source_id') then
          v_entity_rel_id := (v_source_releases_map->>(v_stim->>'source_id'))::uuid;
        else
          v_entity_rel_id := v_default_rel_id;
        end if;

        if v_entity_rel_id is not null then
          insert into public.content_source_mappings (
            source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
          ) values (
            v_entity_rel_id,
            'assessment_stimulus',
            v_stim_id,
            'official_blueprint',
            coalesce(v_stim->>'citation', coalesce(v_stim->>'citation_location', 'Official Blueprint Stimulus')),
            coalesce(v_stim->>'notes', 'Assessment stimulus mapping'),
            '{}'::jsonb
          )
          on conflict (source_release_id, entity_type, entity_id, relationship) do update
          set citation_location = excluded.citation_location,
              notes = excluded.notes,
              metadata = excluded.metadata
          returning id into v_mapping_id;

          v_mappings_count := v_mappings_count + 1;
          insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
          values (v_version_id, 'content_source_mapping', v_mapping_id)
          on conflict do nothing;
        end if;
      end if;
    end loop;
  end if;

  -- 9. Ingest Standalone Target-level Flashcards
  if jsonb_typeof(payload->'flashcards') = 'array' then
    for v_fc in select * from jsonb_array_elements(payload->'flashcards')
    loop
      insert into public.flashcards (
        front, back, explanation, origin_target_version_id
      ) values (
        v_fc->>'front',
        v_fc->>'back',
        v_fc->>'explanation',
        v_version_id
      )
      returning id into v_fc_id;

      v_flashcards_count := v_flashcards_count + 1;
      insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
      values (v_version_id, 'flashcard', v_fc_id);

      -- Link concepts by UUID or slug lookup
      if jsonb_typeof(v_fc->'concept_ids') = 'array' then
        for v_concept_id in select (jsonb_array_elements_text(v_fc->'concept_ids'))::uuid
        loop
          insert into public.flashcard_concepts (flashcard_id, concept_id)
          values (v_fc_id, v_concept_id)
          on conflict do nothing;
        end loop;
      end if;

      if jsonb_typeof(v_fc->'concept_slugs') = 'array' then
        for v_raw_concept_ref in select jsonb_array_elements_text(v_fc->'concept_slugs')
        loop
          if v_concepts_map ? v_raw_concept_ref then
            v_resolved_cid := (v_concepts_map->>v_raw_concept_ref)::uuid;
            insert into public.flashcard_concepts (flashcard_id, concept_id)
            values (v_fc_id, v_resolved_cid)
            on conflict do nothing;
          end if;
        end loop;
      end if;

      -- Flashcard Provenance Mapping
      if v_default_rel_id is not null then
        v_entity_rel_id := null;
        if v_fc ? 'source_release_id' and v_source_releases_map ? (v_fc->>'source_release_id') then
          v_entity_rel_id := (v_source_releases_map->>(v_fc->>'source_release_id'))::uuid;
        elsif v_fc ? 'source_id' and v_source_releases_map ? (v_fc->>'source_id') then
          v_entity_rel_id := (v_source_releases_map->>(v_fc->>'source_id'))::uuid;
        else
          v_entity_rel_id := v_default_rel_id;
        end if;

        if v_entity_rel_id is not null then
          insert into public.content_source_mappings (
            source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
          ) values (
            v_entity_rel_id,
            'flashcard',
            v_fc_id,
            'derived_from',
            coalesce(v_fc->>'citation', coalesce(v_fc->>'citation_location', coalesce(v_fc->>'front', 'Flashcard'))),
            coalesce(v_fc->>'notes', 'Flashcard derived from authoritative blueprint'),
            '{}'::jsonb
          )
          on conflict (source_release_id, entity_type, entity_id, relationship) do update
          set citation_location = excluded.citation_location,
              notes = excluded.notes,
              metadata = excluded.metadata
          returning id into v_mapping_id;

          v_mappings_count := v_mappings_count + 1;
          insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
          values (v_version_id, 'content_source_mapping', v_mapping_id)
          on conflict do nothing;
        end if;
      end if;
    end loop;
  end if;

  -- 10. Ingest Domains, Objectives, Lessons, Blocks, Assessment Items
  if jsonb_typeof(payload->'domains') = 'array' then
    for v_domain in select * from jsonb_array_elements(payload->'domains')
    loop
      insert into public.curriculum_nodes (
        target_version_id, node_type, code, title, description, sort_order, weight, metadata
      ) values (
        v_version_id,
        'domain',
        v_domain->>'code',
        coalesce(v_domain->>'title', 'Domain'),
        v_domain->>'description',
        coalesce((v_domain->>'sort_order')::int, 0),
        case when v_domain->>'weight_percentage' is not null
             then (v_domain->>'weight_percentage')::numeric
             when v_domain->>'weight' is not null
             then (v_domain->>'weight')::numeric
             else null end,
        coalesce(v_domain->'metadata', '{}'::jsonb)
      )
      returning id into v_domain_id;

      v_domains_count := v_domains_count + 1;
      insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
      values (v_version_id, 'curriculum_node', v_domain_id);

      -- Domain Source Mapping
      if v_default_rel_id is not null then
        v_entity_rel_id := null;
        if v_domain ? 'source_release_id' and v_source_releases_map ? (v_domain->>'source_release_id') then
          v_entity_rel_id := (v_source_releases_map->>(v_domain->>'source_release_id'))::uuid;
        elsif v_domain ? 'source_id' and v_source_releases_map ? (v_domain->>'source_id') then
          v_entity_rel_id := (v_source_releases_map->>(v_domain->>'source_id'))::uuid;
        else
          v_entity_rel_id := v_default_rel_id;
        end if;

        if v_entity_rel_id is not null then
          insert into public.content_source_mappings (
            source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
          ) values (
            v_entity_rel_id,
            'curriculum_node',
            v_domain_id,
            'official_blueprint',
            coalesce(v_domain->>'citation', coalesce(v_domain->>'citation_location', 'Domain ' || coalesce(v_domain->>'code', ''))),
            coalesce(v_domain->>'notes', 'Curriculum domain node citation'),
            '{}'::jsonb
          )
          on conflict (source_release_id, entity_type, entity_id, relationship) do update
          set citation_location = excluded.citation_location,
              notes = excluded.notes,
              metadata = excluded.metadata
          returning id into v_mapping_id;

          v_mappings_count := v_mappings_count + 1;
          insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
          values (v_version_id, 'content_source_mapping', v_mapping_id)
          on conflict do nothing;
        end if;
      end if;

      -- Objectives
      if jsonb_typeof(v_domain->'objectives') = 'array' then
        for v_obj in select * from jsonb_array_elements(v_domain->'objectives')
        loop
          insert into public.curriculum_nodes (
            target_version_id, parent_id, node_type, code, title, description, sort_order, metadata
          ) values (
            v_version_id,
            v_domain_id,
            'objective',
            v_obj->>'code',
            coalesce(v_obj->>'title', 'Objective'),
            v_obj->>'description',
            coalesce((v_obj->>'sort_order')::int, 0),
            jsonb_build_object('bloom_level', coalesce(v_obj->>'bloom_level', 'understand'))
          )
          returning id into v_obj_id;

          v_objectives_count := v_objectives_count + 1;
          insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
          values (v_version_id, 'curriculum_node', v_obj_id);

          -- Objective Source Mapping
          if v_default_rel_id is not null then
            v_entity_rel_id := null;
            if v_obj ? 'source_release_id' and v_source_releases_map ? (v_obj->>'source_release_id') then
              v_entity_rel_id := (v_source_releases_map->>(v_obj->>'source_release_id'))::uuid;
            elsif v_obj ? 'source_id' and v_source_releases_map ? (v_obj->>'source_id') then
              v_entity_rel_id := (v_source_releases_map->>(v_obj->>'source_id'))::uuid;
            else
              v_entity_rel_id := coalesce(
                (v_source_releases_map->>(v_domain->>'source_release_id'))::uuid,
                (v_source_releases_map->>(v_domain->>'source_id'))::uuid,
                v_default_rel_id
              );
            end if;

            v_obj_rel_id := v_entity_rel_id;

            if v_entity_rel_id is not null then
              insert into public.content_source_mappings (
                source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
              ) values (
                v_entity_rel_id,
                'curriculum_node',
                v_obj_id,
                'official_blueprint',
                coalesce(v_obj->>'citation', coalesce(v_obj->>'citation_location', 'Objective ' || coalesce(v_obj->>'code', ''))),
                coalesce(v_obj->>'notes', 'Curriculum objective node citation'),
                '{}'::jsonb
              )
              on conflict (source_release_id, entity_type, entity_id, relationship) do update
              set citation_location = excluded.citation_location,
                  notes = excluded.notes,
                  metadata = excluded.metadata
              returning id into v_mapping_id;

              v_mappings_count := v_mappings_count + 1;
              insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
              values (v_version_id, 'content_source_mapping', v_mapping_id)
              on conflict do nothing;
            end if;
          end if;

          -- Link objective concepts by UUID or slug
          if jsonb_typeof(v_obj->'concept_ids') = 'array' then
            for v_concept_id in select (jsonb_array_elements_text(v_obj->'concept_ids'))::uuid
            loop
              insert into public.curriculum_node_concepts (curriculum_node_id, concept_id)
              values (v_obj_id, v_concept_id)
              on conflict do nothing;
            end loop;
          end if;

          if jsonb_typeof(v_obj->'concept_slugs') = 'array' then
            for v_raw_concept_ref in select jsonb_array_elements_text(v_obj->'concept_slugs')
            loop
              if v_concepts_map ? v_raw_concept_ref then
                v_resolved_cid := (v_concepts_map->>v_raw_concept_ref)::uuid;
                insert into public.curriculum_node_concepts (curriculum_node_id, concept_id)
                values (v_obj_id, v_resolved_cid)
                on conflict do nothing;
              end if;
            end loop;
          end if;

          -- Objective Flashcards
          if jsonb_typeof(v_obj->'flashcards') = 'array' then
            for v_fc in select * from jsonb_array_elements(v_obj->'flashcards')
            loop
              insert into public.flashcards (
                front, back, explanation, origin_target_version_id
              ) values (
                v_fc->>'front',
                v_fc->>'back',
                v_fc->>'explanation',
                v_version_id
              )
              returning id into v_fc_id;

              v_flashcards_count := v_flashcards_count + 1;
              insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
              values (v_version_id, 'flashcard', v_fc_id);

              if jsonb_typeof(v_fc->'concept_ids') = 'array' then
                for v_concept_id in select (jsonb_array_elements_text(v_fc->'concept_ids'))::uuid
                loop
                  insert into public.flashcard_concepts (flashcard_id, concept_id)
                  values (v_fc_id, v_concept_id)
                  on conflict do nothing;
                end loop;
              end if;

              if jsonb_typeof(v_fc->'concept_slugs') = 'array' then
                for v_raw_concept_ref in select jsonb_array_elements_text(v_fc->'concept_slugs')
                loop
                  if v_concepts_map ? v_raw_concept_ref then
                    v_resolved_cid := (v_concepts_map->>v_raw_concept_ref)::uuid;
                    insert into public.flashcard_concepts (flashcard_id, concept_id)
                    values (v_fc_id, v_resolved_cid)
                    on conflict do nothing;
                  end if;
                end loop;
              end if;

              -- Objective Flashcard Provenance Mapping
              if v_default_rel_id is not null then
                v_entity_rel_id := null;
                if v_fc ? 'source_release_id' and v_source_releases_map ? (v_fc->>'source_release_id') then
                  v_entity_rel_id := (v_source_releases_map->>(v_fc->>'source_release_id'))::uuid;
                elsif v_fc ? 'source_id' and v_source_releases_map ? (v_fc->>'source_id') then
                  v_entity_rel_id := (v_source_releases_map->>(v_fc->>'source_id'))::uuid;
                else
                  v_entity_rel_id := coalesce(v_obj_rel_id, v_default_rel_id);
                end if;

                if v_entity_rel_id is not null then
                  insert into public.content_source_mappings (
                    source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
                  ) values (
                    v_entity_rel_id,
                    'flashcard',
                    v_fc_id,
                    'derived_from',
                    coalesce(v_fc->>'citation', coalesce(v_fc->>'citation_location', coalesce(v_fc->>'front', 'Objective Flashcard'))),
                    coalesce(v_fc->>'notes', 'Flashcard derived from authoritative objective blueprint'),
                    '{}'::jsonb
                  )
                  on conflict (source_release_id, entity_type, entity_id, relationship) do update
                  set citation_location = excluded.citation_location,
                      notes = excluded.notes,
                      metadata = excluded.metadata
                  returning id into v_mapping_id;

                  v_mappings_count := v_mappings_count + 1;
                  insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
                  values (v_version_id, 'content_source_mapping', v_mapping_id)
                  on conflict do nothing;
                end if;
              end if;
            end loop;
          end if;

          -- Objective Assessment Items
          if jsonb_typeof(v_obj->'assessment_items') = 'array' then
            for v_item in select * from jsonb_array_elements(v_obj->'assessment_items')
            loop
              v_stim_key := v_item->>'stimulus_key';
              v_stim_id := null;
              if v_stim_key is not null and v_stimuli_map ? v_stim_key then
                v_stim_id := (v_stimuli_map->>v_stim_key)::uuid;
              end if;

              insert into public.assessment_items (
                stimulus_id, prompt, interaction_type, response_spec, scoring_spec, explanation, origin_target_version_id
              ) values (
                v_stim_id,
                v_item->>'prompt',
                coalesce(v_item->>'interaction_type', 'single_choice'),
                coalesce(v_item->'response_spec', '{}'::jsonb),
                coalesce(v_item->'scoring_spec', '{}'::jsonb),
                v_item->>'explanation',
                v_version_id
              )
              returning id into v_item_id;

              v_items_count := v_items_count + 1;
              insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
              values (v_version_id, 'assessment_item', v_item_id);

              if jsonb_typeof(v_item->'concept_ids') = 'array' then
                for v_concept_id in select (jsonb_array_elements_text(v_item->'concept_ids'))::uuid
                loop
                  insert into public.assessment_item_concepts (assessment_item_id, concept_id)
                  values (v_item_id, v_concept_id)
                  on conflict do nothing;
                end loop;
              end if;

              if jsonb_typeof(v_item->'concept_slugs') = 'array' then
                for v_raw_concept_ref in select jsonb_array_elements_text(v_item->'concept_slugs')
                loop
                  if v_concepts_map ? v_raw_concept_ref then
                    v_resolved_cid := (v_concepts_map->>v_raw_concept_ref)::uuid;
                    insert into public.assessment_item_concepts (assessment_item_id, concept_id)
                    values (v_item_id, v_resolved_cid)
                    on conflict do nothing;
                  end if;
                end loop;
              end if;

              -- Objective Assessment Item Provenance Mapping
              if v_default_rel_id is not null then
                v_entity_rel_id := null;
                if v_item ? 'source_release_id' and v_source_releases_map ? (v_item->>'source_release_id') then
                  v_entity_rel_id := (v_source_releases_map->>(v_item->>'source_release_id'))::uuid;
                elsif v_item ? 'source_id' and v_source_releases_map ? (v_item->>'source_id') then
                  v_entity_rel_id := (v_source_releases_map->>(v_item->>'source_id'))::uuid;
                else
                  v_entity_rel_id := coalesce(v_obj_rel_id, v_default_rel_id);
                end if;

                if v_entity_rel_id is not null then
                  insert into public.content_source_mappings (
                    source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
                  ) values (
                    v_entity_rel_id,
                    'assessment_item',
                    v_item_id,
                    'derived_from',
                    coalesce(v_item->>'citation', coalesce(v_item->>'citation_location', substring(coalesce(v_item->>'prompt', 'Assessment Item') from 1 for 100))),
                    coalesce(v_item->>'notes', 'Assessment item derived from authoritative blueprint'),
                    '{}'::jsonb
                  )
                  on conflict (source_release_id, entity_type, entity_id, relationship) do update
                  set citation_location = excluded.citation_location,
                      notes = excluded.notes,
                      metadata = excluded.metadata
                  returning id into v_mapping_id;

                  v_mappings_count := v_mappings_count + 1;
                  insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
                  values (v_version_id, 'content_source_mapping', v_mapping_id)
                  on conflict do nothing;
                end if;
              end if;
            end loop;
          end if;

          -- Lessons
          if jsonb_typeof(v_obj->'lessons') = 'array' then
            for v_lesson in select * from jsonb_array_elements(v_obj->'lessons')
            loop
              insert into public.lessons (
                title, description, visibility, origin_target_version_id
              ) values (
                v_lesson->>'title',
                coalesce(v_lesson->>'description', v_lesson->>'summary'),
                'public',
                v_version_id
              )
              returning id into v_lesson_id;

              v_lessons_count := v_lessons_count + 1;
              insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
              values (v_version_id, 'lesson', v_lesson_id);

              -- Lesson Source Mapping
              if v_default_rel_id is not null then
                v_entity_rel_id := null;
                if v_lesson ? 'source_release_id' and v_source_releases_map ? (v_lesson->>'source_release_id') then
                  v_entity_rel_id := (v_source_releases_map->>(v_lesson->>'source_release_id'))::uuid;
                elsif v_lesson ? 'source_id' and v_source_releases_map ? (v_lesson->>'source_id') then
                  v_entity_rel_id := (v_source_releases_map->>(v_lesson->>'source_id'))::uuid;
                else
                  v_entity_rel_id := coalesce(
                    (v_source_releases_map->>(v_obj->>'source_release_id'))::uuid,
                    (v_source_releases_map->>(v_obj->>'source_id'))::uuid,
                    coalesce(
                      (v_source_releases_map->>(v_domain->>'source_release_id'))::uuid,
                      (v_source_releases_map->>(v_domain->>'source_id'))::uuid,
                      v_default_rel_id
                    )
                  );
                end if;

                v_lesson_rel_id := v_entity_rel_id;

                if v_entity_rel_id is not null then
                  insert into public.content_source_mappings (
                    source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
                  ) values (
                    v_entity_rel_id,
                    'lesson',
                    v_lesson_id,
                    'derived_from',
                    coalesce(v_lesson->>'citation', coalesce(v_lesson->>'citation_location', coalesce(v_lesson->>'title', 'Lesson'))),
                    coalesce(v_lesson->>'notes', 'Lesson derived from authoritative source'),
                    '{}'::jsonb
                  )
                  on conflict (source_release_id, entity_type, entity_id, relationship) do update
                  set citation_location = excluded.citation_location,
                      notes = excluded.notes,
                      metadata = excluded.metadata
                  returning id into v_mapping_id;

                  v_mappings_count := v_mappings_count + 1;
                  insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
                  values (v_version_id, 'content_source_mapping', v_mapping_id)
                  on conflict do nothing;
                end if;
              end if;

              -- Bind lesson to objective
              insert into public.curriculum_node_lessons (curriculum_node_id, lesson_id, sort_order)
              values (v_obj_id, v_lesson_id, coalesce((v_lesson->>'order_index')::int, 0))
              on conflict do nothing;

              -- Scoped lesson concept linking
              if jsonb_typeof(v_lesson->'concept_ids') = 'array' then
                for v_concept_id in select (jsonb_array_elements_text(v_lesson->'concept_ids'))::uuid
                loop
                  insert into public.lesson_concepts (lesson_id, concept_id)
                  values (v_lesson_id, v_concept_id)
                  on conflict do nothing;
                end loop;
              end if;

              if jsonb_typeof(v_lesson->'concept_slugs') = 'array' then
                for v_raw_concept_ref in select jsonb_array_elements_text(v_lesson->'concept_slugs')
                loop
                  if v_concepts_map ? v_raw_concept_ref then
                    v_resolved_cid := (v_concepts_map->>v_raw_concept_ref)::uuid;
                    insert into public.lesson_concepts (lesson_id, concept_id)
                    values (v_lesson_id, v_resolved_cid)
                    on conflict do nothing;
                  end if;
                end loop;
              end if;

              -- Lesson Blocks
              if jsonb_typeof(v_lesson->'blocks') = 'array' then
                for v_block in select * from jsonb_array_elements(v_lesson->'blocks')
                loop
                  insert into public.lesson_blocks (
                    lesson_id, block_type, content, sort_order
                  ) values (
                    v_lesson_id,
                    coalesce(v_block->>'block_type', 'markdown'),
                    coalesce(v_block->'content', '{}'::jsonb),
                    coalesce((v_block->>'sort_order')::int, 0)
                  )
                  returning id into v_block_id;

                  v_blocks_count := v_blocks_count + 1;
                  insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
                  values (v_version_id, 'lesson_block', v_block_id);

                  -- Lesson Block Provenance Mapping
                  if v_default_rel_id is not null then
                    v_entity_rel_id := null;
                    if v_block ? 'source_release_id' and v_source_releases_map ? (v_block->>'source_release_id') then
                      v_entity_rel_id := (v_source_releases_map->>(v_block->>'source_release_id'))::uuid;
                    elsif v_block ? 'source_id' and v_source_releases_map ? (v_block->>'source_id') then
                      v_entity_rel_id := (v_source_releases_map->>(v_block->>'source_id'))::uuid;
                    else
                      v_entity_rel_id := coalesce(v_lesson_rel_id, v_default_rel_id);
                    end if;

                    if v_entity_rel_id is not null then
                      insert into public.content_source_mappings (
                        source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
                      ) values (
                        v_entity_rel_id,
                        'lesson_block',
                        v_block_id,
                        'derived_from',
                        coalesce(v_block->>'citation', coalesce(v_block->>'citation_location', coalesce(v_lesson->>'title', 'Lesson Block'))),
                        coalesce(v_block->>'notes', 'Lesson content block citation'),
                        '{}'::jsonb
                      )
                      on conflict (source_release_id, entity_type, entity_id, relationship) do update
                      set citation_location = excluded.citation_location,
                          notes = excluded.notes,
                          metadata = excluded.metadata
                      returning id into v_mapping_id;

                      v_mappings_count := v_mappings_count + 1;
                      insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
                      values (v_version_id, 'content_source_mapping', v_mapping_id)
                      on conflict do nothing;
                    end if;
                  end if;
                end loop;
              end if;

              -- Lesson Terms
              if jsonb_typeof(v_lesson->'terms') = 'array' then
                for v_term in select * from jsonb_array_elements(v_lesson->'terms')
                loop
                  insert into public.terms (lesson_id, term, definition)
                  values (v_lesson_id, v_term->>'term', v_term->>'definition');
                end loop;
              end if;

              -- Lesson Questions
              if jsonb_typeof(v_lesson->'questions') = 'array' then
                for v_question in select * from jsonb_array_elements(v_lesson->'questions')
                loop
                  insert into public.questions (
                    lesson_id, question_text, options, correct_answer, type, explanation
                  ) values (
                    v_lesson_id,
                    coalesce(v_question->>'question_text', v_question->>'question'),
                    coalesce(v_question->'options', '[]'::jsonb),
                    coalesce((coalesce(v_question->>'correct_answer', v_question->>'correct_index'))::int, 0),
                    coalesce(v_question->>'type', 'mcq'),
                    v_question->>'explanation'
                  );
                  v_questions_count := v_questions_count + 1;
                end loop;
              end if;

              -- Lesson Assessment Items
              if jsonb_typeof(v_lesson->'assessment_items') = 'array' then
                for v_item in select * from jsonb_array_elements(v_lesson->'assessment_items')
                loop
                  v_stim_key := v_item->>'stimulus_key';
                  v_stim_id := null;
                  if v_stim_key is not null and v_stimuli_map ? v_stim_key then
                    v_stim_id := (v_stimuli_map->>v_stim_key)::uuid;
                  end if;

                  insert into public.assessment_items (
                    lesson_id, stimulus_id, prompt, interaction_type, response_spec, scoring_spec, explanation, origin_target_version_id
                  ) values (
                    v_lesson_id,
                    v_stim_id,
                    v_item->>'prompt',
                    coalesce(v_item->>'interaction_type', 'single_choice'),
                    coalesce(v_item->'response_spec', '{}'::jsonb),
                    coalesce(v_item->'scoring_spec', '{}'::jsonb),
                    v_item->>'explanation',
                    v_version_id
                  )
                  returning id into v_item_id;

                  v_items_count := v_items_count + 1;
                  insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
                  values (v_version_id, 'assessment_item', v_item_id);

                  if jsonb_typeof(v_item->'concept_ids') = 'array' then
                    for v_concept_id in select (jsonb_array_elements_text(v_item->'concept_ids'))::uuid
                    loop
                      insert into public.assessment_item_concepts (assessment_item_id, concept_id)
                      values (v_item_id, v_concept_id)
                      on conflict do nothing;
                    end loop;
                  end if;

                  if jsonb_typeof(v_item->'concept_slugs') = 'array' then
                    for v_raw_concept_ref in select jsonb_array_elements_text(v_item->'concept_slugs')
                    loop
                      if v_concepts_map ? v_raw_concept_ref then
                        v_resolved_cid := (v_concepts_map->>v_raw_concept_ref)::uuid;
                        insert into public.assessment_item_concepts (assessment_item_id, concept_id)
                        values (v_item_id, v_resolved_cid)
                        on conflict do nothing;
                      end if;
                    end loop;
                  end if;

                  -- Lesson Assessment Item Provenance Mapping
                  if v_default_rel_id is not null then
                    v_entity_rel_id := null;
                    if v_item ? 'source_release_id' and v_source_releases_map ? (v_item->>'source_release_id') then
                      v_entity_rel_id := (v_source_releases_map->>(v_item->>'source_release_id'))::uuid;
                    elsif v_item ? 'source_id' and v_source_releases_map ? (v_item->>'source_id') then
                      v_entity_rel_id := (v_source_releases_map->>(v_item->>'source_id'))::uuid;
                    else
                      v_entity_rel_id := coalesce(v_lesson_rel_id, v_default_rel_id);
                    end if;

                    if v_entity_rel_id is not null then
                      insert into public.content_source_mappings (
                        source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
                      ) values (
                        v_entity_rel_id,
                        'assessment_item',
                        v_item_id,
                        'derived_from',
                        coalesce(v_item->>'citation', coalesce(v_item->>'citation_location', substring(coalesce(v_item->>'prompt', 'Lesson Assessment Item') from 1 for 100))),
                        coalesce(v_item->>'notes', 'Lesson assessment item derived from authoritative blueprint'),
                        '{}'::jsonb
                      )
                      on conflict (source_release_id, entity_type, entity_id, relationship) do update
                      set citation_location = excluded.citation_location,
                          notes = excluded.notes,
                          metadata = excluded.metadata
                      returning id into v_mapping_id;

                      v_mappings_count := v_mappings_count + 1;
                      insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
                      values (v_version_id, 'content_source_mapping', v_mapping_id)
                      on conflict do nothing;
                    end if;
                  end if;
                end loop;
              end if;

            end loop;
          end if; -- lessons

        end loop;
      end if; -- objectives

    end loop;
  end if; -- domains

  -- 11. Ingest Explicit Custom Source Mappings
  if jsonb_typeof(payload->'source_mappings') = 'array' then
    for v_source_mapping in select * from jsonb_array_elements(payload->'source_mappings')
    loop
      insert into public.content_source_mappings (
        source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
      ) values (
        (v_source_mapping->>'source_release_id')::uuid,
        v_source_mapping->>'entity_type',
        (v_source_mapping->>'entity_id')::uuid,
        coalesce(v_source_mapping->>'relationship', 'derived_from'),
        coalesce(v_source_mapping->>'citation_location', v_source_mapping->>'section_reference'),
        coalesce(v_source_mapping->>'notes', v_source_mapping->>'citation_text'),
        coalesce(v_source_mapping->'metadata', '{}'::jsonb)
      )
      on conflict (source_release_id, entity_type, entity_id, relationship) do update
      set citation_location = excluded.citation_location,
          notes = excluded.notes,
          metadata = excluded.metadata
      returning id into v_mapping_id;

      v_mappings_count := v_mappings_count + 1;
      insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
      values (v_version_id, 'content_source_mapping', v_mapping_id)
      on conflict do nothing;
    end loop;
  end if;

  -- 12. Ingest Concept Version Mappings
  if jsonb_typeof(coalesce(payload->'concept_mappings', payload->'target_version_concept_mappings')) = 'array' then
    for v_mapping in select * from jsonb_array_elements(coalesce(payload->'concept_mappings', payload->'target_version_concept_mappings'))
    loop
      -- Check if standard manifest format (from_version_code, from_concept_slug, etc.)
      if v_mapping ? 'from_version_code' or v_mapping ? 'from_concept_slug' then
        v_from_version_code := v_mapping->>'from_version_code';
        v_from_concept_slug := v_mapping->>'from_concept_slug';
        v_to_concept_slug := v_mapping->>'to_concept_slug';
        v_mapping_type := coalesce(v_mapping->>'mapping_type', 'unchanged');

        if v_mapping_type = 'equivalent' then
          v_mapping_type := 'unchanged';
        end if;

        if v_mapping_type not in ('unchanged', 'renamed', 'expanded', 'narrowed', 'replaced', 'removed') then
          raise exception 'Invalid mapping_type "%" for concept mapping. Must be one of unchanged, renamed, expanded, narrowed, replaced, removed.', v_mapping_type;
        end if;

        -- Resolve source version ID
        select id into v_from_tv_id
        from public.target_versions
        where target_id = v_target_id and version_code = v_from_version_code
        limit 1;

        if v_from_tv_id is null then
          raise exception 'Target version with version_code "%" not found for target "%".', v_from_version_code, v_target_id;
        end if;

        -- Resolve source concept ID
        v_from_concept_id := null;
        if v_concepts_map ? v_from_concept_slug then
          v_from_concept_id := (v_concepts_map->>v_from_concept_slug)::uuid;
        else
          select id into v_from_concept_id
          from public.knowledge_concepts
          where slug = v_from_concept_slug
          limit 1;
        end if;

        if v_from_concept_id is null then
          raise exception 'Source concept with slug "%" not found for concept mapping.', v_from_concept_slug;
        end if;

        -- Resolve destination concept ID (nullable for 'removed')
        v_to_concept_id := null;
        if v_to_concept_slug is not null and trim(v_to_concept_slug) <> '' then
          if v_concepts_map ? v_to_concept_slug then
            v_to_concept_id := (v_concepts_map->>v_to_concept_slug)::uuid;
          else
            select id into v_to_concept_id
            from public.knowledge_concepts
            where slug = v_to_concept_slug
            limit 1;
          end if;

          if v_to_concept_id is null and v_mapping_type <> 'removed' then
            raise exception 'Destination concept with slug "%" not found for concept mapping.', v_to_concept_slug;
          end if;
        elsif v_mapping_type <> 'removed' then
          raise exception 'Destination concept slug must be specified for mapping_type "%".', v_mapping_type;
        end if;

        if v_mapping ? 'transfer_weight' and v_mapping->>'transfer_weight' is not null then
          v_transfer_weight := (v_mapping->>'transfer_weight')::numeric;
        elsif v_mapping_type = 'removed' then
          v_transfer_weight := 0.0;
        else
          v_transfer_weight := 1.0;
        end if;

        if v_transfer_weight < 0.0 or v_transfer_weight > 1.0 then
          raise exception 'Concept mapping transfer_weight % must be between 0.0 and 1.0.', v_transfer_weight;
        end if;

        insert into public.target_version_concept_mappings (
          from_target_version_id, from_concept_id, to_target_version_id, to_concept_id,
          mapping_type, transfer_weight, metadata
        ) values (
          v_from_tv_id,
          v_from_concept_id,
          v_version_id,
          v_to_concept_id,
          v_mapping_type,
          v_transfer_weight,
          coalesce(v_mapping->'metadata', '{}'::jsonb)
        )
        on conflict (
          from_target_version_id,
          from_concept_id,
          to_target_version_id,
          coalesce(to_concept_id, '00000000-0000-0000-0000-000000000000'::uuid)
        ) do update
        set mapping_type = excluded.mapping_type,
            transfer_weight = excluded.transfer_weight,
            metadata = excluded.metadata;

        v_concept_mappings_count := v_concept_mappings_count + 1;

      else
        -- Backwards compatibility with raw UUID payload
        v_from_concept_id := (v_mapping->>'from_concept_id')::uuid;
        v_to_concept_id := case when v_mapping->>'to_concept_id' is not null
                                then (v_mapping->>'to_concept_id')::uuid
                                else null end;
        v_mapping_type := coalesce(v_mapping->>'mapping_type', 'unchanged');
        if v_mapping_type = 'equivalent' then
          v_mapping_type := 'unchanged';
        end if;

        if v_mapping ? 'transfer_weight' and v_mapping->>'transfer_weight' is not null then
          v_transfer_weight := (v_mapping->>'transfer_weight')::numeric;
        elsif v_mapping_type = 'removed' then
          v_transfer_weight := 0.0;
        else
          v_transfer_weight := 1.0;
        end if;

        insert into public.target_version_concept_mappings (
          from_target_version_id, from_concept_id, to_target_version_id, to_concept_id,
          mapping_type, transfer_weight, metadata,
          confidence, rationale
        ) values (
          coalesce((v_mapping->>'from_target_version_id')::uuid, v_version_id),
          v_from_concept_id,
          coalesce((v_mapping->>'to_target_version_id')::uuid, v_version_id),
          v_to_concept_id,
          v_mapping_type,
          v_transfer_weight,
          coalesce(v_mapping->'metadata', '{}'::jsonb),
          case when v_mapping->>'confidence' is not null then (v_mapping->>'confidence')::numeric else null end,
          v_mapping->>'rationale'
        )
        on conflict (
          from_target_version_id,
          from_concept_id,
          to_target_version_id,
          coalesce(to_concept_id, '00000000-0000-0000-0000-000000000000'::uuid)
        ) do update
        set mapping_type = excluded.mapping_type,
            transfer_weight = excluded.transfer_weight,
            metadata = excluded.metadata,
            confidence = excluded.confidence,
            rationale = excluded.rationale;

        v_concept_mappings_count := v_concept_mappings_count + 1;
      end if;
    end loop;
  end if;

  -- 13. Return Ingestion Summary
  return jsonb_build_object(
    'target_version_id', v_version_id,
    'concepts_count', v_concepts_count,
    'domains_count', v_domains_count,
    'objectives_count', v_objectives_count,
    'lessons_count', v_lessons_count,
    'blocks_count', v_blocks_count,
    'assessment_items_count', v_items_count,
    'flashcards_count', v_flashcards_count,
    'stimuli_count', v_stimuli_count,
    'questions_count', v_questions_count,
    'mappings_count', v_mappings_count,
    'concept_mappings_count', v_concept_mappings_count
  );
end;
$$;

revoke all on function public.ingest_curriculum_manifest(jsonb) from public, anon, authenticated;
grant execute on function public.ingest_curriculum_manifest(jsonb) to service_role;


-- ----------------------------------------------------------------------------
-- 3. Target Visibility Security Helper & View/RPC Hardening
-- ----------------------------------------------------------------------------

create or replace function public.is_target_visible(p_target_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1 from public.learning_targets lt
    where lt.id = p_target_id
      and (
        coalesce(auth.role(), '') = 'service_role'
        or (lt.status = 'published' and lt.is_public = true)
        or (auth.uid() is not null and lt.created_by = auth.uid())
        or (auth.uid() is not null and public.is_target_reviewer(lt.id))
      )
  );
$$;

revoke all on function public.is_target_visible(uuid) from public;
grant execute on function public.is_target_visible(uuid) to anon, authenticated, service_role;

-- Harden get_target_crosswalk_occupations
create or replace function public.get_target_crosswalk_occupations(
  p_target_id uuid
)
returns table (
  occupation_id uuid,
  occupation_code text,
  occupation_title text,
  occupation_level text,
  job_zone integer,
  field_id uuid,
  field_name text,
  field_role text,
  mapping_kind text,
  classification_code text,
  classification_title text
)
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
begin
  if not public.is_target_visible(p_target_id) then
    raise exception 'Unauthorized or target not found: %', p_target_id;
  end if;

  return query
  select distinct
    ocn.id as occupation_id,
    ocn.code as occupation_code,
    ocn.title as occupation_title,
    ocn.level as occupation_level,
    ocn.job_zone,
    ltf.field_id,
    f.name as field_name,
    ltf.role as field_role,
    ecom.mapping_kind,
    ecn.code as classification_code,
    ecn.title as classification_title
  from public.learning_target_fields ltf
  join public.fields f on f.id = ltf.field_id
  join public.field_external_classifications fec on fec.field_id = ltf.field_id
  join public.external_classification_nodes fn on fn.id = fec.classification_node_id
  join public.external_classification_nodes ecn
    on ecn.system = fn.system
   and ecn.version = fn.version
   and (
     ecn.id = fn.id or
     (fn.level_code = 'series' and substring(ecn.code from 1 for 2) = fn.code) or
     (fn.level_code = 'group' and substring(ecn.code from 1 for 5) = fn.code)
   )
  join public.external_classification_occupation_mappings ecom on ecom.classification_node_id = ecn.id
  join public.occupation_nodes ocn on ocn.id = ecom.occupation_id
  where ltf.target_id = p_target_id
    and ocn.is_active = true
  order by ltf.role asc, ocn.code asc;
end;
$$;

revoke all on function public.get_target_crosswalk_occupations(uuid) from public;
grant execute on function public.get_target_crosswalk_occupations(uuid) to anon, authenticated, service_role;

-- Harden get_cross_target_shared_concepts
create or replace function public.get_cross_target_shared_concepts(
  p_target_a_id uuid,
  p_target_b_id uuid
)
returns table (
  concept_id uuid,
  concept_slug text,
  concept_name text,
  short_definition text,
  emoji text,
  target_a_nodes bigint,
  target_b_nodes bigint
)
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
begin
  if not public.is_target_visible(p_target_a_id) then
    raise exception 'Unauthorized or target not found: %', p_target_a_id;
  end if;

  if not public.is_target_visible(p_target_b_id) then
    raise exception 'Unauthorized or target not found: %', p_target_b_id;
  end if;

  return query
  with target_a_concepts as (
    select distinct cnc.concept_id, count(cnc.curriculum_node_id) as node_count
    from public.curriculum_nodes cn
    join public.target_versions tv on tv.id = cn.target_version_id
    join public.curriculum_node_concepts cnc on cnc.curriculum_node_id = cn.id
    where tv.target_id = p_target_a_id
    group by cnc.concept_id
  ),
  target_b_concepts as (
    select distinct cnc.concept_id, count(cnc.curriculum_node_id) as node_count
    from public.curriculum_nodes cn
    join public.target_versions tv on tv.id = cn.target_version_id
    join public.curriculum_node_concepts cnc on cnc.curriculum_node_id = cn.id
    where tv.target_id = p_target_b_id
    group by cnc.concept_id
  )
  select
    kc.id as concept_id,
    kc.slug as concept_slug,
    kc.name as concept_name,
    kc.short_definition,
    kc.emoji,
    ta.node_count as target_a_nodes,
    tb.node_count as target_b_nodes
  from target_a_concepts ta
  join target_b_concepts tb on tb.concept_id = ta.concept_id
  join public.knowledge_concepts kc on kc.id = ta.concept_id
  order by kc.name asc;
end;
$$;

revoke all on function public.get_cross_target_shared_concepts(uuid, uuid) from public;
grant execute on function public.get_cross_target_shared_concepts(uuid, uuid) to anon, authenticated, service_role;

-- Enforce security_invoker = true on target and field occupation views
alter view public.v_target_occupation_mappings set (security_invoker = true);
alter view public.v_field_occupation_mappings set (security_invoker = true);

-- ----------------------------------------------------------------------------
-- 4. Content Source Artifacts Provenance Visibility Hardening
-- ----------------------------------------------------------------------------
drop policy if exists "public_read_content_source_artifacts" on public.content_source_artifacts;
drop policy if exists "content_source_artifacts_read" on public.content_source_artifacts;

create policy "content_source_artifacts_read"
  on public.content_source_artifacts for select
  to authenticated, anon
  using (
    auth.role() = 'service_role'
    or exists (
      select 1 from public.content_source_mappings csm
      where csm.source_release_id = content_source_artifacts.source_release_id
    )
  );

drop policy if exists "content_source_artifacts_service_write" on public.content_source_artifacts;

create policy "content_source_artifacts_service_write"
  on public.content_source_artifacts for all
  using (auth.role() = 'service_role')
  with check (auth.role() = 'service_role');

INSERT INTO supabase_migrations.schema_migrations (version, name) VALUES ('20261009000000', 'manifest_concept_mappings_and_target_security') ON CONFLICT (version) DO NOTHING;

-- --------------------------------------------------------------------
-- [33/96] Migration: 20261009000001_harden_cross_version_mappings_and_target_version_security.sql
-- --------------------------------------------------------------------
-- ============================================================================
-- Migration: 20261009000001_harden_cross_version_mappings_and_target_version_security.sql
-- Description:
--   1. Harden Concept Mapping Invariants:
--      Enforce conditional constraint on target_version_concept_mappings:
--      'removed' mappings MUST have to_concept_id IS NULL and transfer_weight = 0;
--      non-'removed' mappings MUST have to_concept_id IS NOT NULL.
--   2. Validate Concept Associations to Declared Versions:
--      In ingest_curriculum_manifest, fail closed if from_concept is not associated
--      with from_target_version through curriculum_node_concepts, or if to_concept
--      is not associated with the destination target_version through curriculum_node_concepts.
--   3. Eliminate Draft-Version Leakage in Shared Concepts RPC:
--      Introduce is_target_version_visible(uuid) matching target_versions RLS semantics.
--      Filter both CTEs in get_cross_target_shared_concepts through is_target_version_visible.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. Concept Mapping Invariant Constraint Hardening
-- ----------------------------------------------------------------------------
alter table public.target_version_concept_mappings
  drop constraint if exists tv_concept_mappings_removed_check;

alter table public.target_version_concept_mappings
  add constraint tv_concept_mappings_removed_check
  check (
    (
      mapping_type = 'removed'
      and to_concept_id is null
      and transfer_weight = 0
    )
    or
    (
      mapping_type <> 'removed'
      and to_concept_id is not null
    )
  );

-- ----------------------------------------------------------------------------
-- 2. Target Version Visibility Security Helper
-- ----------------------------------------------------------------------------
create or replace function public.is_target_version_visible(p_target_version_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.target_versions tv
    join public.learning_targets lt on lt.id = tv.target_id
    where tv.id = p_target_version_id
      and (
        coalesce(auth.role(), '') = 'service_role'
        or (lt.status = 'published' and lt.is_public = true and tv.status = 'published')
        or (auth.uid() is not null and lt.created_by = auth.uid())
        or (auth.uid() is not null and tv.status = 'review_ready' and public.is_target_reviewer(lt.id))
      )
  );
$$;

revoke all on function public.is_target_version_visible(uuid) from public;
grant execute on function public.is_target_version_visible(uuid) to anon, authenticated, service_role;

-- ----------------------------------------------------------------------------
-- 3. Harden get_cross_target_shared_concepts with Version Visibility Check
-- ----------------------------------------------------------------------------
create or replace function public.get_cross_target_shared_concepts(
  p_target_a_id uuid,
  p_target_b_id uuid
)
returns table (
  concept_id uuid,
  concept_slug text,
  concept_name text,
  short_definition text,
  emoji text,
  target_a_nodes bigint,
  target_b_nodes bigint
)
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
begin
  if not public.is_target_visible(p_target_a_id) then
    raise exception 'Unauthorized or target not found: %', p_target_a_id;
  end if;

  if not public.is_target_visible(p_target_b_id) then
    raise exception 'Unauthorized or target not found: %', p_target_b_id;
  end if;

  return query
  with target_a_concepts as (
    select distinct cnc.concept_id, count(cnc.curriculum_node_id) as node_count
    from public.curriculum_nodes cn
    join public.target_versions tv on tv.id = cn.target_version_id
    join public.curriculum_node_concepts cnc on cnc.curriculum_node_id = cn.id
    where tv.target_id = p_target_a_id
      and public.is_target_version_visible(tv.id)
    group by cnc.concept_id
  ),
  target_b_concepts as (
    select distinct cnc.concept_id, count(cnc.curriculum_node_id) as node_count
    from public.curriculum_nodes cn
    join public.target_versions tv on tv.id = cn.target_version_id
    join public.curriculum_node_concepts cnc on cnc.curriculum_node_id = cn.id
    where tv.target_id = p_target_b_id
      and public.is_target_version_visible(tv.id)
    group by cnc.concept_id
  )
  select
    kc.id as concept_id,
    kc.slug as concept_slug,
    kc.name as concept_name,
    kc.short_definition,
    kc.emoji,
    ta.node_count as target_a_nodes,
    tb.node_count as target_b_nodes
  from target_a_concepts ta
  join target_b_concepts tb on tb.concept_id = ta.concept_id
  join public.knowledge_concepts kc on kc.id = ta.concept_id
  order by kc.name asc;
end;
$$;

revoke all on function public.get_cross_target_shared_concepts(uuid, uuid) from public;
grant execute on function public.get_cross_target_shared_concepts(uuid, uuid) to anon, authenticated, service_role;

-- ----------------------------------------------------------------------------
-- 4. Harden ingest_curriculum_manifest with Provenance & Invariant Validation
-- ----------------------------------------------------------------------------
create or replace function public.ingest_curriculum_manifest(
  payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_field_id uuid;
  v_field_slug text;
  v_target_id uuid;
  v_target_slug text;
  v_version_id uuid;
  v_version_code text;
  v_version_status text;

  -- Counters
  v_concepts_count int := 0;
  v_stimuli_count int := 0;
  v_domains_count int := 0;
  v_objectives_count int := 0;
  v_lessons_count int := 0;
  v_blocks_count int := 0;
  v_items_count int := 0;
  v_flashcards_count int := 0;
  v_questions_count int := 0;
  v_mappings_count int := 0;

  -- Lookup Maps
  v_stimuli_map jsonb := '{}'::jsonb;         -- stimulus_key -> uuid
  v_concepts_map jsonb := '{}'::jsonb;        -- slug -> uuid
  v_source_releases_map jsonb := '{}'::jsonb; -- source_id or index -> uuid
  v_default_rel_id uuid := null;

  -- Concept processing variables
  v_concept jsonb;
  v_concept_id uuid;
  v_concept_slug text;
  v_concept_name text;
  v_explicit_canon text;
  v_matched_id uuid;
  v_matched_is_ambig boolean;
  v_concept_rel_id uuid;

  -- Content processing variables
  v_stim jsonb;
  v_stim_key text;
  v_stim_id uuid;
  v_domain jsonb;
  v_domain_id uuid;
  v_obj jsonb;
  v_obj_id uuid;
  v_lesson jsonb;
  v_lesson_id uuid;
  v_block jsonb;
  v_block_id uuid;
  v_item jsonb;
  v_item_id uuid;
  v_fc jsonb;
  v_fc_id uuid;
  v_term jsonb;
  v_question jsonb;
  v_mapping jsonb;
  v_source_rel jsonb;
  v_source_rel_idx int := 0;
  v_rel_id uuid;
  v_source_artifact jsonb;
  v_mapping_id uuid;
  v_source_mapping jsonb;
  v_from_concept_id uuid;
  v_to_concept_id uuid;

  v_entity_rel_id uuid;
  v_lesson_rel_id uuid;
  v_obj_rel_id uuid;
  v_raw_concept_ref text;
  v_resolved_cid uuid;

  -- Concept mapping resolution variables
  v_from_version_code text;
  v_from_concept_slug text;
  v_to_concept_slug text;
  v_mapping_type text;
  v_from_tv_id uuid;
  v_to_tv_id uuid;
  v_transfer_weight numeric;
  v_concept_mappings_count int := 0;
begin

  -- 1. Security Check: Service-role only
  if coalesce(current_setting('request.jwt.claim.role', true), '') <> 'service_role'
     and auth.role() <> 'service_role' then
    raise exception 'Unauthorized: ingest_curriculum_manifest requires service_role privilege';
  end if;

  -- 2. Extract / Upsert Field
  v_field_slug := payload->'field'->>'slug';
  if v_field_slug is not null and v_field_slug <> '' then
    select id into v_field_id from public.fields where slug = v_field_slug;
    if v_field_id is null then
      insert into public.fields (slug, name, description, field_kind)
      values (
        v_field_slug,
        coalesce(payload->'field'->>'name', v_field_slug),
        payload->'field'->>'description',
        'native_field'
      )
      returning id into v_field_id;
    end if;
  end if;

  -- 3. Extract / Upsert LearningTarget
  v_target_slug := payload->'target'->>'slug';
  if v_target_slug is null or v_target_slug = '' then
    raise exception 'Missing target.slug in manifest payload';
  end if;

  select id into v_target_id from public.learning_targets where slug = v_target_slug;
  if v_target_id is null then
    insert into public.learning_targets (
      slug, title, target_type, description, field_id, status, is_public
    ) values (
      v_target_slug,
      coalesce(payload->'target'->>'title', v_target_slug),
      coalesce(payload->'target'->>'target_type', coalesce(payload->'target'->>'target_kind', 'certification')),
      payload->'target'->>'description',
      v_field_id,
      'published',
      true
    )
    returning id into v_target_id;
  end if;

  -- 4. Extract / Upsert TargetVersion
  v_version_code := payload->'target_version'->>'version_code';
  if v_version_code is null or v_version_code = '' then
    raise exception 'Missing target_version.version_code in manifest payload';
  end if;

  select id, status into v_version_id, v_version_status
  from public.target_versions
  where target_id = v_target_id and version_code = v_version_code;

  if v_version_id is null then
    insert into public.target_versions (
      target_id, version_code, title, description, valid_from, status, metadata
    ) values (
      v_target_id,
      v_version_code,
      coalesce(payload->'target_version'->>'title', payload->'target'->>'version_title', v_version_code),
      coalesce(payload->'target_version'->>'description', payload->'target'->>'version_description'),
      case when coalesce(payload->'target_version'->>'valid_from', payload->'target'->>'valid_from') is not null
           then (coalesce(payload->'target_version'->>'valid_from', payload->'target'->>'valid_from'))::date
           else null end,
      'draft',
      coalesce(payload->'target_version'->'metadata', '{}'::jsonb)
    )
    returning id, status into v_version_id, v_version_status;
  else
    if v_version_status <> 'draft' then
      raise exception 'Cannot ingest into TargetVersion "%" with status "%". Only draft versions may be replaced.', v_version_code, v_version_status;
    end if;

    update public.target_versions
    set title = coalesce(payload->'target_version'->>'title', payload->'target'->>'version_title', title),
        description = coalesce(payload->'target_version'->>'description', payload->'target'->>'version_description', description),
        valid_from = case when coalesce(payload->'target_version'->>'valid_from', payload->'target'->>'valid_from') is not null
                          then (coalesce(payload->'target_version'->>'valid_from', payload->'target'->>'valid_from'))::date
                          else valid_from end,
        metadata = coalesce(payload->'target_version'->'metadata', metadata),
        updated_at = now()
    where id = v_version_id;
  end if;

  -- 5. Atomically Clean Previous Draft Content for this TargetVersion
  perform public.clean_draft_target_version(v_version_id);

  -- 6. Ingest Source Releases
  if jsonb_typeof(coalesce(payload->'source_releases', payload->'sources')) = 'array' then
    for v_source_rel in select * from jsonb_array_elements(coalesce(payload->'source_releases', payload->'sources'))
    loop
      insert into public.content_source_releases (
        publisher, title, version, source_url, license, retrieved_at, sha256, metadata
      ) values (
        coalesce(v_source_rel->>'publisher', 'Authoritative Source'),
        coalesce(v_source_rel->>'title', 'Official Blueprint'),
        coalesce(v_source_rel->>'version', 'v1'),
        v_source_rel->>'source_url',
        coalesce(v_source_rel->>'license', v_source_rel->>'license_name'),
        case when v_source_rel->>'retrieved_at' is not null
             then (v_source_rel->>'retrieved_at')::timestamptz
             else now() end,
        v_source_rel->>'sha256',
        coalesce(v_source_rel->'metadata', '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
          'system', v_source_rel->>'system',
          'rights_note', v_source_rel->>'rights_note'
        ))
      )
      on conflict (publisher, title, version) do update
      set source_url = excluded.source_url,
          license = excluded.license,
          retrieved_at = excluded.retrieved_at,
          sha256 = excluded.sha256,
          metadata = excluded.metadata
      returning id into v_rel_id;

      v_source_rel_idx := v_source_rel_idx + 1;
      if v_default_rel_id is null then
        v_default_rel_id := v_rel_id;
      end if;

      if v_source_rel ? 'id' then
        v_source_releases_map := v_source_releases_map || jsonb_build_object(v_source_rel->>'id', v_rel_id::text);
      end if;
      if v_source_rel ? 'source_id' then
        v_source_releases_map := v_source_releases_map || jsonb_build_object(v_source_rel->>'source_id', v_rel_id::text);
      end if;
      v_source_releases_map := v_source_releases_map || jsonb_build_object(
        coalesce(v_source_rel->>'publisher', '') || '/' || coalesce(v_source_rel->>'version', ''), v_rel_id::text
      );
      v_source_releases_map := v_source_releases_map || jsonb_build_object(
        (v_source_rel_idx - 1)::text, v_rel_id::text
      );

      -- Link root target_version to this source release
      insert into public.content_source_mappings (
        source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
      ) values (
        v_rel_id,
        'target_version',
        v_version_id,
        'official_blueprint',
        coalesce(payload->'target_version'->>'citation', 'Root Blueprint'),
        'Root target version mapping to authoritative source release',
        '{}'::jsonb
      )
      on conflict (source_release_id, entity_type, entity_id, relationship) do update
      set citation_location = excluded.citation_location,
          notes = excluded.notes,
          metadata = excluded.metadata
      returning id into v_mapping_id;

      v_mappings_count := v_mappings_count + 1;
      insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
      values (v_version_id, 'content_source_mapping', v_mapping_id)
      on conflict do nothing;

      -- Source Artifacts
      if jsonb_typeof(v_source_rel->'artifacts') = 'array' then
        for v_source_artifact in select * from jsonb_array_elements(v_source_rel->'artifacts')
        loop
          insert into public.content_source_artifacts (
            source_release_id, artifact_name, source_url, sha256, file_size_bytes, retrieved_at, metadata
          ) values (
            v_rel_id,
            coalesce(v_source_artifact->>'artifact_name', 'blueprint.pdf'),
            v_source_artifact->>'source_url',
            v_source_artifact->>'sha256',
            case when v_source_artifact->>'file_size_bytes' is not null
                 then (v_source_artifact->>'file_size_bytes')::bigint
                 else null end,
            case when v_source_artifact->>'retrieved_at' is not null
                 then (v_source_artifact->>'retrieved_at')::timestamptz
                 else now() end,
            coalesce(v_source_artifact->'metadata', '{}'::jsonb)
          )
          on conflict (source_release_id, artifact_name) do update
          set source_url = excluded.source_url,
              sha256 = excluded.sha256,
              file_size_bytes = excluded.file_size_bytes,
              retrieved_at = excluded.retrieved_at,
              metadata = excluded.metadata;
        end loop;
      end if;
    end loop;
  end if;

  -- 7. Fully Transactional Canonical Concepts Resolution & Ingestion (Option A)
  if jsonb_typeof(payload->'concepts') = 'array' then
    for v_concept in select * from jsonb_array_elements(payload->'concepts')
    loop
      v_concept_slug := v_concept->>'slug';
      v_concept_name := coalesce(v_concept->>'name', v_concept_slug);
      v_explicit_canon := v_concept->>'canonical_concept';
      v_concept_id := null;

      if v_explicit_canon is not null and trim(v_explicit_canon) <> '' then
        select id into v_concept_id
        from public.knowledge_concepts
        where slug = trim(v_explicit_canon);

        if v_concept_id is null then
          raise exception 'Explicit canonical_concept "%" declared for concept "%" (%) does not exist in knowledge_concepts. Overrides must fail closed.', v_explicit_canon, v_concept_name, v_concept_slug;
        end if;

        if v_field_id is not null then
          insert into public.concept_fields (concept_id, field_id, relationship)
          values (v_concept_id, v_field_id, 'core_concept')
          on conflict (concept_id, field_id) do nothing;
        end if;
      else
        -- Ambiguity-safe resolution RPC
        select r.id, r.is_ambiguous into v_matched_id, v_matched_is_ambig
        from public.resolve_canonical_concept(v_concept_slug, v_concept_name, v_field_id) r
        limit 1;

        if v_matched_is_ambig then
          raise exception 'Ambiguous canonical concept match for "%" (%). Multiple concepts share this name across fields and target field does not disambiguate. Declare "canonical_concept: <existing-slug>" explicitly in the manifest to resolve the ambiguity, or make the concept name specific.', v_concept_name, v_concept_slug;
        end if;

        if v_matched_id is not null then
          v_concept_id := v_matched_id;
          if v_field_id is not null then
            insert into public.concept_fields (concept_id, field_id, relationship)
            values (v_concept_id, v_field_id, 'core_concept')
            on conflict (concept_id, field_id) do nothing;
          end if;
        else
          -- Insert new canonical knowledge concept
          insert into public.knowledge_concepts (
            field_id, slug, name, short_definition, description, emoji, aliases, status
          ) values (
            v_field_id,
            v_concept_slug,
            v_concept_name,
            v_concept->>'short_definition',
            v_concept->>'description',
            coalesce(v_concept->>'emoji', '💡'),
            case when jsonb_typeof(v_concept->'aliases') = 'array'
                 then array(select jsonb_array_elements_text(v_concept->'aliases'))
                 else array[]::text[] end,
            'active'
          )
          returning id into v_concept_id;

          if v_field_id is not null then
            insert into public.concept_fields (concept_id, field_id, relationship)
            values (v_concept_id, v_field_id, 'core_concept')
            on conflict (concept_id, field_id) do nothing;
          end if;
        end if;
      end if;

      v_concepts_count := v_concepts_count + 1;
      v_concepts_map := v_concepts_map || jsonb_build_object(v_concept_slug, v_concept_id::text);

      -- Canonical Concept Provenance Mapping
      if v_default_rel_id is not null then
        v_concept_rel_id := null;
        if v_concept ? 'source_release_id' and v_source_releases_map ? (v_concept->>'source_release_id') then
          v_concept_rel_id := (v_source_releases_map->>(v_concept->>'source_release_id'))::uuid;
        elsif v_concept ? 'source_id' and v_source_releases_map ? (v_concept->>'source_id') then
          v_concept_rel_id := (v_source_releases_map->>(v_concept->>'source_id'))::uuid;
        else
          v_concept_rel_id := v_default_rel_id;
        end if;

        if v_concept_rel_id is not null then
          insert into public.content_source_mappings (
            source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
          ) values (
            v_concept_rel_id,
            'knowledge_concept',
            v_concept_id,
            coalesce(v_concept->>'relationship', 'official_blueprint'),
            coalesce(v_concept->>'citation', coalesce(v_concept->>'citation_location', 'Concept ' || v_concept_slug)),
            coalesce(v_concept->>'notes', coalesce(v_concept->>'citation_notes', 'Authoritative concept definition from blueprint')),
            '{}'::jsonb
          )
          on conflict (source_release_id, entity_type, entity_id, relationship) do update
          set citation_location = excluded.citation_location,
              notes = excluded.notes,
              metadata = excluded.metadata;

          v_mappings_count := v_mappings_count + 1;
        end if;
      end if;
    end loop;
  end if;

  -- 8. Ingest Shared Stimuli (root-level & objective-level)
  if jsonb_typeof(payload->'stimuli') = 'array' then
    for v_stim in select * from jsonb_array_elements(payload->'stimuli')
    loop
      v_stim_key := v_stim->>'stimulus_key';
      insert into public.assessment_stimuli (
        title, body, stimulus_type, metadata, origin_target_version_id
      ) values (
        coalesce(v_stim->>'title', 'Exhibit'),
        coalesce(v_stim->>'body', coalesce(v_stim->>'body_markdown', '')),
        coalesce(v_stim->>'stimulus_type', 'scenario'),
        jsonb_build_object(
          'media_url', v_stim->>'media_url',
          'credit', v_stim->>'credit',
          'attribution', v_stim->>'attribution'
        ),
        v_version_id
      )
      returning id into v_stim_id;

      v_stimuli_count := v_stimuli_count + 1;
      v_stimuli_map := v_stimuli_map || jsonb_build_object(v_stim_key, v_stim_id::text);

      insert into public.content_import_artifacts (target_version_id, entity_type, entity_id, manifest_key)
      values (v_version_id, 'assessment_stimulus', v_stim_id, v_stim_key);

      -- Stimulus Source Mapping
      if v_default_rel_id is not null then
        v_entity_rel_id := null;
        if v_stim ? 'source_release_id' and v_source_releases_map ? (v_stim->>'source_release_id') then
          v_entity_rel_id := (v_source_releases_map->>(v_stim->>'source_release_id'))::uuid;
        elsif v_stim ? 'source_id' and v_source_releases_map ? (v_stim->>'source_id') then
          v_entity_rel_id := (v_source_releases_map->>(v_stim->>'source_id'))::uuid;
        else
          v_entity_rel_id := v_default_rel_id;
        end if;

        if v_entity_rel_id is not null then
          insert into public.content_source_mappings (
            source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
          ) values (
            v_entity_rel_id,
            'assessment_stimulus',
            v_stim_id,
            'official_blueprint',
            coalesce(v_stim->>'citation', coalesce(v_stim->>'citation_location', 'Official Blueprint Stimulus')),
            coalesce(v_stim->>'notes', 'Assessment stimulus mapping'),
            '{}'::jsonb
          )
          on conflict (source_release_id, entity_type, entity_id, relationship) do update
          set citation_location = excluded.citation_location,
              notes = excluded.notes,
              metadata = excluded.metadata
          returning id into v_mapping_id;

          v_mappings_count := v_mappings_count + 1;
          insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
          values (v_version_id, 'content_source_mapping', v_mapping_id)
          on conflict do nothing;
        end if;
      end if;
    end loop;
  end if;

  -- 9. Ingest Standalone Target-level Flashcards
  if jsonb_typeof(payload->'flashcards') = 'array' then
    for v_fc in select * from jsonb_array_elements(payload->'flashcards')
    loop
      insert into public.flashcards (
        front, back, explanation, origin_target_version_id
      ) values (
        v_fc->>'front',
        v_fc->>'back',
        v_fc->>'explanation',
        v_version_id
      )
      returning id into v_fc_id;

      v_flashcards_count := v_flashcards_count + 1;
      insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
      values (v_version_id, 'flashcard', v_fc_id);

      -- Link concepts by UUID or slug lookup
      if jsonb_typeof(v_fc->'concept_ids') = 'array' then
        for v_concept_id in select (jsonb_array_elements_text(v_fc->'concept_ids'))::uuid
        loop
          insert into public.flashcard_concepts (flashcard_id, concept_id)
          values (v_fc_id, v_concept_id)
          on conflict do nothing;
        end loop;
      end if;

      if jsonb_typeof(v_fc->'concept_slugs') = 'array' then
        for v_raw_concept_ref in select jsonb_array_elements_text(v_fc->'concept_slugs')
        loop
          if v_concepts_map ? v_raw_concept_ref then
            v_resolved_cid := (v_concepts_map->>v_raw_concept_ref)::uuid;
            insert into public.flashcard_concepts (flashcard_id, concept_id)
            values (v_fc_id, v_resolved_cid)
            on conflict do nothing;
          end if;
        end loop;
      end if;

      -- Flashcard Provenance Mapping
      if v_default_rel_id is not null then
        v_entity_rel_id := null;
        if v_fc ? 'source_release_id' and v_source_releases_map ? (v_fc->>'source_release_id') then
          v_entity_rel_id := (v_source_releases_map->>(v_fc->>'source_release_id'))::uuid;
        elsif v_fc ? 'source_id' and v_source_releases_map ? (v_fc->>'source_id') then
          v_entity_rel_id := (v_source_releases_map->>(v_fc->>'source_id'))::uuid;
        else
          v_entity_rel_id := v_default_rel_id;
        end if;

        if v_entity_rel_id is not null then
          insert into public.content_source_mappings (
            source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
          ) values (
            v_entity_rel_id,
            'flashcard',
            v_fc_id,
            'derived_from',
            coalesce(v_fc->>'citation', coalesce(v_fc->>'citation_location', coalesce(v_fc->>'front', 'Flashcard'))),
            coalesce(v_fc->>'notes', 'Flashcard derived from authoritative blueprint'),
            '{}'::jsonb
          )
          on conflict (source_release_id, entity_type, entity_id, relationship) do update
          set citation_location = excluded.citation_location,
              notes = excluded.notes,
              metadata = excluded.metadata
          returning id into v_mapping_id;

          v_mappings_count := v_mappings_count + 1;
          insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
          values (v_version_id, 'content_source_mapping', v_mapping_id)
          on conflict do nothing;
        end if;
      end if;
    end loop;
  end if;

  -- 10. Ingest Domains, Objectives, Lessons, Blocks, Assessment Items
  if jsonb_typeof(payload->'domains') = 'array' then
    for v_domain in select * from jsonb_array_elements(payload->'domains')
    loop
      insert into public.curriculum_nodes (
        target_version_id, node_type, code, title, description, sort_order, weight, metadata
      ) values (
        v_version_id,
        'domain',
        v_domain->>'code',
        coalesce(v_domain->>'title', 'Domain'),
        v_domain->>'description',
        coalesce((v_domain->>'sort_order')::int, 0),
        case when v_domain->>'weight_percentage' is not null
             then (v_domain->>'weight_percentage')::numeric
             when v_domain->>'weight' is not null
             then (v_domain->>'weight')::numeric
             else null end,
        coalesce(v_domain->'metadata', '{}'::jsonb)
      )
      returning id into v_domain_id;

      v_domains_count := v_domains_count + 1;
      insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
      values (v_version_id, 'curriculum_node', v_domain_id);

      -- Domain Source Mapping
      if v_default_rel_id is not null then
        v_entity_rel_id := null;
        if v_domain ? 'source_release_id' and v_source_releases_map ? (v_domain->>'source_release_id') then
          v_entity_rel_id := (v_source_releases_map->>(v_domain->>'source_release_id'))::uuid;
        elsif v_domain ? 'source_id' and v_source_releases_map ? (v_domain->>'source_id') then
          v_entity_rel_id := (v_source_releases_map->>(v_domain->>'source_id'))::uuid;
        else
          v_entity_rel_id := v_default_rel_id;
        end if;

        if v_entity_rel_id is not null then
          insert into public.content_source_mappings (
            source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
          ) values (
            v_entity_rel_id,
            'curriculum_node',
            v_domain_id,
            'official_blueprint',
            coalesce(v_domain->>'citation', coalesce(v_domain->>'citation_location', 'Domain ' || coalesce(v_domain->>'code', ''))),
            coalesce(v_domain->>'notes', 'Curriculum domain node citation'),
            '{}'::jsonb
          )
          on conflict (source_release_id, entity_type, entity_id, relationship) do update
          set citation_location = excluded.citation_location,
              notes = excluded.notes,
              metadata = excluded.metadata
          returning id into v_mapping_id;

          v_mappings_count := v_mappings_count + 1;
          insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
          values (v_version_id, 'content_source_mapping', v_mapping_id)
          on conflict do nothing;
        end if;
      end if;

      -- Objectives
      if jsonb_typeof(v_domain->'objectives') = 'array' then
        for v_obj in select * from jsonb_array_elements(v_domain->'objectives')
        loop
          insert into public.curriculum_nodes (
            target_version_id, parent_id, node_type, code, title, description, sort_order, metadata
          ) values (
            v_version_id,
            v_domain_id,
            'objective',
            v_obj->>'code',
            coalesce(v_obj->>'title', 'Objective'),
            v_obj->>'description',
            coalesce((v_obj->>'sort_order')::int, 0),
            jsonb_build_object('bloom_level', coalesce(v_obj->>'bloom_level', 'understand'))
          )
          returning id into v_obj_id;

          v_objectives_count := v_objectives_count + 1;
          insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
          values (v_version_id, 'curriculum_node', v_obj_id);

          -- Objective Source Mapping
          if v_default_rel_id is not null then
            v_entity_rel_id := null;
            if v_obj ? 'source_release_id' and v_source_releases_map ? (v_obj->>'source_release_id') then
              v_entity_rel_id := (v_source_releases_map->>(v_obj->>'source_release_id'))::uuid;
            elsif v_obj ? 'source_id' and v_source_releases_map ? (v_obj->>'source_id') then
              v_entity_rel_id := (v_source_releases_map->>(v_obj->>'source_id'))::uuid;
            else
              v_entity_rel_id := coalesce(
                (v_source_releases_map->>(v_domain->>'source_release_id'))::uuid,
                (v_source_releases_map->>(v_domain->>'source_id'))::uuid,
                v_default_rel_id
              );
            end if;

            v_obj_rel_id := v_entity_rel_id;

            if v_entity_rel_id is not null then
              insert into public.content_source_mappings (
                source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
              ) values (
                v_entity_rel_id,
                'curriculum_node',
                v_obj_id,
                'official_blueprint',
                coalesce(v_obj->>'citation', coalesce(v_obj->>'citation_location', 'Objective ' || coalesce(v_obj->>'code', ''))),
                coalesce(v_obj->>'notes', 'Curriculum objective node citation'),
                '{}'::jsonb
              )
              on conflict (source_release_id, entity_type, entity_id, relationship) do update
              set citation_location = excluded.citation_location,
                  notes = excluded.notes,
                  metadata = excluded.metadata
              returning id into v_mapping_id;

              v_mappings_count := v_mappings_count + 1;
              insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
              values (v_version_id, 'content_source_mapping', v_mapping_id)
              on conflict do nothing;
            end if;
          end if;

          -- Link objective concepts by UUID or slug
          if jsonb_typeof(v_obj->'concept_ids') = 'array' then
            for v_concept_id in select (jsonb_array_elements_text(v_obj->'concept_ids'))::uuid
            loop
              insert into public.curriculum_node_concepts (curriculum_node_id, concept_id)
              values (v_obj_id, v_concept_id)
              on conflict do nothing;
            end loop;
          end if;

          if jsonb_typeof(v_obj->'concept_slugs') = 'array' then
            for v_raw_concept_ref in select jsonb_array_elements_text(v_obj->'concept_slugs')
            loop
              if v_concepts_map ? v_raw_concept_ref then
                v_resolved_cid := (v_concepts_map->>v_raw_concept_ref)::uuid;
                insert into public.curriculum_node_concepts (curriculum_node_id, concept_id)
                values (v_obj_id, v_resolved_cid)
                on conflict do nothing;
              end if;
            end loop;
          end if;

          -- Objective Flashcards
          if jsonb_typeof(v_obj->'flashcards') = 'array' then
            for v_fc in select * from jsonb_array_elements(v_obj->'flashcards')
            loop
              insert into public.flashcards (
                front, back, explanation, origin_target_version_id
              ) values (
                v_fc->>'front',
                v_fc->>'back',
                v_fc->>'explanation',
                v_version_id
              )
              returning id into v_fc_id;

              v_flashcards_count := v_flashcards_count + 1;
              insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
              values (v_version_id, 'flashcard', v_fc_id);

              if jsonb_typeof(v_fc->'concept_ids') = 'array' then
                for v_concept_id in select (jsonb_array_elements_text(v_fc->'concept_ids'))::uuid
                loop
                  insert into public.flashcard_concepts (flashcard_id, concept_id)
                  values (v_fc_id, v_concept_id)
                  on conflict do nothing;
                end loop;
              end if;

              if jsonb_typeof(v_fc->'concept_slugs') = 'array' then
                for v_raw_concept_ref in select jsonb_array_elements_text(v_fc->'concept_slugs')
                loop
                  if v_concepts_map ? v_raw_concept_ref then
                    v_resolved_cid := (v_concepts_map->>v_raw_concept_ref)::uuid;
                    insert into public.flashcard_concepts (flashcard_id, concept_id)
                    values (v_fc_id, v_resolved_cid)
                    on conflict do nothing;
                  end if;
                end loop;
              end if;

              -- Objective Flashcard Provenance Mapping
              if v_default_rel_id is not null then
                v_entity_rel_id := null;
                if v_fc ? 'source_release_id' and v_source_releases_map ? (v_fc->>'source_release_id') then
                  v_entity_rel_id := (v_source_releases_map->>(v_fc->>'source_release_id'))::uuid;
                elsif v_fc ? 'source_id' and v_source_releases_map ? (v_fc->>'source_id') then
                  v_entity_rel_id := (v_source_releases_map->>(v_fc->>'source_id'))::uuid;
                else
                  v_entity_rel_id := coalesce(v_obj_rel_id, v_default_rel_id);
                end if;

                if v_entity_rel_id is not null then
                  insert into public.content_source_mappings (
                    source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
                  ) values (
                    v_entity_rel_id,
                    'flashcard',
                    v_fc_id,
                    'derived_from',
                    coalesce(v_fc->>'citation', coalesce(v_fc->>'citation_location', coalesce(v_fc->>'front', 'Objective Flashcard'))),
                    coalesce(v_fc->>'notes', 'Flashcard derived from authoritative objective blueprint'),
                    '{}'::jsonb
                  )
                  on conflict (source_release_id, entity_type, entity_id, relationship) do update
                  set citation_location = excluded.citation_location,
                      notes = excluded.notes,
                      metadata = excluded.metadata
                  returning id into v_mapping_id;

                  v_mappings_count := v_mappings_count + 1;
                  insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
                  values (v_version_id, 'content_source_mapping', v_mapping_id)
                  on conflict do nothing;
                end if;
              end if;
            end loop;
          end if;

          -- Objective Assessment Items
          if jsonb_typeof(v_obj->'assessment_items') = 'array' then
            for v_item in select * from jsonb_array_elements(v_obj->'assessment_items')
            loop
              v_stim_key := v_item->>'stimulus_key';
              v_stim_id := null;
              if v_stim_key is not null and v_stimuli_map ? v_stim_key then
                v_stim_id := (v_stimuli_map->>v_stim_key)::uuid;
              end if;

              insert into public.assessment_items (
                stimulus_id, prompt, interaction_type, response_spec, scoring_spec, explanation, origin_target_version_id
              ) values (
                v_stim_id,
                v_item->>'prompt',
                coalesce(v_item->>'interaction_type', 'single_choice'),
                coalesce(v_item->'response_spec', '{}'::jsonb),
                coalesce(v_item->'scoring_spec', '{}'::jsonb),
                v_item->>'explanation',
                v_version_id
              )
              returning id into v_item_id;

              v_items_count := v_items_count + 1;
              insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
              values (v_version_id, 'assessment_item', v_item_id);

              if jsonb_typeof(v_item->'concept_ids') = 'array' then
                for v_concept_id in select (jsonb_array_elements_text(v_item->'concept_ids'))::uuid
                loop
                  insert into public.assessment_item_concepts (assessment_item_id, concept_id)
                  values (v_item_id, v_concept_id)
                  on conflict do nothing;
                end loop;
              end if;

              if jsonb_typeof(v_item->'concept_slugs') = 'array' then
                for v_raw_concept_ref in select jsonb_array_elements_text(v_item->'concept_slugs')
                loop
                  if v_concepts_map ? v_raw_concept_ref then
                    v_resolved_cid := (v_concepts_map->>v_raw_concept_ref)::uuid;
                    insert into public.assessment_item_concepts (assessment_item_id, concept_id)
                    values (v_item_id, v_resolved_cid)
                    on conflict do nothing;
                  end if;
                end loop;
              end if;

              -- Objective Assessment Item Provenance Mapping
              if v_default_rel_id is not null then
                v_entity_rel_id := null;
                if v_item ? 'source_release_id' and v_source_releases_map ? (v_item->>'source_release_id') then
                  v_entity_rel_id := (v_source_releases_map->>(v_item->>'source_release_id'))::uuid;
                elsif v_item ? 'source_id' and v_source_releases_map ? (v_item->>'source_id') then
                  v_entity_rel_id := (v_source_releases_map->>(v_item->>'source_id'))::uuid;
                else
                  v_entity_rel_id := coalesce(v_obj_rel_id, v_default_rel_id);
                end if;

                if v_entity_rel_id is not null then
                  insert into public.content_source_mappings (
                    source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
                  ) values (
                    v_entity_rel_id,
                    'assessment_item',
                    v_item_id,
                    'derived_from',
                    coalesce(v_item->>'citation', coalesce(v_item->>'citation_location', substring(coalesce(v_item->>'prompt', 'Assessment Item') from 1 for 100))),
                    coalesce(v_item->>'notes', 'Assessment item derived from authoritative blueprint'),
                    '{}'::jsonb
                  )
                  on conflict (source_release_id, entity_type, entity_id, relationship) do update
                  set citation_location = excluded.citation_location,
                      notes = excluded.notes,
                      metadata = excluded.metadata
                  returning id into v_mapping_id;

                  v_mappings_count := v_mappings_count + 1;
                  insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
                  values (v_version_id, 'content_source_mapping', v_mapping_id)
                  on conflict do nothing;
                end if;
              end if;
            end loop;
          end if;

          -- Lessons
          if jsonb_typeof(v_obj->'lessons') = 'array' then
            for v_lesson in select * from jsonb_array_elements(v_obj->'lessons')
            loop
              insert into public.lessons (
                title, description, visibility, origin_target_version_id
              ) values (
                v_lesson->>'title',
                coalesce(v_lesson->>'description', v_lesson->>'summary'),
                'public',
                v_version_id
              )
              returning id into v_lesson_id;

              v_lessons_count := v_lessons_count + 1;
              insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
              values (v_version_id, 'lesson', v_lesson_id);

              -- Lesson Source Mapping
              if v_default_rel_id is not null then
                v_entity_rel_id := null;
                if v_lesson ? 'source_release_id' and v_source_releases_map ? (v_lesson->>'source_release_id') then
                  v_entity_rel_id := (v_source_releases_map->>(v_lesson->>'source_release_id'))::uuid;
                elsif v_lesson ? 'source_id' and v_source_releases_map ? (v_lesson->>'source_id') then
                  v_entity_rel_id := (v_source_releases_map->>(v_lesson->>'source_id'))::uuid;
                else
                  v_entity_rel_id := coalesce(
                    (v_source_releases_map->>(v_obj->>'source_release_id'))::uuid,
                    (v_source_releases_map->>(v_obj->>'source_id'))::uuid,
                    coalesce(
                      (v_source_releases_map->>(v_domain->>'source_release_id'))::uuid,
                      (v_source_releases_map->>(v_domain->>'source_id'))::uuid,
                      v_default_rel_id
                    )
                  );
                end if;

                v_lesson_rel_id := v_entity_rel_id;

                if v_entity_rel_id is not null then
                  insert into public.content_source_mappings (
                    source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
                  ) values (
                    v_entity_rel_id,
                    'lesson',
                    v_lesson_id,
                    'derived_from',
                    coalesce(v_lesson->>'citation', coalesce(v_lesson->>'citation_location', coalesce(v_lesson->>'title', 'Lesson'))),
                    coalesce(v_lesson->>'notes', 'Lesson derived from authoritative source'),
                    '{}'::jsonb
                  )
                  on conflict (source_release_id, entity_type, entity_id, relationship) do update
                  set citation_location = excluded.citation_location,
                      notes = excluded.notes,
                      metadata = excluded.metadata
                  returning id into v_mapping_id;

                  v_mappings_count := v_mappings_count + 1;
                  insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
                  values (v_version_id, 'content_source_mapping', v_mapping_id)
                  on conflict do nothing;
                end if;
              end if;

              -- Bind lesson to objective
              insert into public.curriculum_node_lessons (curriculum_node_id, lesson_id, sort_order)
              values (v_obj_id, v_lesson_id, coalesce((v_lesson->>'order_index')::int, 0))
              on conflict do nothing;

              -- Scoped lesson concept linking
              if jsonb_typeof(v_lesson->'concept_ids') = 'array' then
                for v_concept_id in select (jsonb_array_elements_text(v_lesson->'concept_ids'))::uuid
                loop
                  insert into public.lesson_concepts (lesson_id, concept_id)
                  values (v_lesson_id, v_concept_id)
                  on conflict do nothing;
                end loop;
              end if;

              if jsonb_typeof(v_lesson->'concept_slugs') = 'array' then
                for v_raw_concept_ref in select jsonb_array_elements_text(v_lesson->'concept_slugs')
                loop
                  if v_concepts_map ? v_raw_concept_ref then
                    v_resolved_cid := (v_concepts_map->>v_raw_concept_ref)::uuid;
                    insert into public.lesson_concepts (lesson_id, concept_id)
                    values (v_lesson_id, v_resolved_cid)
                    on conflict do nothing;
                  end if;
                end loop;
              end if;

              -- Lesson Blocks
              if jsonb_typeof(v_lesson->'blocks') = 'array' then
                for v_block in select * from jsonb_array_elements(v_lesson->'blocks')
                loop
                  insert into public.lesson_blocks (
                    lesson_id, block_type, content, sort_order
                  ) values (
                    v_lesson_id,
                    coalesce(v_block->>'block_type', 'markdown'),
                    coalesce(v_block->'content', '{}'::jsonb),
                    coalesce((v_block->>'sort_order')::int, 0)
                  )
                  returning id into v_block_id;

                  v_blocks_count := v_blocks_count + 1;
                  insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
                  values (v_version_id, 'lesson_block', v_block_id);

                  -- Lesson Block Provenance Mapping
                  if v_default_rel_id is not null then
                    v_entity_rel_id := null;
                    if v_block ? 'source_release_id' and v_source_releases_map ? (v_block->>'source_release_id') then
                      v_entity_rel_id := (v_source_releases_map->>(v_block->>'source_release_id'))::uuid;
                    elsif v_block ? 'source_id' and v_source_releases_map ? (v_block->>'source_id') then
                      v_entity_rel_id := (v_source_releases_map->>(v_block->>'source_id'))::uuid;
                    else
                      v_entity_rel_id := coalesce(v_lesson_rel_id, v_default_rel_id);
                    end if;

                    if v_entity_rel_id is not null then
                      insert into public.content_source_mappings (
                        source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
                      ) values (
                        v_entity_rel_id,
                        'lesson_block',
                        v_block_id,
                        'derived_from',
                        coalesce(v_block->>'citation', coalesce(v_block->>'citation_location', coalesce(v_lesson->>'title', 'Lesson Block'))),
                        coalesce(v_block->>'notes', 'Lesson content block citation'),
                        '{}'::jsonb
                      )
                      on conflict (source_release_id, entity_type, entity_id, relationship) do update
                      set citation_location = excluded.citation_location,
                          notes = excluded.notes,
                          metadata = excluded.metadata
                      returning id into v_mapping_id;

                      v_mappings_count := v_mappings_count + 1;
                      insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
                      values (v_version_id, 'content_source_mapping', v_mapping_id)
                      on conflict do nothing;
                    end if;
                  end if;
                end loop;
              end if;

              -- Lesson Terms
              if jsonb_typeof(v_lesson->'terms') = 'array' then
                for v_term in select * from jsonb_array_elements(v_lesson->'terms')
                loop
                  insert into public.terms (lesson_id, term, definition)
                  values (v_lesson_id, v_term->>'term', v_term->>'definition');
                end loop;
              end if;

              -- Lesson Questions
              if jsonb_typeof(v_lesson->'questions') = 'array' then
                for v_question in select * from jsonb_array_elements(v_lesson->'questions')
                loop
                  insert into public.questions (
                    lesson_id, question_text, options, correct_answer, type, explanation
                  ) values (
                    v_lesson_id,
                    coalesce(v_question->>'question_text', v_question->>'question'),
                    coalesce(v_question->'options', '[]'::jsonb),
                    coalesce((coalesce(v_question->>'correct_answer', v_question->>'correct_index'))::int, 0),
                    coalesce(v_question->>'type', 'mcq'),
                    v_question->>'explanation'
                  );
                  v_questions_count := v_questions_count + 1;
                end loop;
              end if;

              -- Lesson Assessment Items
              if jsonb_typeof(v_lesson->'assessment_items') = 'array' then
                for v_item in select * from jsonb_array_elements(v_lesson->'assessment_items')
                loop
                  v_stim_key := v_item->>'stimulus_key';
                  v_stim_id := null;
                  if v_stim_key is not null and v_stimuli_map ? v_stim_key then
                    v_stim_id := (v_stimuli_map->>v_stim_key)::uuid;
                  end if;

                  insert into public.assessment_items (
                    lesson_id, stimulus_id, prompt, interaction_type, response_spec, scoring_spec, explanation, origin_target_version_id
                  ) values (
                    v_lesson_id,
                    v_stim_id,
                    v_item->>'prompt',
                    coalesce(v_item->>'interaction_type', 'single_choice'),
                    coalesce(v_item->'response_spec', '{}'::jsonb),
                    coalesce(v_item->'scoring_spec', '{}'::jsonb),
                    v_item->>'explanation',
                    v_version_id
                  )
                  returning id into v_item_id;

                  v_items_count := v_items_count + 1;
                  insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
                  values (v_version_id, 'assessment_item', v_item_id);

                  if jsonb_typeof(v_item->'concept_ids') = 'array' then
                    for v_concept_id in select (jsonb_array_elements_text(v_item->'concept_ids'))::uuid
                    loop
                      insert into public.assessment_item_concepts (assessment_item_id, concept_id)
                      values (v_item_id, v_concept_id)
                      on conflict do nothing;
                    end loop;
                  end if;

                  if jsonb_typeof(v_item->'concept_slugs') = 'array' then
                    for v_raw_concept_ref in select jsonb_array_elements_text(v_item->'concept_slugs')
                    loop
                      if v_concepts_map ? v_raw_concept_ref then
                        v_resolved_cid := (v_concepts_map->>v_raw_concept_ref)::uuid;
                        insert into public.assessment_item_concepts (assessment_item_id, concept_id)
                        values (v_item_id, v_resolved_cid)
                        on conflict do nothing;
                      end if;
                    end loop;
                  end if;

                  -- Lesson Assessment Item Provenance Mapping
                  if v_default_rel_id is not null then
                    v_entity_rel_id := null;
                    if v_item ? 'source_release_id' and v_source_releases_map ? (v_item->>'source_release_id') then
                      v_entity_rel_id := (v_source_releases_map->>(v_item->>'source_release_id'))::uuid;
                    elsif v_item ? 'source_id' and v_source_releases_map ? (v_item->>'source_id') then
                      v_entity_rel_id := (v_source_releases_map->>(v_item->>'source_id'))::uuid;
                    else
                      v_entity_rel_id := coalesce(v_lesson_rel_id, v_default_rel_id);
                    end if;

                    if v_entity_rel_id is not null then
                      insert into public.content_source_mappings (
                        source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
                      ) values (
                        v_entity_rel_id,
                        'assessment_item',
                        v_item_id,
                        'derived_from',
                        coalesce(v_item->>'citation', coalesce(v_item->>'citation_location', substring(coalesce(v_item->>'prompt', 'Lesson Assessment Item') from 1 for 100))),
                        coalesce(v_item->>'notes', 'Lesson assessment item derived from authoritative blueprint'),
                        '{}'::jsonb
                      )
                      on conflict (source_release_id, entity_type, entity_id, relationship) do update
                      set citation_location = excluded.citation_location,
                          notes = excluded.notes,
                          metadata = excluded.metadata
                      returning id into v_mapping_id;

                      v_mappings_count := v_mappings_count + 1;
                      insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
                      values (v_version_id, 'content_source_mapping', v_mapping_id)
                      on conflict do nothing;
                    end if;
                  end if;
                end loop;
              end if;

            end loop;
          end if; -- lessons

        end loop;
      end if; -- objectives

    end loop;
  end if; -- domains

  -- 11. Ingest Explicit Custom Source Mappings
  if jsonb_typeof(payload->'source_mappings') = 'array' then
    for v_source_mapping in select * from jsonb_array_elements(payload->'source_mappings')
    loop
      insert into public.content_source_mappings (
        source_release_id, entity_type, entity_id, relationship, citation_location, notes, metadata
      ) values (
        (v_source_mapping->>'source_release_id')::uuid,
        v_source_mapping->>'entity_type',
        (v_source_mapping->>'entity_id')::uuid,
        coalesce(v_source_mapping->>'relationship', 'derived_from'),
        coalesce(v_source_mapping->>'citation_location', v_source_mapping->>'section_reference'),
        coalesce(v_source_mapping->>'notes', v_source_mapping->>'citation_text'),
        coalesce(v_source_mapping->'metadata', '{}'::jsonb)
      )
      on conflict (source_release_id, entity_type, entity_id, relationship) do update
      set citation_location = excluded.citation_location,
          notes = excluded.notes,
          metadata = excluded.metadata
      returning id into v_mapping_id;

      v_mappings_count := v_mappings_count + 1;
      insert into public.content_import_artifacts (target_version_id, entity_type, entity_id)
      values (v_version_id, 'content_source_mapping', v_mapping_id)
      on conflict do nothing;
    end loop;
  end if;

  -- 12. Ingest Concept Version Mappings
  if jsonb_typeof(coalesce(payload->'concept_mappings', payload->'target_version_concept_mappings')) = 'array' then
    for v_mapping in select * from jsonb_array_elements(coalesce(payload->'concept_mappings', payload->'target_version_concept_mappings'))
    loop
      -- Check if standard manifest format (from_version_code, from_concept_slug, etc.)
      if v_mapping ? 'from_version_code' or v_mapping ? 'from_concept_slug' then
        v_from_version_code := v_mapping->>'from_version_code';
        v_from_concept_slug := v_mapping->>'from_concept_slug';
        v_to_concept_slug := v_mapping->>'to_concept_slug';
        v_mapping_type := coalesce(v_mapping->>'mapping_type', 'unchanged');

        if v_mapping_type = 'equivalent' then
          v_mapping_type := 'unchanged';
        end if;

        if v_mapping_type not in ('unchanged', 'renamed', 'expanded', 'narrowed', 'replaced', 'removed') then
          raise exception 'Invalid mapping_type "%" for concept mapping. Must be one of unchanged, renamed, expanded, narrowed, replaced, removed.', v_mapping_type;
        end if;

        -- Resolve source version ID
        select id into v_from_tv_id
        from public.target_versions
        where target_id = v_target_id and version_code = v_from_version_code
        limit 1;

        if v_from_tv_id is null then
          raise exception 'Target version with version_code "%" not found for target "%".', v_from_version_code, v_target_id;
        end if;

        -- Resolve source concept ID
        v_from_concept_id := null;
        if v_concepts_map ? v_from_concept_slug then
          v_from_concept_id := (v_concepts_map->>v_from_concept_slug)::uuid;
        else
          select id into v_from_concept_id
          from public.knowledge_concepts
          where slug = v_from_concept_slug
          limit 1;
        end if;

        if v_from_concept_id is null then
          raise exception 'Source concept with slug "%" not found for concept mapping.', v_from_concept_slug;
        end if;

        -- Validate source concept is attached to source version through curriculum_node_concepts
        if not exists (
          select 1
          from public.curriculum_node_concepts cnc
          join public.curriculum_nodes cn on cn.id = cnc.curriculum_node_id
          where cn.target_version_id = v_from_tv_id
            and cnc.concept_id = v_from_concept_id
        ) then
          raise exception 'Source concept "%" (id: %) is not associated with source target version "%" (version_code: %).',
            v_from_concept_slug, v_from_concept_id, v_from_tv_id, v_from_version_code;
        end if;

        -- Validate destination concept and mapping invariant
        v_to_concept_id := null;
        if v_mapping_type = 'removed' then
          if v_to_concept_slug is not null and trim(v_to_concept_slug) <> '' then
            raise exception 'Removed concept mapping for source concept "%" cannot specify a destination concept (got "%").',
              v_from_concept_slug, v_to_concept_slug;
          end if;

          if v_mapping ? 'transfer_weight' and v_mapping->>'transfer_weight' is not null and (v_mapping->>'transfer_weight')::numeric <> 0.0 then
            raise exception 'Removed concept mapping for source concept "%" must have transfer_weight = 0 (got %).',
              v_from_concept_slug, (v_mapping->>'transfer_weight')::numeric;
          end if;
          v_transfer_weight := 0.0;
        else
          if v_to_concept_slug is null or trim(v_to_concept_slug) = '' then
            raise exception 'Destination concept slug must be specified for mapping_type "%".', v_mapping_type;
          end if;

          if v_concepts_map ? v_to_concept_slug then
            v_to_concept_id := (v_concepts_map->>v_to_concept_slug)::uuid;
          else
            select id into v_to_concept_id
            from public.knowledge_concepts
            where slug = v_to_concept_slug
            limit 1;
          end if;

          if v_to_concept_id is null then
            raise exception 'Destination concept with slug "%" not found for concept mapping.', v_to_concept_slug;
          end if;

          -- Validate destination concept is attached to destination version through curriculum_node_concepts
          if not exists (
            select 1
            from public.curriculum_node_concepts cnc
            join public.curriculum_nodes cn on cn.id = cnc.curriculum_node_id
            where cn.target_version_id = v_version_id
              and cnc.concept_id = v_to_concept_id
          ) then
            raise exception 'Destination concept "%" (id: %) is not associated with destination target version "%".',
              v_to_concept_slug, v_to_concept_id, v_version_id;
          end if;

          if v_mapping ? 'transfer_weight' and v_mapping->>'transfer_weight' is not null then
            v_transfer_weight := (v_mapping->>'transfer_weight')::numeric;
          else
            v_transfer_weight := 1.0;
          end if;

          if v_transfer_weight < 0.0 or v_transfer_weight > 1.0 then
            raise exception 'Concept mapping transfer_weight % must be between 0.0 and 1.0.', v_transfer_weight;
          end if;
        end if;

        insert into public.target_version_concept_mappings (
          from_target_version_id, from_concept_id, to_target_version_id, to_concept_id,
          mapping_type, transfer_weight, metadata
        ) values (
          v_from_tv_id,
          v_from_concept_id,
          v_version_id,
          v_to_concept_id,
          v_mapping_type,
          v_transfer_weight,
          coalesce(v_mapping->'metadata', '{}'::jsonb)
        )
        on conflict (
          from_target_version_id,
          from_concept_id,
          to_target_version_id,
          coalesce(to_concept_id, '00000000-0000-0000-0000-000000000000'::uuid)
        ) do update
        set mapping_type = excluded.mapping_type,
            transfer_weight = excluded.transfer_weight,
            metadata = excluded.metadata;

        v_concept_mappings_count := v_concept_mappings_count + 1;

      else
        -- Backwards compatibility with raw UUID payload
        v_from_concept_id := (v_mapping->>'from_concept_id')::uuid;
        v_to_concept_id := case when v_mapping->>'to_concept_id' is not null and trim(v_mapping->>'to_concept_id') <> ''
                                then (v_mapping->>'to_concept_id')::uuid
                                else null end;
        v_mapping_type := coalesce(v_mapping->>'mapping_type', 'unchanged');
        if v_mapping_type = 'equivalent' then
          v_mapping_type := 'unchanged';
        end if;

        if v_mapping_type not in ('unchanged', 'renamed', 'expanded', 'narrowed', 'replaced', 'removed') then
          raise exception 'Invalid mapping_type "%" for concept mapping.', v_mapping_type;
        end if;

        v_from_tv_id := coalesce((v_mapping->>'from_target_version_id')::uuid, v_version_id);
        v_to_tv_id := coalesce((v_mapping->>'to_target_version_id')::uuid, v_version_id);

        if v_mapping_type = 'removed' then
          if v_to_concept_id is not null then
            raise exception 'Removed concept mapping for source concept id % cannot specify a destination concept.', v_from_concept_id;
          end if;
          if v_mapping ? 'transfer_weight' and v_mapping->>'transfer_weight' is not null and (v_mapping->>'transfer_weight')::numeric <> 0.0 then
            raise exception 'Removed concept mapping for source concept id % must have transfer_weight = 0 (got %).',
              v_from_concept_id, (v_mapping->>'transfer_weight')::numeric;
          end if;
          v_transfer_weight := 0.0;
        else
          if v_to_concept_id is null then
            raise exception 'Destination concept id must be specified for mapping_type "%".', v_mapping_type;
          end if;

          if v_mapping ? 'transfer_weight' and v_mapping->>'transfer_weight' is not null then
            v_transfer_weight := (v_mapping->>'transfer_weight')::numeric;
          else
            v_transfer_weight := 1.0;
          end if;

          if v_transfer_weight < 0.0 or v_transfer_weight > 1.0 then
            raise exception 'Concept mapping transfer_weight % must be between 0.0 and 1.0.', v_transfer_weight;
          end if;
        end if;

        -- Validate source concept attached to from_target_version
        if not exists (
          select 1
          from public.curriculum_node_concepts cnc
          join public.curriculum_nodes cn on cn.id = cnc.curriculum_node_id
          where cn.target_version_id = v_from_tv_id
            and cnc.concept_id = v_from_concept_id
        ) then
          raise exception 'Source concept id % is not associated with source target version %.',
            v_from_concept_id, v_from_tv_id;
        end if;

        -- Validate destination concept attached to to_target_version if present
        if v_to_concept_id is not null and not exists (
          select 1
          from public.curriculum_node_concepts cnc
          join public.curriculum_nodes cn on cn.id = cnc.curriculum_node_id
          where cn.target_version_id = v_to_tv_id
            and cnc.concept_id = v_to_concept_id
        ) then
          raise exception 'Destination concept id % is not associated with destination target version %.',
            v_to_concept_id, v_to_tv_id;
        end if;

        insert into public.target_version_concept_mappings (
          from_target_version_id, from_concept_id, to_target_version_id, to_concept_id,
          mapping_type, transfer_weight, metadata,
          confidence, rationale
        ) values (
          v_from_tv_id,
          v_from_concept_id,
          v_to_tv_id,
          v_to_concept_id,
          v_mapping_type,
          v_transfer_weight,
          coalesce(v_mapping->'metadata', '{}'::jsonb),
          case when v_mapping->>'confidence' is not null then (v_mapping->>'confidence')::numeric else null end,
          v_mapping->>'rationale'
        )
        on conflict (
          from_target_version_id,
          from_concept_id,
          to_target_version_id,
          coalesce(to_concept_id, '00000000-0000-0000-0000-000000000000'::uuid)
        ) do update
        set mapping_type = excluded.mapping_type,
            transfer_weight = excluded.transfer_weight,
            metadata = excluded.metadata,
            confidence = excluded.confidence,
            rationale = excluded.rationale;

        v_concept_mappings_count := v_concept_mappings_count + 1;
      end if;
    end loop;
  end if;
  -- 13. Return Ingestion Summary
  return jsonb_build_object(
    'target_version_id', v_version_id,
    'concepts_count', v_concepts_count,
    'domains_count', v_domains_count,
    'objectives_count', v_objectives_count,
    'lessons_count', v_lessons_count,
    'blocks_count', v_blocks_count,
    'assessment_items_count', v_items_count,
    'flashcards_count', v_flashcards_count,
    'stimuli_count', v_stimuli_count,
    'questions_count', v_questions_count,
    'mappings_count', v_mappings_count,
    'concept_mappings_count', v_concept_mappings_count
  );
end;
$$;

revoke all on function public.ingest_curriculum_manifest(jsonb) from public, anon, authenticated;
grant execute on function public.ingest_curriculum_manifest(jsonb) to service_role;

INSERT INTO supabase_migrations.schema_migrations (version, name) VALUES ('20261009000001', 'harden_cross_version_mappings_and_target_version_security') ON CONFLICT (version) DO NOTHING;

-- --------------------------------------------------------------------
-- [34/96] Migration: 20261009000002_harden_mapping_rls_migration_rpc_and_retired_visibility.sql
-- --------------------------------------------------------------------
-- ============================================================================
-- Migration: 20261009000002_harden_mapping_rls_migration_rpc_and_retired_visibility.sql
-- Description:
--   1. Harden target_version_concept_mappings read RLS:
--      Replace open 'using (true)' policy with one requiring that both the source
--      and destination target versions are visible to the caller (via
--      is_target_version_visible), or caller is service_role.
--   2. Allow learners to read retired target versions they are enrolled in:
--      Update target_versions RLS policy 'versions_read' so that learners whose
--      learning_contexts reference a retired version can read that target_version row.
--      This fixes v_target_version_updates (security_invoker = true) when detecting
--      retired or outdated versions for active learner contexts.
--   3. Harden evaluate_target_version_migration RPC:
--      Enforce that caller may only evaluate from a source target version that is
--      normally visible OR referenced by caller's own learning_context.
--      Enforce that destination target version is normally visible (via
--      is_target_version_visible).
--   4. Harden migrate_user_context_target_version RPC:
--      Enforce that destination target version is normally visible (via
--      is_target_version_visible).
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. Harden target_version_concept_mappings Read Policy
-- ----------------------------------------------------------------------------
drop policy if exists "tv_concept_mappings_read" on public.target_version_concept_mappings;
create policy "tv_concept_mappings_read" on public.target_version_concept_mappings
  for select using (
    coalesce(auth.role(), '') = 'service_role'
    or (
      public.is_target_version_visible(from_target_version_id)
      and public.is_target_version_visible(to_target_version_id)
    )
  );

-- ----------------------------------------------------------------------------
-- 2. Update target_versions Read Policy for Retired Enrolled Versions
-- ----------------------------------------------------------------------------
drop policy if exists "versions_read" on public.target_versions;
create policy "versions_read" on public.target_versions
  for select using (
    coalesce(auth.role(), '') = 'service_role'
    or exists (
      select 1 from public.learning_targets t
      where t.id = target_versions.target_id
        and (
          (t.status = 'published' and t.is_public = true and target_versions.status = 'published')
          or (t.created_by = auth.uid())
          or (target_versions.status = 'review_ready' and public.is_target_reviewer(t.id))
        )
    )
    or (
      target_versions.status = 'retired'
      and exists (
        select 1 from public.learning_contexts lc
        where lc.target_version_id = target_versions.id
          and lc.user_id = auth.uid()
      )
    )
  );

-- ----------------------------------------------------------------------------
-- 3. Harden evaluate_target_version_migration RPC
-- ----------------------------------------------------------------------------
create or replace function public.evaluate_target_version_migration(
  p_user_id uuid,
  p_from_target_version_id uuid,
  p_to_target_version_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_source_concepts_count integer;
  v_target_concepts_count integer;
  v_mapped_count integer;
  v_retained_count integer;
  v_removed_count integer;
  v_new_concepts_count integer;
  v_avg_weight numeric(5,2);
  v_user_assessed_count integer;
  v_projected_retained_assessed numeric(5,2);
  v_mappings_json jsonb;
  v_from_tv record;
  v_to_tv record;
begin
  if coalesce(auth.role(), '') <> 'service_role'
     and (auth.uid() is null or p_user_id is null or auth.uid() <> p_user_id) then
    raise exception 'Unauthorized: cannot evaluate migration evidence for another user.';
  end if;

  select * into v_from_tv
  from public.target_versions
  where id = p_from_target_version_id;

  if not found then
    raise exception 'Source target version not found.';
  end if;

  select tv.*, lt.created_by as target_owner
  into v_to_tv
  from public.target_versions tv
  join public.learning_targets lt on lt.id = tv.target_id
  where tv.id = p_to_target_version_id;

  if not found then
    raise exception 'Destination target version not found.';
  end if;

  if v_from_tv.target_id <> v_to_tv.target_id then
    raise exception 'Cannot evaluate migration across different learning targets.';
  end if;

  if not (
    public.is_target_version_visible(p_from_target_version_id)
    or exists (
      select 1 from public.learning_contexts lc
      where lc.user_id = p_user_id
        and lc.target_version_id = p_from_target_version_id
    )
  ) then
    raise exception 'Unauthorized: source target version is not accessible for this caller.';
  end if;

  if not public.is_target_version_visible(p_to_target_version_id) then
    raise exception 'Unauthorized: destination target version is not published for this caller.';
  end if;

  select count(distinct cnc.concept_id)
  into v_source_concepts_count
  from public.curriculum_node_concepts cnc
  join public.curriculum_nodes cn on cn.id = cnc.curriculum_node_id
  where cn.target_version_id = p_from_target_version_id;

  select count(distinct cnc.concept_id)
  into v_target_concepts_count
  from public.curriculum_node_concepts cnc
  join public.curriculum_nodes cn on cn.id = cnc.curriculum_node_id
  where cn.target_version_id = p_to_target_version_id;

  select
    count(*),
    count(*) filter (where m.transfer_weight > 0 and m.to_concept_id is not null),
    count(*) filter (
      where m.mapping_type = 'removed'
         or m.to_concept_id is null
         or m.transfer_weight = 0
    ),
    coalesce(round(avg(m.transfer_weight) * 100, 2), 100.00)
  into
    v_mapped_count,
    v_retained_count,
    v_removed_count,
    v_avg_weight
  from public.target_version_concept_mappings m
  where m.from_target_version_id = p_from_target_version_id
    and m.to_target_version_id = p_to_target_version_id;

  if v_mapped_count = 0 and v_source_concepts_count > 0 then
    select count(distinct s.concept_id)
    into v_retained_count
    from (
      select distinct cnc.concept_id
      from public.curriculum_node_concepts cnc
      join public.curriculum_nodes cn on cn.id = cnc.curriculum_node_id
      where cn.target_version_id = p_from_target_version_id
    ) s
    where s.concept_id in (
      select distinct cnc2.concept_id
      from public.curriculum_node_concepts cnc2
      join public.curriculum_nodes cn2 on cn2.id = cnc2.curriculum_node_id
      where cn2.target_version_id = p_to_target_version_id
    );

    v_mapped_count := v_retained_count;
    v_removed_count := greatest(0, v_source_concepts_count - v_retained_count);
    v_avg_weight := round(
      (v_retained_count::numeric / v_source_concepts_count::numeric) * 100,
      2
    );
  end if;

  v_new_concepts_count := greatest(0, v_target_concepts_count - v_retained_count);

  select count(distinct ucs.concept_id)
  into v_user_assessed_count
  from public.user_concept_state ucs
  where ucs.user_id = p_user_id
    and ucs.evidence_count > 0
    and ucs.concept_id in (
      select distinct cnc.concept_id
      from public.curriculum_node_concepts cnc
      join public.curriculum_nodes cn on cn.id = cnc.curriculum_node_id
      where cn.target_version_id = p_from_target_version_id
    );

  v_projected_retained_assessed :=
    round((v_user_assessed_count::numeric * (v_avg_weight / 100.0)), 1);

  select coalesce(jsonb_agg(jsonb_build_object(
    'from_concept_id', m.from_concept_id,
    'to_concept_id', m.to_concept_id,
    'mapping_type', m.mapping_type,
    'transfer_weight', m.transfer_weight,
    'from_concept_name', fc.name,
    'to_concept_name', tc.name
  )), '[]'::jsonb)
  into v_mappings_json
  from public.target_version_concept_mappings m
  left join public.knowledge_concepts fc on fc.id = m.from_concept_id
  left join public.knowledge_concepts tc on tc.id = m.to_concept_id
  where m.from_target_version_id = p_from_target_version_id
    and m.to_target_version_id = p_to_target_version_id;

  return jsonb_build_object(
    'from_target_version_id', p_from_target_version_id,
    'to_target_version_id', p_to_target_version_id,
    'total_source_concepts', v_source_concepts_count,
    'total_target_concepts', v_target_concepts_count,
    'mapped_concepts_count', v_mapped_count,
    'retained_concepts_count', v_retained_count,
    'removed_concepts_count', v_removed_count,
    'new_concepts_count', v_new_concepts_count,
    'transfer_retention_pct', v_avg_weight,
    'user_assessed_concepts_count', v_user_assessed_count,
    'projected_retained_assessed_count', v_projected_retained_assessed,
    'concept_mappings', v_mappings_json
  );
end;
$$;

revoke all on function public.evaluate_target_version_migration(uuid, uuid, uuid) from public;
grant execute on function public.evaluate_target_version_migration(uuid, uuid, uuid) to authenticated, service_role;

-- ----------------------------------------------------------------------------
-- 4. Harden migrate_user_context_target_version RPC
-- ----------------------------------------------------------------------------
create or replace function public.migrate_user_context_target_version(
  p_user_id uuid,
  p_context_id uuid,
  p_to_target_version_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_context record;
  v_from_tv record;
  v_to_tv record;
  v_mapping record;
  v_transferred_count integer := 0;
  v_evaluation jsonb;
  v_retention_pct numeric(5,2) := 100.00;
  v_is_privileged_editor boolean := false;
begin
  if coalesce(auth.role(), '') <> 'service_role'
     and (auth.uid() is null or auth.uid() <> p_user_id) then
    raise exception 'Unauthorized: cannot migrate context for another user.';
  end if;

  select * into v_context
  from public.learning_contexts
  where id = p_context_id and user_id = p_user_id;

  if not found then
    raise exception 'Learning context not found or does not belong to user.';
  end if;

  select * into v_from_tv
  from public.target_versions
  where id = v_context.target_version_id;

  if not found then
    raise exception 'Current target version not found.';
  end if;

  select * into v_to_tv
  from public.target_versions
  where id = p_to_target_version_id;

  if not found then
    raise exception 'Destination target version not found.';
  end if;

  if v_from_tv.target_id <> v_to_tv.target_id then
    raise exception 'Cannot migrate context across different learning targets.';
  end if;

  if not public.is_target_version_visible(p_to_target_version_id) then
    raise exception 'Unauthorized: destination target version is not published for this caller.';
  end if;

  if coalesce(auth.role(), '') = 'service_role' then
    v_is_privileged_editor := true;
  elsif auth.uid() is not null then
    select exists (
      select 1
      from public.learning_targets lt
      where lt.id = v_to_tv.target_id
        and lt.created_by = auth.uid()
    ) or public.is_target_reviewer(v_to_tv.target_id)
    into v_is_privileged_editor;
  end if;

  if v_to_tv.status = 'published' then
    null;
  elsif v_to_tv.status = 'review_ready' and v_is_privileged_editor then
    null;
  else
    raise exception 'Cannot migrate to target version with status "%" for this caller.', v_to_tv.status;
  end if;

  v_evaluation := public.evaluate_target_version_migration(
    p_user_id,
    v_from_tv.id,
    v_to_tv.id
  );
  v_retention_pct :=
    coalesce((v_evaluation->>'transfer_retention_pct')::numeric, 100.00);

  for v_mapping in
    select
      m.from_concept_id,
      m.to_concept_id,
      m.transfer_weight
    from public.target_version_concept_mappings m
    where m.from_target_version_id = v_from_tv.id
      and m.to_target_version_id = v_to_tv.id
      and m.to_concept_id is not null
      and m.transfer_weight > 0
  loop
    if v_mapping.from_concept_id <> v_mapping.to_concept_id then
      insert into public.user_concept_state (
        user_id,
        concept_id,
        retrieval_band,
        confidence,
        evidence_count,
        weighted_correct,
        weighted_total,
        last_evidence_at,
        updated_at
      )
      select
        p_user_id,
        v_mapping.to_concept_id,
        ucs.retrieval_band,
        ucs.confidence,
        round(ucs.evidence_count * v_mapping.transfer_weight)::integer,
        ucs.weighted_correct * v_mapping.transfer_weight,
        ucs.weighted_total * v_mapping.transfer_weight,
        ucs.last_evidence_at,
        now()
      from public.user_concept_state ucs
      where ucs.user_id = p_user_id
        and ucs.concept_id = v_mapping.from_concept_id
        and ucs.evidence_count > 0
      on conflict (user_id, concept_id) do update set
        evidence_count = greatest(
          public.user_concept_state.evidence_count,
          excluded.evidence_count
        ),
        weighted_correct = greatest(
          public.user_concept_state.weighted_correct,
          excluded.weighted_correct
        ),
        weighted_total = greatest(
          public.user_concept_state.weighted_total,
          excluded.weighted_total
        ),
        last_evidence_at = coalesce(
          excluded.last_evidence_at,
          public.user_concept_state.last_evidence_at
        ),
        updated_at = now();
    end if;

    v_transferred_count := v_transferred_count + 1;
  end loop;

  update public.learning_contexts
  set
    target_version_id = v_to_tv.id,
    updated_at = now()
  where id = p_context_id;

  -- Resume pointers are disposable breadcrumbs and carry activity IDs rather
  -- than curriculum-node foreign keys. A target-version migration can make the
  -- saved lesson/study-set position stale, so clear the pointer atomically.
  delete from public.resume_pointers
  where context_id = p_context_id;

  insert into public.user_version_migration_logs (
    user_id,
    context_id,
    from_target_version_id,
    to_target_version_id,
    transferred_concepts_count,
    retained_mastery_pct,
    migration_metadata
  )
  values (
    p_user_id,
    p_context_id,
    v_from_tv.id,
    v_to_tv.id,
    v_transferred_count,
    v_retention_pct,
    jsonb_build_object(
      'from_version_code', v_from_tv.version_code,
      'to_version_code', v_to_tv.version_code,
      'evaluation', v_evaluation
    )
  );

  return jsonb_build_object(
    'success', true,
    'context_id', p_context_id,
    'from_version_code', v_from_tv.version_code,
    'to_version_code', v_to_tv.version_code,
    'transferred_concepts_count', v_transferred_count,
    'retained_mastery_pct', v_retention_pct
  );
end;
$$;

revoke all on function public.migrate_user_context_target_version(uuid, uuid, uuid) from public;
grant execute on function public.migrate_user_context_target_version(uuid, uuid, uuid) to authenticated, service_role;

INSERT INTO supabase_migrations.schema_migrations (version, name) VALUES ('20261009000002', 'harden_mapping_rls_migration_rpc_and_retired_visibility') ON CONFLICT (version) DO NOTHING;

-- --------------------------------------------------------------------
-- [35/96] Migration: 20261009000003_control_learning_context_target_version_and_migration_auth.sql
-- --------------------------------------------------------------------
-- ============================================================================
-- Migration: 20261009000003_control_learning_context_target_version_and_migration_auth.sql
-- Description:
--   1. Architectural Split between Normal Visibility & Historical-Context Access:
--      - public.is_target_version_visible(uuid): Normal catalog visibility
--        (published public versions, target author, reviewer in review_ready, admin).
--      - public.has_historical_target_version_access(uuid, uuid): Historical access
--        strictly granted to learners who legitimately enrolled before retirement.
--   2. Target Versions Read RLS:
--      - Re-declare 'versions_read' using is_target_version_visible() and
--        has_historical_target_version_access().
--   3. Controlled Learning Context Target Version (Database Trigger):
--      - Add trigger on public.learning_contexts preventing users from arbitrarily
--        assigning target_version_id to draft, review_ready, or retired versions.
--      - On INSERT or whenever target_version_id changes, require caller to have
--        normal visibility (is_target_version_visible) or service_role privilege.
--      - For target-root contexts (root_type = 'target'), verify root_id matches
--        the target_versions.target_id.
--      - Prevent reassigning user_id on context rows for non-admin callers.
--   4. Harden evaluate_target_version_migration RPC:
--      - Require source target version to be normally visible OR accessible via
--        has_historical_target_version_access(p_from_target_version_id, p_user_id).
--      - Require destination target version to be normally visible.
--   5. Harden migrate_user_context_target_version RPC:
--      - Require current target version to be normally visible OR accessible via
--        has_historical_target_version_access(current_tv_id, p_user_id).
--      - Require destination target version to be normally visible.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. Normal Visibility & Historical Access Helper Functions
-- ----------------------------------------------------------------------------

-- Normal (Catalog) Visibility:
-- Returns true if the target version is currently visible in the general catalog
-- (e.g., published version of a public published target, target owner, reviewer).
-- Deliberately excludes retired versions so they cannot be newly selected or browsed.
create or replace function public.is_target_version_visible(p_target_version_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.target_versions tv
    join public.learning_targets lt on lt.id = tv.target_id
    where tv.id = p_target_version_id
      and (
        coalesce(auth.role(), '') = 'service_role'
        or (lt.status = 'published' and lt.is_public = true and tv.status = 'published')
        or (auth.uid() is not null and lt.created_by = auth.uid())
        or (auth.uid() is not null and tv.status = 'review_ready' and public.is_target_reviewer(lt.id))
      )
  );
$$;

revoke all on function public.is_target_version_visible(uuid) from public;
grant execute on function public.is_target_version_visible(uuid) to anon, authenticated, service_role;

-- Historical-Context Access:
-- Returns true ONLY if the target version is retired AND the specified user
-- has a legitimate learning context referencing it.
-- This separates historical access granted to existing learners from general catalog visibility.
create or replace function public.has_historical_target_version_access(
  p_target_version_id uuid,
  p_user_id uuid default auth.uid()
)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.target_versions tv
    join public.learning_contexts lc
      on lc.target_version_id = tv.id
     and lc.user_id = p_user_id
    where tv.id = p_target_version_id
      and tv.status = 'retired'
  );
$$;

revoke all on function public.has_historical_target_version_access(uuid, uuid) from public;
grant execute on function public.has_historical_target_version_access(uuid, uuid) to anon, authenticated, service_role;

-- ----------------------------------------------------------------------------
-- 2. Target Versions Read Policy (Two-Tier Visibility)
-- ----------------------------------------------------------------------------
drop policy if exists "versions_read" on public.target_versions;
create policy "versions_read" on public.target_versions
  for select using (
    coalesce(auth.role(), '') = 'service_role'
    or public.is_target_version_visible(id)
    or public.has_historical_target_version_access(id, auth.uid())
  );

-- ----------------------------------------------------------------------------
-- 3. Controlled Learning Context Target Version Trigger
-- ----------------------------------------------------------------------------
create or replace function public.validate_learning_context_target_version()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_target_id uuid;
  v_is_admin boolean;
begin
  v_is_admin := coalesce(auth.role(), '') = 'service_role';

  -- Prevent non-admins from transferring context ownership to another user
  if tg_op = 'UPDATE' and new.user_id is distinct from old.user_id and not v_is_admin then
    raise exception 'Unauthorized: cannot reassign learning context ownership.';
  end if;

  if new.target_version_id is not null then
    -- Verify target version exists and retrieve its learning target id
    select tv.target_id into v_target_id
    from public.target_versions tv
    where tv.id = new.target_version_id;

    if not found then
      raise exception 'Target version % does not exist.', new.target_version_id;
    end if;

    -- Verify target-root contexts match the target version's learning target id
    if new.root_type = 'target' then
      if new.root_id is null or lower(trim(new.root_id)) <> lower(v_target_id::text) then
        raise exception 'Learning context root_id does not match target version target_id.';
      end if;
    end if;

    -- Enforce normal visibility on INSERT or when target_version_id is modified.
    -- Existing unchanged references to versions that subsequently retired remain allowed.
    if tg_op = 'INSERT' or new.target_version_id is distinct from old.target_version_id then
      if not v_is_admin and not public.is_target_version_visible(new.target_version_id) then
        raise exception 'Unauthorized: target version % is not visible or accessible.', new.target_version_id;
      end if;
    end if;
  end if;

  return new;
end;
$$;

drop trigger if exists trg_validate_learning_context_target_version on public.learning_contexts;
create trigger trg_validate_learning_context_target_version
  before insert or update on public.learning_contexts
  for each row execute function public.validate_learning_context_target_version();

-- ----------------------------------------------------------------------------
-- 4. Harden evaluate_target_version_migration RPC
-- ----------------------------------------------------------------------------
create or replace function public.evaluate_target_version_migration(
  p_user_id uuid,
  p_from_target_version_id uuid,
  p_to_target_version_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_source_concepts_count integer;
  v_target_concepts_count integer;
  v_mapped_count integer;
  v_retained_count integer;
  v_removed_count integer;
  v_new_concepts_count integer;
  v_avg_weight numeric(5,2);
  v_user_assessed_count integer;
  v_projected_retained_assessed numeric(5,2);
  v_mappings_json jsonb;
  v_from_tv record;
  v_to_tv record;
begin
  if coalesce(auth.role(), '') <> 'service_role'
     and (auth.uid() is null or p_user_id is null or auth.uid() <> p_user_id) then
    raise exception 'Unauthorized: cannot evaluate migration evidence for another user.';
  end if;

  select * into v_from_tv
  from public.target_versions
  where id = p_from_target_version_id;

  if not found then
    raise exception 'Source target version not found.';
  end if;

  select tv.*, lt.created_by as target_owner
  into v_to_tv
  from public.target_versions tv
  join public.learning_targets lt on lt.id = tv.target_id
  where tv.id = p_to_target_version_id;

  if not found then
    raise exception 'Destination target version not found.';
  end if;

  if v_from_tv.target_id <> v_to_tv.target_id then
    raise exception 'Cannot evaluate migration across different learning targets.';
  end if;

  -- Source version must be normally visible OR the user must have legitimate historical-context access
  if not (
    public.is_target_version_visible(p_from_target_version_id)
    or public.has_historical_target_version_access(p_from_target_version_id, p_user_id)
  ) then
    raise exception 'Unauthorized: source target version is not accessible for this caller.';
  end if;

  -- Destination version must be normally visible
  if not public.is_target_version_visible(p_to_target_version_id) then
    raise exception 'Unauthorized: destination target version is not published for this caller.';
  end if;

  select count(distinct cnc.concept_id)
  into v_source_concepts_count
  from public.curriculum_node_concepts cnc
  join public.curriculum_nodes cn on cn.id = cnc.curriculum_node_id
  where cn.target_version_id = p_from_target_version_id;

  select count(distinct cnc.concept_id)
  into v_target_concepts_count
  from public.curriculum_node_concepts cnc
  join public.curriculum_nodes cn on cn.id = cnc.curriculum_node_id
  where cn.target_version_id = p_to_target_version_id;

  select
    count(*),
    count(*) filter (where m.transfer_weight > 0 and m.to_concept_id is not null),
    count(*) filter (
      where m.mapping_type = 'removed'
         or m.to_concept_id is null
         or m.transfer_weight = 0
    ),
    coalesce(round(avg(m.transfer_weight) * 100, 2), 100.00)
  into
    v_mapped_count,
    v_retained_count,
    v_removed_count,
    v_avg_weight
  from public.target_version_concept_mappings m
  where m.from_target_version_id = p_from_target_version_id
    and m.to_target_version_id = p_to_target_version_id;

  select count(distinct ucs.concept_id)
  into v_user_assessed_count
  from public.user_concept_state ucs
  join public.curriculum_node_concepts cnc on cnc.concept_id = ucs.concept_id
  join public.curriculum_nodes cn on cn.id = cnc.curriculum_node_id
  where ucs.user_id = p_user_id
    and cn.target_version_id = p_from_target_version_id
    and ucs.evidence_count > 0;

  if v_user_assessed_count > 0 then
    select coalesce(
      round(
        sum(m.transfer_weight) / v_user_assessed_count * 100,
        2
      ),
      0.00
    )
    into v_projected_retained_assessed
    from public.user_concept_state ucs
    join public.curriculum_node_concepts cnc on cnc.concept_id = ucs.concept_id
    join public.curriculum_nodes cn on cn.id = cnc.curriculum_node_id
    left join public.target_version_concept_mappings m
      on m.from_concept_id = ucs.concept_id
     and m.from_target_version_id = p_from_target_version_id
     and m.to_target_version_id = p_to_target_version_id
    where ucs.user_id = p_user_id
      and cn.target_version_id = p_from_target_version_id
      and ucs.evidence_count > 0;
  else
    v_projected_retained_assessed := 100.00;
  end if;

  v_new_concepts_count := greatest(0, coalesce(v_target_concepts_count, 0) - coalesce(v_retained_count, 0));

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'from_concept_id', m.from_concept_id,
        'to_concept_id', m.to_concept_id,
        'mapping_type', m.mapping_type,
        'transfer_weight', m.transfer_weight,
        'source_name', sc.name,
        'target_name', tc.name
      )
      order by sc.name
    ),
    '[]'::jsonb
  )
  into v_mappings_json
  from public.target_version_concept_mappings m
  left join public.knowledge_concepts sc on sc.id = m.from_concept_id
  left join public.knowledge_concepts tc on tc.id = m.to_concept_id
  where m.from_target_version_id = p_from_target_version_id
    and m.to_target_version_id = p_to_target_version_id;

  return jsonb_build_object(
    'source_version_id', p_from_target_version_id,
    'source_version_code', v_from_tv.version_code,
    'destination_version_id', p_to_target_version_id,
    'destination_version_code', v_to_tv.version_code,
    'source_concepts_count', coalesce(v_source_concepts_count, 0),
    'target_concepts_count', coalesce(v_target_concepts_count, 0),
    'mapped_concepts_count', coalesce(v_mapped_count, 0),
    'retained_concepts_count', coalesce(v_retained_count, 0),
    'removed_concepts_count', coalesce(v_removed_count, 0),
    'new_concepts_count', v_new_concepts_count,
    'average_transfer_weight', v_avg_weight,
    'user_assessed_concepts_count', coalesce(v_user_assessed_count, 0),
    'projected_retained_mastery_pct', coalesce(v_projected_retained_assessed, 100.00),
    'mappings', v_mappings_json,
    'evaluated_at', now()
  );
end;
$$;

revoke all on function public.evaluate_target_version_migration(uuid, uuid, uuid) from public;
grant execute on function public.evaluate_target_version_migration(uuid, uuid, uuid) to authenticated, service_role;

-- ----------------------------------------------------------------------------
-- 5. Harden migrate_user_context_target_version RPC
-- ----------------------------------------------------------------------------
create or replace function public.migrate_user_context_target_version(
  p_user_id uuid,
  p_context_id uuid,
  p_to_target_version_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_context record;
  v_from_tv record;
  v_to_tv record;
  v_mapping record;
  v_transferred_count integer := 0;
  v_evaluation jsonb;
  v_retention_pct numeric(5,2) := 100.00;
  v_is_privileged_editor boolean := false;
begin
  if coalesce(auth.role(), '') <> 'service_role'
     and (auth.uid() is null or auth.uid() <> p_user_id) then
    raise exception 'Unauthorized: cannot migrate context for another user.';
  end if;

  select * into v_context
  from public.learning_contexts
  where id = p_context_id and user_id = p_user_id;

  if not found then
    raise exception 'Learning context not found or does not belong to user.';
  end if;

  select * into v_from_tv
  from public.target_versions
  where id = v_context.target_version_id;

  if not found then
    raise exception 'Current target version not found.';
  end if;

  select * into v_to_tv
  from public.target_versions
  where id = p_to_target_version_id;

  if not found then
    raise exception 'Destination target version not found.';
  end if;

  if v_from_tv.target_id <> v_to_tv.target_id then
    raise exception 'Cannot migrate context across different learning targets.';
  end if;

  -- Current target version must be normally visible OR accessible via historical context
  if not (
    public.is_target_version_visible(v_from_tv.id)
    or public.has_historical_target_version_access(v_from_tv.id, p_user_id)
  ) then
    raise exception 'Unauthorized: current target version is not accessible for this caller.';
  end if;

  -- Destination version must be normally visible
  if not public.is_target_version_visible(p_to_target_version_id) then
    raise exception 'Unauthorized: destination target version is not published for this caller.';
  end if;

  if coalesce(auth.role(), '') = 'service_role' then
    v_is_privileged_editor := true;
  elsif auth.uid() is not null then
    select exists (
      select 1
      from public.learning_targets lt
      where lt.id = v_to_tv.target_id
        and lt.created_by = auth.uid()
    ) or public.is_target_reviewer(v_to_tv.target_id)
    into v_is_privileged_editor;
  end if;

  if v_to_tv.status = 'published' then
    null;
  elsif v_to_tv.status = 'review_ready' and v_is_privileged_editor then
    null;
  else
    raise exception 'Cannot migrate to target version with status "%" for this caller.', v_to_tv.status;
  end if;

  v_evaluation := public.evaluate_target_version_migration(
    p_user_id,
    v_from_tv.id,
    v_to_tv.id
  );

  v_retention_pct := coalesce((v_evaluation->>'projected_retained_mastery_pct')::numeric, 100.00);

  for v_mapping in
    select
      m.from_concept_id,
      m.to_concept_id,
      m.transfer_weight
    from public.target_version_concept_mappings m
    where m.from_target_version_id = v_from_tv.id
      and m.to_target_version_id = v_to_tv.id
      and m.to_concept_id is not null
      and m.transfer_weight > 0
  loop
    if v_mapping.from_concept_id <> v_mapping.to_concept_id then
      insert into public.user_concept_state (
        user_id,
        concept_id,
        retrieval_band,
        confidence,
        evidence_count,
        weighted_correct,
        weighted_total,
        last_evidence_at,
        updated_at
      )
      select
        p_user_id,
        v_mapping.to_concept_id,
        ucs.retrieval_band,
        ucs.confidence,
        round(ucs.evidence_count * v_mapping.transfer_weight)::integer,
        ucs.weighted_correct * v_mapping.transfer_weight,
        ucs.weighted_total * v_mapping.transfer_weight,
        ucs.last_evidence_at,
        now()
      from public.user_concept_state ucs
      where ucs.user_id = p_user_id
        and ucs.concept_id = v_mapping.from_concept_id
        and ucs.evidence_count > 0
      on conflict (user_id, concept_id) do update set
        evidence_count = greatest(
          public.user_concept_state.evidence_count,
          excluded.evidence_count
        ),
        weighted_correct = greatest(
          public.user_concept_state.weighted_correct,
          excluded.weighted_correct
        ),
        weighted_total = greatest(
          public.user_concept_state.weighted_total,
          excluded.weighted_total
        ),
        last_evidence_at = coalesce(
          excluded.last_evidence_at,
          public.user_concept_state.last_evidence_at
        ),
        updated_at = now();
    end if;

    v_transferred_count := v_transferred_count + 1;
  end loop;

  update public.learning_contexts
  set
    target_version_id = v_to_tv.id,
    updated_at = now()
  where id = p_context_id;

  delete from public.resume_pointers
  where context_id = p_context_id;

  insert into public.user_version_migration_logs (
    user_id,
    context_id,
    from_target_version_id,
    to_target_version_id,
    transferred_concepts_count,
    retained_mastery_pct,
    migration_metadata
  ) values (
    p_user_id,
    p_context_id,
    v_from_tv.id,
    v_to_tv.id,
    v_transferred_count,
    v_retention_pct,
    jsonb_build_object(
      'source_version_code', v_from_tv.version_code,
      'destination_version_code', v_to_tv.version_code,
      'evaluation', v_evaluation,
      'migrated_at', now()
    )
  );

  return jsonb_build_object(
    'success', true,
    'context_id', p_context_id,
    'from_version_id', v_from_tv.id,
    'from_version_code', v_from_tv.version_code,
    'to_version_id', v_to_tv.id,
    'to_version_code', v_to_tv.version_code,
    'transferred_concepts_count', v_transferred_count,
    'retained_mastery_pct', v_retention_pct,
    'evaluation', v_evaluation
  );
end;
$$;

revoke all on function public.migrate_user_context_target_version(uuid, uuid, uuid) from public;
grant execute on function public.migrate_user_context_target_version(uuid, uuid, uuid) to authenticated, service_role;

INSERT INTO supabase_migrations.schema_migrations (version, name) VALUES ('20261009000003', 'control_learning_context_target_version_and_migration_auth') ON CONFLICT (version) DO NOTHING;

-- --------------------------------------------------------------------
-- [36/96] Migration: 20261009000004_restore_rpc_contracts_and_close_enrollment_oracle.sql
-- --------------------------------------------------------------------
-- ============================================================================
-- Migration: 20261009000004_restore_rpc_contracts_and_close_enrollment_oracle.sql
-- Description:
--   1. Harden has_historical_target_version_access against enrollment oracle:
--      - Restrict cross-user evaluation for non-service-role callers to auth.uid().
--      - If an ordinary caller supplies p_user_id <> auth.uid(), return false.
--   2. Restore canonical evaluate_target_version_migration RPC contract:
--      - Restores the exact schema expected by Dart client models:
--        from_target_version_id, to_target_version_id, total_source_concepts,
--        total_target_concepts, mapped_concepts_count, retained_concepts_count,
--        removed_concepts_count, new_concepts_count, transfer_retention_pct,
--        user_assessed_concepts_count, projected_retained_assessed_count,
--        concept_mappings (with from_concept_name, to_concept_name).
--      - Maintains two-tier visibility checks: source requires normal visibility
--        OR has_historical_target_version_access; destination requires normal visibility.
--   3. Restore canonical migrate_user_context_target_version RPC:
--      - Restores robust INSERT ... ON CONFLICT (user_id, concept_id) DO UPDATE SET ...
--        merge logic ensuring existing destination concept mastery is upgraded.
--      - References valid user_concept_state columns (last_evidence_at, updated_at).
--      - Preserves valid retrieval_band check constraints.
--      - Restores response schema matching Dart UserVersionMigrationResult model.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. Harden has_historical_target_version_access against enrollment oracle
-- ----------------------------------------------------------------------------
create or replace function public.has_historical_target_version_access(
  p_target_version_id uuid,
  p_user_id uuid default auth.uid()
)
returns boolean
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_effective_user_id uuid;
begin
  if p_target_version_id is null then
    return false;
  end if;

  -- Prevent enrollment oracle: ordinary callers cannot query whether another user
  -- has an enrolled context. Non-service-role callers are strictly scoped to auth.uid().
  if coalesce(auth.role(), '') = 'service_role' then
    v_effective_user_id := coalesce(p_user_id, auth.uid());
  else
    if auth.uid() is null then
      return false;
    end if;
    -- If an explicit user_id was supplied and does not match caller auth.uid(), reject
    if p_user_id is not null and p_user_id <> auth.uid() then
      return false;
    end if;
    v_effective_user_id := auth.uid();
  end if;

  if v_effective_user_id is null then
    return false;
  end if;

  return exists (
    select 1
    from public.target_versions tv
    join public.learning_contexts lc
      on lc.target_version_id = tv.id
     and lc.user_id = v_effective_user_id
    where tv.id = p_target_version_id
      and tv.status = 'retired'
  );
end;
$$;

revoke all on function public.has_historical_target_version_access(uuid, uuid) from public;
grant execute on function public.has_historical_target_version_access(uuid, uuid) to anon, authenticated, service_role;

-- ----------------------------------------------------------------------------
-- 2. Restore canonical evaluate_target_version_migration RPC contract
-- ----------------------------------------------------------------------------
create or replace function public.evaluate_target_version_migration(
  p_user_id uuid,
  p_from_target_version_id uuid,
  p_to_target_version_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_source_concepts_count integer;
  v_target_concepts_count integer;
  v_mapped_count integer;
  v_retained_count integer;
  v_removed_count integer;
  v_new_concepts_count integer;
  v_avg_weight numeric(5,2);
  v_user_assessed_count integer;
  v_projected_retained_assessed numeric(5,2);
  v_mappings_json jsonb;
  v_from_tv record;
  v_to_tv record;
begin
  if coalesce(auth.role(), '') <> 'service_role'
     and (auth.uid() is null or p_user_id is null or auth.uid() <> p_user_id) then
    raise exception 'Unauthorized: cannot evaluate migration evidence for another user.';
  end if;

  select * into v_from_tv
  from public.target_versions
  where id = p_from_target_version_id;

  if not found then
    raise exception 'Source target version not found.';
  end if;

  select tv.*, lt.created_by as target_owner
  into v_to_tv
  from public.target_versions tv
  join public.learning_targets lt on lt.id = tv.target_id
  where tv.id = p_to_target_version_id;

  if not found then
    raise exception 'Destination target version not found.';
  end if;

  if v_from_tv.target_id <> v_to_tv.target_id then
    raise exception 'Cannot evaluate migration across different learning targets.';
  end if;

  -- Source target version must be normally visible OR accessible via historical context for p_user_id
  if not (
    public.is_target_version_visible(p_from_target_version_id)
    or public.has_historical_target_version_access(p_from_target_version_id, p_user_id)
  ) then
    raise exception 'Unauthorized: source target version is not accessible for this caller.';
  end if;

  -- Destination version must be normally visible
  if not public.is_target_version_visible(p_to_target_version_id) then
    raise exception 'Unauthorized: destination target version is not published for this caller.';
  end if;

  select count(distinct cnc.concept_id)
  into v_source_concepts_count
  from public.curriculum_node_concepts cnc
  join public.curriculum_nodes cn on cn.id = cnc.curriculum_node_id
  where cn.target_version_id = p_from_target_version_id;

  select count(distinct cnc.concept_id)
  into v_target_concepts_count
  from public.curriculum_node_concepts cnc
  join public.curriculum_nodes cn on cn.id = cnc.curriculum_node_id
  where cn.target_version_id = p_to_target_version_id;

  select
    count(*),
    count(*) filter (where m.transfer_weight > 0 and m.to_concept_id is not null),
    count(*) filter (
      where m.mapping_type = 'removed'
         or m.to_concept_id is null
         or m.transfer_weight = 0
    ),
    coalesce(round(avg(m.transfer_weight) * 100, 2), 100.00)
  into
    v_mapped_count,
    v_retained_count,
    v_removed_count,
    v_avg_weight
  from public.target_version_concept_mappings m
  where m.from_target_version_id = p_from_target_version_id
    and m.to_target_version_id = p_to_target_version_id;

  if v_mapped_count = 0 and v_source_concepts_count > 0 then
    select count(distinct s.concept_id)
    into v_retained_count
    from (
      select distinct cnc.concept_id
      from public.curriculum_node_concepts cnc
      join public.curriculum_nodes cn on cn.id = cnc.curriculum_node_id
      where cn.target_version_id = p_from_target_version_id
    ) s
    where s.concept_id in (
      select distinct cnc2.concept_id
      from public.curriculum_node_concepts cnc2
      join public.curriculum_nodes cn2 on cn2.id = cnc2.curriculum_node_id
      where cn2.target_version_id = p_to_target_version_id
    );

    v_mapped_count := v_retained_count;
    v_removed_count := greatest(0, v_source_concepts_count - v_retained_count);
    v_avg_weight := round(
      (v_retained_count::numeric / v_source_concepts_count::numeric) * 100,
      2
    );
  end if;

  v_new_concepts_count := greatest(0, v_target_concepts_count - v_retained_count);

  select count(distinct ucs.concept_id)
  into v_user_assessed_count
  from public.user_concept_state ucs
  where ucs.user_id = p_user_id
    and ucs.evidence_count > 0
    and ucs.concept_id in (
      select distinct cnc.concept_id
      from public.curriculum_node_concepts cnc
      join public.curriculum_nodes cn on cn.id = cnc.curriculum_node_id
      where cn.target_version_id = p_from_target_version_id
    );

  v_projected_retained_assessed :=
    round((v_user_assessed_count::numeric * (v_avg_weight / 100.0)), 1);

  select coalesce(jsonb_agg(jsonb_build_object(
    'from_concept_id', m.from_concept_id,
    'to_concept_id', m.to_concept_id,
    'mapping_type', m.mapping_type,
    'transfer_weight', m.transfer_weight,
    'from_concept_name', fc.name,
    'to_concept_name', tc.name
  )), '[]'::jsonb)
  into v_mappings_json
  from public.target_version_concept_mappings m
  left join public.knowledge_concepts fc on fc.id = m.from_concept_id
  left join public.knowledge_concepts tc on tc.id = m.to_concept_id
  where m.from_target_version_id = p_from_target_version_id
    and m.to_target_version_id = p_to_target_version_id;

  return jsonb_build_object(
    'from_target_version_id', p_from_target_version_id,
    'to_target_version_id', p_to_target_version_id,
    'total_source_concepts', v_source_concepts_count,
    'total_target_concepts', v_target_concepts_count,
    'mapped_concepts_count', v_mapped_count,
    'retained_concepts_count', v_retained_count,
    'removed_concepts_count', v_removed_count,
    'new_concepts_count', v_new_concepts_count,
    'transfer_retention_pct', v_avg_weight,
    'user_assessed_concepts_count', v_user_assessed_count,
    'projected_retained_assessed_count', v_projected_retained_assessed,
    'concept_mappings', v_mappings_json
  );
end;
$$;

revoke all on function public.evaluate_target_version_migration(uuid, uuid, uuid) from public;
grant execute on function public.evaluate_target_version_migration(uuid, uuid, uuid) to authenticated, service_role;

-- ----------------------------------------------------------------------------
-- 3. Restore canonical migrate_user_context_target_version RPC
-- ----------------------------------------------------------------------------
create or replace function public.migrate_user_context_target_version(
  p_user_id uuid,
  p_context_id uuid,
  p_to_target_version_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_context record;
  v_from_tv record;
  v_to_tv record;
  v_mapping record;
  v_transferred_count integer := 0;
  v_evaluation jsonb;
  v_retention_pct numeric(5,2) := 100.00;
  v_is_privileged_editor boolean := false;
begin
  if coalesce(auth.role(), '') <> 'service_role'
     and (auth.uid() is null or auth.uid() <> p_user_id) then
    raise exception 'Unauthorized: cannot migrate context for another user.';
  end if;

  select * into v_context
  from public.learning_contexts
  where id = p_context_id and user_id = p_user_id;

  if not found then
    raise exception 'Learning context not found or does not belong to user.';
  end if;

  select * into v_from_tv
  from public.target_versions
  where id = v_context.target_version_id;

  if not found then
    raise exception 'Current target version not found.';
  end if;

  select * into v_to_tv
  from public.target_versions
  where id = p_to_target_version_id;

  if not found then
    raise exception 'Destination target version not found.';
  end if;

  if v_from_tv.target_id <> v_to_tv.target_id then
    raise exception 'Cannot migrate context across different learning targets.';
  end if;

  -- Current target version must be normally visible OR accessible via historical context
  if not (
    public.is_target_version_visible(v_from_tv.id)
    or public.has_historical_target_version_access(v_from_tv.id, p_user_id)
  ) then
    raise exception 'Unauthorized: current target version is not accessible for this caller.';
  end if;

  -- Destination version must be normally visible
  if not public.is_target_version_visible(p_to_target_version_id) then
    raise exception 'Unauthorized: destination target version is not published for this caller.';
  end if;

  if coalesce(auth.role(), '') = 'service_role' then
    v_is_privileged_editor := true;
  elsif auth.uid() is not null then
    select exists (
      select 1
      from public.learning_targets lt
      where lt.id = v_to_tv.target_id
        and lt.created_by = auth.uid()
    ) or public.is_target_reviewer(v_to_tv.target_id)
    into v_is_privileged_editor;
  end if;

  if v_to_tv.status = 'published' then
    null;
  elsif v_to_tv.status = 'review_ready' and v_is_privileged_editor then
    null;
  else
    raise exception 'Cannot migrate to target version with status "%" for this caller.', v_to_tv.status;
  end if;

  v_evaluation := public.evaluate_target_version_migration(
    p_user_id,
    v_from_tv.id,
    v_to_tv.id
  );
  v_retention_pct :=
    coalesce((v_evaluation->>'transfer_retention_pct')::numeric, 100.00);

  for v_mapping in
    select
      m.from_concept_id,
      m.to_concept_id,
      m.transfer_weight
    from public.target_version_concept_mappings m
    where m.from_target_version_id = v_from_tv.id
      and m.to_target_version_id = v_to_tv.id
      and m.to_concept_id is not null
      and m.transfer_weight > 0
  loop
    if v_mapping.from_concept_id <> v_mapping.to_concept_id then
      insert into public.user_concept_state (
        user_id,
        concept_id,
        retrieval_band,
        confidence,
        evidence_count,
        weighted_correct,
        weighted_total,
        last_evidence_at,
        updated_at
      )
      select
        p_user_id,
        v_mapping.to_concept_id,
        ucs.retrieval_band,
        ucs.confidence,
        round(ucs.evidence_count * v_mapping.transfer_weight)::integer,
        ucs.weighted_correct * v_mapping.transfer_weight,
        ucs.weighted_total * v_mapping.transfer_weight,
        ucs.last_evidence_at,
        now()
      from public.user_concept_state ucs
      where ucs.user_id = p_user_id
        and ucs.concept_id = v_mapping.from_concept_id
        and ucs.evidence_count > 0
      on conflict (user_id, concept_id) do update set
        evidence_count = greatest(
          public.user_concept_state.evidence_count,
          excluded.evidence_count
        ),
        weighted_correct = greatest(
          public.user_concept_state.weighted_correct,
          excluded.weighted_correct
        ),
        weighted_total = greatest(
          public.user_concept_state.weighted_total,
          excluded.weighted_total
        ),
        last_evidence_at = coalesce(
          excluded.last_evidence_at,
          public.user_concept_state.last_evidence_at
        ),
        updated_at = now();
    end if;

    v_transferred_count := v_transferred_count + 1;
  end loop;

  update public.learning_contexts
  set
    target_version_id = v_to_tv.id,
    updated_at = now()
  where id = p_context_id;

  -- Resume pointers are disposable breadcrumbs and carry activity IDs rather
  -- than curriculum-node foreign keys. A target-version migration can make the
  -- saved lesson/study-set position stale, so clear the pointer atomically.
  delete from public.resume_pointers
  where context_id = p_context_id;

  insert into public.user_version_migration_logs (
    user_id,
    context_id,
    from_target_version_id,
    to_target_version_id,
    transferred_concepts_count,
    retained_mastery_pct,
    migration_metadata
  )
  values (
    p_user_id,
    p_context_id,
    v_from_tv.id,
    v_to_tv.id,
    v_transferred_count,
    v_retention_pct,
    jsonb_build_object(
      'from_version_code', v_from_tv.version_code,
      'to_version_code', v_to_tv.version_code,
      'evaluation', v_evaluation
    )
  );

  return jsonb_build_object(
    'success', true,
    'context_id', p_context_id,
    'from_version_code', v_from_tv.version_code,
    'to_version_code', v_to_tv.version_code,
    'transferred_concepts_count', v_transferred_count,
    'retained_mastery_pct', v_retention_pct
  );
end;
$$;

revoke all on function public.migrate_user_context_target_version(uuid, uuid, uuid) from public;
grant execute on function public.migrate_user_context_target_version(uuid, uuid, uuid) to authenticated, service_role;

INSERT INTO supabase_migrations.schema_migrations (version, name) VALUES ('20261009000004', 'restore_rpc_contracts_and_close_enrollment_oracle') ON CONFLICT (version) DO NOTHING;

-- --------------------------------------------------------------------
-- [37/96] Migration: 20261009000005_learning_target_catalog_provenance.sql
-- --------------------------------------------------------------------
-- Catalog source integrity. This migration is append-only.
-- A public entry is either an official platform record or a reviewed community record.
-- A private learner draft remains editable/visible to its owner.
alter table public.learning_targets
  add column if not exists review_status text not null default 'unreviewed';

alter table public.learning_targets
  add constraint learning_targets_review_status_check
  check (review_status in ('unreviewed', 'pending', 'approved', 'rejected'));

-- Existing platform-imported public entries remain catalog-visible, without
-- incorrectly labeling them official if their is_official flag is false.
update public.learning_targets
set review_status = case
  when is_official or (created_by is null and status = 'published' and is_public)
    then 'approved'
  when created_by is not null and status = 'published' and is_public
    then 'pending'
  else 'unreviewed'
end;

-- Previously public user-created entries were never vetted: retain them for
-- owners, but remove them from public discovery pending review.
update public.learning_targets
set status = 'draft', is_public = false
where created_by is not null
  and is_official = false
  and review_status = 'pending'
  and status = 'published'
  and is_public = true;

-- Defense in depth: never trust client-supplied origin, review, or publication
-- flags. A future moderator or trusted ingestion job uses service_role.
create or replace function public.enforce_learning_target_catalog_provenance()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
declare
  v_role text := coalesce(auth.role(), '');
begin
  -- Migrations/SQL fixtures run directly as privileged DB users without a JWT.
  -- A security-definer RPC called by an API client retains the caller JWT and
  -- therefore is NOT granted this exception.
  if v_role = 'service_role' or
     (v_role = '' and current_user in ('postgres', 'supabase_admin', 'service_role')) then
    -- Trusted ingestion of system-authored catalog records keeps working
    -- without pretending that all such records are "official".
    if tg_op = 'INSERT'
       and new.created_by is null
       and new.is_public and new.status = 'published'
       and new.review_status = 'unreviewed' then
      new.review_status := 'approved';
    end if;
    if tg_op = 'DELETE' then return old; end if;
    return new;
  end if;

  if auth.uid() is null then
    raise exception 'Sign in before changing learning goals.' using errcode = '42501';
  end if;

  if tg_op = 'DELETE' then
    if old.created_by is distinct from auth.uid()
       or old.is_official or old.review_status = 'approved' then
      raise exception 'Only trusted reviewers may delete verified goals.'
        using errcode = '42501';
    end if;
    return old;
  end if;

  if tg_op = 'INSERT' then
    if new.created_by is distinct from auth.uid()
       or new.is_official or new.is_public
       or new.status <> 'draft'
       or new.review_status <> 'unreviewed' then
      raise exception 'User goals must begin as private, unreviewed drafts.'
        using errcode = '42501';
    end if;
  else
    if old.created_by is distinct from auth.uid()
       or new.created_by is distinct from old.created_by
       or old.is_official or new.is_official
       or old.review_status = 'approved'
       or new.review_status not in ('unreviewed', 'pending')
       or new.is_public
       or new.status <> 'draft' then
      raise exception 'Only trusted reviewers may publish or verify goals.'
        using errcode = '42501';
    end if;
  end if;

  return new;
end;
$$;

drop trigger if exists enforce_learning_target_catalog_provenance
  on public.learning_targets;
create trigger enforce_learning_target_catalog_provenance
before insert or update or delete on public.learning_targets
for each row execute function public.enforce_learning_target_catalog_provenance();

-- Explicit catalog read contract, while preserving owner access.
drop policy if exists "targets_read" on public.learning_targets;
create policy "targets_read" on public.learning_targets
for select using (
  auth.uid() = created_by
  or (status = 'published' and is_public
      and (is_official or review_status = 'approved'))
);

create index if not exists learning_targets_public_review_idx
on public.learning_targets (target_type, title)
where status = 'published' and is_public
  and (is_official or review_status = 'approved');

comment on column public.learning_targets.review_status is
  'Unreviewed/pending/rejected user drafts are private; approved community entries can be public. Only trusted service-role workflows may approve.';

INSERT INTO supabase_migrations.schema_migrations (version, name) VALUES ('20261009000005', 'learning_target_catalog_provenance') ON CONFLICT (version) DO NOTHING;

-- --------------------------------------------------------------------
-- [38/96] Migration: 20261012000000_catalog_candidate_intake.sql
-- --------------------------------------------------------------------
-- Phase P0: private credential/license/exam/program candidate intake.
-- Candidate names and issuer links are NOT approved catalog destinations.
-- New bulk sources and requirements must be reviewed before publication.
-- Never expose raw candidates/demand evidence to the public API.
create table public.catalog_intake_candidates (
  id uuid primary key default gen_random_uuid(),
  source_namespace text not null check (source_namespace ~ '^[a-z0-9_]{3,48}$'),
  source_key text not null check (length(source_key) between 1 and 128),
  destination_type text not null check (destination_type in (
    'certification', 'professional_license', 'licensure_exam',
    'standardized_exam', 'academic_program', 'training_course'
  )),
  title text not null check (length(btrim(title)) between 3 and 240),
  issuer_name text not null check (length(btrim(issuer_name)) between 2 and 200),
  issuer_url text not null check (issuer_url ~ '^https://[^[:space:]]+$'),
  source_url text not null check (source_url ~ '^https://[^[:space:]]+$'),
  jurisdiction text not null default 'US' check (length(jurisdiction) between 2 and 48),
  description text,
  cip_code text,
  onet_code text,
  edition text,
  source_rights text not null default 'link_metadata_only'
    check (source_rights in ('link_metadata_only', 'approved_for_display', 'blocked')),
  review_status text not null default 'pending'
    check (review_status in ('pending', 'approved', 'rejected')),
  verified_at timestamptz,
  publication_status text not null default 'draft'
    check (publication_status in ('draft', 'published', 'retired')),
  linked_target_id uuid references public.learning_targets(id) on delete set null,
  metadata jsonb not null default '{}'::jsonb check (jsonb_typeof(metadata) = 'object'),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (source_namespace, source_key),
  constraint intake_publish_review_gate check (
    publication_status <> 'published' or (
      review_status = 'approved'
      and verified_at is not null
      and source_rights = 'approved_for_display'
    )
  )
);

create index catalog_intake_review_idx
  on public.catalog_intake_candidates (review_status, destination_type, jurisdiction);
create index catalog_intake_title_idx
  on public.catalog_intake_candidates (lower(title));
create index catalog_intake_target_idx
  on public.catalog_intake_candidates (linked_target_id)
  where linked_target_id is not null;

comment on table public.catalog_intake_candidates is
  'Private issuer-linked discovery intake; pending candidates are NOT published credentials or verified license requirements.';

create table public.catalog_intake_demand_signals (
  id uuid primary key default gen_random_uuid(),
  candidate_id uuid not null references public.catalog_intake_candidates(id) on delete cascade,
  metric text not null check (metric in (
    'bls_annual_openings', 'ipeds_completions', 'onet_job_postings',
    'issuer_exam_participants', 'search_interest_index',
    'community_goal_saves', 'community_searches'
  )),
  metric_value numeric not null check (metric_value >= 0),
  observed_period text not null check (observed_period ~ '^20[0-9]{2}(-[0-9]{2})?$'),
  geography text not null check (length(geography) between 2 and 48),
  publisher text not null check (length(btrim(publisher)) between 2 and 120),
  evidence_url text not null check (evidence_url ~ '^https://[^[:space:]]+$'),
  method_note text not null check (length(btrim(method_note)) > 0),
  data_rights text not null default 'metadata_only'
    check (data_rights in ('metadata_only', 'approved_aggregate')),
  observed_at timestamptz not null default now(),
  unique (candidate_id, metric, observed_period, geography, publisher)
);

create index catalog_intake_demand_recent_idx
  on public.catalog_intake_demand_signals (metric, observed_period, geography);

comment on table public.catalog_intake_demand_signals is
  'Evidence only: nonnegative observed metrics with source, period and geography. No imputed popularity and no unlicensed provider text.';

-- Intentional explicit deny for browser clients. Administrative ingestion is
-- service-role only; no user can promote a candidate to official status.
alter table public.catalog_intake_candidates enable row level security;
alter table public.catalog_intake_demand_signals enable row level security;

revoke all on table public.catalog_intake_candidates from public, anon, authenticated;
revoke all on table public.catalog_intake_demand_signals from public, anon, authenticated;
grant select, insert, update, delete on table public.catalog_intake_candidates to service_role;
grant select, insert, update, delete on table public.catalog_intake_demand_signals to service_role;

INSERT INTO supabase_migrations.schema_migrations (version, name) VALUES ('20261012000000', 'catalog_candidate_intake') ON CONFLICT (version) DO NOTHING;

-- --------------------------------------------------------------------
-- [39/96] Migration: 20261012000001_catalog_official_demand_observations.sql
-- --------------------------------------------------------------------
-- P1 official numerical evidence: private, versioned CIP/SOC observations.
-- NEVER interpret a CIP-SOC mapping as proof of a license, exam or
-- certification requirement. Figures remain associated with taxonomy codes.
create table public.catalog_official_demand_observations (
  id uuid primary key default gen_random_uuid(),
  taxonomy_system text not null check (taxonomy_system in ('cip','bls_soc')),
  taxonomy_version text not null check (taxonomy_version in ('2020','soc_2018')),
  taxonomy_code text not null check (
    (taxonomy_system='cip' and taxonomy_version='2020'
      and taxonomy_code ~ '^[0-9]{2}\.[0-9]{4}$')
    or
    (taxonomy_system='bls_soc' and taxonomy_version='soc_2018'
      and taxonomy_code ~ '^[0-9]{2}-[0-9]{4}$')
  ),
  metric text not null check (metric in (
    'ipeds_awards_conferred', 'bls_annual_openings_thousands'
  )),
  metric_value numeric(15,2) not null check (metric_value >= 0),
  metric_unit text not null check (metric_unit in ('awards', 'thousands_of_jobs')),
  period text not null check (period in ('2024-2025','2025-2035')),
  geography text not null default 'US' check (geography='US'),
  dimension text not null default 'all'
    check (dimension ~ '^[a-zA-Z0-9_:.-]{1,64}$'),
  publisher text not null check (publisher in ('NCES_IPEDS','BLS_EMP')),
  source_release text not null check (source_release in ('C2025_A_provisional','BLS_EMP_2025_2035')),
  source_url text not null check (source_url ~ '^https://[^[:space:]]+$'),
  source_sha256 text not null check (source_sha256 ~ '^[0-9a-f]{64}$'),
  method_note text not null check (length(btrim(method_note)) >= 20),
  imported_at timestamptz not null default now(),
  constraint demand_observation_semantics check (
    (taxonomy_system='cip' and metric='ipeds_awards_conferred'
      and metric_unit='awards' and period='2024-2025'
      and publisher='NCES_IPEDS' and source_release='C2025_A_provisional')
    or
    (taxonomy_system='bls_soc' and metric='bls_annual_openings_thousands'
      and metric_unit='thousands_of_jobs' and period='2025-2035'
      and publisher='BLS_EMP' and source_release='BLS_EMP_2025_2035'
      and dimension='all')
  ),
  unique(taxonomy_system,taxonomy_version,taxonomy_code,metric,period,geography,dimension,source_release)
);

create index catalog_demand_measure_order_idx
on public.catalog_official_demand_observations (metric, period, metric_value desc);
create index catalog_demand_taxonomy_idx
on public.catalog_official_demand_observations (taxonomy_system, taxonomy_version, taxonomy_code);

alter table public.catalog_official_demand_observations enable row level security;
revoke all on table public.catalog_official_demand_observations from public, anon, authenticated;
grant select, insert, update, delete on table public.catalog_official_demand_observations to service_role;

comment on table public.catalog_official_demand_observations is
  'Private sourced national demand measures linked to CIP or SOC ONLY; a high score is not proof that a certification or legal license is popular. BLS values stay in published thousands, not precise counts.';

create table public.catalog_official_demand_imports (
  source_release text not null primary key
    check (source_release in ('C2025_A_provisional','BLS_EMP_2025_2035')),
  source_url text not null,
  sha256 text not null check (sha256 ~ '^[0-9a-f]{64}$'),
  source_bytes bigint not null check (source_bytes > 0),
  observations integer not null check (observations > 0),
  checked_at timestamptz not null default now(),
  method_note text not null
);
alter table public.catalog_official_demand_imports enable row level security;
revoke all on table public.catalog_official_demand_imports from public, anon, authenticated;
grant select, insert, update on table public.catalog_official_demand_imports to service_role;

INSERT INTO supabase_migrations.schema_migrations (version, name) VALUES ('20261012000001', 'catalog_official_demand_observations') ON CONFLICT (version) DO NOTHING;

-- --------------------------------------------------------------------
-- [40/96] Migration: 20261012000002_catalog_bls_reporting_code_members.sql
-- --------------------------------------------------------------------
-- BLS publication/combined reporting codes are not detailed SOC 2018 codes.
-- These associations state membership ONLY. Job openings for the combined
-- BLS series must never be duplicated/allocated across component SOC codes.
create table public.catalog_bls_reporting_code_members (
  bls_release text not null default 'BLS_EMP_2025_2035'
    check (bls_release = 'BLS_EMP_2025_2035'),
  reporting_code text not null check (reporting_code ~ '^[0-9]{2}-[0-9]{4}$'),
  soc_2018_code text not null check (soc_2018_code ~ '^[0-9]{2}-[0-9]{4}$'),
  relationship text not null default 'includes_occupation'
    check (relationship = 'includes_occupation'),
  allocation_policy text not null default 'not_allocated'
    check (allocation_policy = 'not_allocated'),
  source_url text not null default 'https://www.bls.gov/oes/oes_ques.htm'
    check (source_url = 'https://www.bls.gov/oes/oes_ques.htm'),
  source_note text not null
    check (length(btrim(source_note)) >= 30),
  created_at timestamptz not null default now(),
  primary key (bls_release, reporting_code, soc_2018_code),
  check (reporting_code <> soc_2018_code)
);
alter table public.catalog_bls_reporting_code_members enable row level security;
revoke all on table public.catalog_bls_reporting_code_members from public, anon, authenticated;
grant select, insert, update, delete on table public.catalog_bls_reporting_code_members to service_role;

-- Explicit BLS source-documented hybrid code to 2018 detailed occupation
-- membership. Each composite still has ONE published aggregate number.
with source_members(reporting_code, code, explanation) as (
  values
    ('21-1018','21-1011','BLS combines substance abuse/behavioral disorder and mental health counselors'),
    ('21-1018','21-1014','BLS combines substance abuse/behavioral disorder and mental health counselors'),
    ('25-2052','25-2055','BLS combines kindergarten and elementary special education teachers'),
    ('25-2052','25-2056','BLS combines kindergarten and elementary special education teachers'),
    ('25-9045','25-9042','BLS combines non-postsecondary teaching assistants across several specialties'),
    ('25-9045','25-9043','BLS combines non-postsecondary teaching assistants across several specialties'),
    ('25-9045','25-9049','BLS combines non-postsecondary teaching assistants across several specialties'),
    ('51-2028','51-2022','BLS combines electrical/electronic and electromechanical assemblers'),
    ('51-2028','51-2023','BLS combines electrical/electronic and electromechanical assemblers'),
    ('53-1047','53-1042','BLS combines four transportation/material-moving supervisor SOC occupations'),
    ('53-1047','53-1043','BLS combines four transportation/material-moving supervisor SOC occupations'),
    ('53-1047','53-1044','BLS combines four transportation/material-moving supervisor SOC occupations'),
    ('53-1047','53-1049','BLS combines four transportation/material-moving supervisor SOC occupations')
)
insert into public.catalog_bls_reporting_code_members
(reporting_code, soc_2018_code, source_note)
select reporting_code,code,explanation
from source_members
on conflict (bls_release,reporting_code,soc_2018_code) do nothing;

comment on table public.catalog_bls_reporting_code_members is
'BLS documentation-based combined reporting code membership: never allocate, duplicate or sum combined openings into each component SOC.';

-- No public view or grants. Future reporting must retain raw 831 BLS rows
-- and show one reporting-category total (not fractional allocations).

-- One observation per BLS original code. Membership is a separate relation;
-- this view classifies hybrid codes but NEVER explodes a total across members.
create view public.v_catalog_bls_observation_coverage
with (security_invoker = true) as
select
  o.taxonomy_code as bls_reporting_code,
  o.metric_value as annual_openings_thousands,
  o.period,
  o.source_release,
  case
    when exists (
      select 1 from public.occupation_nodes n
      where n.taxonomy_system='bls_soc'
        and n.taxonomy_version='soc_2018'
        and n.is_active
        and n.code=o.taxonomy_code
    ) then 'exact_soc_2018'
    when exists (
      select 1 from public.catalog_bls_reporting_code_members c
      where c.bls_release=o.source_release
        and c.reporting_code=o.taxonomy_code
    ) then 'combined_reporting_code'
    else 'unmapped'
  end as coverage_status,
  (
    select count(*)::integer
    from public.catalog_bls_reporting_code_members c
    where c.bls_release=o.source_release
      and c.reporting_code=o.taxonomy_code
  ) as member_soc_count
from public.catalog_official_demand_observations o
where o.publisher='BLS_EMP'
  and o.metric='bls_annual_openings_thousands'
  and o.source_release='BLS_EMP_2025_2035';

revoke all on public.v_catalog_bls_observation_coverage
from public, anon, authenticated;
grant select on public.v_catalog_bls_observation_coverage to service_role;

comment on view public.v_catalog_bls_observation_coverage is
  'Private one-row-per-original-BLS-observation coverage classifications; 826 exact SOC 2018 + 5 combined reporting categories, without double counting.';

