-- --------------------------------------------------------------------
-- [44/96] Migration: 20261012000006_catalog_license_pathway_versions.sql
-- --------------------------------------------------------------------
-- P2e: carefully reviewed, versioned regulator-sourced *selected* licensing steps.
-- This does not change the original issuer directory's requirements_status:
-- a sourced partial pathway is NOT a comprehensive eligibility assessment.
create function public.catalog_license_tree_valid(node jsonb, depth integer default 0)
returns boolean language plpgsql immutable security invoker
set search_path = pg_catalog
as $$
declare
  kind text;
  item jsonb;
begin
  if node is null or jsonb_typeof(node) <> 'object' or depth > 8 then
    return false;
  end if;
  kind := node->>'op';
  if kind in ('all','any') then
    if jsonb_typeof(node->'children') is distinct from 'array'
       or jsonb_array_length(node->'children') < 2
       or jsonb_array_length(node->'children') > 20
       or (select count(*) from jsonb_object_keys(node)) <> 2 then
      return false;
    end if;
    for item in select value from jsonb_array_elements(node->'children') loop
      if not public.catalog_license_tree_valid(item, depth+1) then
        return false;
      end if;
    end loop;
    return true;
  elsif kind = 'step' then
    return (select count(*) from jsonb_object_keys(node)) between 4 and 5
       and node ? 'label' and node ? 'stage' and node ? 'source_url'
       and ((select count(*) from jsonb_object_keys(node)) = 4 or node ? 'condition')
       and length(btrim(node->>'label')) between 8 and 280
       and node->>'stage' in (
         'education','training','experience','examination',
         'background_screening','application','appointment',
         'continuing_education','authorization','other')
       and (node->>'source_url') ~ '^https://[^[:space:]]+$'
       and (not (node ? 'condition') or
         (jsonb_typeof(node->'condition')='string' and
          length(btrim(node->>'condition')) between 10 and 280));
  end if;
  return false;
end
$$;
revoke all on function public.catalog_license_tree_valid(jsonb,integer) from public,anon,authenticated;
grant execute on function public.catalog_license_tree_valid(jsonb,integer) to service_role;
comment on function public.catalog_license_tree_valid(jsonb,integer) is
 'Reject unsupported or malformed nested AND/OR pathway expressions. Source domain and legal accuracy require separate reviewer checks.';

create table public.catalog_license_pathway_versions (
  id uuid primary key default gen_random_uuid(),
  source_namespace text not null,
  source_key text not null,
  revision integer not null check (revision between 1 and 100000),
  jurisdiction text not null check (length(jurisdiction) between 2 and 48),
  route_kind text not null default 'examination'
    check (route_kind in ('examination','endorsement','renewal','other')),
  title text not null check (length(btrim(title)) between 8 and 180),
  overview text not null check (length(btrim(overview)) between 80 and 1200),
  coverage text not null default 'selected_steps_only'
    check (coverage='selected_steps_only'),
  source_url text not null check (source_url ~ '^https://[^[:space:]]+$'),
  source_checked_at timestamptz not null,
  reviewed_at timestamptz,
  reviewer text,
  effective_from date,
  effective_until date,
  supersedes_revision integer,
  review_status text not null default 'pending'
    check (review_status in ('pending','approved','rejected')),
  publication_status text not null default 'draft'
    check (publication_status in ('draft','published','retired')),
  pathway_tree jsonb not null check (public.catalog_license_tree_valid(pathway_tree)),
  created_at timestamptz not null default now(),
  constraint license_pathway_parent_fk foreign key (source_namespace,source_key)
    references public.catalog_verified_destinations(source_namespace,source_key)
    on update restrict on delete restrict,
  constraint license_pathway_revision_unique unique (source_namespace,source_key,revision),
  constraint license_pathway_supersedes_ck check (
    supersedes_revision is null or
    (supersedes_revision > 0 and supersedes_revision < revision)),
  constraint license_pathway_effective_range_ck check (
    effective_from is null or effective_until is null
    or effective_until >= effective_from),
  constraint license_pathway_approval_ck check (
    publication_status <> 'published' or (
      review_status='approved' and reviewed_at is not null
      and reviewer is not null and length(btrim(reviewer)) >= 3))
);
create unique index catalog_license_pathway_one_current_idx
  on public.catalog_license_pathway_versions (source_namespace,source_key)
  where publication_status='published';
create index catalog_license_pathway_visibility_idx
  on public.catalog_license_pathway_versions
  (source_namespace,source_key,publication_status,source_checked_at desc);

comment on table public.catalog_license_pathway_versions is
 'Versioned, regulator-sourced selected licensure steps. Explicit nested AND/OR. Partial coverage only; not comprehensive qualification, license issuance, course, or exam award.';

create function public.guard_catalog_license_pathway_version()
returns trigger language plpgsql security invoker
set search_path = public,pg_temp
as $$
declare d record;
begin
  if tg_op='DELETE' then
    if old.publication_status <> 'draft' then
      raise exception 'Reviewed pathways cannot be deleted; retire and version instead';
    end if;
    return old;
  end if;

  if tg_op='UPDATE' and old.publication_status in ('published','retired') then
    if old.publication_status='published'
       and new.publication_status='retired'
       and (to_jsonb(new) - 'publication_status')
           = (to_jsonb(old) - 'publication_status') then
      return new;
    end if;
    raise exception 'Published pathway versions are immutable; create a new revision';
  end if;

  select destination_type,jurisdiction,publication_status
    into d from public.catalog_verified_destinations
    where source_namespace=new.source_namespace and source_key=new.source_key;

  if not found or d.destination_type <> 'professional_license'
       or d.jurisdiction is distinct from new.jurisdiction then
    raise exception 'Pathway must match a professional license and its jurisdiction';
  end if;

  if new.source_checked_at > now() then
    raise exception 'Source review timestamp cannot be in the future';
  end if;

  if new.publication_status='published' then
    if d.publication_status <> 'published'
       or new.review_status <> 'approved'
       or new.reviewed_at is null
       or new.reviewer is null
       or length(btrim(new.reviewer)) < 3
       or new.reviewed_at < new.source_checked_at
       or new.reviewed_at > now()
       or new.source_checked_at < now() - interval '180 days' then
      raise exception 'Publishing requires current documented regulator review';
    end if;
    if new.supersedes_revision is not null and not exists (
      select 1 from public.catalog_license_pathway_versions previous
      where previous.source_namespace=new.source_namespace
        and previous.source_key=new.source_key
        and previous.revision=new.supersedes_revision
        and previous.publication_status='retired'
    ) then
      raise exception 'Superseded revision must first be retired';
    end if;
  end if;
  return new;
end
$$;
revoke all on function public.guard_catalog_license_pathway_version() from public,anon,authenticated;
create trigger trg_guard_catalog_license_pathway
before insert or update or delete on public.catalog_license_pathway_versions
for each row execute function public.guard_catalog_license_pathway_version();

-- A destination revoked or retired due to issuer review changes immediately
-- retires a published pathway (and prevents stale resurrection).
create function public.retire_license_pathways_after_destination_change()
returns trigger language plpgsql security invoker
set search_path=public,pg_temp
as $$
begin
  if old.publication_status='published' and new.publication_status='retired' then
    update public.catalog_license_pathway_versions
       set publication_status='retired'
     where source_namespace=new.source_namespace
       and source_key=new.source_key
       and publication_status='published';
  end if;
  return new;
end
$$;
revoke all on function public.retire_license_pathways_after_destination_change() from public,anon,authenticated;
create trigger trg_retire_license_pathway_with_destination
after update of publication_status on public.catalog_verified_destinations
for each row execute function public.retire_license_pathways_after_destination_change();

alter table public.catalog_license_pathway_versions enable row level security;
revoke all on public.catalog_license_pathway_versions from public,anon,authenticated;
grant select on public.catalog_license_pathway_versions to anon,authenticated;
grant select,insert,update,delete on public.catalog_license_pathway_versions to service_role;
create policy catalog_license_pathway_reviewed_public_select
on public.catalog_license_pathway_versions for select to anon,authenticated
using (
  publication_status='published' and review_status='approved'
  and source_checked_at >= now() - interval '180 days'
  and (effective_from is null or effective_from <= current_date)
  and (effective_until is null or effective_until >= current_date)
  and exists (
    select 1 from public.catalog_verified_destinations d
    where d.source_namespace=public.catalog_license_pathway_versions.source_namespace
      and d.source_key=public.catalog_license_pathway_versions.source_key
      and d.publication_status='published'
      and d.destination_type='professional_license'
      and d.jurisdiction=public.catalog_license_pathway_versions.jurisdiction
  )
);

INSERT INTO supabase_migrations.schema_migrations (version, name) VALUES ('20261012000006', 'catalog_license_pathway_versions') ON CONFLICT (version) DO NOTHING;

-- --------------------------------------------------------------------
-- [45/96] Migration: 20261015000000_cip_internal_field_bootstrap.sql
-- --------------------------------------------------------------------
-- ============================================================================
-- CIP 2020 internal field bootstrap (CANONICAL_TAXONOMY_ARCHITECTURE.md §3.2,
-- §10.2 Phase 2.2–2.4).
--
-- The official CIP 2020 graph (48 series, 466 groups, 2,295 programs) is
-- imported into external_classification_nodes, but only the 48 series were
-- given internal `fields`. This migration:
--   1. Adds bootstrap_cip_internal_fields(): a transactional, idempotent,
--      fail-closed bootstrap that gives every active CIP 2020 node exactly one
--      permanent internal field (subfield / program_classification) linked by
--      an exact_match mapping and an internal parent_id.
--   2. Adds taxonomy_internal_coverage(): a read-only report that keeps
--      internal-hierarchy completeness separate from external import counts.
--   3. Backfills the hierarchy for whatever CIP 2020 nodes are present.
--
-- Rules:
--   * Existing exact mappings (e.g. the 48 curated broad fields and their
--     catalog cluster memberships) are reused; IDs are never regenerated.
--   * Nothing is merged on title or slug. Generated slugs carry the CIP code,
--     and an existing slug collision aborts instead of merging.
--   * Only CIP 2020 is bootstrapped. Later editions must be mapped to existing
--     fields through reviewed lineage, never duplicated automatically.
--   * Clients cannot run the bootstrap; it is service_role only.
-- ============================================================================

create or replace function public.cip_internal_field_slug(p_title text, p_code text)
returns text
language sql
immutable
set search_path = pg_catalog
as $$
  select coalesce(
           nullif(btrim(left(regexp_replace(lower(coalesce(p_title, '')), '[^a-z0-9]+', '-', 'g'), 80), '-'), ''),
           'field'
         ) || '-cip-' || replace(p_code, '.', '-');
$$;

comment on function public.cip_internal_field_slug(text, text) is
  'Deterministic, code-qualified slug for CIP-bootstrapped internal fields. '
  'Including the code keeps repeated CIP titles (e.g. 11.01 and 11.0101) distinct.';

-- Active CIP nodes of one level that still lack an exact internal field.
create or replace function public.cip_bootstrap_pending(p_version text, p_level text)
returns table (
  node_id uuid,
  code text,
  slug text,
  name text,
  description text,
  cross_references text[],
  illustrative_examples text[],
  parent_field_id uuid,
  sort_order integer
)
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  select
    n.id,
    n.code,
    public.cip_internal_field_slug(n.title, n.code),
    regexp_replace(btrim(n.title), '\s*\.+$', ''),
    n.definition,
    coalesce(n.cross_references, '{}'),
    coalesce(n.illustrative_examples, '{}'),
    pf.field_id,
    case
      when p_level = 'series' and n.code ~ '^\d+$' then n.code::integer
      when split_part(n.code, '.', 2) ~ '^\d+$' then split_part(n.code, '.', 2)::integer
      else 0
    end
  from public.external_classification_nodes n
  left join public.field_external_classifications pf
    on pf.classification_node_id = n.parent_id
   and pf.mapping_type = 'exact_match'
  where n.system = 'cip' and n.version = p_version and n.is_active
    and n.level_code = p_level
    and not exists (
      select 1 from public.field_external_classifications fec
      where fec.classification_node_id = n.id and fec.mapping_type = 'exact_match'
    );
$$;

revoke all on function public.cip_bootstrap_pending(text, text) from public, anon, authenticated;
grant execute on function public.cip_bootstrap_pending(text, text) to service_role;

create or replace function public.bootstrap_cip_internal_fields(p_version text default '2020')
returns jsonb
language plpgsql
security invoker
set search_path = public, pg_temp
as $$
declare
  v_level text;
  v_kind text;
  v_count bigint;
  v_created jsonb := '{}'::jsonb;
  v_total_created bigint := 0;
  v_problem text;
  v_active bigint;
  v_mapped bigint;
  v_overrides bigint;
begin
  if p_version is distinct from '2020' then
    raise exception 'CIP % cannot be bootstrapped: only CIP 2020 creates internal fields; later editions require reviewed mappings to existing fields',
      coalesce(p_version, '<null>')
      using errcode = '22023';
  end if;

  -- Serialize concurrent runs so two callers cannot both create a node's field.
  perform pg_advisory_xact_lock(hashtext('public.bootstrap_cip_internal_fields'));

  -- 1. Fail closed on unsupported hierarchy levels.
  select string_agg(distinct n.level_code, ', ') into v_problem
  from external_classification_nodes n
  where n.system = 'cip' and n.version = p_version and n.is_active
    and n.level_code not in ('series', 'group', 'program');
  if v_problem is not null then
    raise exception 'CIP % has unsupported level codes: %', p_version, v_problem
      using errcode = 'P0001';
  end if;

  -- 2. Fail closed on broken or inconsistent external parents.
  select string_agg(x.code, ', ' order by x.code) into v_problem
  from (
    select n.code
    from external_classification_nodes n
    left join external_classification_nodes p on p.id = n.parent_id
    where n.system = 'cip' and n.version = p_version and n.is_active
      and (
        (n.level_code = 'series' and n.parent_id is not null)
        or (
          n.level_code <> 'series'
          and (
            p.id is null
            or not p.is_active
            or p.system <> n.system
            or p.version <> n.version
            or p.level_code <> case n.level_code when 'group' then 'series' else 'group' end
            or left(n.code, length(p.code)) <> p.code
          )
        )
      )
    order by n.code
    limit 20
  ) x;
  if v_problem is not null then
    raise exception 'CIP % hierarchy is broken; refusing to bootstrap. Invalid parents for: %', p_version, v_problem
      using errcode = 'P0001';
  end if;

  -- 3. Fail closed on ambiguous existing exact mappings.
  select string_agg(x.code, ', ' order by x.code) into v_problem
  from (
    select n.code
    from field_external_classifications fec
    join external_classification_nodes n on n.id = fec.classification_node_id
    where n.system = 'cip' and n.version = p_version and fec.mapping_type = 'exact_match'
    group by n.code
    having count(*) > 1
    order by n.code
    limit 20
  ) x;
  if v_problem is not null then
    raise exception 'CIP % nodes have multiple exact internal fields: %', p_version, v_problem
      using errcode = 'P0001';
  end if;

  select string_agg(x.slug, ', ' order by x.slug) into v_problem
  from (
    select f.slug
    from field_external_classifications fec
    join external_classification_nodes n on n.id = fec.classification_node_id
    join fields f on f.id = fec.field_id
    where n.system = 'cip' and n.version = p_version and fec.mapping_type = 'exact_match'
    group by f.slug
    having count(*) > 1
    order by f.slug
    limit 20
  ) x;
  if v_problem is not null then
    raise exception 'Internal fields exactly match multiple CIP % nodes: %', p_version, v_problem
      using errcode = 'P0001';
  end if;

  -- 4. Create missing fields top-down so each level's parents already exist.
  foreach v_level in array array['series', 'group', 'program'] loop
    v_kind := case v_level
      when 'series' then 'broad_field'
      when 'group' then 'subfield'
      else 'program_classification'
    end;

    if v_level <> 'series' and exists (
      select 1 from public.cip_bootstrap_pending(p_version, v_level) p
      where p.parent_field_id is null
    ) then
      raise exception 'CIP % % nodes have no internal parent field; refusing to create orphans', p_version, v_level
        using errcode = 'P0001';
    end if;

    select string_agg(x.slug, ', ' order by x.slug) into v_problem
    from (
      select p.slug
      from public.cip_bootstrap_pending(p_version, v_level) p
      join fields f on f.slug = p.slug
      order by p.slug
      limit 20
    ) x;
    if v_problem is not null then
      raise exception 'Refusing to merge CIP % nodes into existing unmapped fields with slugs: %', p_version, v_problem
        using errcode = 'P0001';
    end if;

    -- The pending CTE is evaluated once, before either insert runs.
    with pending as materialized (
      select * from public.cip_bootstrap_pending(p_version, v_level)
    ),
    inserted as (
      insert into fields (
        name, slug, description, field_kind, parent_id, sort_order, is_active,
        cross_references, illustrative_examples, metadata
      )
      select
        p.name, p.slug, p.description, v_kind, p.parent_field_id, p.sort_order, true,
        p.cross_references, p.illustrative_examples,
        jsonb_build_object(
          'bootstrap',
          jsonb_build_object('system', 'cip', 'version', p_version, 'code', p.code)
        )
      from pending p
      returning id, slug
    )
    insert into field_external_classifications (field_id, classification_node_id, mapping_type, notes)
    select i.id, p.node_id, 'exact_match', 'CIP ' || p_version || ' internal field bootstrap'
    from inserted i
    join pending p on p.slug = i.slug;

    get diagnostics v_count = row_count;
    v_created := v_created || jsonb_build_object(v_kind, v_count);
    v_total_created := v_total_created + v_count;
  end loop;

  -- 5. Post-condition: every active node has exactly one exact internal field.
  select count(*), count(*) filter (where m.exact_count = 1)
  into v_active, v_mapped
  from (
    select (
      select count(*) from field_external_classifications fec
      where fec.classification_node_id = n.id and fec.mapping_type = 'exact_match'
    ) as exact_count
    from external_classification_nodes n
    where n.system = 'cip' and n.version = p_version and n.is_active
  ) m;
  if v_active <> v_mapped then
    raise exception 'CIP % bootstrap incomplete: % of % active nodes mapped', p_version, v_mapped, v_active
      using errcode = 'P0001';
  end if;

  -- Curated internal re-homing of pre-existing fields is preserved, but reported.
  select count(*) into v_overrides
  from external_classification_nodes n
  join field_external_classifications c
    on c.classification_node_id = n.id and c.mapping_type = 'exact_match'
  join fields f on f.id = c.field_id
  join field_external_classifications pc
    on pc.classification_node_id = n.parent_id and pc.mapping_type = 'exact_match'
  where n.system = 'cip' and n.version = p_version and n.is_active
    and n.level_code <> 'series'
    and f.parent_id is distinct from pc.field_id;

  return jsonb_build_object(
    'system', 'cip',
    'version', p_version,
    'active_nodes', v_active,
    'mapped_nodes', v_mapped,
    'created', v_created,
    'created_total', v_total_created,
    'reused_existing', v_active - v_total_created,
    'internal_parent_overrides', v_overrides
  );
end;
$$;

comment on function public.bootstrap_cip_internal_fields(text) is
  'Service-role only. Idempotently gives every active CIP 2020 node one permanent internal field '
  'with an exact_match mapping and internal parent. Fails closed on broken parents, ambiguous '
  'mappings, or slug collisions. Rerun after official CIP imports.';

revoke all on function public.bootstrap_cip_internal_fields(text) from public, anon, authenticated;
grant execute on function public.bootstrap_cip_internal_fields(text) to service_role;

create or replace function public.taxonomy_internal_coverage(p_version text default '2020')
returns jsonb
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  with nodes as (
    select n.id, n.level_code, n.parent_id
    from external_classification_nodes n
    where n.system = 'cip' and n.version = p_version and n.is_active
  ),
  node_exact as (
    select nodes.id, nodes.level_code, nodes.parent_id,
           count(fec.id) as exact_count,
           min(fec.field_id::text)::uuid as field_id
    from nodes
    left join field_external_classifications fec
      on fec.classification_node_id = nodes.id and fec.mapping_type = 'exact_match'
    group by nodes.id, nodes.level_code, nodes.parent_id
  ),
  levels as (
    select level_code,
           count(*) as active_nodes,
           count(*) filter (where exact_count = 1) as exact_mapped,
           count(*) filter (where exact_count = 0) as unmapped,
           count(*) filter (where exact_count > 1) as ambiguous
    from node_exact
    group by level_code
  ),
  multi_node_fields as (
    select count(*) as n from (
      select fec.field_id
      from field_external_classifications fec
      join external_classification_nodes n on n.id = fec.classification_node_id
      where n.system = 'cip' and n.version = p_version and fec.mapping_type = 'exact_match'
      group by fec.field_id
      having count(*) > 1
    ) x
  ),
  kinds as (
    select f.field_kind, count(*) as n
    from fields f
    where f.is_active
    group by f.field_kind
  ),
  hierarchy as (
    select
      count(*) filter (where f.field_kind in ('subfield', 'program_classification') and f.parent_id is null)
        as nested_fields_without_parent,
      count(*) filter (where f.field_kind = 'subfield' and p.id is not null and p.field_kind <> 'broad_field')
        as subfields_under_wrong_kind,
      count(*) filter (where f.field_kind = 'program_classification' and p.id is not null and p.field_kind <> 'subfield')
        as programs_under_wrong_kind
    from fields f
    left join fields p on p.id = f.parent_id
    where f.is_active
  ),
  overrides as (
    select count(*) as n
    from node_exact c
    join node_exact pc on pc.id = c.parent_id
    join fields f on f.id = c.field_id
    where c.exact_count = 1 and pc.exact_count = 1
      and f.parent_id is distinct from pc.field_id
  )
  select jsonb_build_object(
    'system', 'cip',
    'version', p_version,
    'levels', coalesce((
      select jsonb_object_agg(level_code, jsonb_build_object(
        'active_nodes', active_nodes,
        'exact_mapped', exact_mapped,
        'unmapped', unmapped,
        'ambiguous', ambiguous))
      from levels), '{}'::jsonb),
    'active_fields_by_kind', coalesce((select jsonb_object_agg(field_kind, n) from kinds), '{}'::jsonb),
    'hierarchy', (
      select jsonb_build_object(
        'fields_matching_multiple_nodes', (select n from multi_node_fields),
        'nested_fields_without_parent', h.nested_fields_without_parent,
        'subfields_under_wrong_kind', h.subfields_under_wrong_kind,
        'programs_under_wrong_kind', h.programs_under_wrong_kind,
        'internal_parent_overrides', (select n from overrides))
      from hierarchy h),
    'complete', (
      exists (select 1 from nodes)
      and not exists (select 1 from node_exact where exact_count <> 1)
      and (select n from multi_node_fields) = 0
      and (select nested_fields_without_parent + subfields_under_wrong_kind + programs_under_wrong_kind
           from hierarchy) = 0
      and (select n from overrides) = 0
    )
  );
$$;

comment on function public.taxonomy_internal_coverage(text) is
  'Read-only internal hierarchy coverage for CIP-backed fields. Separate from external import '
  'counts: an imported CIP graph does not imply an internal hierarchy, and neither implies catalog '
  'completeness. Anonymous callers only see active fields (RLS).';

revoke all on function public.taxonomy_internal_coverage(text) from public;
grant execute on function public.taxonomy_internal_coverage(text) to anon, authenticated, service_role;

-- Children of a field are fetched by parent; keep that lookup indexed and ordered.
create index if not exists fields_parent_active_sort_idx
  on public.fields (parent_id, sort_order, name)
  where is_active;

-- Backfill whatever CIP 2020 graph is present. On a fresh database this only
-- reuses the seeded broad fields; after the official import it creates the
-- 466 subfields and 2,295 program fields.
select public.bootstrap_cip_internal_fields('2020');

-- Refresh planner statistics after the bulk backfill so lookups stay fast.
analyze public.fields;
analyze public.field_external_classifications;

INSERT INTO supabase_migrations.schema_migrations (version, name) VALUES ('20261015000000', 'cip_internal_field_bootstrap') ON CONFLICT (version) DO NOTHING;

-- --------------------------------------------------------------------
-- [46/96] Migration: 20261015010000_native_literacy_life_skills_fields.sql
-- --------------------------------------------------------------------
-- ============================================================================
-- LearningApp-authored literacy and practical-life field taxonomy.
--
-- These native fields organize the app's existing literacy, life-milestone,
-- and life-survival screens. They are not external academic classifications,
-- official standards, credentials, or statements of legal/medical requirements.
-- The six shipped sample programming concepts are linked to their existing
-- field through concept_fields; no new concept placements are inferred.
-- ============================================================================

insert into public.catalog_clusters (
  id, slug, title, description, emoji, accent_color, sort_order, is_active
)
values (
  gen_random_uuid(),
  'cluster_life_milestones',
  'Life Milestones & Survival Literacy',
  'Foundational literacy, civic milestones, and practical life-skills practice.',
  '🏛️',
  '#4338CA',
  13,
  true
)
on conflict (slug) do update
set is_active = true,
    sort_order = excluded.sort_order
where catalog_clusters.title = excluded.title;

do $$
begin
  if exists (
    select 1 from public.catalog_clusters
    where slug = 'cluster_life_milestones'
      and title <> 'Life Milestones & Survival Literacy'
  ) then
    raise exception 'Catalog cluster slug cluster_life_milestones is already used by a different cluster'
      using errcode = 'P0001';
  end if;
end
$$;

insert into public.fields (
  name, slug, description, field_kind, parent_id, sort_order, is_active, aliases, metadata
)
values
  (
    'Foundational Literacy',
    'foundational-literacy',
    'Learning areas for beginning reading, oral language, and adult basic-education reading practice.',
    'native_field',
    null,
    1,
    true,
    array['early literacy', 'basic reading'],
    jsonb_build_object('taxonomy_origin', 'learningapp_authored', 'source_surface', 'foundational_literacy_screen')
  ),
  (
    'Civic and Community Literacy',
    'civic-and-community-literacy',
    'Learning areas for civic knowledge and practical community navigation.',
    'native_field',
    null,
    2,
    true,
    array['civic learning', 'community navigation'],
    jsonb_build_object('taxonomy_origin', 'learningapp_authored', 'source_surface', 'life_milestones_screen')
  ),
  (
    'Practical Life Skills',
    'practical-life-skills',
    'Learning areas represented by LearningApp practical life-skills practice screens.',
    'native_field',
    null,
    3,
    true,
    array['survival literacy', 'everyday skills'],
    jsonb_build_object('taxonomy_origin', 'learningapp_authored', 'source_surface', 'life_domains_screen')
  )
on conflict (slug) do nothing;

insert into public.fields (
  name, slug, description, field_kind, parent_id, sort_order, is_active, aliases, metadata
)
select
  child.name,
  child.slug,
  child.description,
  'native_field',
  parent.id,
  child.sort_order,
  true,
  child.aliases,
  jsonb_build_object(
    'taxonomy_origin', 'learningapp_authored',
    'source_surface', child.source_surface
  )
from (
  values
    (
      'Phonics and Word Decoding',
      'phonics-and-word-decoding',
      'Beginning reading practice with letter-sound relationships and word decoding.',
      'foundational-literacy',
      1,
      array['phonics', 'decoding'],
      'foundational_literacy_screen'
    ),
    (
      'Supported Reading and Comprehension',
      'supported-reading-and-comprehension',
      'Supported reading practice using decodable stories and comprehension activities.',
      'foundational-literacy',
      2,
      array['reading fluency', 'reading comprehension', 'decodable stories'],
      'foundational_literacy_screen'
    ),
    (
      'Oral Language and Listening',
      'oral-language-and-listening',
      'Oral-first language and listening practice used alongside foundational literacy.',
      'foundational-literacy',
      3,
      array['oral language', 'listening'],
      'oral_diagnostic_widget'
    ),
    (
      'Adult Basic-Education Reading',
      'adult-basic-education-reading',
      'Reading practice bridging foundational literacy toward adult basic education.',
      'foundational-literacy',
      4,
      array['GED reading bridge', 'adult reading'],
      'ged_bridge_widget'
    ),
    (
      'Civics and Naturalization Preparation',
      'civics-and-naturalization-preparation',
      'Civic knowledge and oral interview practice represented by the citizenship milestone screen.',
      'civic-and-community-literacy',
      1,
      array['US civics', 'citizenship preparation'],
      'uscis_civics_simulator_widget'
    ),
    (
      'Driver Safety and License Preparation',
      'driver-safety-and-license-preparation',
      'Road-safety and driver-exam practice represented by the Florida driver milestone screen.',
      'civic-and-community-literacy',
      2,
      array['driver education', 'road safety'],
      'dmv_exam_simulator_widget'
    ),
    (
      'Cash and ATM Practice',
      'cash-and-atm-practice',
      'Practice recognizing US cash and using an ATM interface.',
      'practical-life-skills',
      1,
      array['cash literacy', 'ATM practice'],
      'currency_atm_widget'
    ),
    (
      'Health Literacy and First Aid',
      'health-literacy-and-first-aid',
      'Practice reading prescription labels and learning introductory first-aid actions.',
      'practical-life-skills',
      2,
      array['prescription labels', 'first aid'],
      'rx_and_first_aid_widget'
    ),
    (
      'Food Safety',
      'food-safety',
      'Food-handling and food-safety practice represented by the LearningApp food-safety screen.',
      'practical-life-skills',
      3,
      array['food handling'],
      'food_safety_widget'
    ),
    (
      'Workplace Safety',
      'workplace-safety',
      'Workplace-safety practice represented by the LearningApp workplace-safety screen.',
      'practical-life-skills',
      4,
      array['occupational safety'],
      'workplace_safety_widget'
    )
) as child(name, slug, description, parent_slug, sort_order, aliases, source_surface)
join public.fields parent on parent.slug = child.parent_slug
where parent.field_kind = 'native_field'
  and parent.metadata->>'taxonomy_origin' = 'learningapp_authored'
on conflict (slug) do nothing;

do $$
declare
  v_cluster_id uuid;
  v_field_id uuid;
  v_expected record;
begin
  -- Never adopt a same-slug field owned by another taxonomy source.
  if exists (
    select 1 from public.fields f
    where f.slug in (
      'foundational-literacy',
      'civic-and-community-literacy',
      'practical-life-skills',
      'phonics-and-word-decoding',
      'supported-reading-and-comprehension',
      'oral-language-and-listening',
      'adult-basic-education-reading',
      'civics-and-naturalization-preparation',
      'driver-safety-and-license-preparation',
      'cash-and-atm-practice',
      'health-literacy-and-first-aid',
      'food-safety',
      'workplace-safety'
    )
      and (
        f.field_kind <> 'native_field'
        or f.metadata->>'taxonomy_origin' is distinct from 'learningapp_authored'
      )
  ) then
    raise exception 'A native learning field slug is already owned by another taxonomy source'
      using errcode = 'P0001';
  end if;

  -- All native children must retain their declared parent, not just their name.
  for v_expected in
    select * from (values
      ('phonics-and-word-decoding', 'foundational-literacy'),
      ('supported-reading-and-comprehension', 'foundational-literacy'),
      ('oral-language-and-listening', 'foundational-literacy'),
      ('adult-basic-education-reading', 'foundational-literacy'),
      ('civics-and-naturalization-preparation', 'civic-and-community-literacy'),
      ('driver-safety-and-license-preparation', 'civic-and-community-literacy'),
      ('cash-and-atm-practice', 'practical-life-skills'),
      ('health-literacy-and-first-aid', 'practical-life-skills'),
      ('food-safety', 'practical-life-skills'),
      ('workplace-safety', 'practical-life-skills')
    ) expected(child_slug, parent_slug)
  loop
    if not exists (
      select 1
      from public.fields child
      join public.fields parent on parent.slug = v_expected.parent_slug
      where child.slug = v_expected.child_slug
        and child.parent_id = parent.id
        and child.is_active
    ) then
      raise exception 'Native learning field % is missing or has an invalid parent',
        v_expected.child_slug using errcode = 'P0001';
    end if;
  end loop;

  select id into strict v_cluster_id
  from public.catalog_clusters
  where slug = 'cluster_life_milestones';

  for v_expected in
    select * from (values
      ('foundational-literacy', 1),
      ('civic-and-community-literacy', 2),
      ('practical-life-skills', 3)
    ) expected(field_slug, sort_order)
  loop
    select id into strict v_field_id
    from public.fields
    where slug = v_expected.field_slug and is_active;

    insert into public.catalog_cluster_fields (cluster_id, field_id, sort_order)
    values (v_cluster_id, v_field_id, v_expected.sort_order)
      on conflict (cluster_id, field_id) do update
        set sort_order = excluded.sort_order;
    end loop;
end
$$;

-- Preserve the existing single-field placement while exposing the same links
-- through the canonical many-to-many concept_fields relation.
insert into public.concept_fields (concept_id, field_id, relationship)
select c.id, c.field_id, 'core_concept'
from public.knowledge_concepts c
where c.status = 'active'
  and c.field_id is not null
  and c.id in (
    'b1000000-0000-0000-0000-000000000001',
    'b1000000-0000-0000-0000-000000000002',
    'b1000000-0000-0000-0000-000000000003',
    'b1000000-0000-0000-0000-000000000004',
    'b1000000-0000-0000-0000-000000000005',
    'b1000000-0000-0000-0000-000000000006'
  )
on conflict (concept_id, field_id) do nothing;

INSERT INTO supabase_migrations.schema_migrations (version, name) VALUES ('20261015010000', 'native_literacy_life_skills_fields') ON CONFLICT (version) DO NOTHING;

-- --------------------------------------------------------------------
-- [47/96] Migration: 20261016000000_word_learning_w1_foundation.sql
-- --------------------------------------------------------------------
-- Word Learning W1: private word lists and skill-aware review.
-- Additive only; do not apply to hosted Supabase without explicit authorization.
create table if not exists public.word_lists (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  title text not null check (length(trim(title)) between 1 and 160),
  description text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists word_lists_user_updated_idx
  on public.word_lists(user_id, updated_at desc);

create table if not exists public.word_list_entries (
  id uuid primary key default gen_random_uuid(),
  list_id uuid not null references public.word_lists(id) on delete cascade,
  word text not null check (length(trim(word)) between 1 and 160),
  form_key text not null check (length(form_key) between 1 and 1000),
  locale text not null default 'en-US',
  entry_kind text not null default 'ordinary'
    check (entry_kind in ('ordinary', 'proper_name', 'custom')),
  case_policy text not null default 'ignore_case'
    check (case_policy in ('ignore_case', 'exact')),
  accepted_forms jsonb not null default '[]'::jsonb
    check (jsonb_typeof(accepted_forms) = 'array'),
  pronunciation_hint text,
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (list_id, form_key)
);

create index if not exists word_list_entries_order_idx
  on public.word_list_entries(list_id, sort_order, created_at);

alter table public.word_lists enable row level security;
alter table public.word_list_entries enable row level security;

-- Data API table grants are separate from RLS; anonymous Supabase users
-- also hold the authenticated Postgres role. Never grant writes to anon.
grant select, insert, update, delete on public.word_lists to authenticated;
grant select, insert, update, delete on public.word_list_entries to authenticated;

create policy word_lists_owner_only on public.word_lists
  for all to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

create policy word_list_entries_owner_only on public.word_list_entries
  for all to authenticated
  using (
    exists (select 1 from public.word_lists wl
      where wl.id = word_list_entries.list_id and wl.user_id = (select auth.uid()))
  )
  with check (
    exists (select 1 from public.word_lists wl
      where wl.id = word_list_entries.list_id and wl.user_id = (select auth.uid()))
  );

-- Existing review_items remains the single review scheduler.
-- A stable content_id such as 'word:v1:<form-key>:spelling' is shared
-- across lists; it is not a foreign key to a word_list_entries row.
alter table public.review_items
  drop constraint if exists review_items_content_type_check;
alter table public.review_items
  add constraint review_items_content_type_check
  check (content_type in ('term', 'question', 'concept', 'flashcard', 'word_skill'));

-- The Dart ReviewableItem serializer already emits 'metadata'. Earlier
-- stored SQL did not declare it. Add safely before W1 persists word reviews.
alter table public.review_items
  add column if not exists metadata jsonb not null default '{}'::jsonb;

