-- --------------------------------------------------------------------
-- [55/96] Migration: 20261024000000_eco_01_community_qa.sql
-- --------------------------------------------------------------------
-- =============================================================================
-- Migration 55: ECO-01 Community Q&A Baseline & Moderation Integration
-- Description:
--   Establishes the concept-scoped Community Q&A schema (community_questions,
--   community_answers, community_votes), maintaining strict domain separation
--   from assessment engine questions.
--   Enforces Phase 1 private engineering boundaries:
--     - Public UGC creation is restricted to administrators and curated seed FAQs.
--     - Authenticated learners can create draft or under-review questions/answers.
--     - Integrates with moderation_reports and submit_moderation_report RPC.
--     - Provides cast_community_vote atomic upvote RPC.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 1. Extend moderation_reports target_type check constraint
-- -----------------------------------------------------------------------------
alter table public.moderation_reports
  drop constraint if exists moderation_reports_target_type_check;

alter table public.moderation_reports
  add constraint moderation_reports_target_type_check
  check (target_type in (
    'course', 'lesson', 'study_set', 'word_list', 'curriculum',
    'resource', 'question', 'profile', 'community_question', 'community_answer'
  ));

-- -----------------------------------------------------------------------------
-- 2. Create Community Questions Table
-- -----------------------------------------------------------------------------
create table if not exists public.community_questions (
  id uuid primary key default gen_random_uuid(),
  author_id uuid references auth.users(id) on delete cascade not null,
  title text not null check (length(trim(title)) >= 5 and length(title) <= 200),
  body_markdown text not null check (length(trim(body_markdown)) >= 10 and length(body_markdown) <= 10000),
  status text not null default 'draft' check (status in ('draft', 'under_review', 'published', 'archived')),
  is_seeded boolean not null default false,
  concept_id text,
  target_id text,
  lesson_id uuid references public.lessons(id) on delete set null,
  cip_code text,
  view_count integer not null default 0 check (view_count >= 0),
  upvote_count integer not null default 0 check (upvote_count >= 0),
  answer_count integer not null default 0 check (answer_count >= 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- Indexes for Community Questions
create index if not exists idx_community_questions_status_created
  on public.community_questions (status, created_at desc);

create index if not exists idx_community_questions_concept
  on public.community_questions (concept_id, created_at desc)
  where concept_id is not null;

create index if not exists idx_community_questions_target
  on public.community_questions (target_id, created_at desc)
  where target_id is not null;

create index if not exists idx_community_questions_lesson
  on public.community_questions (lesson_id, created_at desc)
  where lesson_id is not null;

create index if not exists idx_community_questions_author
  on public.community_questions (author_id, created_at desc);

-- -----------------------------------------------------------------------------
-- 3. Create Community Answers Table
-- -----------------------------------------------------------------------------
create table if not exists public.community_answers (
  id uuid primary key default gen_random_uuid(),
  question_id uuid references public.community_questions(id) on delete cascade not null,
  author_id uuid references auth.users(id) on delete cascade not null,
  body_markdown text not null check (length(trim(body_markdown)) >= 10 and length(body_markdown) <= 20000),
  is_ai_generated boolean not null default false,
  ai_model_name text check (ai_model_name is null or (length(trim(ai_model_name)) > 0 and length(ai_model_name) <= 64)),
  is_accepted boolean not null default false,
  status text not null default 'published' check (status in ('draft', 'under_review', 'published', 'archived', 'flagged')),
  upvote_count integer not null default 0 check (upvote_count >= 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- Indexes for Community Answers
create index if not exists idx_community_answers_question_created
  on public.community_answers (question_id, created_at asc);

create index if not exists idx_community_answers_author
  on public.community_answers (author_id, created_at desc);

-- -----------------------------------------------------------------------------
-- 4. Create Community Votes Table
-- -----------------------------------------------------------------------------
create table if not exists public.community_votes (
  id uuid primary key default gen_random_uuid(),
  user_id uuid references auth.users(id) on delete cascade not null,
  target_type text not null check (target_type in ('question', 'answer')),
  target_id uuid not null,
  created_at timestamptz not null default now(),
  unique (user_id, target_type, target_id)
);

create index if not exists idx_community_votes_target
  on public.community_votes (target_type, target_id);

-- -----------------------------------------------------------------------------
-- 5. Trigger for Answer Count on Community Questions
-- -----------------------------------------------------------------------------
create or replace function public.handle_community_answer_count()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    if new.status = 'published' then
      update public.community_questions
         set answer_count = answer_count + 1,
             updated_at = now()
       where id = new.question_id;
    end if;
  elsif tg_op = 'UPDATE' then
    if old.status <> 'published' and new.status = 'published' then
      update public.community_questions
         set answer_count = answer_count + 1,
             updated_at = now()
       where id = new.question_id;
    elsif old.status = 'published' and new.status <> 'published' then
      update public.community_questions
         set answer_count = greatest(0, answer_count - 1),
             updated_at = now()
       where id = new.question_id;
    end if;
  elsif tg_op = 'DELETE' then
    if old.status = 'published' then
      update public.community_questions
         set answer_count = greatest(0, answer_count - 1),
             updated_at = now()
       where id = old.question_id;
    end if;
  end if;
  return null;
end;
$$;

drop trigger if exists trg_community_answer_count on public.community_answers;
create trigger trg_community_answer_count
  after insert or update of status or delete on public.community_answers
  for each row execute function public.handle_community_answer_count();

-- -----------------------------------------------------------------------------
-- 6. Atomic Upvoting RPC
-- -----------------------------------------------------------------------------
create or replace function public.cast_community_vote(
  p_target_type text,
  p_target_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid;
  v_exists boolean;
  v_voted boolean;
  v_new_count integer;
begin
  v_uid := auth.uid();
  if v_uid is null then
    raise exception 'Authentication required to vote' using errcode = '42501';
  end if;

  if p_target_type not in ('question', 'answer') then
    raise exception 'Invalid vote target_type: %', p_target_type using errcode = '22023';
  end if;

  -- Verify target existence and visibility
  if p_target_type = 'question' then
    select exists (
      select 1 from public.community_questions
       where id = p_target_id
         and (status = 'published' or author_id = v_uid or private.is_admin())
    ) into v_exists;
  else
    select exists (
      select 1 from public.community_answers
       where id = p_target_id
         and (status = 'published' or author_id = v_uid or private.is_admin())
    ) into v_exists;
  end if;

  if not v_exists then
    raise exception 'Target % does not exist or is inaccessible', p_target_id using errcode = 'P0002';
  end if;

  -- Transaction advisory lock per user & target
  perform pg_advisory_xact_lock(hashtext('vote_' || v_uid::text || '_' || p_target_id::text));

  select exists (
    select 1 from public.community_votes
     where user_id = v_uid
       and target_type = p_target_type
       and target_id = p_target_id
  ) into v_voted;

  if v_voted then
    -- Remove vote (toggle off)
    delete from public.community_votes
     where user_id = v_uid
       and target_type = p_target_type
       and target_id = p_target_id;

    if p_target_type = 'question' then
      update public.community_questions
         set upvote_count = greatest(0, upvote_count - 1),
             updated_at = now()
       where id = p_target_id
       returning upvote_count into v_new_count;
    else
      update public.community_answers
         set upvote_count = greatest(0, upvote_count - 1),
             updated_at = now()
       where id = p_target_id
       returning upvote_count into v_new_count;
    end if;

    return jsonb_build_object('voted', false, 'upvote_count', v_new_count);
  else
    -- Add vote (toggle on)
    insert into public.community_votes (user_id, target_type, target_id)
    values (v_uid, p_target_type, p_target_id);

    if p_target_type = 'question' then
      update public.community_questions
         set upvote_count = upvote_count + 1,
             updated_at = now()
       where id = p_target_id
       returning upvote_count into v_new_count;
    else
      update public.community_answers
         set upvote_count = upvote_count + 1,
             updated_at = now()
       where id = p_target_id
       returning upvote_count into v_new_count;
    end if;

    return jsonb_build_object('voted', true, 'upvote_count', v_new_count);
  end if;
end;
$$;

revoke all on function public.cast_community_vote(text, uuid) from public, anon;
grant execute on function public.cast_community_vote(text, uuid) to authenticated, service_role;

-- -----------------------------------------------------------------------------
-- 7. Update submit_moderation_report with community targets
-- -----------------------------------------------------------------------------
create or replace function public.submit_moderation_report(
  p_target_type text,
  p_target_id uuid,
  p_reason text,
  p_description text default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_caller_id uuid;
  v_report_id uuid;
  v_recent_reports_count integer;
begin
  v_caller_id := auth.uid();
  if v_caller_id is null then
    raise exception 'Authentication required to submit moderation reports' using errcode = '42501';
  end if;

  if p_reason not in ('spam', 'harassment', 'misinformation', 'copyright', 'minor_safety', 'inappropriate', 'other') then
    raise exception 'Invalid report reason: %', p_reason using errcode = '22023';
  end if;

  -- Validate target type, verify actual target existence AND caller visibility authorization
  case p_target_type
    when 'course' then
      if not exists (
        select 1 from public.courses
         where id = p_target_id
           and (is_public = true or user_id = v_caller_id)
      ) then
        raise exception 'Target course % does not exist or caller lacks access', p_target_id using errcode = 'P0002';
      end if;
    when 'lesson' then
      if not public.is_lesson_visible(p_target_id) then
        raise exception 'Target lesson % does not exist or caller lacks access', p_target_id using errcode = 'P0002';
      end if;
    when 'study_set' then
      if not exists (
        select 1 from public.study_sets
         where id = p_target_id
           and user_id = v_caller_id
      ) then
        raise exception 'Target study_set % does not exist or caller lacks access', p_target_id using errcode = 'P0002';
      end if;
    when 'word_list' then
      if not exists (
        select 1 from public.word_lists
         where id = p_target_id
           and user_id = v_caller_id
      ) then
        raise exception 'Target word_list % does not exist or caller lacks access', p_target_id using errcode = 'P0002';
      end if;
    when 'curriculum' then
      if not exists (
        select 1 from public.curriculum_nodes cn
          join public.target_versions v on v.id = cn.target_version_id
          join public.learning_targets t on t.id = v.target_id
         where cn.id = p_target_id
           and (
             (t.status = 'published' and t.is_public = true and v.status = 'published')
             or t.created_by = v_caller_id
           )
      ) then
        raise exception 'Target curriculum % does not exist or caller lacks access', p_target_id using errcode = 'P0002';
      end if;
    when 'resource' then
      if not exists (
        select 1 from public.user_curriculum_resources
         where id = p_target_id
           and user_id = v_caller_id
      ) then
        raise exception 'Target resource % does not exist or caller lacks access', p_target_id using errcode = 'P0002';
      end if;
    when 'question' then
      if not exists (
        select 1 from public.questions q
         where q.id = p_target_id
           and q.lesson_id is not null
           and public.is_lesson_visible(q.lesson_id)
      ) then
        raise exception 'Target question % does not exist or caller lacks access', p_target_id using errcode = 'P0002';
      end if;
    when 'community_question' then
      if not exists (
        select 1 from public.community_questions cq
         where cq.id = p_target_id
           and (cq.status = 'published' or cq.author_id = v_caller_id or private.is_admin())
      ) then
        raise exception 'Target community question % does not exist or caller lacks access', p_target_id using errcode = 'P0002';
      end if;
    when 'community_answer' then
      if not exists (
        select 1 from public.community_answers ca
         where ca.id = p_target_id
           and (ca.status = 'published' or ca.author_id = v_caller_id or private.is_admin())
      ) then
        raise exception 'Target community answer % does not exist or caller lacks access', p_target_id using errcode = 'P0002';
      end if;
    when 'profile' then
      raise exception 'Profile reporting is disabled until public profile launch' using errcode = '0A000';
    else
      raise exception 'Invalid target_type: %', p_target_type using errcode = '22023';
  end case;

  -- Transactional concurrency lock: serialize submissions per user to prevent concurrent rate limit bypass
  perform pg_advisory_xact_lock(hashtext('moderation_report_rate_limit'), hashtext(v_caller_id::text));

  -- Rate limit check: maximum 10 reports per hour per user
  select count(*)::integer into v_recent_reports_count
    from public.moderation_reports
   where reporter_id = v_caller_id
     and created_at > now() - interval '1 hour';

  if v_recent_reports_count >= 10 then
    raise exception 'Rate limit exceeded: too many moderation reports submitted. Please wait before submitting additional reports.' using errcode = 'P0004';
  end if;

  -- Deduplication check for active report on the same target
  if exists (
    select 1
      from public.moderation_reports
     where reporter_id = v_caller_id
       and target_type = p_target_type
       and target_id = p_target_id
       and status in ('pending', 'under_review')
  ) then
    raise exception 'Duplicate report: you already have an active report for this content.' using errcode = '23505';
  end if;

  insert into public.moderation_reports (
    reporter_id, target_type, target_id, reason, description, status
  ) values (
    v_caller_id, p_target_type, p_target_id, p_reason, p_description, 'pending'
  ) returning id into v_report_id;

  return v_report_id;
end;
$$;

revoke all on function public.submit_moderation_report(text, uuid, text, text) from public, anon;
grant execute on function public.submit_moderation_report(text, uuid, text, text) to authenticated, service_role;

-- -----------------------------------------------------------------------------
-- 8. Row Level Security & Defense-in-Depth Permissions
-- -----------------------------------------------------------------------------
alter table public.community_questions enable row level security;
alter table public.community_answers enable row level security;
alter table public.community_votes enable row level security;

-- Table-level grants: least privilege
revoke all on table public.community_questions from public, anon;
revoke all on table public.community_answers from public, anon;
revoke all on table public.community_votes from public, anon;

grant select on table public.community_questions to anon, authenticated;
grant insert, update, delete on table public.community_questions to authenticated;

grant select on table public.community_answers to anon, authenticated;
grant insert, update, delete on table public.community_answers to authenticated;

grant select on table public.community_votes to authenticated;
-- Direct writes to votes revoked: must use cast_community_vote RPC
revoke insert, update, delete on table public.community_votes from authenticated;

-- Policies for Community Questions
create policy community_questions_select_policy on public.community_questions
  for select
  using (status = 'published' or author_id = auth.uid() or private.is_admin());

create policy community_questions_insert_policy on public.community_questions
  for insert
  to authenticated
  with check (
    (author_id = auth.uid() and is_seeded = false and status in ('draft', 'under_review'))
    or private.is_admin()
  );

create policy community_questions_update_policy on public.community_questions
  for update
  to authenticated
  using (
    (author_id = auth.uid() and is_seeded = false and status in ('draft', 'under_review'))
    or private.is_admin()
  )
  with check (
    (author_id = auth.uid() and is_seeded = false and status in ('draft', 'under_review'))
    or private.is_admin()
  );

create policy community_questions_delete_policy on public.community_questions
  for delete
  to authenticated
  using (
    (author_id = auth.uid() and status = 'draft')
    or private.is_admin()
  );

-- Policies for Community Answers
create policy community_answers_select_policy on public.community_answers
  for select
  using (status = 'published' or author_id = auth.uid() or private.is_admin());

create policy community_answers_insert_policy on public.community_answers
  for insert
  to authenticated
  with check (
    (author_id = auth.uid() and status in ('draft', 'under_review'))
    or private.is_admin()
  );

create policy community_answers_update_policy on public.community_answers
  for update
  to authenticated
  using (
    (author_id = auth.uid() and status in ('draft', 'under_review'))
    or private.is_admin()
  )
  with check (
    (author_id = auth.uid() and status in ('draft', 'under_review'))
    or private.is_admin()
  );

create policy community_answers_delete_policy on public.community_answers
  for delete
  to authenticated
  using (
    (author_id = auth.uid() and status = 'draft')
    or private.is_admin()
  );

-- Policies for Community Votes
create policy community_votes_select_policy on public.community_votes
  for select
  to authenticated
  using (user_id = auth.uid() or private.is_admin());

INSERT INTO supabase_migrations.schema_migrations (version, name) VALUES ('20261024000000', 'eco_01_community_qa') ON CONFLICT (version) DO NOTHING;

-- --------------------------------------------------------------------
-- [56/96] Migration: 20261025000000_eco_01_community_hardening.sql
-- --------------------------------------------------------------------
-- =============================================================================
-- Migration 56: ECO-01 Community Q&A Access-Control & Counter Hardening
-- Description:
--   1. Separates anonymous public SELECT policies from authenticated author/admin
--      policies, eliminating 42501 execution errors on private.is_admin() for anon.
--   2. Enforces parent-question publication constraints on community_answers
--      select, upvoting, and moderation reporting.
--   3. Installs BEFORE UPDATE tamper-prevention triggers on community_questions
--      and community_answers preventing non-admins from mutating authoritative
--      counters (upvote_count, answer_count, view_count), is_seeded, is_accepted,
--      or timestamps.
--   4. Revokes public/anon execution on trigger functions.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 1. Hardened Community Questions SELECT Policies
-- -----------------------------------------------------------------------------
drop policy if exists community_questions_select_policy on public.community_questions;
drop policy if exists community_questions_public_select_policy on public.community_questions;
drop policy if exists community_questions_auth_select_policy on public.community_questions;

-- Public policy: accessible to anon, authenticated, and service_role without calling private.is_admin()
create policy community_questions_public_select_policy on public.community_questions
  for select
  to anon, authenticated, service_role
  using (status = 'published');

-- Authenticated policy: author access to own drafts & admin oversight
create policy community_questions_auth_select_policy on public.community_questions
  for select
  to authenticated
  using (author_id = auth.uid() or private.is_admin());

-- -----------------------------------------------------------------------------
-- 2. Hardened Community Answers SELECT Policies (Parent Visibility Enforced)
-- -----------------------------------------------------------------------------
drop policy if exists community_answers_select_policy on public.community_answers;
drop policy if exists community_answers_public_select_policy on public.community_answers;
drop policy if exists community_answers_auth_select_policy on public.community_answers;

-- Public policy: answer must be published AND parent question must be published
create policy community_answers_public_select_policy on public.community_answers
  for select
  to anon, authenticated, service_role
  using (
    status = 'published'
    and exists (
      select 1 from public.community_questions q
       where q.id = question_id
         and q.status = 'published'
    )
  );

-- Authenticated policy: author access if parent question is accessible to author or admin
create policy community_answers_auth_select_policy on public.community_answers
  for select
  to authenticated
  using (
    (author_id = auth.uid() and exists (
      select 1 from public.community_questions q
       where q.id = question_id
         and (q.status = 'published' or q.author_id = auth.uid() or private.is_admin())
    ))
    or private.is_admin()
  );

-- -----------------------------------------------------------------------------
-- 3. Tamper-Proofing Authoritative Counters & System Fields (BEFORE UPDATE Triggers)
-- -----------------------------------------------------------------------------
create or replace function public.prevent_community_question_tampering()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  -- Allow authorized internal updates initiated by trusted security-definer RPCs or triggers
  if current_setting('community.internal_counter_update', true) = 'true' then
    return new;
  end if;

  if not private.is_admin() then
    -- Non-admin authors cannot manipulate authoritative counters, seeded flag, or timestamps
    if new.upvote_count <> old.upvote_count or
       new.view_count <> old.view_count or
       new.answer_count <> old.answer_count or
       new.is_seeded <> old.is_seeded or
       new.created_at <> old.created_at or
       new.author_id <> old.author_id then
      raise exception 'Direct modification of system-maintained community question fields is forbidden'
        using errcode = '42501';
    end if;
    new.updated_at := now();
  end if;
  return new;
end;
$$;

drop trigger if exists trg_prevent_community_question_tampering on public.community_questions;
create trigger trg_prevent_community_question_tampering
  before update on public.community_questions
  for each row execute function public.prevent_community_question_tampering();

create or replace function public.prevent_community_answer_tampering()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  -- Allow authorized internal updates initiated by trusted security-definer RPCs or triggers
  if current_setting('community.internal_counter_update', true) = 'true' then
    return new;
  end if;

  if not private.is_admin() then
    -- Non-admin authors cannot manipulate upvote_count, is_accepted, question link, or timestamps
    if new.upvote_count <> old.upvote_count or
       new.is_accepted <> old.is_accepted or
       new.created_at <> old.created_at or
       new.author_id <> old.author_id or
       new.question_id <> old.question_id then
      raise exception 'Direct modification of system-maintained community answer fields is forbidden'
        using errcode = '42501';
    end if;
    new.updated_at := now();
  end if;
  return new;
end;
$$;

drop trigger if exists trg_prevent_community_answer_tampering on public.community_answers;
create trigger trg_prevent_community_answer_tampering
  before update on public.community_answers
  for each row execute function public.prevent_community_answer_tampering();

-- Authoritative answer count trigger function (sets internal_counter_update to allow question counter updates)
create or replace function public.handle_community_answer_count()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform set_config('community.internal_counter_update', 'true', true);

  if tg_op = 'INSERT' then
    if new.status = 'published' then
      update public.community_questions
         set answer_count = answer_count + 1,
             updated_at = now()
       where id = new.question_id;
    end if;
  elsif tg_op = 'UPDATE' then
    if old.status <> 'published' and new.status = 'published' then
      update public.community_questions
         set answer_count = answer_count + 1,
             updated_at = now()
       where id = new.question_id;
    elsif old.status = 'published' and new.status <> 'published' then
      update public.community_questions
         set answer_count = greatest(0, answer_count - 1),
             updated_at = now()
       where id = new.question_id;
    end if;
  elsif tg_op = 'DELETE' then
    if old.status = 'published' then
      update public.community_questions
         set answer_count = greatest(0, answer_count - 1),
             updated_at = now()
       where id = old.question_id;
    end if;
  end if;
  return null;
end;
$$;

-- Column privileges hardening (defense in depth for authenticated updates)
revoke update on table public.community_questions from authenticated;
grant update (title, body_markdown, status, concept_id, target_id, lesson_id, cip_code) on table public.community_questions to authenticated;

revoke update on table public.community_answers from authenticated;
grant update (body_markdown, status) on table public.community_answers to authenticated;

-- Revoke execute on trigger functions from public & anon
revoke all on function public.handle_community_answer_count() from public, anon;
revoke all on function public.prevent_community_question_tampering() from public, anon;
revoke all on function public.prevent_community_answer_tampering() from public, anon;

-- -----------------------------------------------------------------------------
-- 4. Update Atomic Upvoting RPC with Parent Question Visibility Check
-- -----------------------------------------------------------------------------
create or replace function public.cast_community_vote(
  p_target_type text,
  p_target_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid;
  v_exists boolean;
  v_voted boolean;
  v_new_count integer;
begin
  v_uid := auth.uid();
  if v_uid is null then
    raise exception 'Authentication required to vote' using errcode = '42501';
  end if;

  if p_target_type not in ('question', 'answer') then
    raise exception 'Invalid vote target_type: %', p_target_type using errcode = '22023';
  end if;

  -- Verify target existence and visibility (including parent question visibility for answers)
  if p_target_type = 'question' then
    select exists (
      select 1 from public.community_questions
       where id = p_target_id
         and (status = 'published' or author_id = v_uid or private.is_admin())
    ) into v_exists;
  else
    select exists (
      select 1 from public.community_answers a
       join public.community_questions q on q.id = a.question_id
       where a.id = p_target_id
         and (
           (a.status = 'published' and q.status = 'published')
           or (a.author_id = v_uid and (q.status = 'published' or q.author_id = v_uid or private.is_admin()))
           or private.is_admin()
         )
    ) into v_exists;
  end if;

  if not v_exists then
    raise exception 'Target % does not exist or is inaccessible', p_target_id using errcode = 'P0002';
  end if;

  -- Transaction advisory lock per user & target
  perform pg_advisory_xact_lock(hashtext('vote_' || v_uid::text || '_' || p_target_id::text));

  select exists (
    select 1 from public.community_votes
     where user_id = v_uid
       and target_type = p_target_type
       and target_id = p_target_id
  ) into v_voted;

  -- Set transaction-local internal counter flag so tamper trigger allows atomic RPC updates
  perform set_config('community.internal_counter_update', 'true', true);

  if v_voted then
    -- Remove vote (toggle off)
    delete from public.community_votes
     where user_id = v_uid
       and target_type = p_target_type
       and target_id = p_target_id;

    if p_target_type = 'question' then
      update public.community_questions
         set upvote_count = greatest(0, upvote_count - 1),
             updated_at = now()
       where id = p_target_id
       returning upvote_count into v_new_count;
    else
      update public.community_answers
         set upvote_count = greatest(0, upvote_count - 1),
             updated_at = now()
       where id = p_target_id
       returning upvote_count into v_new_count;
    end if;

    return jsonb_build_object('voted', false, 'upvote_count', v_new_count);
  else
    -- Add vote (toggle on)
    insert into public.community_votes (user_id, target_type, target_id)
    values (v_uid, p_target_type, p_target_id);

    if p_target_type = 'question' then
      update public.community_questions
         set upvote_count = upvote_count + 1,
             updated_at = now()
       where id = p_target_id
       returning upvote_count into v_new_count;
    else
      update public.community_answers
         set upvote_count = upvote_count + 1,
             updated_at = now()
       where id = p_target_id
       returning upvote_count into v_new_count;
    end if;

    return jsonb_build_object('voted', true, 'upvote_count', v_new_count);
  end if;
end;
$$;

revoke all on function public.cast_community_vote(text, uuid) from public, anon;
grant execute on function public.cast_community_vote(text, uuid) to authenticated, service_role;

-- -----------------------------------------------------------------------------
-- 5. Update Moderation Report RPC with Parent Question Visibility Check
-- -----------------------------------------------------------------------------
create or replace function public.submit_moderation_report(
  p_target_type text,
  p_target_id uuid,
  p_reason text,
  p_description text default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_caller_id uuid;
  v_report_id uuid;
  v_recent_reports_count integer;
begin
  v_caller_id := auth.uid();
  if v_caller_id is null then
    raise exception 'Authentication required to submit moderation reports' using errcode = '42501';
  end if;

  if p_reason not in ('spam', 'harassment', 'misinformation', 'copyright', 'minor_safety', 'inappropriate', 'other') then
    raise exception 'Invalid report reason: %', p_reason using errcode = '22023';
  end if;

  -- Validate target type, verify actual target existence AND caller visibility authorization
  case p_target_type
    when 'course' then
      if not exists (
        select 1 from public.courses
         where id = p_target_id
           and (is_public = true or user_id = v_caller_id)
      ) then
        raise exception 'Target course % does not exist or caller lacks access', p_target_id using errcode = 'P0002';
      end if;
    when 'lesson' then
      if not public.is_lesson_visible(p_target_id) then
        raise exception 'Target lesson % does not exist or caller lacks access', p_target_id using errcode = 'P0002';
      end if;
    when 'study_set' then
      if not exists (
        select 1 from public.study_sets
         where id = p_target_id
           and user_id = v_caller_id
      ) then
        raise exception 'Target study_set % does not exist or caller lacks access', p_target_id using errcode = 'P0002';
      end if;
    when 'word_list' then
      if not exists (
        select 1 from public.word_lists
         where id = p_target_id
           and user_id = v_caller_id
      ) then
        raise exception 'Target word_list % does not exist or caller lacks access', p_target_id using errcode = 'P0002';
      end if;
    when 'curriculum' then
      if not exists (
        select 1 from public.curriculum_nodes cn
          join public.target_versions v on v.id = cn.target_version_id
          join public.learning_targets t on t.id = v.target_id
         where cn.id = p_target_id
           and (
             (t.status = 'published' and t.is_public = true and v.status = 'published')
             or t.created_by = v_caller_id
           )
      ) then
        raise exception 'Target curriculum % does not exist or caller lacks access', p_target_id using errcode = 'P0002';
      end if;
    when 'resource' then
      if not exists (
        select 1 from public.user_curriculum_resources
         where id = p_target_id
           and user_id = v_caller_id
      ) then
        raise exception 'Target resource % does not exist or caller lacks access', p_target_id using errcode = 'P0002';
      end if;
    when 'question' then
      if not exists (
        select 1 from public.questions q
         where q.id = p_target_id
           and q.lesson_id is not null
           and public.is_lesson_visible(q.lesson_id)
      ) then
        raise exception 'Target question % does not exist or caller lacks access', p_target_id using errcode = 'P0002';
      end if;
    when 'community_question' then
      if not exists (
        select 1 from public.community_questions cq
         where cq.id = p_target_id
           and (cq.status = 'published' or cq.author_id = v_caller_id or private.is_admin())
      ) then
        raise exception 'Target community question % does not exist or caller lacks access', p_target_id using errcode = 'P0002';
      end if;
    when 'community_answer' then
      if not exists (
        select 1 from public.community_answers ca
         join public.community_questions cq on cq.id = ca.question_id
         where ca.id = p_target_id
           and (
             (ca.status = 'published' and cq.status = 'published')
             or (ca.author_id = v_caller_id and (cq.status = 'published' or cq.author_id = v_caller_id or private.is_admin()))
             or private.is_admin()
           )
      ) then
        raise exception 'Target community answer % does not exist or caller lacks access', p_target_id using errcode = 'P0002';
      end if;
    when 'profile' then
      raise exception 'Profile reporting is disabled until public profile launch' using errcode = '0A000';
    else
      raise exception 'Invalid target_type: %', p_target_type using errcode = '22023';
  end case;

  -- Transactional concurrency lock: serialize submissions per user to prevent concurrent rate limit bypass
  perform pg_advisory_xact_lock(hashtext('moderation_report_rate_limit'), hashtext(v_caller_id::text));

  -- Rate limit check: maximum 10 reports per hour per user
  select count(*)::integer into v_recent_reports_count
    from public.moderation_reports
   where reporter_id = v_caller_id
     and created_at > now() - interval '1 hour';

  if v_recent_reports_count >= 10 then
    raise exception 'Rate limit exceeded: too many moderation reports submitted. Please wait before submitting additional reports.' using errcode = 'P0004';
  end if;

  -- Deduplication check for active report on the same target
  if exists (
    select 1
      from public.moderation_reports
     where reporter_id = v_caller_id
       and target_type = p_target_type
       and target_id = p_target_id
       and status in ('pending', 'under_review')
  ) then
    raise exception 'Duplicate report: you already have an active report for this content.' using errcode = '23505';
  end if;

  insert into public.moderation_reports (
    reporter_id, target_type, target_id, reason, description, status
  ) values (
    v_caller_id, p_target_type, p_target_id, p_reason, p_description, 'pending'
  ) returning id into v_report_id;

  return v_report_id;
end;
$$;

revoke all on function public.submit_moderation_report(text, uuid, text, text) from public, anon;
grant execute on function public.submit_moderation_report(text, uuid, text, text) to authenticated, service_role;

INSERT INTO supabase_migrations.schema_migrations (version, name) VALUES ('20261025000000', 'eco_01_community_hardening') ON CONFLICT (version) DO NOTHING;

-- --------------------------------------------------------------------
-- [57/96] Migration: 20261026000000_eco_01_insert_hardening.sql
-- --------------------------------------------------------------------
-- =============================================================================
-- Migration 57: ECO-01 Community Q&A INSERT Integrity & Trigger ACL Hardening
-- Description:
--   1. Restricts column-level INSERT privileges on public.community_questions
--      and public.community_answers to genuinely authorable fields. Excludes
--      system-maintained counters (upvote_count, answer_count, view_count)
--      and audit timestamps (created_at, updated_at) from client write access.
--   2. Extends tamper-prevention triggers to BEFORE INSERT OR UPDATE, enforcing
--      clean initial states and server-controlled timestamps even for privileged sessions.
--   3. Hardens RLS WITH CHECK expressions on INSERT to disallow non-clean counter
--      or acceptance states for non-admins.
--   4. Revokes explicit authenticated EXECUTE grants from all community trigger functions.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 1. Column-Level INSERT Privilege Restrictions
-- -----------------------------------------------------------------------------
-- Questions: authenticated authors can specify content, seeding, and taxonomy fields.
-- Counters (upvote_count, view_count, answer_count) and audit timestamps are revoked.
revoke insert on table public.community_questions from authenticated;
grant insert (id, author_id, title, body_markdown, status, is_seeded, concept_id, target_id, lesson_id, cip_code)
  on table public.community_questions to authenticated;

-- Answers: authenticated authors can specify content and acceptance/provenance fields.
-- Counters (upvote_count) and audit timestamps are revoked.
revoke insert on table public.community_answers from authenticated;
grant insert (id, question_id, author_id, body_markdown, is_ai_generated, is_accepted, status)
  on table public.community_answers to authenticated;

-- -----------------------------------------------------------------------------
-- 2. Hardened RLS INSERT Policies (Defense-in-Depth)
-- -----------------------------------------------------------------------------
drop policy if exists community_questions_insert_policy on public.community_questions;
create policy community_questions_insert_policy on public.community_questions
  for insert
  to authenticated
  with check (
    (
      author_id = auth.uid()
      and is_seeded = false
      and status in ('draft', 'under_review')
      and upvote_count = 0
      and answer_count = 0
      and view_count = 0
    )
    or private.is_admin()
  );

drop policy if exists community_answers_insert_policy on public.community_answers;
create policy community_answers_insert_policy on public.community_answers
  for insert
  to authenticated
  with check (
    (
      author_id = auth.uid()
      and status in ('draft', 'under_review')
      and is_accepted = false
      and is_ai_generated = false
      and upvote_count = 0
    )
    or private.is_admin()
  );

-- -----------------------------------------------------------------------------
-- 3. Extend Tamper-Proofing Triggers to BEFORE INSERT OR UPDATE
-- -----------------------------------------------------------------------------
create or replace function public.prevent_community_question_tampering()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  -- Allow authorized internal updates initiated by trusted security-definer RPCs or triggers
  if current_setting('community.internal_counter_update', true) = 'true' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if not private.is_admin() then
      if new.upvote_count <> 0 or
         new.view_count <> 0 or
         new.answer_count <> 0 or
         new.is_seeded <> false then
        raise exception 'Direct modification of system-maintained community question fields is forbidden'
          using errcode = '42501';
      end if;
      new.created_at := now();
      new.updated_at := now();
    end if;
    return new;
  end if;

  if tg_op = 'UPDATE' then
    if not private.is_admin() then
      -- Non-admin authors cannot manipulate authoritative counters, seeded flag, or timestamps
      if new.upvote_count <> old.upvote_count or
         new.view_count <> old.view_count or
         new.answer_count <> old.answer_count or
         new.is_seeded <> old.is_seeded or
         new.created_at <> old.created_at or
         new.author_id <> old.author_id then
        raise exception 'Direct modification of system-maintained community question fields is forbidden'
          using errcode = '42501';
      end if;
      new.updated_at := now();
    end if;
    return new;
  end if;

  return new;
end;
$$;

drop trigger if exists trg_prevent_community_question_tampering on public.community_questions;
create trigger trg_prevent_community_question_tampering
  before insert or update on public.community_questions
  for each row execute function public.prevent_community_question_tampering();

create or replace function public.prevent_community_answer_tampering()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  -- Allow authorized internal updates initiated by trusted security-definer RPCs or triggers
  if current_setting('community.internal_counter_update', true) = 'true' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if not private.is_admin() then
      if new.upvote_count <> 0 or
         new.is_accepted <> false or
         new.is_ai_generated <> false then
        raise exception 'Direct modification of system-maintained community answer fields is forbidden'
          using errcode = '42501';
      end if;
      new.created_at := now();
      new.updated_at := now();
    end if;
    return new;
  end if;

  if tg_op = 'UPDATE' then
    if not private.is_admin() then
      -- Non-admin authors cannot manipulate upvote_count, is_accepted, question link, or timestamps
      if new.upvote_count <> old.upvote_count or
         new.is_accepted <> old.is_accepted or
         new.created_at <> old.created_at or
         new.author_id <> old.author_id or
         new.question_id <> old.question_id then
        raise exception 'Direct modification of system-maintained community answer fields is forbidden'
          using errcode = '42501';
      end if;
      new.updated_at := now();
    end if;
    return new;
  end if;

  return new;
end;
$$;

drop trigger if exists trg_prevent_community_answer_tampering on public.community_answers;
create trigger trg_prevent_community_answer_tampering
  before insert or update on public.community_answers
  for each row execute function public.prevent_community_answer_tampering();

-- -----------------------------------------------------------------------------
-- 4. Revoke Authenticated EXECUTE on All Community Trigger Functions
-- -----------------------------------------------------------------------------
revoke all on function public.handle_community_answer_count() from public, anon, authenticated;
revoke all on function public.prevent_community_question_tampering() from public, anon, authenticated;
revoke all on function public.prevent_community_answer_tampering() from public, anon, authenticated;

INSERT INTO supabase_migrations.schema_migrations (version, name) VALUES ('20261026000000', 'eco_01_insert_hardening') ON CONFLICT (version) DO NOTHING;

-- --------------------------------------------------------------------
-- [58/96] Migration: 20261027000000_eco_02_moderator_review_workflow.sql
-- --------------------------------------------------------------------
-- =============================================================================
-- Migration 58: ECO-02 Pilot FAQ Seeding & Review Workflow
-- Description:
--   1. Implements Moderator Review RPCs:
--      - public.review_community_question: review, publish, reject, or archive queued questions.
--      - public.review_community_answer: review, publish, reject, or archive queued answers.
--      - public.accept_community_answer: accept an answer (restricted to question author or moderator).
--   2. Extends community RLS policies so that moderators (private.is_moderator())
--      can view questions and answers under review.
--   3. Provides idempotent public.seed_pilot_community_faqs RPC to seed reference
--      pilot FAQs with accepted answers across Literacy, Workplace Safety, and Florida Licensure.
--   4. Safely calls seeding only when an author is present in auth.users (preserving clean-slate CI).
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 1. Extend RLS SELECT Policies to Permit Moderator Access
-- -----------------------------------------------------------------------------
drop policy if exists community_questions_auth_select_policy on public.community_questions;
create policy community_questions_auth_select_policy on public.community_questions
  for select
  to authenticated
  using (author_id = auth.uid() or private.is_moderator());

drop policy if exists community_answers_auth_select_policy on public.community_answers;
create policy community_answers_auth_select_policy on public.community_answers
  for select
  to authenticated
  using (
    (author_id = auth.uid() and exists (
      select 1 from public.community_questions q
       where q.id = question_id
         and (q.status = 'published' or q.author_id = auth.uid() or private.is_moderator())
    ))
    or private.is_moderator()
  );

-- -----------------------------------------------------------------------------
-- 2. Question Review RPC (review_community_question)
-- -----------------------------------------------------------------------------
create or replace function public.review_community_question(
  p_question_id uuid,
  p_action text,
  p_notes text default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_caller_id uuid;
  v_current_status text;
  v_new_status text;
begin
  v_caller_id := auth.uid();
  if v_caller_id is null or not private.is_moderator() then
    raise exception 'Access denied: caller does not possess moderator privileges'
      using errcode = '42501';
  end if;

  if p_action not in ('publish', 'reject', 'archive') then
    raise exception 'Invalid review action: %', p_action
      using errcode = '22023';
  end if;

  select status into v_current_status
    from public.community_questions
   where id = p_question_id
     for update;

  if not found then
    raise exception 'Question % not found', p_question_id
      using errcode = 'P0002';
  end if;

  v_new_status := case
    when p_action = 'publish' then 'published'
    when p_action = 'reject' then 'archived'
    when p_action = 'archive' then 'archived'
  end;

  -- Allow internal modification of status and updated_at
  perform set_config('community.internal_counter_update', 'true', true);

  update public.community_questions
     set status = v_new_status,
         updated_at = now()
   where id = p_question_id;

  return jsonb_build_object(
    'success', true,
    'question_id', p_question_id,
    'action', p_action,
    'previous_status', v_current_status,
    'status', v_new_status,
    'notes', p_notes
  );
end;
$$;

revoke all on function public.review_community_question(uuid, text, text) from public, anon;
grant execute on function public.review_community_question(uuid, text, text) to authenticated, service_role;

-- -----------------------------------------------------------------------------
-- 3. Answer Review RPC (review_community_answer)
-- -----------------------------------------------------------------------------
create or replace function public.review_community_answer(
  p_answer_id uuid,
  p_action text,
  p_notes text default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_caller_id uuid;
  v_answer record;
  v_parent_status text;
  v_new_status text;
begin
  v_caller_id := auth.uid();
  if v_caller_id is null or not private.is_moderator() then
    raise exception 'Access denied: caller does not possess moderator privileges'
      using errcode = '42501';
  end if;

  if p_action not in ('publish', 'reject', 'archive', 'flag') then
    raise exception 'Invalid review action: %', p_action
      using errcode = '22023';
  end if;

  select * into v_answer
    from public.community_answers
   where id = p_answer_id
     for update;

  if not found then
    raise exception 'Answer % not found', p_answer_id
      using errcode = 'P0002';
  end if;

  if p_action = 'publish' then
    select status into v_parent_status
      from public.community_questions
     where id = v_answer.question_id;

    if v_parent_status <> 'published' then
      raise exception 'Cannot publish answer for non-published parent question'
        using errcode = '22000';
    end if;
    v_new_status := 'published';
  elsif p_action = 'reject' or p_action = 'archive' then
    v_new_status := 'archived';
  elsif p_action = 'flag' then
    v_new_status := 'flagged';
  end if;

  perform set_config('community.internal_counter_update', 'true', true);

  update public.community_answers
     set status = v_new_status,
         updated_at = now()
   where id = p_answer_id;

  return jsonb_build_object(
    'success', true,
    'answer_id', p_answer_id,
    'action', p_action,
    'status', v_new_status,
    'notes', p_notes
  );
end;
$$;

revoke all on function public.review_community_answer(uuid, text, text) from public, anon;
grant execute on function public.review_community_answer(uuid, text, text) to authenticated, service_role;

-- -----------------------------------------------------------------------------
-- 4. Answer Acceptance RPC (accept_community_answer)
-- -----------------------------------------------------------------------------
create or replace function public.accept_community_answer(
  p_answer_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_caller_id uuid;
  v_answer record;
  v_question record;
begin
  v_caller_id := auth.uid();
  if v_caller_id is null then
    raise exception 'Authentication required'
      using errcode = '42501';
  end if;

  select * into v_answer
    from public.community_answers
   where id = p_answer_id
     for update;

  if not found then
    raise exception 'Answer % not found', p_answer_id
      using errcode = 'P0002';
  end if;

  select * into v_question
    from public.community_questions
   where id = v_answer.question_id
     for update;

  if not found then
    raise exception 'Parent question not found'
      using errcode = 'P0002';
  end if;

  -- Caller must be question author OR a moderator/admin
  if v_question.author_id <> v_caller_id and not private.is_moderator() then
    raise exception 'Only the question author or a moderator may accept an answer'
      using errcode = '42501';
  end if;

  if v_answer.status <> 'published' or v_question.status <> 'published' then
    raise exception 'Only published answers to published questions can be accepted'
      using errcode = '22000';
  end if;

  perform set_config('community.internal_counter_update', 'true', true);

  -- Unaccept any previously accepted answers for this question
  update public.community_answers
     set is_accepted = false,
         updated_at = now()
   where question_id = v_answer.question_id
     and id <> p_answer_id
     and is_accepted = true;

  -- Accept target answer
  update public.community_answers
     set is_accepted = true,
         updated_at = now()
   where id = p_answer_id;

  return jsonb_build_object(
    'success', true,
    'answer_id', p_answer_id,
    'question_id', v_answer.question_id,
    'is_accepted', true
  );
end;
$$;

revoke all on function public.accept_community_answer(uuid) from public, anon;
grant execute on function public.accept_community_answer(uuid) to authenticated, service_role;

-- -----------------------------------------------------------------------------
-- 5. Seed Pilot FAQs RPC (seed_pilot_community_faqs)
-- -----------------------------------------------------------------------------
create or replace function public.seed_pilot_community_faqs(p_author_id uuid default null)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_author_id uuid;
  v_count integer := 0;
  v_q_id uuid;
  v_seed record;
begin
  -- Resolve author id
  if p_author_id is not null then
    v_author_id := p_author_id;
  else
    select user_id into v_author_id
      from public.moderation_roles
     where role = 'admin'
     limit 1;
  end if;

  if v_author_id is null then
    return 0;
  end if;

  -- Check existence in auth.users
  if not exists (select 1 from auth.users where id = v_author_id) then
    return 0;
  end if;

  perform set_config('community.internal_counter_update', 'true', true);

  -- 18 Authoritative Pilot FAQs across Literacy, Workplace Safety, and Florida Licensure
  for v_seed in (
    select
      'What is the CVC pattern in phonics and how is it taught?' as title,
      'What does the CVC acronym stand for, and why is it considered the foundational pattern in early phonics instruction?' as body,
      'literacy.cvc.basics' as concept_id,
      'CVC stands for Consonant-Vowel-Consonant (e.g., ''cat'', ''pin'', ''sun'', ''bed'', ''fog''). In CVC words, the single vowel in the middle always makes its short vowel sound. Blending these three distinct phonemes (onset, vowel nucleus, and coda) is the core initial milestone in phonemic decoding before learners progress to consonant blends, vowel teams, or silent-e patterns.' as answer_body
    union all select
      'How do sight words differ from decodable words?',
      'Why are high-frequency words often called sight words, and should learners sound them out or memorize them?',
      'literacy.sight_words',
      'Decodable words follow transparent phonetic rules that learners can sound out letter by letter using taught grapheme-phoneme correspondences. High-frequency ''sight words'' (such as ''the'', ''was'', ''said'', ''of'') often contain irregular or advanced spelling patterns. Modern evidence-based reading instruction recommends ''orthographic mapping''—pointing out the regular sound parts while explicitly highlighting the irregular ''heart'' sounds, enabling instantaneous word retrieval without pure rote memorization.'
    union all select
      'What is the difference between continuous blending and segmented blending?',
      'When teaching a struggling reader to blend letter sounds into words, what is continuous blending and why is it recommended?',
      'literacy.phonics.blending',
      'Segmented blending pauses between each individual sound (e.g., /s/ ... /a/ ... /t/), which places heavy demands on working memory. Continuous blending (also called additive or connected phonation) stretches continuous sounds smoothly into one another without pausing (e.g., ''ssssaaaat''). Research indicates continuous blending significantly reduces memory drop-off and error rates for early and struggling readers.'
    union all select
      'What is a consonant digraph versus a consonant blend?',
      'What distinguishes consonant digraphs like ''sh'' and ''th'' from consonant blends like ''bl'' and ''st''?',
      'literacy.digraphs',
      'A consonant digraph consists of two letters that team together to represent a single, unique phoneme (e.g., ''sh'' in ''ship'', ''th'' in ''thin'', ''ch'' in ''chin'', ''ck'' in ''duck''). In contrast, a consonant blend consists of two or three consonants where each letter retains its own distinct individual sound that can still be heard when spoken together (e.g., /b/ and /l/ in ''black'', /s/ and /t/ in ''stop'').'
    union all select
      'How does onset-rime awareness support phonological development?',
      'Why is dividing words into onset and rime beneficial for pre-readers and developing spellers?',
      'literacy.rhyming',
      'In phonological awareness, the ''onset'' is the initial consonant sound before the vowel (e.g., /c/ in ''cat''), and the ''rime'' is the vowel and any subsequent consonants (e.g., ''-at''). Recognizing common rimes (word families like ''-at'', ''-in'', ''-op'') accelerates reading fluency because learners can rapidly map and read dozens of new words by simply swapping the onset consonant.'
    union all select
      'How does the split vowel digraph or silent-e rule function?',
      'What is the phonetic mechanic behind the final silent-e in words like ''cake'', ''ride'', and ''rope''?',
      'literacy.silent_e',
      'The final ''e'' in CVCe words (Consonant-Vowel-Consonant-e) is historically a marker indicating that the preceding vowel sound is ''long'' (it pronounces its alphabet name). Linguistically, this is a split vowel digraph (e.g., a_e, i_e, o_e, u_e). Teaching this rule helps readers transition from short vowel decoding (''cap'' to ''cape'', ''pin'' to ''pine'').'
    union all select
      'What are the standard OSHA requirements for Personal Protective Equipment (PPE)?',
      'Under OSHA general industry guidelines, when must an employer provide PPE and what gear is mandated?',
      'workplace.safety.ppe',
      'Under OSHA 29 CFR 1910 Subpart I, employers must assess the workplace to identify hazards that necessitate PPE. When engineering or administrative controls are insufficient, employers must provide appropriate PPE at no cost to workers. Standard general industry PPE includes ANSI Z87.1 approved eye protection, hard hats conforming to ANSI Z89.1, puncture- and impact-resistant safety footwear (ASTM F2413), and hearing protection in zones exceeding 85 dBA TWA.'
    union all select
      'What information must be included in a Safety Data Sheet (SDS) under GHS?',
      'How is an OSHA Hazard Communication Safety Data Sheet structured, and which sections are critical for immediate chemical spills?',
      'workplace.safety.hazcom',
      'OSHA''s Hazard Communication Standard (29 CFR 1910.1200) aligns with the Globally Harmonized System (GHS) and mandates a standardized 16-section Safety Data Sheet (SDS). For immediate emergencies, Section 1 (Identification), Section 2 (Hazard Identification with pictograms and signal words), Section 4 (First-Aid Measures), Section 5 (Fire-Fighting Measures), and Section 6 (Accidental Release Measures) provide the essential rapid-response instructions.'
    union all select
      'What does the PASS acronym stand for when operating a fire extinguisher?',
      'What is the proper procedural technique for safely deploying a portable workplace fire extinguisher?',
      'workplace.safety.fire',
      'The PASS technique describes the 4-step sequence for operating a portable fire extinguisher: 1) Pull the pin to break the tamper seal. 2) Aim low, pointing the nozzle or hose at the base of the fire, not the flames. 3) Squeeze the handle or lever slowly to discharge the extinguishing agent. 4) Sweep the nozzle from side to side across the base of the fuel until the flames are fully extinguished.'
    union all select
      'What is Lockout/Tagout (LOTO) and why is it mandatory during machinery maintenance?',
      'Under OSHA standard 29 CFR 1910.147, what is the primary purpose of hazardous energy control procedures?',
      'workplace.safety.lockout_tagout',
      'Lockout/Tagout (LOTO) establishes minimum performance requirements to prevent unexpected energization, startup, or release of stored energy during servicing or maintenance of machines and equipment. A designated lockout device physically holds the energy-isolating mechanism in a safe position, while a standardized tagout warning tag indicates the equipment must not be energized until the authorized technician removes the lock.'
    union all select
      'What are the primary OSHA walking-working surface requirements for housekeeping?',
      'How should walkways, aisles, and floors be maintained in commercial and industrial workspaces to prevent fall injuries?',
      'workplace.safety.slips_trips_falls',
      'Under OSHA 29 CFR 1910.22, all places of employment, passageways, storerooms, and service rooms must be kept clean, orderly, and in a sanitary condition. Floors must be kept dry and clear of debris, electrical cords, and protrusions. Where wet processes are used, employers must provide adequate drainage, non-slip mats, or false floors to maintain traction.'
    union all select
      'What core components are required in an OSHA Emergency Action Plan (EAP)?',
      'When an employer is required to have an Emergency Action Plan under 29 CFR 1910.38, what procedures must be documented?',
      'workplace.safety.emergency_action',
      'An OSHA Emergency Action Plan must document: 1) Procedures for reporting fires and other emergencies; 2) Emergency evacuation procedures, including designated exit route assignments; 3) Procedures for employees who remain to operate critical operations before evacuation; 4) Procedures to account for all employees after evacuation; 5) Rescue and medical duties for assigned workers; and 6) Preferred names or job titles of individuals to contact for further information.'
    union all select
      'What are the continuing education (CE) requirements for Florida Cosmetology license renewal?',
      'How many continuing education hours are required by the Florida Board of Cosmetology for biennial license renewal?',
      'licensure.cosmetology.ce',
      'Under Florida Administrative Code Rule 61G5-20, licensed cosmetologists must complete 10 hours of board-approved continuing education prior to their biennial license expiration (October 31st of even-numbered years). The 10 hours must include: 1 hour of HIV/AIDS education, 3 hours of sanitation and sterilization, 1 hour of OSHA/chemical hazards, 1 hour of workers'' compensation, 2 hours of Florida cosmetology laws and rules, and 2 hours of general cosmetology topics.'
    union all select
      'What are the work and in-service training requirements to renew a Florida CNA certificate?',
      'How does a Certified Nursing Assistant maintain an active license with the Florida Board of Nursing?',
      'licensure.cna.renewal',
      'Under Florida Statutes Chapter 464 and Rule 64B9-15, a Certified Nursing Assistant (CNA) license renews biennially. To qualify for active renewal, the CNA must perform nursing-related services for monetary compensation within the 24-month renewal cycle and complete a minimum of 24 hours of in-service training (12 hours per calendar year) covering mandatory topics such as medical error prevention, infection control, CPR, patient rights, and HIPAA compliance.'
    union all select
      'What is the first-renewal post-licensing requirement for Florida Real Estate Sales Associates?',
      'What coursework must a newly licensed Florida real estate sales associate complete before their initial license expiration date?',
      'licensure.real_estate.post_licensing',
      'Florida Real Estate Commission (FREC) Rule 61J2-3 requires all newly licensed sales associates to satisfactorily complete a commission-approved 45-hour post-licensing education course prior to their first biennial license expiration date. There is no grace period in Florida: failure to complete the 45-hour post-licensing course before the expiration date renders the license null and void by operation of law.'
    union all select
      'How does license reciprocity work for Florida Certified Electrical Contractors?',
      'Does the Florida Electrical Contractors'' Licensing Board (ECLB) grant reciprocal recognition to electrical licenses from other states?',
      'licensure.electrical.reciprocity',
      'The Florida Electrical Contractors'' Licensing Board (ECLB) offers licensure by endorsement to applicants who hold a valid, current electrical contractor license from jurisdictions with substantially similar examination and experience standards. Florida currently maintains formal endorsement agreements with select states (including Georgia, North Carolina, and California). Endorsement applicants must still satisfy Florida financial responsibility requirements, criminal background checks, and submit proof of active workers'' compensation coverage.'
    union all select
      'What training hours are required for the Florida Class D Security Officer License?',
      'Under Florida Chapter 493, what curriculum and hours must an applicant complete to earn a Class D Security Officer License?',
      'licensure.security_guard.class_d',
      'Under Florida Statutes Chapter 493, applicants for the Class ''D'' Security Officer License must successfully complete a 40-hour training curriculum at a licensed security officer school. The training covers Florida law, security officer conduct, observation techniques, report writing, emergency procedures, terrorism awareness, and first aid. Once completed, the license is issued by the Florida Department of Agriculture and Consumer Services (FDACS) and is valid for two years.'
    union all select
      'What experience qualifications are required for the Florida Certified General Contractor (CGC) exam?',
      'What combination of education and four years of commercial construction experience is required by the Florida CILB?',
      'licensure.construction.general_contractor',
      'The Florida Construction Industry Licensing Board (CILB) requires applicants for the Certified General Contractor (CGC) license to demonstrate four years of proven commercial construction experience. Acceptable combinations include: 1) A 4-year accredited degree in construction or engineering plus 1 year of hands-on supervisory experience; 2) 3 years of accredited college credits plus 1 year of experience; or 3) 4 years of active field experience, with at least 1 year acting as a foreman or supervisor on commercial structures exceeding four stories.'
  ) loop
    -- Check if question already exists
    select id into v_q_id
      from public.community_questions
     where title = v_seed.title;

    if v_q_id is null then
      insert into public.community_questions (
        author_id, title, body_markdown, status, is_seeded,
        concept_id, view_count, upvote_count, answer_count
      ) values (
        v_author_id, v_seed.title, v_seed.body, 'published', true,
        v_seed.concept_id, 0, 0, 1
      ) returning id into v_q_id;

      insert into public.community_answers (
        question_id, author_id, body_markdown, is_ai_generated,
        is_accepted, status, upvote_count
      ) values (
        v_q_id, v_author_id, v_seed.answer_body, false,
        true, 'published', 0
      );

      v_count := v_count + 1;
    end if;
  end loop;

  return v_count;
end;
$$;

revoke all on function public.seed_pilot_community_faqs(uuid) from public, anon;
grant execute on function public.seed_pilot_community_faqs(uuid) to authenticated, service_role;

-- -----------------------------------------------------------------------------
-- 6. Safe Conditional Immediate Seeding (Preserves Clean-Slate CI)
-- -----------------------------------------------------------------------------
do $$
declare
  v_admin_id uuid;
  v_seeded_count integer;
begin
  select user_id into v_admin_id
    from public.moderation_roles
   where role = 'admin'
   limit 1;

  if v_admin_id is not null and exists (select 1 from auth.users where id = v_admin_id) then
    v_seeded_count := public.seed_pilot_community_faqs(v_admin_id);
    raise notice 'ECO-02: Successfully seeded % pilot FAQs with accepted answers.', v_seeded_count;
  else
    raise notice 'ECO-02: Skipping immediate FAQ seeding (no admin user found in auth.users). Seed via tool/seed_pilot_community_faqs.dart after user provisioning.';
  end if;
end;
$$;

INSERT INTO supabase_migrations.schema_migrations (version, name) VALUES ('20261027000000', 'eco_02_moderator_review_workflow') ON CONFLICT (version) DO NOTHING;

-- --------------------------------------------------------------------
-- [59/96] Migration: 20261028000000_eco_02_hardening.sql
-- --------------------------------------------------------------------
-- ECO-02 Hardening & Integrity Fixes
-- Migration Version: 20261028000000
-- 1. Restrict seed_pilot_community_faqs to verified administrators (private.is_admin())
-- 2. Correct answer_count trigger double-increment and repair existing counters
-- 3. Correct Florida DBPR licensure facts (Cosmetology, Electrical Endorsement, General Contractor)
-- 4. Server-enforce Public UGC Launch Gate (community_config.public_ugc_enabled)
-- 5. Introduce durable community review decision audit table (community_review_audit)

-- -----------------------------------------------------------------------------
-- 1. Community Configuration & Public UGC Launch Gate
-- -----------------------------------------------------------------------------
create table if not exists public.community_config (
  key text primary key,
  value boolean not null default false,
  description text,
  updated_at timestamptz not null default now(),
  updated_by uuid references auth.users(id) on delete set null
);

alter table public.community_config enable row level security;

drop policy if exists community_config_select_policy on public.community_config;
create policy community_config_select_policy on public.community_config
  for select to authenticated, anon
  using (true);

revoke all on table public.community_config from public, anon;
grant select on table public.community_config to anon, authenticated;
grant all on table public.community_config to service_role;

insert into public.community_config (key, value, description)
values (
  'public_ugc_enabled',
  false,
  'Controls whether learner-submitted community questions and answers can be published to the public catalog'
)
on conflict (key) do nothing;

create or replace function private.is_community_ugc_public_enabled()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(
    (select value from public.community_config where key = 'public_ugc_enabled'),
    false
  );
$$;

revoke all on function private.is_community_ugc_public_enabled() from public, anon;
grant execute on function private.is_community_ugc_public_enabled() to authenticated, service_role;

-- -----------------------------------------------------------------------------
-- 2. Community Review Audit Table (Immutable Audit Log)
-- -----------------------------------------------------------------------------
create table if not exists public.community_review_audit (
  id uuid primary key default gen_random_uuid(),
  target_type text not null check (target_type in ('question', 'answer')),
  target_id uuid not null,
  reviewer_id uuid references auth.users(id) on delete set null,
  action text not null check (action in ('publish', 'reject', 'archive', 'flag')),
  previous_status text not null,
  new_status text not null,
  notes text,
  created_at timestamptz not null default now()
);

alter table public.community_review_audit enable row level security;

create index if not exists idx_community_review_audit_target
  on public.community_review_audit(target_type, target_id);

create index if not exists idx_community_review_audit_reviewer
  on public.community_review_audit(reviewer_id);

create index if not exists idx_community_review_audit_created
  on public.community_review_audit(created_at desc);

drop policy if exists community_review_audit_select_policy on public.community_review_audit;
create policy community_review_audit_select_policy on public.community_review_audit
  for select
  to authenticated
  using (private.is_moderator());

revoke all on table public.community_review_audit from public, anon;
revoke insert, update, delete on table public.community_review_audit from authenticated;
grant select on table public.community_review_audit to authenticated;
grant all on table public.community_review_audit to service_role;

-- -----------------------------------------------------------------------------
-- 3. Hardened Question Review RPC (Review Audit & UGC Launch Gate)
-- -----------------------------------------------------------------------------
create or replace function public.review_community_question(
  p_question_id uuid,
  p_action text,
  p_notes text default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_caller_id uuid;
  v_question record;
  v_new_status text;
begin
  v_caller_id := auth.uid();
  if v_caller_id is null or not private.is_moderator() then
    raise exception 'Access denied: caller does not possess moderator privileges'
      using errcode = '42501';
  end if;

  if p_action not in ('publish', 'reject', 'archive') then
    raise exception 'Invalid review action: %', p_action
      using errcode = '22023';
  end if;

  select * into v_question
    from public.community_questions
   where id = p_question_id
     for update;

  if not found then
    raise exception 'Question % not found', p_question_id
      using errcode = 'P0002';
  end if;

  -- Public UGC Launch Gate: Non-seeded learner questions cannot be published until public UGC is enabled
  if p_action = 'publish' and not v_question.is_seeded and not private.is_community_ugc_public_enabled() then
    raise exception 'Public learner UGC is currently disabled. Learner questions cannot be published before operational launch clearance.'
      using errcode = '22000';
  end if;

  v_new_status := case
    when p_action = 'publish' then 'published'
    when p_action = 'reject' then 'archived'
    when p_action = 'archive' then 'archived'
  end;

  -- Allow internal modification of status and updated_at
  perform set_config('community.internal_counter_update', 'true', true);

  update public.community_questions
     set status = v_new_status,
         updated_at = now()
   where id = p_question_id;

  -- Insert durable audit record
  insert into public.community_review_audit (
    target_type, target_id, reviewer_id, action, previous_status, new_status, notes
  ) values (
    'question', p_question_id, v_caller_id, p_action, v_question.status, v_new_status, p_notes
  );

  return jsonb_build_object(
    'success', true,
    'question_id', p_question_id,
    'action', p_action,
    'previous_status', v_question.status,
    'status', v_new_status,
    'notes', p_notes
  );
end;
$$;

revoke all on function public.review_community_question(uuid, text, text) from public, anon;
grant execute on function public.review_community_question(uuid, text, text) to authenticated, service_role;

-- -----------------------------------------------------------------------------
-- 4. Hardened Answer Review RPC (Review Audit & UGC Launch Gate)
-- -----------------------------------------------------------------------------
create or replace function public.review_community_answer(
  p_answer_id uuid,
  p_action text,
  p_notes text default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_caller_id uuid;
  v_answer record;
  v_parent_question record;
  v_new_status text;
begin
  v_caller_id := auth.uid();
  if v_caller_id is null or not private.is_moderator() then
    raise exception 'Access denied: caller does not possess moderator privileges'
      using errcode = '42501';
  end if;

  if p_action not in ('publish', 'reject', 'archive', 'flag') then
    raise exception 'Invalid review action: %', p_action
      using errcode = '22023';
  end if;

  select * into v_answer
    from public.community_answers
   where id = p_answer_id
     for update;

  if not found then
    raise exception 'Answer % not found', p_answer_id
      using errcode = 'P0002';
  end if;

  select * into v_parent_question
    from public.community_questions
   where id = v_answer.question_id;

  if not found then
    raise exception 'Parent question not found'
      using errcode = 'P0002';
  end if;

  if p_action = 'publish' then
    if v_parent_question.status <> 'published' then
      raise exception 'Cannot publish answer for non-published parent question'
        using errcode = '22000';
    end if;

    -- Public UGC Launch Gate: Non-seeded learner answers cannot be published until public UGC is enabled
    if not v_parent_question.is_seeded and not private.is_community_ugc_public_enabled() then
      raise exception 'Public learner UGC is currently disabled. Learner answers cannot be published before operational launch clearance.'
        using errcode = '22000';
    end if;

    v_new_status := 'published';
  elsif p_action = 'reject' or p_action = 'archive' then
    v_new_status := 'archived';
  elsif p_action = 'flag' then
    v_new_status := 'flagged';
  end if;

  perform set_config('community.internal_counter_update', 'true', true);

  update public.community_answers
     set status = v_new_status,
         updated_at = now()
   where id = p_answer_id;

  -- Insert durable audit record
  insert into public.community_review_audit (
    target_type, target_id, reviewer_id, action, previous_status, new_status, notes
  ) values (
    'answer', p_answer_id, v_caller_id, p_action, v_answer.status, v_new_status, p_notes
  );

  return jsonb_build_object(
    'success', true,
    'answer_id', p_answer_id,
    'action', p_action,
    'status', v_new_status,
    'notes', p_notes
  );
end;
$$;

revoke all on function public.review_community_answer(uuid, text, text) from public, anon;
grant execute on function public.review_community_answer(uuid, text, text) to authenticated, service_role;

-- -----------------------------------------------------------------------------
-- 5. Hardened Seed Pilot FAQs RPC (Admin Authorization & Trigger Fix)
-- -----------------------------------------------------------------------------
create or replace function public.seed_pilot_community_faqs(p_author_id uuid default null)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_author_id uuid;
  v_count integer := 0;
  v_q_id uuid;
  v_seed record;
begin
  -- Enforce authorization: caller must be a verified administrator or service role
  if auth.uid() is not null then
    if not private.is_admin() then
      raise exception 'Access denied: only administrators may invoke seed_pilot_community_faqs'
        using errcode = '42501';
    end if;
  elsif coalesce(auth.jwt()->>'role', '') <> 'service_role' and session_user <> 'postgres' then
    raise exception 'Access denied: only administrators may invoke seed_pilot_community_faqs'
      using errcode = '42501';
  end if;

  -- Resolve author id
  if p_author_id is not null then
    v_author_id := p_author_id;
  else
    select user_id into v_author_id
      from public.moderation_roles
     where role = 'admin'
     limit 1;
  end if;

  if v_author_id is null then
    return 0;
  end if;

  -- Check existence in auth.users
  if not exists (select 1 from auth.users where id = v_author_id) then
    return 0;
  end if;

  perform set_config('community.internal_counter_update', 'true', true);

  -- 18 Authoritative Pilot FAQs across Literacy, Workplace Safety, and Florida Licensure
  for v_seed in (
    select
      'What is the CVC pattern in phonics and how is it taught?' as title,
      'What does the CVC acronym stand for, and why is it considered the foundational pattern in early phonics instruction?' as body,
      'literacy.cvc.basics' as concept_id,
      'CVC stands for Consonant-Vowel-Consonant (e.g., ''cat'', ''pin'', ''sun'', ''bed'', ''fog''). In CVC words, the single vowel in the middle always makes its short vowel sound. Blending these three distinct phonemes (onset, vowel nucleus, and coda) is the core initial milestone in phonemic decoding before learners progress to consonant blends, vowel teams, or silent-e patterns. Source: National Reading Panel & Evidence-Based Reading Research. Verified October 2026. Note: Platform-curated educational reference.' as answer_body
    union all select
      'How do sight words differ from decodable words?',
      'Why are high-frequency words often called sight words, and should learners sound them out or memorize them?',
      'literacy.sight_words',
      'Decodable words follow transparent phonetic rules that learners can sound out letter by letter using taught grapheme-phoneme correspondences. High-frequency ''sight words'' (such as ''the'', ''was'', ''said'', ''of'') often contain irregular or advanced spelling patterns. Modern evidence-based reading instruction recommends ''orthographic mapping''—pointing out the regular sound parts while explicitly highlighting the irregular ''heart'' sounds, enabling instantaneous word retrieval without pure rote memorization. Source: National Reading Panel & Evidence-Based Reading Research. Verified October 2026. Note: Platform-curated educational reference.'
    union all select
      'What is the difference between continuous blending and segmented blending?',
      'When teaching a struggling reader to blend letter sounds into words, what is continuous blending and why is it recommended?',
      'literacy.phonics.blending',
      'Segmented blending pauses between each individual sound (e.g., /s/ ... /a/ ... /t/), which places heavy demands on working memory. Continuous blending (also called additive or connected phonation) stretches continuous sounds smoothly into one another without pausing (e.g., ''ssssaaaat''). Research indicates continuous blending significantly reduces memory drop-off and error rates for early and struggling readers. Source: National Reading Panel & Evidence-Based Reading Research. Verified October 2026. Note: Platform-curated educational reference.'
    union all select
      'What is a consonant digraph versus a consonant blend?',
      'What distinguishes consonant digraphs like ''sh'' and ''th'' from consonant blends like ''bl'' and ''st''?',
      'literacy.digraphs',
      'A consonant digraph consists of two letters that team together to represent a single, unique phoneme (e.g., ''sh'' in ''ship'', ''th'' in ''thin'', ''ch'' in ''chin'', ''ck'' in ''duck''). In contrast, a consonant blend consists of two or three consonants where each letter retains its own distinct individual sound that can still be heard when spoken together (e.g., /b/ and /l/ in ''black'', /s/ and /t/ in ''stop''). Source: National Reading Panel & Evidence-Based Reading Research. Verified October 2026. Note: Platform-curated educational reference.'
    union all select
      'How does onset-rime awareness support phonological development?',
      'Why is dividing words into onset and rime beneficial for pre-readers and developing spellers?',
      'literacy.rhyming',
      'In phonological awareness, the ''onset'' is the initial consonant sound before the vowel (e.g., /c/ in ''cat''), and the ''rime'' is the vowel and any subsequent consonants (e.g., ''-at''). Recognizing common rimes (word families like ''-at'', ''-in'', ''-op'') accelerates reading fluency because learners can rapidly map and read dozens of new words by simply swapping the onset consonant. Source: National Reading Panel & Evidence-Based Reading Research. Verified October 2026. Note: Platform-curated educational reference.'
    union all select
      'How does the silent-e (split digraph) change vowel sounds in English?',
      'What is the phonics principle behind the ''magic e'' or silent-e pattern in words like ''hop'' vs ''hope''?',
      'literacy.silent_e',
      'In the VCe (Vowel-Consonant-e) pattern, the final silent ''e'' signals that the preceding vowel represents its long vowel sound (saying its name) rather than the short vowel sound heard in closed CVC syllables (e.g., ''cap'' becomes ''cape'', ''pin'' becomes ''pine'', ''tub'' becomes ''tube''). Linguistically, this is a split vowel digraph, where the two vowel letters work together across the intervening consonant. Source: National Reading Panel & Evidence-Based Reading Research. Verified October 2026. Note: Platform-curated educational reference.'
    union all select
      'What are the five levels of the Hierarchy of Controls in workplace safety?',
      'Under NIOSH and OSHA standards, how should employers prioritize hazard mitigation methods?',
      'workplace.safety.ppe',
      'The Hierarchy of Controls prioritizes hazard mitigation from most to least effective: 1) Elimination (physically remove the hazard); 2) Substitution (replace the hazard with a safer alternative); 3) Engineering Controls (isolate people from the hazard, e.g., machine guards, ventilation); 4) Administrative Controls (change the way people work through procedures, training, and signs); and 5) Personal Protective Equipment (PPE: gloves, respirators, hard hats, earplugs). PPE is the last line of defense, not the first. Source: OSHA & NIOSH Safety Standards. Verified October 2026. Note: Platform-curated educational reference; does not replace employer site safety training.'
    union all select
      'What information must be included on an OSHA-compliant GHS chemical safety label?',
      'What are the mandatory elements required on hazardous chemical container labels under OSHA HazCom 2012?',
      'workplace.safety.hazcom',
      'Under OSHA''s Hazard Communication Standard (29 CFR 1910.1200) aligned with the Globally Harmonized System (GHS), container labels must include six mandatory elements: 1) Product Identifier (chemical name/code); 2) Signal Word (''Danger'' for severe hazards, ''Warning'' for less severe); 3) Hazard Statements (nature and degree of hazard); 4) Precautionary Statements (prevention, response, storage, disposal); 5) GHS Pictograms (red diamond borders with black hazard symbols); and 6) Supplier Identification (manufacturer name, address, and emergency telephone number). Source: OSHA HazCom Standard (29 CFR 1910.1200). Verified October 2026. Note: Platform-curated educational reference; does not replace employer site safety training.'
    union all select
      'What is the PASS method for operating a portable fire extinguisher?',
      'What four-step sequence should workers follow when using a portable fire extinguisher during an incipient-stage fire?',
      'workplace.safety.fire',
      'The PASS acronym summarizes the correct technique: 1) Pull the safety pin from the handle; 2) Aim low, pointing the extinguisher nozzle or hose at the base of the fire (not into the flames); 3) Squeeze the handle lever slowly and evenly to discharge the extinguishing agent; 4) Sweep the nozzle from side to side across the base of the fire until the fire is completely out. Workers should only fight fires in their incipient stage when a safe exit path is behind them. Source: OSHA Standard 29 CFR 1910.157 & NFPA Guidelines. Verified October 2026. Note: Platform-curated educational reference; does not replace employer site safety training.'
    union all select
      'What is Lockout/Tagout (LOTO) and why is it mandatory during machinery maintenance?',
      'Under OSHA standard 29 CFR 1910.147, what is the primary purpose of hazardous energy control procedures?',
      'workplace.safety.lockout_tagout',
      'Lockout/Tagout (LOTO) establishes minimum performance requirements to prevent unexpected energization, startup, or release of stored energy during servicing or maintenance of machines and equipment. A designated lockout device physically holds the energy-isolating mechanism in a safe position, while a standardized tagout warning tag indicates the equipment must not be energized until the authorized technician removes the lock. Source: OSHA Standard 29 CFR 1910.147. Verified October 2026. Note: Platform-curated educational reference; does not replace employer site safety training.'
    union all select
      'What are the primary OSHA walking-working surface requirements for housekeeping?',
      'How should walkways, aisles, and floors be maintained in commercial and industrial workspaces to prevent fall injuries?',
      'workplace.safety.slips_trips_falls',
      'Under OSHA 29 CFR 1910.22, all places of employment, passageways, storerooms, and service rooms must be kept clean, orderly, and in a sanitary condition. Floors must be kept dry and clear of debris, electrical cords, and protrusions. Where wet processes are used, employers must provide adequate drainage, non-slip mats, or false floors to maintain traction. Source: OSHA Standard 29 CFR 1910.22. Verified October 2026. Note: Platform-curated educational reference; does not replace employer site safety training.'
    union all select
      'What core components are required in an OSHA Emergency Action Plan (EAP)?',
      'When an employer is required to have an Emergency Action Plan under 29 CFR 1910.38, what procedures must be documented?',
      'workplace.safety.emergency_action',
      'An OSHA Emergency Action Plan must document: 1) Procedures for reporting fires and other emergencies; 2) Emergency evacuation procedures, including designated exit route assignments; 3) Procedures for employees who remain to operate critical operations before evacuation; 4) Procedures to account for all employees after evacuation; 5) Rescue and medical duties for assigned workers; and 6) Preferred names or job titles of individuals to contact for further information. Source: OSHA Standard 29 CFR 1910.38. Verified October 2026. Note: Platform-curated educational reference; does not replace employer site safety training.'
    union all select
      'What are the continuing education (CE) requirements for Florida Cosmetology license renewal?',
      'How many continuing education hours are required by the Florida Board of Cosmetology for biennial license renewal?',
      'licensure.cosmetology.ce',
      'Under Section 477.019, Florida Statutes, and Rule 61G5-20.002, Florida Administrative Code (F.A.C.), Florida licensed cosmetologists must complete 10 hours of Board-approved continuing education prior to biennial license renewal. Cosmetology licenses are divided into two renewal groups: Group 1 expires October 31 of odd-numbered years, and Group 2 expires October 31 of even-numbered years. The mandatory 10-hour curriculum allocation requires: 1 hour of Board-approved HIV/AIDS education, 3 hours of sanitation and sterilization, 0.5 hour of Occupational Safety and Health Administration (OSHA) regulations, 0.5 hour of Workers'' Compensation law, 1 hour of Florida and Federal laws and rules, and 4 hours of General cosmetology courses or specialty electives. Source: Florida DBPR Board of Cosmetology (Rule 61G5-20.002, F.A.C.; § 477.019, Fla. Stat.). Verified October 2026. Note: Platform-curated educational reference; does not constitute legal counsel or regulatory endorsement.'
    union all select
      'What are the work and in-service training requirements to renew a Florida CNA certificate?',
      'How does a Certified Nursing Assistant maintain an active license with the Florida Board of Nursing?',
      'licensure.cna.renewal',
      'Under Florida Statutes Chapter 464 and Rule 64B9-15, a Certified Nursing Assistant (CNA) license renews biennially. To qualify for active renewal, the CNA must perform nursing-related services for monetary compensation within the 24-month renewal cycle and complete a minimum of 24 hours of in-service training (12 hours per calendar year) covering mandatory topics such as medical error prevention, infection control, CPR, patient rights, and HIPAA compliance. Source: Florida Board of Nursing (Rule 64B9-15, F.A.C.; Ch. 464, Fla. Stat.). Verified October 2026. Note: Platform-curated educational reference; does not constitute legal counsel or regulatory endorsement.'
    union all select
      'What is the first-renewal post-licensing requirement for Florida Real Estate Sales Associates?',
      'What coursework must a newly licensed Florida real estate sales associate complete before their initial license expiration date?',
      'licensure.real_estate.post_licensing',
      'Florida Real Estate Commission (FREC) Rule 61J2-3 requires all newly licensed sales associates to satisfactorily complete a commission-approved 45-hour post-licensing education course prior to their first biennial license expiration date. There is no grace period in Florida: failure to complete the 45-hour post-licensing course before the expiration date renders the license null and void by operation of law. Source: Florida Real Estate Commission (Rule 61J2-3, F.A.C.; Ch. 475, Fla. Stat.). Verified October 2026. Note: Platform-curated educational reference; does not constitute legal counsel or regulatory endorsement.'
    union all select
      'How does license reciprocity work for Florida Certified Electrical Contractors?',
      'Does the Florida Electrical Contractors'' Licensing Board (ECLB) grant reciprocal recognition to electrical licenses from other states?',
      'licensure.electrical.reciprocity',
      'The Florida Electrical Contractors'' Licensing Board (ECLB) explicitly states that Florida does not have reciprocal licensing agreements with any other state. Under Section 489.511, Florida Statutes, out-of-state contractors must apply for Licensure by Endorsement rather than reciprocity. To qualify for endorsement without retaking the Florida technical examination, an applicant must demonstrate either: 1) They passed a state or national examination substantially equivalent to Florida''s examination at the time taken; or 2) They held a valid, active electrical contractor license in another state for at least 10 years, with qualifications meeting or exceeding Florida statutory standards. All endorsement applicants must independently satisfy Florida financial responsibility requirements, credit reporting, fingerprint-based criminal history background checks, and proof of active workers'' compensation insurance. Source: Florida DBPR Electrical Contractors'' Licensing Board (ECLB; § 489.511, Fla. Stat.). Verified October 2026. Note: Platform-curated educational reference; does not constitute legal counsel or regulatory endorsement.'
    union all select
      'What training hours are required for the Florida Class D Security Officer License?',
      'Under Florida Chapter 493, what curriculum and hours must an applicant complete to earn a Class D Security Officer License?',
      'licensure.security_guard.class_d',
      'Under Florida Statutes Chapter 493, applicants for the Class ''D'' Security Officer License must successfully complete a 40-hour training curriculum at a licensed security officer school. The training covers Florida law, security officer conduct, observation techniques, report writing, emergency procedures, terrorism awareness, and first aid. Once completed, the license is issued by the Florida Department of Agriculture and Consumer Services (FDACS) and is valid for two years. Source: Florida Department of Agriculture and Consumer Services (FDACS; Ch. 493, Fla. Stat.). Verified October 2026. Note: Platform-curated educational reference; does not constitute legal counsel or regulatory endorsement.'
    union all select
      'What experience qualifications are required for the Florida Certified General Contractor (CGC) exam?',
      'What combination of education and four years of commercial construction experience is required by the Florida CILB?',
      'licensure.construction.general_contractor',
      'The Florida Construction Industry Licensing Board (CILB) requires applicants for the Certified General Contractor (CGC) license under Section 489.111, Florida Statutes, and Rule 61G4-15.001, F.A.C., to demonstrate four years of proven commercial construction experience. For general contractors, commercial high-rise experience is specifically defined as new commercial construction of structures of not less than four stories (at least four stories or taller). Qualifying experience must encompass substantial structural knowledge in: foundations and piers, structural framing, elevated slabs and post-tensioning, structural masonry, and curtain walls. Acceptable qualifying paths include: 1) A 4-year accredited degree in construction, engineering, or architecture plus 1 year of proven supervisory experience; 2) 3 years of accredited college credits plus 1 year of supervisory experience; or 3) 4 years of active field experience, with at least 1 year acting as a foreman or supervisor on commercial projects including structures of not less than four stories. Source: Florida DBPR Construction Industry Licensing Board (CILB; § 489.111, Fla. Stat.; Rule 61G4-15.001, F.A.C.). Verified October 2026. Note: Platform-curated educational reference; does not constitute legal counsel or regulatory endorsement.'
  ) loop
    -- Check if question already exists
    select id into v_q_id
      from public.community_questions
     where title = v_seed.title;

    if v_q_id is null then
      -- Insert question with answer_count = 0; trg_community_answer_count trigger will increment to 1 on answer insertion
      insert into public.community_questions (
        author_id, title, body_markdown, status, is_seeded,
        concept_id, view_count, upvote_count, answer_count
      ) values (
        v_author_id, v_seed.title, v_seed.body, 'published', true,
        v_seed.concept_id, 0, 0, 0
      ) returning id into v_q_id;

      insert into public.community_answers (
        question_id, author_id, body_markdown, is_ai_generated,
        is_accepted, status, upvote_count
      ) values (
        v_q_id, v_author_id, v_seed.answer_body, false,
        true, 'published', 0
      );

      v_count := v_count + 1;
    else
      -- Question already exists: update accepted answer body with verified content
      update public.community_answers
         set body_markdown = v_seed.answer_body,
             updated_at = now()
       where question_id = v_q_id
         and is_accepted = true;
    end if;
  end loop;

  return v_count;
end;
$$;

revoke all on function public.seed_pilot_community_faqs(uuid) from public, anon;
grant execute on function public.seed_pilot_community_faqs(uuid) to authenticated, service_role;

-- -----------------------------------------------------------------------------
-- 6. Immediate Production Data Repair & Sourcing Update
-- -----------------------------------------------------------------------------
do $$
begin
  perform set_config('community.internal_counter_update', 'true', true);

  -- Repair 1: Recalculate accurate answer_count for all questions
  update public.community_questions q
     set answer_count = coalesce(
       (select count(*)
          from public.community_answers a
         where a.question_id = q.id
           and a.status = 'published'),
