-- --------------------------------------------------------------------
-- [71/96] Migration: 20261101080000_exm_02b_account_practice_export.sql
-- --------------------------------------------------------------------
-- EXM-02B: one-statement, owner-only account-wide R1–R4 evidence export.
-- This covers saved reference-practice events across ALL original and retired
-- manifest revisions. It is NOT an export of the learner's entire LearningApp
-- account. No retention interval or automatic purging is instituted here.
-- Client answers, private correct tokens and reviewer records are never read.

create function public.exam_reference_drill_account_export(
  p_max_records integer default 5000
)
returns jsonb
language plpgsql stable security invoker
set search_path=pg_catalog,public,pg_temp
as $export$
declare
  actor_uid uuid;
  record_count integer;
  clean_steps jsonb;
begin
  actor_uid := (select auth.uid());
  if actor_uid is null
     or (select (auth.jwt()->>'is_anonymous')::boolean) is distinct from false then
    raise exception 'Permanent sign-in required for private practice export'
      using errcode='42501';
  end if;
  if p_max_records is null or p_max_records < 1 or p_max_records > 5000 then
    raise exception 'Invalid reference-practice export bound'
      using errcode='22023';
  end if;

  -- A single bounded database statement makes deletion/grade reads share
  -- the same MVCC snapshot, unlike a sequence of cursor-page network RPCs.
  -- SECURITY INVOKER and ordinary SELECT+RLS on both relations are required.
  with bounded as materialized (
    select e.id,e.owner_auth_uid,e.client_attempt_id,
      e.assessment_item_id,e.approved_binding_id,e.manifest_revision_id,
      e.exam_part_key,e.administration_date,e.item_content_revision,
      e.answer_location_revision,e.drill_step,e.responded,e.app_elapsed_ms,
      e.self_reported_book_ms,e.started_at,e.completed_at,e.recorded_at,
      e.verification_state
    from public.exam_reference_drill_events e
    where e.owner_auth_uid=actor_uid
    order by e.recorded_at desc,e.id desc
    limit p_max_records + 1
  )
  select count(*)::integer,
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'event_id',e.id,
          'owner_auth_uid',e.owner_auth_uid,
          'client_attempt_id',e.client_attempt_id,
          'assessment_item_id',e.assessment_item_id,
          'approved_binding_id',e.approved_binding_id,
          'manifest_revision_id',e.manifest_revision_id,
          'exam_part_key',e.exam_part_key,
          'administration_date',e.administration_date,
          'item_content_revision',e.item_content_revision,
          'answer_location_revision',e.answer_location_revision,
          'drill_step',e.drill_step,
          'responded',e.responded,
          'app_elapsed_ms',e.app_elapsed_ms,
          'self_reported_book_ms',e.self_reported_book_ms,
          'started_at',e.started_at,
          'completed_at',e.completed_at,
          'recorded_at',e.recorded_at,
          'verification_state',e.verification_state,
          'is_correct',g.is_correct,
          'scoring_version',g.scoring_version,
          'graded_at',g.graded_at
        ) order by e.recorded_at desc,e.id desc
      ),'[]'::jsonb
    )
  into record_count,clean_steps
  from bounded e
  left join public.exam_reference_drill_grades g
    on g.event_id=e.id
   and g.owner_auth_uid=e.owner_auth_uid
   and g.approved_binding_id=e.approved_binding_id
   and g.drill_step=e.drill_step;

  if record_count > p_max_records then
    raise exception 'Reference practice export exceeds the safe record bound'
      using errcode='54000';
  end if;

  return jsonb_build_object(
    'format','learningapp-exm-reference-practice-account-v1',
    'scope','reference-practice-all-editions',
    'owner_auth_uid',actor_uid,
    'record_count',record_count,
    'generated_at',now(),
    'snapshot_consistency','single-sql-statement',
    'steps',clean_steps
  );
end
$export$;

revoke all on function public.exam_reference_drill_account_export(integer)
  from public,anon,authenticated;
grant execute on function public.exam_reference_drill_account_export(integer)
  to authenticated;
comment on function public.exam_reference_drill_account_export(integer) is
  'Owner-RLS one-statement reference-practice export, all saved manifest revisions, 5000-event cap. No submitted answers, private rubrics or reviewer material.';

INSERT INTO supabase_migrations.schema_migrations (version, name) VALUES ('20261101080000', 'exm_02b_account_practice_export') ON CONFLICT (version) DO NOTHING;

-- --------------------------------------------------------------------
-- [72/96] Migration: 20261101090000_exm_02b_owner_practice_erasure.sql
-- --------------------------------------------------------------------
-- EXM-02B: opt-in owner-only preview and erasure of SAVED reference
-- practice events across current and retired manifest editions.
-- No automatic retention timer or irreversible action is executed by migration.
-- Existing grade FK ON DELETE CASCADE removes derived grades automatically.

create function public.exam_reference_drill_erasure_preview()
returns jsonb
language plpgsql stable security invoker
set search_path=pg_catalog,public,pg_temp
as $preview$
declare
  actor_uid uuid;
  ids uuid[];
  total integer;
  editions integer;
  graded integer;
begin
  actor_uid := (select auth.uid());
  if actor_uid is null
     or (select (auth.jwt()->>'is_anonymous')::boolean) is distinct from false then
    raise exception 'Permanent owner sign-in required'
      using errcode='42501';
  end if;
  select array_agg(e.id order by e.id),count(*)::integer,
    count(distinct e.manifest_revision_id)::integer
    into ids,total,editions
    from public.exam_reference_drill_events e
    where e.owner_auth_uid=actor_uid;
  -- Explicitly cap new erasure workflow until large-account policy is
  -- approved; do not pretend a preview or action is complete above bound.
  if total > 5000 then
    raise exception 'Saved practice exceeds safe erasure limit'
      using errcode='54000';
  end if;
  select count(*)::integer into graded
    from public.exam_reference_drill_grades g
    join public.exam_reference_drill_events e on e.id=g.event_id
    where e.owner_auth_uid=actor_uid
      and g.owner_auth_uid=actor_uid;
  return jsonb_build_object(
    'scope','reference-practice-all-editions',
    'owner_auth_uid',actor_uid,
    'event_count',total,
    'graded_count',graded,
    'edition_count',editions,
    'snapshot_fingerprint',md5(coalesce(array_to_string(ids,','),''))
  );
end
$preview$;

create function public.exam_reference_drill_erase_owned(
  p_expected_count integer,
  p_expected_fingerprint text,
  p_confirmation text
)
returns jsonb
language plpgsql volatile security invoker
set search_path=pg_catalog,public,pg_temp
as $erase$
declare
  actor_uid uuid;
  selected_ids uuid[];
  selected_count integer;
  fingerprint text;
  removed_count integer;
  remaining_count integer;
begin
  actor_uid := (select auth.uid());
  if actor_uid is null
     or (select (auth.jwt()->>'is_anonymous')::boolean) is distinct from false then
    raise exception 'Permanent owner sign-in required'
      using errcode='42501';
  end if;
  if p_confirmation is distinct from 'DELETE REFERENCE PRACTICE'
     or p_expected_count is null or p_expected_count < 1
     or p_expected_count > 5000
     or p_expected_fingerprint is null
     or p_expected_fingerprint !~ '^[a-f0-9]{32}$' then
    raise exception 'Explicit preview and exact deletion confirmation required'
      using errcode='22023';
  end if;

  -- A read-only owner-RLS query identifies the previewed IDs. PostgreSQL
  -- SELECT FOR UPDATE/SHARE would wrongly require granting UPDATE access,
  -- which EXM events intentionally deny. The DELETE locks its selected rows;
  -- only those IDs can be removed, never concurrent new inserts. An observed
  -- row-count mismatch aborts this entire transaction.
  select array_agg(selected.id order by selected.id),count(*)::integer
    into selected_ids,selected_count
    from (
      select e.id from public.exam_reference_drill_events e
      where e.owner_auth_uid=actor_uid
      order by e.id
    ) selected;
  if selected_count > 5000 then
    raise exception 'Saved practice exceeds safe erasure limit'
      using errcode='54000';
  end if;
  fingerprint := md5(coalesce(array_to_string(selected_ids,','),''));
  if selected_count <> p_expected_count
     or fingerprint <> p_expected_fingerprint then
    raise exception 'Saved practice changed; prepare a fresh preview'
      using errcode='P0001';
  end if;

  delete from public.exam_reference_drill_events e
    where e.owner_auth_uid=actor_uid and e.id=any(selected_ids);
  get diagnostics removed_count = row_count;
  if removed_count <> selected_count then
    raise exception 'Incomplete owner-practice erasure; transaction rolled back';
  end if;

  select count(*)::integer into remaining_count
    from public.exam_reference_drill_events e
    where e.owner_auth_uid=actor_uid;
  return jsonb_build_object(
    'scope','reference-practice-all-editions',
    'owner_auth_uid',actor_uid,
    'deleted_events',removed_count,
    'remaining_events',remaining_count
  );
end
$erase$;

revoke all on function public.exam_reference_drill_erasure_preview()
  from public,anon,authenticated;
revoke all on function public.exam_reference_drill_erase_owned(integer,text,text)
  from public,anon,authenticated;
grant execute on function public.exam_reference_drill_erasure_preview()
  to authenticated;
grant execute on function public.exam_reference_drill_erase_owned(integer,text,text)
  to authenticated;

comment on function public.exam_reference_drill_erasure_preview() is
  'Owner-RLS saved event/grade inventory only. Fingerprint tracks the exact observed event ID set; no answer material.';
comment on function public.exam_reference_drill_erase_owned(integer,text,text) is
  'Explicit confirmed, owner-RLS deletion of exact previewed EXM step IDs; dependent grades cascade. Not whole account erasure or automated retention.';

INSERT INTO supabase_migrations.schema_migrations (version, name) VALUES ('20261101090000', 'exm_02b_owner_practice_erasure') ON CONFLICT (version) DO NOTHING;

-- --------------------------------------------------------------------
-- [73/96] Migration: 20261101100000_exm_02b_batched_practice_erasure.sql
-- --------------------------------------------------------------------
-- EXM-02B: explicitly approved bounded erasure for large saved histories.
-- No automatic retention, background job, UPDATE privilege or scheduler.
-- The learner must re-preview and reconfirm EACH batch; 1,000 max per call.
-- This adds new RPCs without changing the previously reviewed ones.

create function public.exam_reference_drill_batch_erasure_preview(
  p_batch_limit integer default 1000
)
returns jsonb
language plpgsql stable security invoker
set search_path=pg_catalog,public,pg_temp
as $preview$
declare
  actor_uid uuid;
  all_count bigint;
  selected_ids uuid[];
  batch_count integer;
  batch_editions integer;
  batch_grades integer;
begin
  actor_uid := (select auth.uid());
  if actor_uid is null
     or (select (auth.jwt()->>'is_anonymous')::boolean) is distinct from false then
    raise exception 'Permanent owner sign-in required'
      using errcode='42501';
  end if;
  if p_batch_limit is null or p_batch_limit < 1 or p_batch_limit > 1000 then
    raise exception 'Batch size must be between 1 and 1000'
      using errcode='22023';
  end if;

  select count(*) into all_count
    from public.exam_reference_drill_events e
    where e.owner_auth_uid=actor_uid;

  select array_agg(batch.id order by batch.id),
      count(*)::integer,count(distinct batch.manifest_revision_id)::integer
    into selected_ids,batch_count,batch_editions
    from (
      select e.id,e.manifest_revision_id
      from public.exam_reference_drill_events e
      where e.owner_auth_uid=actor_uid
      order by e.id
      limit p_batch_limit
    ) batch;
  select count(*)::integer into batch_grades
    from public.exam_reference_drill_grades g
    where g.owner_auth_uid=actor_uid and g.event_id=any(selected_ids);

  return jsonb_build_object(
    'scope','reference-practice-next-batch',
    'owner_auth_uid',actor_uid,
    'total_events',all_count,
    'batch_events',batch_count,
    'batch_grades',batch_grades,
    'batch_editions',batch_editions,
    'batch_limit',p_batch_limit,
    'batch_fingerprint',md5(coalesce(array_to_string(selected_ids,','),''))
  );
end
$preview$;

create function public.exam_reference_drill_erase_batch(
  p_batch_limit integer,
  p_expected_count integer,
  p_expected_fingerprint text,
  p_confirmation text
)
returns jsonb
language plpgsql volatile security invoker
set search_path=pg_catalog,public,pg_temp
as $delete$
declare
  actor_uid uuid;
  selected_ids uuid[];
  selected_count integer;
  removed_count integer;
  remaining_count bigint;
begin
  actor_uid := (select auth.uid());
  if actor_uid is null
     or (select (auth.jwt()->>'is_anonymous')::boolean) is distinct from false then
    raise exception 'Permanent owner sign-in required'
      using errcode='42501';
  end if;
  if p_confirmation is distinct from 'DELETE NEXT BATCH'
     or p_batch_limit is null or p_batch_limit < 1 or p_batch_limit > 1000
     or p_expected_count is null or p_expected_count < 1
     or p_expected_count > p_batch_limit
     or p_expected_fingerprint is null
     or p_expected_fingerprint !~ '^[a-f0-9]{32}$' then
    raise exception 'Exact batch preview and confirmation required'
      using errcode='22023';
  end if;

  -- Select a bounded, deterministic ID set with owner RLS (no FOR UPDATE,
  -- which would require forbidden client UPDATE privilege). New inserts are
  -- never swept into this ID set. DELETE row locks and a strict rowcount
  -- assertion enforce rollback on concurrent removals.
  select array_agg(batch.id order by batch.id),count(*)::integer
    into selected_ids,selected_count
    from (
      select e.id
      from public.exam_reference_drill_events e
      where e.owner_auth_uid=actor_uid
      order by e.id
      limit p_batch_limit
    ) batch;
  if selected_count <> p_expected_count
     or md5(coalesce(array_to_string(selected_ids,','),'')) <>
       p_expected_fingerprint then
    raise exception 'Batch changed; refresh the preview before deleting'
      using errcode='P0001';
  end if;

  delete from public.exam_reference_drill_events e
    where e.owner_auth_uid=actor_uid and e.id=any(selected_ids);
  get diagnostics removed_count = row_count;
  if removed_count <> selected_count then
    raise exception 'Incomplete batch deletion; transaction rolled back'
      using errcode='P0001';
  end if;
  select count(*) into remaining_count
    from public.exam_reference_drill_events e
    where e.owner_auth_uid=actor_uid;
  return jsonb_build_object(
    'scope','reference-practice-next-batch',
    'owner_auth_uid',actor_uid,
    'deleted_events',removed_count,
    'remaining_events',remaining_count
  );
end
$delete$;

revoke all on function public.exam_reference_drill_batch_erasure_preview(integer)
  from public,anon,authenticated;
revoke all on function public.exam_reference_drill_erase_batch(integer,integer,text,text)
  from public,anon,authenticated;
grant execute on function public.exam_reference_drill_batch_erasure_preview(integer)
  to authenticated;
grant execute on function public.exam_reference_drill_erase_batch(integer,integer,text,text)
  to authenticated;

comment on function public.exam_reference_drill_batch_erasure_preview(integer) is
 'RLS owner-only preview of next deterministic 1–1000 saved EXM steps, including retired editions. No automatic erasure.';
comment on function public.exam_reference_drill_erase_batch(integer,integer,text,text) is
 'Explicit RLS owner-only, fingerprint-checked deletion of exactly one previewed step batch. Re-preview and re-confirm every subsequent batch.';

INSERT INTO supabase_migrations.schema_migrations (version, name) VALUES ('20261101100000', 'exm_02b_batched_practice_erasure') ON CONFLICT (version) DO NOTHING;

-- --------------------------------------------------------------------
-- [74/96] Migration: 20261101110000_exm_02b_verified_large_export.sql
-- --------------------------------------------------------------------
-- EXM-02B: verified bounded multi-request export for >5,000 saved events.
-- Existing single-statement export stays untouched. No answer keys, client
-- response tokens, new persistence tables, retention rules or service roles.
-- A double inventory digest detects changed event IDs and newly scored grades
-- across cursor-page requests; it is NOT one MVCC snapshot across requests.
-- All functions are SECURITY INVOKER with pre-existing owner SELECT RLS.
create function public.exam_reference_drill_export_inventory()
returns jsonb
language plpgsql stable security invoker
set search_path=pg_catalog,public,pg_temp
as $inventory$
declare
  actor_uid uuid;
  n bigint;
  fingerprint text;
begin
  actor_uid := (select auth.uid());
  if actor_uid is null
     or (select (auth.jwt()->>'is_anonymous')::boolean) is distinct from false then
    raise exception 'Permanent owner sign-in required'
      using errcode='42501';
  end if;
  select count(*),
     md5(coalesce(string_agg(
       e.id::text || ':' ||
       coalesce(g.is_correct::text, 'unscored') || ':' ||
       coalesce(g.scoring_version::text, 'none') || ':' ||
       coalesce(extract(epoch from g.graded_at)::text, 'none'),
       ',' order by e.recorded_at desc,e.id desc
     ),''))
    into n,fingerprint
    from public.exam_reference_drill_events e
    left join public.exam_reference_drill_grades g
      on g.event_id=e.id
     and g.owner_auth_uid=e.owner_auth_uid
     and g.approved_binding_id=e.approved_binding_id
     and g.drill_step=e.drill_step
   where e.owner_auth_uid=actor_uid;

  -- This is a product/client-size bound, not a retention deletion trigger.
  if n > 50000 then
    raise exception 'Reference history exceeds current verified export bound'
      using errcode='54000';
  end if;
  return jsonb_build_object(
    'scope','reference-practice-all-editions',
    'owner_auth_uid',actor_uid,
    'record_count',n,
    'record_fingerprint',fingerprint,
    'verification','pre-and-post-inventory-digest-v1'
  );
end
$inventory$;

create function public.exam_reference_drill_export_page(
  p_limit integer default 250,
  p_before_recorded_at timestamptz default null,
  p_before_event_id uuid default null
)
returns jsonb
language plpgsql stable security invoker
set search_path=pg_catalog,public,pg_temp
as $page$
declare
  actor_uid uuid;
  records jsonb;
  row_count integer;
begin
  actor_uid := (select auth.uid());
  if actor_uid is null
     or (select (auth.jwt()->>'is_anonymous')::boolean) is distinct from false then
    raise exception 'Permanent owner sign-in required'
      using errcode='42501';
  end if;
  if p_limit is null or p_limit < 1 or p_limit > 250 or
     (p_before_recorded_at is null) <> (p_before_event_id is null) then
    raise exception 'Invalid exact export cursor/limit'
      using errcode='22023';
  end if;

  select count(*)::integer,coalesce(jsonb_agg(
       jsonb_build_object(
         'event_id',e.id,'owner_auth_uid',e.owner_auth_uid,
         'client_attempt_id',e.client_attempt_id,
         'assessment_item_id',e.assessment_item_id,
         'approved_binding_id',e.approved_binding_id,
         'manifest_revision_id',e.manifest_revision_id,
         'exam_part_key',e.exam_part_key,
         'administration_date',e.administration_date,
         'item_content_revision',e.item_content_revision,
         'answer_location_revision',e.answer_location_revision,
         'drill_step',e.drill_step,'responded',e.responded,
         'app_elapsed_ms',e.app_elapsed_ms,
         'self_reported_book_ms',e.self_reported_book_ms,
         'started_at',e.started_at,'completed_at',e.completed_at,
         'recorded_at',e.recorded_at,
         'verification_state',e.verification_state,
         'is_correct',g.is_correct,
         'scoring_version',g.scoring_version,
         'graded_at',g.graded_at
       ) order by e.recorded_at desc,e.id desc),'[]'::jsonb)
   into row_count,records
   from (
     select *
     from public.exam_reference_drill_events x
     where x.owner_auth_uid=actor_uid
       and (p_before_recorded_at is null or
         (x.recorded_at,x.id) < (p_before_recorded_at,p_before_event_id))
     order by x.recorded_at desc,x.id desc
     limit p_limit
   ) e
   left join public.exam_reference_drill_grades g
     on g.event_id=e.id
    and g.owner_auth_uid=e.owner_auth_uid
    and g.approved_binding_id=e.approved_binding_id
    and g.drill_step=e.drill_step;
  return jsonb_build_object(
    'scope','reference-practice-all-editions',
    'owner_auth_uid',actor_uid,
    'row_count',row_count,
    'rows',records
  );
end
$page$;

revoke all on function public.exam_reference_drill_export_inventory()
  from public,anon,authenticated;
revoke all on function public.exam_reference_drill_export_page(integer,timestamptz,uuid)
  from public,anon,authenticated;
grant execute on function public.exam_reference_drill_export_inventory()
  to authenticated;
grant execute on function public.exam_reference_drill_export_page(integer,timestamptz,uuid)
  to authenticated;
comment on function public.exam_reference_drill_export_inventory() is
 'Owner-RLS bounded 50k all-edition step inventory and grade-state fingerprint for pre/post verified export.';
comment on function public.exam_reference_drill_export_page(integer,timestamptz,uuid) is
 'Owner-RLS 250-row keyset page of public EXM event+server grade fields; no scoring keys/reviewer data.';

