-- --------------------------------------------------------------------
-- [76/96] Migration: 20261101130000_exm_03_assigned_practice_scoring.sql
-- --------------------------------------------------------------------
-- EXM-03: Backend-only canonical recording for assigned practice sets.
-- Deliberately NOT a public RPC; production consumer/portability release gate
-- requires authenticated server adapter, full export and tested erasure UI.

create table public.exam_part_practice_assignments (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references auth.users(id) on delete cascade,
  target_id uuid not null references public.learning_targets(id),
  target_version_id uuid not null references public.target_versions(id),
  exam_part_key text not null check (exam_part_key ~ '^[a-z][a-z0-9_]{0,127}$'),
  curriculum_root_node_id uuid not null references public.curriculum_nodes(id),
  manifest_revision_id uuid not null
    references public.exam_reference_manifest_revisions(id),
  practice_kind text not null check (practice_kind in ('diagnostic','mock')),
  -- Exact server-issued set: [{id: uuid, sha256: canonical item fingerprint}].
  -- No scoring keys, correct answers or protected material stored here.
  assigned_items jsonb not null check (
    jsonb_typeof(assigned_items)='array'
    and jsonb_array_length(assigned_items) between 6 and 50
  ),
  issued_at timestamptz not null default now(),
  expires_at timestamptz not null,
  constraint exm03_assignment_bounded_expiry
    check (expires_at > issued_at and
      expires_at <= issued_at + interval '2 hours')
);
create index exm03_assignment_owner_idx
  on public.exam_part_practice_assignments(owner_id,issued_at desc);
alter table public.exam_part_practice_assignments enable row level security;
revoke all on public.exam_part_practice_assignments
  from public,anon,authenticated;
grant select,insert,delete on public.exam_part_practice_assignments
  to service_role;
comment on table public.exam_part_practice_assignments is
  'Immutable backend-issued private practice assignment. No client access; exact reviewed item IDs and SHA-256 snapshots only.';

create function public.exm03_reject_assignment_update()
returns trigger language plpgsql security invoker
set search_path=pg_catalog
as $guard$
begin
  raise exception 'Practice assignment cannot be edited after issuance'
    using errcode='42501';
end
$guard$;
revoke all on function public.exm03_reject_assignment_update()
  from public,anon,authenticated;
create trigger exm03_assignment_immutable
  before update on public.exam_part_practice_assignments
  for each row execute function public.exm03_reject_assignment_update();

alter table public.exam_part_practice_attempts
  add column assignment_id uuid not null unique
    references public.exam_part_practice_assignments(id) on delete cascade,
  add column response_sha256 text not null
    check (response_sha256 ~ '^[a-f0-9]{64}$');

create function public.exm03_record_assigned_practice(
  p_assignment_id uuid,
  p_responses jsonb
)
returns jsonb
language plpgsql security definer
set search_path=pg_catalog,public,pg_temp
as $record$
declare
  a public.exam_part_practice_assignments%rowtype;
  existing public.exam_part_practice_attempts%rowtype;
  v_version record;
  v_manifest public.exam_reference_manifest_revisions%rowtype;
  v_item public.assessment_items%rowtype;
  v_answer jsonb;
  v_entry jsonb;
  v_item_id uuid;
  v_ids uuid[] := array[]::uuid[];
  v_hash text;
  v_response_hash text;
  v_questions integer;
  v_correct integer := 0;
  v_distinct_concepts integer;
  v_expected integer;
  v_actual integer;
  v_edition text;
begin
  if p_assignment_id is null or
     jsonb_typeof(p_responses) is distinct from 'object' then
    raise exception 'Exact assigned practice and object responses required'
      using errcode='22023';
  end if;

  v_response_hash := encode(
    sha256(convert_to(p_responses::text,'UTF8')),'hex');

  -- Row lock serializes simultaneous retries for one issued set.
  select * into a from public.exam_part_practice_assignments
    where id=p_assignment_id for update;
  if not found then
    raise exception 'Practice assignment is unavailable'
      using errcode='42501';
  end if;

  -- Exactly-once recording: an identical retry may recover a committed result
  -- (including after expiry); a conflicting replay must never overwrite it.
  select * into existing from public.exam_part_practice_attempts
    where assignment_id=a.id;
  if found then
    if existing.response_sha256 <> v_response_hash then
      raise exception 'Conflicting replay for assigned practice'
        using errcode='23505';
    end if;
    return jsonb_build_object(
      'attempt_id',existing.id,
      'target_version_id',existing.target_version_id,
      'exam_part_key',existing.exam_part_key,
      'question_count',existing.question_count,
      'fully_correct_count',existing.fully_correct_count,
      'partial_count',existing.partial_count,
      'practice_score',existing.practice_score,
      'already_recorded',true,
      'official_exam_result',false
    );
  end if;

  if a.issued_at > now()+interval '1 minute'
     or a.expires_at <= now()
     or a.issued_at < now()-interval '2 hours' then
    raise exception 'Practice assignment is outside its issued window'
      using errcode='42501';
  end if;

  select v.status,v.target_id,v.metadata,
    t.status as target_status,t.is_public
    into v_version
    from public.target_versions v
    join public.learning_targets t on t.id=v.target_id
    where v.id=a.target_version_id;
  if not found or v_version.target_id <> a.target_id
     or v_version.status <> 'published'
     or v_version.target_status <> 'published'
     or v_version.is_public is distinct from true
     or jsonb_typeof(v_version.metadata->'exam_preparation'->'exam_parts')
         is distinct from 'array'
     or not exists (
       select 1 from jsonb_array_elements(
         v_version.metadata->'exam_preparation'->'exam_parts'
       ) as part(value)
       where part.value->>'key'=a.exam_part_key
         and part.value->>'curriculum_root_node_id'
             =a.curriculum_root_node_id::text
     ) or not exists (
       select 1 from public.curriculum_nodes cn
       where cn.id=a.curriculum_root_node_id
         and cn.target_version_id=a.target_version_id
     ) then
    raise exception 'No published matching target/version/part curriculum'
      using errcode='42501';
  end if;

  select * into v_manifest from public.exam_reference_manifest_revisions
    where id=a.manifest_revision_id;
  if not found or v_manifest.target_version_id <> a.target_version_id
     or v_manifest.exam_part_key <> a.exam_part_key
     or v_manifest.publication_status <> 'published'
     or v_manifest.review_status <> 'approved'
     or current_date < v_manifest.effective_from
     or (v_manifest.effective_until is not null
         and current_date > v_manifest.effective_until) then
    raise exception 'No current approved source manifest for this part'
      using errcode='42501';
  end if;

  v_questions := jsonb_array_length(a.assigned_items);
  if v_questions not between 6 and 50 or
     (select count(*) from jsonb_object_keys(p_responses)) <> v_questions
     or pg_column_size(p_responses)>65536 then
    raise exception 'Complete bounded assigned responses required'
      using errcode='22023';
  end if;

  for v_entry in select value from jsonb_array_elements(a.assigned_items)
      as assigned(value)
  loop
    if jsonb_typeof(v_entry) is distinct from 'object'
       or (select count(*) from jsonb_object_keys(v_entry)) <> 2
       or coalesce(v_entry->>'id','') !~
          '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'
       or coalesce(v_entry->>'sha256','') !~ '^[a-f0-9]{64}$' then
      raise exception 'Malformed immutable practice assignment'
        using errcode='22023';
    end if;
    v_item_id := (v_entry->>'id')::uuid;
    if v_item_id=any(v_ids) then
      raise exception 'Assigned questions may not repeat'
        using errcode='22023';
    end if;
    v_ids := array_append(v_ids,v_item_id);

    select * into v_item from public.assessment_items
      where id=v_item_id and origin_target_version_id=a.target_version_id;
    v_hash := public.exam_reference_item_fingerprint(v_item_id);
    if not found or v_item.interaction_type <> 'single_choice'
       or v_hash is null or v_hash <> v_entry->>'sha256'
       or not exists (
         select 1 from public.assessment_item_reference_validity b
         where b.assessment_item_id=v_item_id
           and b.manifest_revision_id=a.manifest_revision_id
           and b.publication_status='published'
           and b.review_status='approved'
           and b.rights_review_status='approved'
           and b.item_content_sha256=v_hash
       ) then
      raise exception 'Assigned item is changed, unreviewed or not version-owned'
        using errcode='42501';
    end if;

    -- An item must have at least one core concept *unique* to the selected
    -- subtree and ALL its mapped concepts must be part-unique core concepts.
    -- Shared concepts may support general readiness, never part identity.
    if not exists (
      with recursive subtree(id) as (
        select id from public.curriculum_nodes
         where id=a.curriculum_root_node_id
           and target_version_id=a.target_version_id
        union
        select child.id from public.curriculum_nodes child
        join subtree parent on child.parent_id=parent.id
        where child.target_version_id=a.target_version_id
      )
      select 1 from public.assessment_item_concepts ic
      where ic.assessment_item_id=v_item_id
        and exists (
          select 1 from public.curriculum_node_concepts nc
          where nc.concept_id=ic.concept_id
            and nc.relevance='core'
            and nc.curriculum_node_id in (select id from subtree)
        )
        and not exists (
          select 1 from public.curriculum_node_concepts nc
          join public.curriculum_nodes outside_node
            on outside_node.id=nc.curriculum_node_id
          where nc.concept_id=ic.concept_id
            and outside_node.target_version_id=a.target_version_id
            and outside_node.id not in (select id from subtree)
        )
    ) or exists (
      with recursive subtree(id) as (
        select id from public.curriculum_nodes
         where id=a.curriculum_root_node_id
           and target_version_id=a.target_version_id
        union
        select child.id from public.curriculum_nodes child
        join subtree parent on child.parent_id=parent.id
        where child.target_version_id=a.target_version_id
      )
      select 1 from public.assessment_item_concepts ic
      where ic.assessment_item_id=v_item_id
        and (
          not exists (
            select 1 from public.curriculum_node_concepts nc
            where nc.concept_id=ic.concept_id and nc.relevance='core'
              and nc.curriculum_node_id in (select id from subtree)
          ) or exists (
            select 1 from public.curriculum_node_concepts nc
            join public.curriculum_nodes outside_node
              on outside_node.id=nc.curriculum_node_id
            where nc.concept_id=ic.concept_id
              and outside_node.target_version_id=a.target_version_id
              and outside_node.id not in (select id from subtree)
          )
        )
    ) then
      raise exception 'Assigned question belongs outside selected part'
        using errcode='42501';
    end if;

    if jsonb_typeof(v_item.response_spec->'options') is distinct from 'array'
       or jsonb_array_length(v_item.response_spec->'options') not between 2 and 10
       or jsonb_typeof(v_item.scoring_spec->'correct_index')
          is distinct from 'number'
       or coalesce(v_item.scoring_spec->>'correct_index','') !~ '^[0-9]+$' then
      raise exception 'Unsupported canonical question scoring'
        using errcode='42501';
    end if;
    v_expected := (v_item.scoring_spec->>'correct_index')::integer;
    if v_expected < 0 or
       v_expected >= jsonb_array_length(v_item.response_spec->'options') then
      raise exception 'Invalid canonical correct index'
        using errcode='42501';
    end if;

    v_answer := p_responses -> (v_item_id::text);
    if v_answer is null or jsonb_typeof(v_answer) is distinct from 'number'
       or (v_answer #>> '{}') !~ '^[0-9]+$' then
      raise exception 'Response must be a single-choice option index'
        using errcode='22023';
    end if;
    v_actual := (v_answer #>> '{}')::integer;
    if v_actual >= jsonb_array_length(v_item.response_spec->'options') then
      raise exception 'Response option index out of bounds'
        using errcode='22023';
    end if;
    if v_actual=v_expected then
      v_correct := v_correct+1;
    end if;
  end loop;

  -- At least three separate core concepts, not six copies of one item.
  with recursive subtree(id) as (
    select id from public.curriculum_nodes
      where id=a.curriculum_root_node_id
        and target_version_id=a.target_version_id
    union
    select n.id from public.curriculum_nodes n
      join subtree p on n.parent_id=p.id
      where n.target_version_id=a.target_version_id
  )
  select count(distinct ic.concept_id) into v_distinct_concepts
  from public.assessment_item_concepts ic
    join public.curriculum_node_concepts nc
      on nc.concept_id=ic.concept_id and nc.relevance='core'
  where ic.assessment_item_id=any(v_ids)
    and nc.curriculum_node_id in (select id from subtree);
  if v_distinct_concepts < 3 then
    raise exception 'Practice requires three distinct reviewed concepts'
      using errcode='42501';
  end if;

  v_edition := encode(sha256(convert_to(
    a.manifest_revision_id::text || ':' || a.assigned_items::text,
    'UTF8')),'hex');

  insert into public.exam_part_practice_attempts (
    owner_id,target_id,target_version_id,exam_part_key,
    curriculum_root_node_id,practice_kind,
    question_count,fully_correct_count,partial_count,
    practice_score,question_edition_fingerprint,assignment_id,response_sha256
  ) values (
    a.owner_id,a.target_id,a.target_version_id,a.exam_part_key,
    a.curriculum_root_node_id,a.practice_kind,
    v_questions,v_correct,0,
    round(v_correct::numeric/v_questions,6),v_edition,a.id,v_response_hash
  ) returning * into existing;

  return jsonb_build_object(
    'attempt_id',existing.id,
    'target_version_id',existing.target_version_id,
    'exam_part_key',existing.exam_part_key,
    'question_count',existing.question_count,
    'fully_correct_count',existing.fully_correct_count,
    'partial_count',existing.partial_count,
    'practice_score',existing.practice_score,
    'already_recorded',false,
    'official_exam_result',false
  );
end
$record$;

revoke all on function public.exm03_record_assigned_practice(uuid,jsonb)
  from public,anon,authenticated;
grant execute on function public.exm03_record_assigned_practice(uuid,jsonb)
  to service_role;
comment on function public.exm03_record_assigned_practice(uuid,jsonb) is
  'Service-role only, transactional, idempotent canonical single-choice scoring of preassigned, unchanged, approved part-specific items. Never an official exam score. Not exposed to learner clients.';


-- Erasure must remove the underlying issued assignment as well as its scored
-- row. Otherwise deleting the result and retrying the same assignment would
-- recreate "erased" history. Replace unrestricted owner DELETE with one
-- transaction that cascades assignment -> attempt, then verifies emptiness.
revoke delete on public.exam_part_practice_attempts from authenticated;
drop policy if exists exm03_attempt_delete_owner
  on public.exam_part_practice_attempts;

create function public.exm03_erase_part_attempts(
  p_target_version_id uuid,
  p_exam_part_key text
)
returns integer
language plpgsql security definer
set search_path=pg_catalog,public,pg_temp
as $erase$
declare
  actor uuid;
  deleted_count integer;
begin
  actor := (select auth.uid());
  if actor is null or
     (select (auth.jwt()->>'is_anonymous')::boolean)
        is distinct from false or
     p_target_version_id is null or
     p_exam_part_key is null or
     p_exam_part_key !~ '^[a-z][a-z0-9_]{0,127}$' then
    raise exception 'Permanent account and exact exam part required'
      using errcode='42501';
  end if;

  -- Atomic erasure of both completed and unused assignments for that part.
  -- The attempt FK uses ON DELETE CASCADE, preventing any recorded retry.
  with removed as (
    delete from public.exam_part_practice_assignments a
    where a.owner_id=actor
      and a.target_version_id=p_target_version_id
      and a.exam_part_key=p_exam_part_key
    returning a.id
  )
  select count(*) into deleted_count from removed;

  if exists (
    select 1 from public.exam_part_practice_attempts t
      where t.owner_id=actor
        and t.target_version_id=p_target_version_id
        and t.exam_part_key=p_exam_part_key
  ) or exists (
    select 1 from public.exam_part_practice_assignments a
      where a.owner_id=actor
        and a.target_version_id=p_target_version_id
        and a.exam_part_key=p_exam_part_key
  ) then
    raise exception 'Part history erasure did not complete'
      using errcode='40001';
  end if;
  return deleted_count;
end
$erase$;
revoke all on function public.exm03_erase_part_attempts(uuid,text)
  from public,anon,authenticated;
grant execute on function public.exm03_erase_part_attempts(uuid,text)
  to authenticated;
comment on function public.exm03_erase_part_attempts(uuid,text) is
  'Permanent owner-only atomic exact-part erasure of assignments and attempt history, with no replay re-creation. Requires confirmation in future UI.';

INSERT INTO supabase_migrations.schema_migrations (version, name) VALUES ('20261101130000', 'exm_03_assigned_practice_scoring') ON CONFLICT (version) DO NOTHING;

-- --------------------------------------------------------------------
-- [77/96] Migration: 20261101140000_exm_03_authenticated_assignment_issuer.sql
-- --------------------------------------------------------------------
-- EXM-03: Authenticated, server-assigned educational practice questions.
-- Only the database chooses reviewed canonical items; clients specify solely
-- an exact published target version and exam part. No answer keys are returned.
-- Submission and scoring remain service-role-only pending privacy release gates.

create function public.exm03_issue_assigned_practice(
  p_target_version_id uuid,
  p_exam_part_key text
)
returns jsonb
language plpgsql volatile security definer
set search_path=pg_catalog,public,pg_temp
as $issue$
declare
  actor_id uuid;
  session_id uuid;
  profile jsonb;
  v_target_id uuid;
  v_root uuid;
  v_manifest uuid;
  v_count integer;
  v_distinct_concepts integer;
  v_assigned jsonb;
  v_visible jsonb;
  v_assignment uuid;
  v_expiry timestamptz;
begin
  -- PostgREST validates the JWT signature; the issuer additionally checks
  -- permanent-account status and the exact still-live Auth session.
  actor_id := (select auth.uid());
  if actor_id is null
     or (select auth.jwt()->>'role') is distinct from 'authenticated'
     or (select (auth.jwt()->>'is_anonymous')::boolean) is distinct from false
     or nullif(auth.jwt()->>'session_id','') is null
     or (auth.jwt()->>'session_id') !~
       '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
     or p_target_version_id is null
     or p_exam_part_key is null
     or p_exam_part_key !~ '^[a-z][a-z0-9_]{0,127}$' then
    raise exception 'Permanent authenticated session and exact part required'
      using errcode='42501';
  end if;
  session_id := (auth.jwt()->>'session_id')::uuid;
  if not exists (
    select 1 from auth.sessions s
    where s.id=session_id and s.user_id=actor_id
      and (s.not_after is null or s.not_after > now())
  ) then
    raise exception 'Authentication session is no longer active'
      using errcode='42501';
  end if;

  select v.target_id,v.metadata into v_target_id,profile
  from public.target_versions v
  join public.learning_targets t on t.id=v.target_id
  where v.id=p_target_version_id
    and v.status='published'
    and t.status='published'
    and t.is_public=true;
  if v_target_id is null
     or jsonb_typeof(profile->'exam_preparation'->'exam_parts')
         is distinct from 'array' then
    raise exception 'Published version with configured parts required'
      using errcode='42501';
  end if;
  if (select count(*) from jsonb_array_elements(
        profile->'exam_preparation'->'exam_parts') as part(value)
      where part.value->>'key'=p_exam_part_key) <> 1 then
    raise exception 'Exactly one configured exam-part key required'
      using errcode='42501';
  end if;

  select cn.id into v_root
  from jsonb_array_elements(profile->'exam_preparation'->'exam_parts')
    as part(value)
  join public.curriculum_nodes cn
    on cn.id::text=part.value->>'curriculum_root_node_id'
   and cn.target_version_id=p_target_version_id
  where part.value->>'key'=p_exam_part_key;
  if v_root is null then
    raise exception 'Exam part root must belong to this version'
      using errcode='42501';
  end if;

  select m.id into v_manifest
  from public.exam_reference_manifest_revisions m
  where m.target_version_id=p_target_version_id
    and m.exam_part_key=p_exam_part_key
    and m.publication_status='published'
    and m.review_status='approved'
    and current_date>=m.effective_from
    and (m.effective_until is null or current_date<=m.effective_until)
  order by m.revision desc
  limit 1;
  if v_manifest is null then
    raise exception 'No effective approved reference manifest for part'
      using errcode='42501';
  end if;

  -- Per-owner advisory lock prevents concurrent issuance from outrunning
  -- the quota. Failed issuance rolls everything back without leaking keys.
  perform pg_advisory_xact_lock(hashtextextended(actor_id::text, 61503));
  select count(*) into v_count
  from public.exam_part_practice_assignments a
  where a.owner_id=actor_id and a.issued_at>now()-interval '24 hours';
  if v_count>=12 then
    raise exception 'Practice issuance quota reached'
      using errcode='42501';
  end if;
  select count(*) into v_count
  from public.exam_part_practice_assignments a
  where a.owner_id=actor_id
    and a.expires_at>now()
    and not exists (
      select 1 from public.exam_part_practice_attempts t
      where t.assignment_id=a.id
    );
  if v_count>=2 then
    raise exception 'Finish or expire existing practice assignments first'
      using errcode='42501';
  end if;

  -- SQL owns question selection. Candidate qualification mirrors the
  -- protected grader: original independently approved published bindings,
  -- current unchanged item hash, supported canonical single choice, and all
  -- concepts exclusively core within the selected subtree (not shared).
  for v_pick in 1..12 loop
    with recursive part_nodes(id) as (
      select v_root
      union
      select n.id from public.curriculum_nodes n
      join part_nodes p on n.parent_id=p.id
      where n.target_version_id=p_target_version_id
    ),
    eligible as (
      select i.id, public.exam_reference_item_fingerprint(i.id) as sha
      from public.assessment_items i
      join public.assessment_item_reference_validity b
        on b.assessment_item_id=i.id
       and b.manifest_revision_id=v_manifest
       and b.publication_status='published'
       and b.review_status='approved'
       and b.rights_review_status='approved'
      where i.origin_target_version_id=p_target_version_id
        and i.interaction_type='single_choice'
        and i.response_spec ? 'options'
        and jsonb_typeof(i.response_spec->'options')='array'
        and jsonb_array_length(i.response_spec->'options') between 2 and 10
        and i.scoring_spec ? 'correct_index'
        and jsonb_typeof(i.scoring_spec->'correct_index')='number'
        and (i.scoring_spec->>'correct_index') ~ '^[0-9]+$'
        and (i.scoring_spec->>'correct_index')::integer
              < jsonb_array_length(i.response_spec->'options')
        and b.item_content_sha256 =
              public.exam_reference_item_fingerprint(i.id)
        and exists (
          select 1 from public.assessment_item_concepts ic
          where ic.assessment_item_id=i.id
            and exists (
              select 1 from public.curriculum_node_concepts nc
              where nc.concept_id=ic.concept_id and nc.relevance='core'
                and nc.curriculum_node_id in (select id from part_nodes)
            )
        )
        and not exists (
          select 1 from public.assessment_item_concepts ic
          where ic.assessment_item_id=i.id
            and (
              not exists (
                select 1 from public.curriculum_node_concepts nc
                where nc.concept_id=ic.concept_id and nc.relevance='core'
                  and nc.curriculum_node_id in (select id from part_nodes)
              ) or exists (
                select 1 from public.curriculum_node_concepts nc
                join public.curriculum_nodes outsider
                  on outsider.id=nc.curriculum_node_id
                where nc.concept_id=ic.concept_id
                  and outsider.target_version_id=p_target_version_id
                  and outsider.id not in (select id from part_nodes)
              )
            )
        )
      group by i.id
    ),
    selection as (
      select id,sha from eligible order by random() limit 6
    )
    select jsonb_agg(jsonb_build_object('id',id,'sha256',sha)
                     order by id),
           count(*) into v_assigned,v_count
    from selection;

    if v_count<>6 then
      raise exception 'Not enough verified part-specific questions'
        using errcode='42501';
    end if;
    select count(distinct ic.concept_id) into v_distinct_concepts
    from jsonb_array_elements(v_assigned) as chosen(value)
    join public.assessment_item_concepts ic
      on ic.assessment_item_id=(chosen.value->>'id')::uuid;
    exit when v_distinct_concepts>=3;
  end loop;
  if v_distinct_concepts<3 then
    raise exception 'Part practice requires three distinct core concepts'
      using errcode='42501';
  end if;

  v_expiry := now()+interval '90 minutes';
  insert into public.exam_part_practice_assignments (
    owner_id,target_id,target_version_id,exam_part_key,
    curriculum_root_node_id,manifest_revision_id,practice_kind,
    assigned_items,issued_at,expires_at
  ) values (
    actor_id,v_target_id,p_target_version_id,p_exam_part_key,
    v_root,v_manifest,'diagnostic',
    v_assigned,now(),v_expiry
  ) returning id into v_assignment;

  -- Do not return scoring_spec, explanations, private source bindings, hashes
  -- or answers. Only safe visible options and exact question IDs are returned.
  select jsonb_agg(jsonb_build_object(
    'id',i.id,
    'interaction_type',i.interaction_type,
    'prompt',i.prompt,
    'response_spec',jsonb_build_object('options',i.response_spec->'options')
  ) order by chosen.ordinality)
  into v_visible
  from jsonb_array_elements(v_assigned) with ordinality as chosen(value, ordinality)
  join public.assessment_items i
    on i.id=(chosen.value->>'id')::uuid;

  return jsonb_build_object(
    'assignment_id',v_assignment,
    'target_version_id',p_target_version_id,
    'exam_part_key',p_exam_part_key,
    'expires_at',v_expiry,
    'practice_only',true,
    'question_count',6,
    'questions',v_visible
  );
end
$issue$;

revoke all on function public.exm03_issue_assigned_practice(uuid,text)
  from public,anon,authenticated;
grant execute on function public.exm03_issue_assigned_practice(uuid,text)
  to authenticated;
comment on function public.exm03_issue_assigned_practice(uuid,text) is
  'Permanent live-session owner-only, quota-bound server-assigned reviewed six-item part diagnostic. Returns safe questions only. Grading remains private; not an official exam.';

INSERT INTO supabase_migrations.schema_migrations (version, name) VALUES ('20261101140000', 'exm_03_authenticated_assignment_issuer') ON CONFLICT (version) DO NOTHING;

-- --------------------------------------------------------------------
-- [78/96] Migration: 20261101150000_exm_03_authenticated_submit_protected_items.sql
-- --------------------------------------------------------------------
-- EXM-03: secure the browser-to-canonical-scorer boundary and prevent
-- protected independently approved exam answer keys leaking through legacy
-- assessment_items SELECT('*') policies.
-- No write is performed against hosted learner data by committing this file.

-- The issuer inserts assignments without providing this column. The default
-- binds newly issued learner practice to the same verified JWT session.
-- Synthetic/backend-only assignments have null; public submit fails closed.
alter table public.exam_part_practice_assignments
  add column issued_session_id uuid
    default (nullif(auth.jwt()->>'session_id',''))::uuid;

create index exm03_assignment_owner_session_idx
 on public.exam_part_practice_assignments
 (owner_id,issued_session_id,issued_at desc);

create function public.exm03_submit_assigned_practice(
  p_assignment_id uuid,
  p_responses jsonb
)
returns jsonb
language plpgsql volatile security definer
set search_path=pg_catalog,public,pg_temp
as $submit$
declare
  actor_id uuid;
  active_session uuid;
  matching_assignment_id uuid;
  result jsonb;
begin
  actor_id := (select auth.uid());
  if actor_id is null
     or (auth.jwt()->>'role') is distinct from 'authenticated'
     or (auth.jwt()->>'is_anonymous') is distinct from 'false'
     or coalesce(auth.jwt()->>'session_id','') !~
          '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
     or p_assignment_id is null
     or p_responses is null
     or jsonb_typeof(p_responses) is distinct from 'object'
     or pg_column_size(p_responses) > 65536 then
    raise exception 'Live permanent session and bounded responses required'
      using errcode='42501';
  end if;
  active_session := (auth.jwt()->>'session_id')::uuid;

  if not exists (
    select 1 from auth.sessions s
    where s.id=active_session and s.user_id=actor_id
      and (s.not_after is null or s.not_after>now())
  ) then
    raise exception 'Authentication session is no longer active'
      using errcode='42501';
  end if;

  -- Neither the user ID nor the issued session may be client-provided.
  -- Assignment locks in the canonical scorer serialize concurrent retries.
  select a.id into matching_assignment_id
  from public.exam_part_practice_assignments a
  where a.id=p_assignment_id
    and a.owner_id=actor_id
    and a.issued_session_id=active_session;
  if matching_assignment_id is null then
    raise exception 'Practice assignment does not belong to this session'
      using errcode='42501';
  end if;

  -- No untrusted grader, question IDs, correct answer, version, or score
  -- arguments are accepted. This function inherits the backend's protected
  -- canonical scorer and all of its review/replay validations.
  result := public.exm03_record_assigned_practice(
    p_assignment_id,p_responses);

  -- Complete writes are still subject to same-session verification.
  if not exists (
    select 1 from auth.sessions s
    where s.id=active_session and s.user_id=actor_id
      and (s.not_after is null or s.not_after>now())
  ) then
    raise exception 'Session ended during practice submission'
      using errcode='42501';
  end if;
  return result;
end
$submit$;

revoke all on function public.exm03_submit_assigned_practice(uuid,jsonb)
  from public,anon,authenticated;
grant execute on function public.exm03_submit_assigned_practice(uuid,jsonb)
  to authenticated;
comment on function public.exm03_submit_assigned_practice(uuid,jsonb) is
 'Exact live-session owner-bound educational practice submission. Calls private canonical scorer; identity from verified JWT only. Never an official examination result.';

-- Existing learning activities consume assessment_items directly.
-- Approved EXM-02A question bindings have a protected scoring_spec; exclude
-- precisely those items from direct anon/authenticated table reads, including
-- permissive owner and lesson policies. Trusted canonical issuer is the safe
-- read path, while the private grader retains privileged access.
create function public.exm03_has_protected_binding(p_item_id uuid)
returns boolean language sql stable security definer
set search_path=pg_catalog,public,pg_temp
as $private$
  select exists (
    select 1 from public.assessment_item_reference_validity b
    where b.assessment_item_id=p_item_id
      and b.publication_status='published'
      and b.review_status='approved'
      and b.rights_review_status='approved'
  );
$private$;
revoke all on function public.exm03_has_protected_binding(uuid)
  from public,anon,authenticated;
grant execute on function public.exm03_has_protected_binding(uuid)
  to anon,authenticated;

create policy exm03_no_direct_read_of_approved_answers
 on public.assessment_items
 as restrictive for select to anon,authenticated
 using (not public.exm03_has_protected_binding(id));

comment on policy exm03_no_direct_read_of_approved_answers
 on public.assessment_items is
 'Prevent direct learner or anon scoring_spec exposure for independently approved published exam items; read their safe projection via the authenticated practice issuer. Other legacy items remain unaffected.';

-- Approved items must not bypass through a normal SELECT(*) or
-- owner/lesson version visibility policy. No client editor can read their
-- private canonical scoring rubric through this table.

-- An item response_spec may contain richer option objects. Returning that
-- JSON from the issuer could disclose embedded correctness flags. Require
-- ordinary text-only choices for every backend-issued v1 single-choice set.
create function public.exm03_safe_visible_choices(p_options jsonb)
returns boolean language plpgsql immutable security invoker
set search_path=pg_catalog
as $choices$
declare
  choice jsonb;
begin
  if jsonb_typeof(p_options) is distinct from 'array'
     or jsonb_array_length(p_options) not between 2 and 10 then
    return false;
  end if;
  for choice in select value from jsonb_array_elements(p_options) loop
    if jsonb_typeof(choice) is distinct from 'string'
       or length(btrim(choice #>> '{}')) not between 1 and 1000 then
      return false;
    end if;
  end loop;
  return true;
end
$choices$;
revoke all on function public.exm03_safe_visible_choices(jsonb)
  from public,anon,authenticated;
grant execute on function public.exm03_safe_visible_choices(jsonb)
  to service_role;

create function public.exm03_guard_visible_assignment()
returns trigger language plpgsql security definer
set search_path=pg_catalog,public,pg_temp
as $guard_choices$
declare
  q jsonb;
  canonical_options jsonb;
begin
  for q in select value from jsonb_array_elements(new.assigned_items) loop
    if (q->>'id') is null or
       coalesce(q->>'id','') !~
       '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' then
      raise exception 'Invalid assigned item identifier'
        using errcode='42501';
    end if;
    select i.response_spec->'options' into canonical_options
      from public.assessment_items i where i.id=(q->>'id')::uuid;
    if not public.exm03_safe_visible_choices(canonical_options) then
      raise exception 'Exam question options must be reviewed plain text'
        using errcode='42501';
    end if;
  end loop;
  return new;
end
$guard_choices$;
revoke all on function public.exm03_guard_visible_assignment()
  from public,anon,authenticated;
create trigger exm03_plain_text_issued_questions
before insert on public.exam_part_practice_assignments
for each row execute function public.exm03_guard_visible_assignment();

comment on function public.exm03_safe_visible_choices(jsonb) is
 'Protect public practice question projection from nested object options with correct-answer flags; only bounded, nonempty text choices may be issued.';

INSERT INTO supabase_migrations.schema_migrations (version, name) VALUES ('20261101150000', 'exm_03_authenticated_submit_protected_items') ON CONFLICT (version) DO NOTHING;

-- --------------------------------------------------------------------
-- [79/96] Migration: 20261101160000_exm_03_account_practice_portability.sql
-- --------------------------------------------------------------------
-- EXM-03: account-wide educational practice portability for bounded histories.
-- Never grants direct access to private assignments, scoring rubrics or responses.
-- This is a DRAFT migration only; no hosted SQL is changed by this commit.

-- Only an active permanent Supabase Auth session may export or erase.
create function public.exm03_portability_owner()
returns uuid language plpgsql stable security definer
set search_path=pg_catalog,public,pg_temp
as $owner$
declare
  v_owner uuid := (select auth.uid());
  v_session uuid;
begin
  if v_owner is null
     or (auth.jwt()->>'role') is distinct from 'authenticated'
     or (auth.jwt()->>'is_anonymous') is distinct from 'false'
     or coalesce(auth.jwt()->>'session_id','') !~
       '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' then
    raise exception 'A live permanent account session is required'
      using errcode='42501';
  end if;
  v_session := (auth.jwt()->>'session_id')::uuid;
  if not exists (select 1 from auth.sessions s
                 where s.id=v_session and s.user_id=v_owner
                 and (s.not_after is null or s.not_after>now())) then
    raise exception 'Practice portability session has ended'
      using errcode='42501';
  end if;
  return v_owner;
end
$owner$;
revoke all on function public.exm03_portability_owner()
  from public,anon,authenticated;

-- Existing R1-R4 events, newly graded receipts, pending assignments and
-- completed EXM-03 attempts all contribute to the same inventory token.
-- Fail closed beyond explicit bounds. Never call this a complete account
-- export of unrelated LearningApp data.
create function public.exm03_account_practice_inventory()
returns jsonb language plpgsql stable security definer
set search_path=pg_catalog,public,pg_temp
as $inventory$
declare
  v_owner uuid := public.exm03_portability_owner();
  v_events bigint;
  v_grades bigint;
  v_assignments bigint;
  v_attempts bigint;
  v_reference_digest text;
  v_part_digest text;
begin
  select count(*),count(g.event_id),
    md5(coalesce(string_agg(
      e.id::text||':'||coalesce(g.is_correct::text,'ungraded')||':'||
      coalesce(g.scoring_version::text,'none')||':'||
      coalesce(g.graded_at::text,'none'),
      ',' order by e.id),'')) into v_events,v_grades,v_reference_digest
  from public.exam_reference_drill_events e
  left join public.exam_reference_drill_grades g
    on g.event_id=e.id and g.owner_auth_uid=e.owner_auth_uid
    and g.approved_binding_id=e.approved_binding_id
    and g.drill_step=e.drill_step
  where e.owner_auth_uid=v_owner;

  select count(*),count(t.id),
    md5(coalesce(string_agg(
      a.id::text||':'||coalesce(t.id::text,'unscored')||':'||
      coalesce(t.response_sha256,'none')||':'||
      coalesce(t.practice_score::text,'none'),
      ',' order by a.id),'')) into v_assignments,v_attempts,v_part_digest
  from public.exam_part_practice_assignments a
  left join public.exam_part_practice_attempts t
    on t.assignment_id=a.id and t.owner_id=a.owner_id
  where a.owner_id=v_owner;

  if v_events>5000 or v_assignments>5000 then
    raise exception 'Combined export/erasure size exceeds reviewed bound'
      using errcode='54000';
  end if;
  return jsonb_build_object(
    'scope','exm-educational-practice-all-editions-v1',
    'owner_id',v_owner,
    'reference_events',v_events,
    'reference_grades',v_grades,
    'part_assignments',v_assignments,
    'part_attempts',v_attempts,
    'snapshot_fingerprint',md5(
      v_owner::text||':'||v_reference_digest||':'||v_part_digest),
    'bound_per_store',5000
  );
end
$inventory$;
revoke all on function public.exm03_account_practice_inventory()
  from public,anon,authenticated;
grant execute on function public.exm03_account_practice_inventory()
  to authenticated;

-- STABLE read: reference rows and EXM-03 rows come from the same statement
-- snapshot. The older EXM-02B archive alone does NOT include EXM-03.
create function public.exm03_account_practice_export()
returns jsonb language plpgsql stable security definer
set search_path=pg_catalog,public,pg_temp
as $export$
declare
  v_owner uuid := public.exm03_portability_owner();
  v_inventory jsonb;
  v_reference jsonb;
  v_parts jsonb;
begin
  v_inventory := public.exm03_account_practice_inventory();
  v_reference := public.exam_reference_drill_account_export(5000);
  select coalesce(jsonb_agg(jsonb_build_object(
    'assignment_id',a.id,
    'target_id',a.target_id,
    'target_version_id',a.target_version_id,
    'exam_part_key',a.exam_part_key,
    'curriculum_root_node_id',a.curriculum_root_node_id,
    'manifest_revision_id',a.manifest_revision_id,
    'practice_kind',a.practice_kind,
    'issued_at',a.issued_at,
    'expires_at',a.expires_at,
    'attempt',case when t.id is null then null else jsonb_build_object(
      'attempt_id',t.id,
      'completed_at',t.completed_at,
      'question_count',t.question_count,
      'fully_correct_count',t.fully_correct_count,
      'partial_count',t.partial_count,
      'practice_score',t.practice_score,
      'question_edition_fingerprint',t.question_edition_fingerprint,
      'official_exam_result',false
    ) end
  ) order by a.issued_at desc,a.id desc),'[]'::jsonb)
  into v_parts
  from public.exam_part_practice_assignments a
  left join public.exam_part_practice_attempts t
    on t.assignment_id=a.id and t.owner_id=a.owner_id
  where a.owner_id=v_owner;

  if jsonb_array_length(v_parts)<>(v_inventory->>'part_assignments')::integer
     or (v_reference->>'record_count')::integer<>
         (v_inventory->>'reference_events')::integer then
    raise exception 'Practice export inventory changed during collection'
      using errcode='40001';
  end if;
  return jsonb_build_object(
    'format','learningapp-exm-combined-practice-v1',
    'scope','educational-practice-history-not-entire-account',
    'owner_id',v_owner,
    'generated_at',now(),
    'snapshot_consistency','single-stable-rpc-statement',
    'inventory',v_inventory,
    'reference_practice',v_reference,
    'part_practice',v_parts,
    'includes_unsubmitted_assignments',true,
    'official_exam_result',false
  );
end
$export$;
revoke all on function public.exm03_account_practice_export()
  from public,anon,authenticated;
grant execute on function public.exm03_account_practice_export()
  to authenticated;

-- Coordinate future R1-R4 inserts with this account's erasure lock.
-- Does not bypass existing RLS/validated-content trigger.
create function public.exm03_reference_insert_owner_lock()
returns trigger language plpgsql security invoker
set search_path=pg_catalog,public,pg_temp
as $lock$
begin
  perform pg_advisory_xact_lock(
    hashtextextended(new.owner_auth_uid::text,61503));
  return new;
end
$lock$;
revoke all on function public.exm03_reference_insert_owner_lock()
  from public,anon,authenticated;
create trigger exm03_reference_insert_owner_lock
  before insert on public.exam_reference_drill_events
  for each row execute function public.exm03_reference_insert_owner_lock();

-- Caller must view a fresh inventory, review the counts and enter the
-- literal phrase. Entire SQL transaction rolls back if anything differs.
-- No automatic erasure, scheduling or retention TTL.
create function public.exm03_erase_account_practice(
  p_expected_events integer,
  p_expected_assignments integer,
  p_expected_attempts integer,
  p_expected_fingerprint text,
  p_confirmation text
)
returns jsonb language plpgsql volatile security definer
set search_path=pg_catalog,public,pg_temp
as $erase$
declare
  v_owner uuid := public.exm03_portability_owner();
  v_current jsonb;
  v_deleted_events integer;
  v_deleted_assignments integer;
  v_remaining_events bigint;
  v_remaining_assignments bigint;
  v_remaining_grades bigint;
  v_remaining_attempts bigint;
begin
  if p_confirmation is distinct from 'DELETE ALL EXAM PRACTICE'
     or p_expected_events is null or p_expected_events<0
     or p_expected_assignments is null or p_expected_assignments<0
     or p_expected_attempts is null or p_expected_attempts<0
     or coalesce(p_expected_fingerprint,'') !~ '^[a-f0-9]{32}$' then
    raise exception 'Preview and explicit practice-history confirmation required'
      using errcode='22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(v_owner::text,61503));
  v_current := public.exm03_account_practice_inventory();
  if (v_current->>'reference_events')::integer<>p_expected_events
     or (v_current->>'part_assignments')::integer<>p_expected_assignments
     or (v_current->>'part_attempts')::integer<>p_expected_attempts
     or v_current->>'snapshot_fingerprint'<>p_expected_fingerprint then
    raise exception 'History changed; obtain and confirm a fresh inventory'
      using errcode='40001';
  end if;

  delete from public.exam_reference_drill_events e
    where e.owner_auth_uid=v_owner;
  get diagnostics v_deleted_events = row_count;
  delete from public.exam_part_practice_assignments a
    where a.owner_id=v_owner;
  get diagnostics v_deleted_assignments = row_count;
  if v_deleted_events<>p_expected_events
     or v_deleted_assignments<>p_expected_assignments then
    raise exception 'Incomplete practice deletion; all work rolled back'
      using errcode='40001';
  end if;

  select count(*) into v_remaining_events
    from public.exam_reference_drill_events where owner_auth_uid=v_owner;
  select count(*) into v_remaining_grades
    from public.exam_reference_drill_grades where owner_auth_uid=v_owner;
  select count(*) into v_remaining_assignments
    from public.exam_part_practice_assignments where owner_id=v_owner;
  select count(*) into v_remaining_attempts
    from public.exam_part_practice_attempts where owner_id=v_owner;
  if v_remaining_events<>0 or v_remaining_grades<>0
     or v_remaining_assignments<>0 or v_remaining_attempts<>0 then
    raise exception 'Dependent practice data remains; transaction rolled back'
      using errcode='40001';
  end if;
  perform public.exm03_portability_owner();
  return jsonb_build_object(
    'scope','exm-educational-practice-all-editions-v1',
    'owner_id',v_owner,
    'deleted_reference_events',v_deleted_events,
    'deleted_part_assignments',v_deleted_assignments,
    'remaining_reference_events',v_remaining_events,
    'remaining_reference_grades',v_remaining_grades,
    'remaining_part_assignments',v_remaining_assignments,
    'remaining_part_attempts',v_remaining_attempts,
    'irreversible',true
  );
end
$erase$;
revoke all on function public.exm03_erase_account_practice(integer,integer,integer,text,text)
  from public,anon,authenticated;
grant execute on function public.exm03_erase_account_practice(integer,integer,integer,text,text)
  to authenticated;

comment on function public.exm03_account_practice_export() is
 'Owner live-session, complete small-history archive of saved R1-R4 events/grades and EXM-03 assignments/attempts. 5000 per-store hard bound; private keys and responses excluded.';
comment on function public.exm03_erase_account_practice(integer,integer,integer,text,text) is
 'Explicit fingerprint-confirmed atomic erasure across R1-R4 reference events/grades and EXM-03 assignments/attempts. Disallows stale previews and oversized histories.';

INSERT INTO supabase_migrations.schema_migrations (version, name) VALUES ('20261101160000', 'exm_03_account_practice_portability') ON CONFLICT (version) DO NOTHING;

-- --------------------------------------------------------------------
-- [80/96] Migration: 20261101170000_exm_03_verified_large_combined_export.sql
-- --------------------------------------------------------------------
-- EXM-03: verified 50k per-store inventory and private keyset page for
-- issued assignments.  This forward migration does not change prior files.
-- Combined export across separate requests must compare pre/post inventory
-- digests and reject partial collections.  50k remains an explicit hard cap.
create or replace function public.exm03_account_practice_inventory()
returns jsonb language plpgsql stable security definer
set search_path=pg_catalog,public,pg_temp
as $inventory$
declare
  v_owner uuid := public.exm03_portability_owner();
  v_events bigint;
  v_grades bigint;
  v_assignments bigint;
  v_attempts bigint;
  v_reference_digest text;
  v_part_digest text;
begin
  select count(*),count(g.event_id),
    md5(coalesce(string_agg(
      e.id::text||':'||coalesce(g.is_correct::text,'ungraded')||':'||
      coalesce(g.scoring_version::text,'none')||':'||
      coalesce(g.graded_at::text,'none'),
      ',' order by e.id),'')) into v_events,v_grades,v_reference_digest
  from public.exam_reference_drill_events e
  left join public.exam_reference_drill_grades g
    on g.event_id=e.id and g.owner_auth_uid=e.owner_auth_uid
    and g.approved_binding_id=e.approved_binding_id
    and g.drill_step=e.drill_step
  where e.owner_auth_uid=v_owner;

  select count(*),count(t.id),
    md5(coalesce(string_agg(
      a.id::text||':'||coalesce(t.id::text,'unscored')||':'||
      coalesce(t.response_sha256,'none')||':'||
      coalesce(t.practice_score::text,'none'),
      ',' order by a.id),'')) into v_assignments,v_attempts,v_part_digest
  from public.exam_part_practice_assignments a
  left join public.exam_part_practice_attempts t
    on t.assignment_id=a.id and t.owner_id=a.owner_id
  where a.owner_id=v_owner;

  if v_events>50000 or v_assignments>50000 then
    raise exception 'Combined export/erasure size exceeds reviewed bound'
      using errcode='54000';
  end if;
  return jsonb_build_object(
    'scope','exm-educational-practice-all-editions-v1',
    'owner_id',v_owner,
    'reference_events',v_events,
    'reference_grades',v_grades,
    'part_assignments',v_assignments,
    'part_attempts',v_attempts,
    'snapshot_fingerprint',md5(
      v_owner::text||':'||v_reference_digest||':'||v_part_digest),
    'bound_per_store',50000
  );
end
$inventory$;
comment on function public.exm03_account_practice_inventory() is
 'Authenticated, live-session owner inventory across graded R1-R4 and assigned EXM-03 practice; 50k per store bound, stable fingerprint.';

create index if not exists exm03_assignment_owner_page_idx
  on public.exam_part_practice_assignments(owner_id,issued_at desc,id desc);

create function public.exm03_account_part_export_page(
  p_limit integer default 250,
  p_before_issued_at timestamptz default null,
  p_before_assignment_id uuid default null
)
returns jsonb language plpgsql stable security definer
set search_path=pg_catalog,public,pg_temp
as $page$
declare
  v_owner uuid := public.exm03_portability_owner();
  v_rows jsonb;
  v_count integer;
begin
  if p_limit is null or p_limit<1 or p_limit>250
     or (p_before_issued_at is null) <> (p_before_assignment_id is null) then
    raise exception 'Invalid EXM assignment export page cursor'
      using errcode='22023';
  end if;

  select count(*)::integer,coalesce(jsonb_agg(jsonb_build_object(
    'assignment_id',a.id,
    'target_id',a.target_id,
    'target_version_id',a.target_version_id,
    'exam_part_key',a.exam_part_key,
    'curriculum_root_node_id',a.curriculum_root_node_id,
    'manifest_revision_id',a.manifest_revision_id,
    'practice_kind',a.practice_kind,
    'issued_at',a.issued_at,
    'expires_at',a.expires_at,
    'attempt',case when t.id is null then null else jsonb_build_object(
      'attempt_id',t.id,
      'completed_at',t.completed_at,
      'question_count',t.question_count,
      'fully_correct_count',t.fully_correct_count,
      'partial_count',t.partial_count,
      'practice_score',t.practice_score,
      'question_edition_fingerprint',t.question_edition_fingerprint,
      'official_exam_result',false
    ) end
  ) order by a.issued_at desc,a.id desc),'[]'::jsonb)
  into v_count,v_rows
  from (
    select *
    from public.exam_part_practice_assignments x
    where x.owner_id=v_owner
      and (p_before_issued_at is null
        or (x.issued_at,x.id)<(p_before_issued_at,p_before_assignment_id))
    order by x.issued_at desc,x.id desc
    limit p_limit
  ) a
  left join public.exam_part_practice_attempts t
    on t.assignment_id=a.id and t.owner_id=a.owner_id;

  perform public.exm03_portability_owner();
  return jsonb_build_object(
    'scope','exm-educational-practice-all-editions-v1',
    'owner_id',v_owner,
    'row_count',v_count,
    'rows',v_rows
  );
end
$page$;
revoke all on function public.exm03_account_part_export_page(integer,timestamptz,uuid)
  from public,anon,authenticated;
grant execute on function public.exm03_account_part_export_page(integer,timestamptz,uuid)
  to authenticated;
comment on function public.exm03_account_part_export_page(integer,timestamptz,uuid) is
 'Private, permanent live-session owner-scoped EXM-03 assignment + scored summary page (<=250); no answers, item lists, session data or scoring tokens.';

INSERT INTO supabase_migrations.schema_migrations (version, name) VALUES ('20261101170000', 'exm_03_verified_large_combined_export') ON CONFLICT (version) DO NOTHING;

-- --------------------------------------------------------------------
-- [81/96] Migration: 20261101180000_exm_03_release_hardening_and_date_eligibility.sql
-- --------------------------------------------------------------------
-- =============================================================================
-- Migration 81: EXM-03 Release Hardening, Date-Specific Eligibility & RLS Defenses
--
-- Remediates release gates:
-- 1. Binds assigned practice issuance and canonical scoring to the learner's actual
--    exam administration date, replacing invalid current_date assumptions.
-- 2. Hardens public.exm03_has_protected_binding so retired approved items permanently
--    retain restrictive RLS answer-key protection against client SELECT('*').
-- 3. Revokes unauthenticated and authenticated execute privileges from the unconfirmed
--    exm03_erase_part_attempts RPC; user erasure must proceed via exm03_erase_account_practice.
-- 4. Introduces usage_role ('practice_pool', 'held_out_transfer', 'selection_probe')
--    on assessment_item_reference_validity and strictly excludes held-out items
--    from ordinary learner practice issuance.
-- 5. Includes administration_date in assignment records and export pages.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 1. Add administration_date to exam_part_practice_assignments
-- -----------------------------------------------------------------------------
alter table public.exam_part_practice_assignments
  add column if not exists administration_date date;

update public.exam_part_practice_assignments
  set administration_date = coalesce(administration_date, (issued_at at time zone 'UTC')::date, current_date)
  where administration_date is null;

alter table public.exam_part_practice_assignments
  alter column administration_date set not null;

create index if not exists exm03_assignment_admin_date_idx
  on public.exam_part_practice_assignments (target_version_id, exam_part_key, administration_date);

-- -----------------------------------------------------------------------------
-- 2. Add usage_role to assessment_item_reference_validity
-- -----------------------------------------------------------------------------
alter table public.assessment_item_reference_validity
  add column if not exists usage_role text not null default 'practice_pool'
    check (usage_role in ('practice_pool', 'held_out_transfer', 'selection_probe'));

create index if not exists exm02a_validity_usage_role_idx
  on public.assessment_item_reference_validity (manifest_revision_id, publication_status, usage_role);

comment on column public.assessment_item_reference_validity.usage_role is
  'Differentiates practice pool items from held-out transfer probes and nonproduction selection probes.';

-- -----------------------------------------------------------------------------
-- 3. Harden exm03_has_protected_binding for Retired Items
-- -----------------------------------------------------------------------------
create or replace function public.exm03_has_protected_binding(p_item_id uuid)
returns boolean language sql stable security definer
set search_path=pg_catalog,public,pg_temp
as $private$
  select exists (
    select 1 from public.assessment_item_reference_validity b
    where b.assessment_item_id=p_item_id
      and b.publication_status in ('published', 'retired')
      and b.review_status='approved'
      and b.rights_review_status='approved'
  );
$private$;

revoke all on function public.exm03_has_protected_binding(uuid)
  from public,anon,authenticated;
grant execute on function public.exm03_has_protected_binding(uuid)
  to anon,authenticated;

comment on function public.exm03_has_protected_binding(uuid) is
  'Returns true if item has an approved published OR retired reference binding. Restrictive RLS uses this to permanently protect scoring_spec from direct client reads.';

-- -----------------------------------------------------------------------------
-- 4. Revoke Authenticated Execute from Unconfirmed exm03_erase_part_attempts
-- -----------------------------------------------------------------------------
revoke all on function public.exm03_erase_part_attempts(uuid,text)
  from public,anon,authenticated;
grant execute on function public.exm03_erase_part_attempts(uuid,text)
  to service_role;

comment on function public.exm03_erase_part_attempts(uuid,text) is
  'Service-role only internal or administrative erasure. Learner client erasure must proceed through exm03_erase_account_practice with session validation, advisory locking, confirmation phrase, and fingerprint verification.';

-- -----------------------------------------------------------------------------
-- 5. Replace exm03_issue_assigned_practice with Date-Specific Signature
-- -----------------------------------------------------------------------------
drop function if exists public.exm03_issue_assigned_practice(uuid,text);

create or replace function public.exm03_issue_assigned_practice(
  p_target_version_id uuid,
  p_exam_part_key text,
  p_administration_date date
)
returns jsonb
language plpgsql volatile security definer
set search_path=pg_catalog,public,pg_temp
as $issue$
declare
  actor_id uuid;
  session_id uuid;
  profile jsonb;
  v_target_id uuid;
  v_root uuid;
  v_manifest uuid;
  v_count integer;
  v_distinct_concepts integer;
  v_assigned jsonb;
  v_visible jsonb;
  v_assignment uuid;
  v_expiry timestamptz;
begin
  -- PostgREST validates the JWT signature; the issuer additionally checks
  -- permanent-account status and the exact still-live Auth session.
  actor_id := (select auth.uid());
  if actor_id is null
     or (select auth.jwt()->>'role') is distinct from 'authenticated'
     or (select (auth.jwt()->>'is_anonymous')::boolean) is distinct from false
     or nullif(auth.jwt()->>'session_id','') is null
     or (auth.jwt()->>'session_id') !~
       '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
     or p_target_version_id is null
     or p_exam_part_key is null
     or p_exam_part_key !~ '^[a-z][a-z0-9_]{0,127}$'
     or p_administration_date is null then
    raise exception 'Permanent authenticated session, exact part, and administration date required'
      using errcode='42501';
  end if;
  session_id := (auth.jwt()->>'session_id')::uuid;
  if not exists (
    select 1 from auth.sessions s
    where s.id=session_id and s.user_id=actor_id
      and (s.not_after is null or s.not_after > now())
  ) then
    raise exception 'Authentication session is no longer active'
      using errcode='42501';
  end if;

  select v.target_id,v.metadata into v_target_id,profile
  from public.target_versions v
  join public.learning_targets t on t.id=v.target_id
  where v.id=p_target_version_id
    and v.status='published'
    and t.status='published'
    and t.is_public=true;
  if v_target_id is null
     or jsonb_typeof(profile->'exam_preparation'->'exam_parts')
         is distinct from 'array' then
    raise exception 'Published version with configured parts required'
      using errcode='42501';
  end if;
  if (select count(*) from jsonb_array_elements(
        profile->'exam_preparation'->'exam_parts') as part(value)
      where part.value->>'key'=p_exam_part_key) <> 1 then
    raise exception 'Exactly one configured exam-part key required'
      using errcode='42501';
  end if;

  select cn.id into v_root
  from jsonb_array_elements(profile->'exam_preparation'->'exam_parts')
    as part(value)
  join public.curriculum_nodes cn
    on cn.id::text=part.value->>'curriculum_root_node_id'
   and cn.target_version_id=p_target_version_id
  where part.value->>'key'=p_exam_part_key;
  if v_root is null then
    raise exception 'Exam part root must belong to this version'
      using errcode='42501';
  end if;

  -- Select manifest effective on the learner's actual administration date, NOT current_date.
  select m.id into v_manifest
  from public.exam_reference_manifest_revisions m
  where m.target_version_id=p_target_version_id
    and m.exam_part_key=p_exam_part_key
    and m.publication_status='published'
    and m.review_status='approved'
    and p_administration_date >= m.effective_from
    and (m.effective_until is null or p_administration_date <= m.effective_until)
  order by m.revision desc
  limit 1;
  if v_manifest is null then
    raise exception 'No effective approved reference manifest for part on requested administration date'
      using errcode='42501';
  end if;

  -- Per-owner advisory lock prevents concurrent issuance from outrunning
  -- the quota. Failed issuance rolls everything back without leaking keys.
  perform pg_advisory_xact_lock(hashtextextended(actor_id::text, 61503));
  select count(*) into v_count
  from public.exam_part_practice_assignments a
  where a.owner_id=actor_id and a.issued_at>now()-interval '24 hours';
  if v_count>=12 then
    raise exception 'Practice issuance quota reached'
      using errcode='42501';
  end if;
  select count(*) into v_count
  from public.exam_part_practice_assignments a
  where a.owner_id=actor_id
    and a.expires_at>now()
    and not exists (
      select 1 from public.exam_part_practice_attempts t
      where t.assignment_id=a.id
    );
  if v_count>=2 then
    raise exception 'Finish or expire existing practice assignments first'
      using errcode='42501';
  end if;

  -- Bounded loop to assemble 6 single-choice items spanning >= 3 core concepts.
  -- Excludes held-out transfer probes and selection probes (usage_role must be 'practice_pool').
  for v_attempt in 1..20 loop
    with recursive part_nodes(id) as (
      select v_root
      union
      select n.id from public.curriculum_nodes n
      join part_nodes p on n.parent_id=p.id
      where n.target_version_id=p_target_version_id
    ),
    eligible as (
      select i.id, public.exam_reference_item_fingerprint(i.id) as sha
      from public.assessment_items i
      join public.assessment_item_reference_validity b
        on b.assessment_item_id=i.id
       and b.manifest_revision_id=v_manifest
       and b.publication_status='published'
       and b.review_status='approved'
       and b.rights_review_status='approved'
       and b.usage_role='practice_pool'
      where i.origin_target_version_id=p_target_version_id
        and i.interaction_type='single_choice'
        and i.response_spec ? 'options'
        and jsonb_typeof(i.response_spec->'options')='array'
        and jsonb_array_length(i.response_spec->'options') between 2 and 10
        and i.scoring_spec ? 'correct_index'
        and jsonb_typeof(i.scoring_spec->'correct_index')='number'
        and (i.scoring_spec->>'correct_index') ~ '^[0-9]+$'
        and (i.scoring_spec->>'correct_index')::integer
              < jsonb_array_length(i.response_spec->'options')
        and b.item_content_sha256 =
              public.exam_reference_item_fingerprint(i.id)
        and exists (
          select 1 from public.assessment_item_concepts ic
          where ic.assessment_item_id=i.id
            and exists (
              select 1 from public.curriculum_node_concepts nc
              where nc.concept_id=ic.concept_id and nc.relevance='core'
                and nc.curriculum_node_id in (select id from part_nodes)
            )
        )
        and not exists (
          select 1 from public.assessment_item_concepts ic
          where ic.assessment_item_id=i.id
            and (
              not exists (
                select 1 from public.curriculum_node_concepts nc
                where nc.concept_id=ic.concept_id and nc.relevance='core'
                  and nc.curriculum_node_id in (select id from part_nodes)
              ) or exists (
                select 1 from public.curriculum_node_concepts nc
                join public.curriculum_nodes outsider
                  on outsider.id=nc.curriculum_node_id
                where nc.concept_id=ic.concept_id
                  and outsider.target_version_id=p_target_version_id
                  and outsider.id not in (select id from part_nodes)
              )
            )
        )
      group by i.id
    ),
    selection as (
      select id,sha from eligible order by random() limit 6
    )
    select jsonb_agg(jsonb_build_object('id',id,'sha256',sha)
                     order by id),
           count(*) into v_assigned,v_count
    from selection;

    if v_count<>6 then
      raise exception 'Not enough verified part-specific questions'
        using errcode='42501';
    end if;
    select count(distinct ic.concept_id) into v_distinct_concepts
    from jsonb_array_elements(v_assigned) as chosen(value)
    join public.assessment_item_concepts ic
      on ic.assessment_item_id=(chosen.value->>'id')::uuid;
    exit when v_distinct_concepts>=3;
  end loop;
  if v_distinct_concepts<3 then
    raise exception 'Part practice requires three distinct core concepts'
      using errcode='42501';
  end if;

  v_expiry := now()+interval '90 minutes';
  insert into public.exam_part_practice_assignments (
    owner_id,target_id,target_version_id,exam_part_key,
    curriculum_root_node_id,manifest_revision_id,practice_kind,
    assigned_items,issued_at,expires_at,administration_date
  ) values (
    actor_id,v_target_id,p_target_version_id,p_exam_part_key,
    v_root,v_manifest,'diagnostic',
    v_assigned,now(),v_expiry,p_administration_date
  ) returning id into v_assignment;

  select jsonb_agg(jsonb_build_object(
    'id',i.id,
    'interaction_type',i.interaction_type,
    'prompt',i.prompt,
    'response_spec',jsonb_build_object('options',i.response_spec->'options')
  ) order by chosen.ordinality)
  into v_visible
  from jsonb_array_elements(v_assigned) with ordinality as chosen(value, ordinality)
  join public.assessment_items i
    on i.id=(chosen.value->>'id')::uuid;

  return jsonb_build_object(
    'assignment_id',v_assignment,
    'target_version_id',p_target_version_id,
    'exam_part_key',p_exam_part_key,
    'administration_date',p_administration_date::text,
    'expires_at',v_expiry,
    'practice_only',true,
    'question_count',6,
    'questions',v_visible
  );
end
$issue$;

revoke all on function public.exm03_issue_assigned_practice(uuid,text,date)
  from public,anon,authenticated;
grant execute on function public.exm03_issue_assigned_practice(uuid,text,date)
  to authenticated;

comment on function public.exm03_issue_assigned_practice(uuid,text,date) is
  'Permanent live-session owner-only, quota-bound server-assigned reviewed six-item part diagnostic for a specific exam administration date. Returns safe questions only. Excludes held-out items. Grading remains private; not an official exam.';

-- -----------------------------------------------------------------------------
-- 6. Update exm03_record_assigned_practice to Validate Assignment Administration Date
-- -----------------------------------------------------------------------------
create or replace function public.exm03_record_assigned_practice(
  p_assignment_id uuid,
  p_responses jsonb
)
returns jsonb
language plpgsql security definer
set search_path=pg_catalog,public,pg_temp
as $record$
declare
  a public.exam_part_practice_assignments%rowtype;
  existing public.exam_part_practice_attempts%rowtype;
  v_version record;
  v_manifest public.exam_reference_manifest_revisions%rowtype;
  v_questions integer;
  v_correct integer := 0;
  v_response_hash text;
  v_entry jsonb;
  v_item_id uuid;
  v_ids uuid[] := array[]::uuid[];
  v_item public.assessment_items%rowtype;
  v_hash text;
  v_actual text;
  v_expected text;
  v_distinct_concepts integer;
  v_edition text;
begin
  if p_assignment_id is null
     or p_responses is null
     or jsonb_typeof(p_responses) is distinct from 'object' then
    raise exception 'Assignment ID and responses object required'
      using errcode='22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_assignment_id::text, 61501));

  select * into a from public.exam_part_practice_assignments
    where id=p_assignment_id;
  if not found then
    raise exception 'Practice assignment not found'
      using errcode='42501';
  end if;

  v_response_hash := encode(sha256(convert_to(p_responses::text,'UTF8')),'hex');

  select * into existing from public.exam_part_practice_attempts
    where assignment_id=a.id;
  if found then
    if existing.response_sha256 = v_response_hash then
      return jsonb_build_object(
        'attempt_id',existing.id,
        'target_version_id',existing.target_version_id,
        'exam_part_key',existing.exam_part_key,
        'question_count',existing.question_count,
        'fully_correct_count',existing.fully_correct_count,
        'partial_count',existing.partial_count,
        'practice_score',existing.practice_score,
        'already_recorded',true,
        'official_exam_result',false
      );
    end if;
    raise exception 'Assignment already scored with different responses'
      using errcode='23505';
  end if;

  if a.expires_at <= now() then
    raise exception 'Practice assignment expired'
      using errcode='42501';
  end if;

  select v.id,v.target_id,v.status,v.metadata into v_version
  from public.target_versions v
  join public.learning_targets t on t.id=v.target_id
  where v.id=a.target_version_id
    and v.target_id=a.target_id
    and v.status='published'
    and t.status='published'
    and t.is_public=true;
  if not found or not exists (
        select 1 from jsonb_array_elements(
          v_version.metadata->'exam_preparation'->'exam_parts'
        ) as part(value)
        where part.value->>'key'=a.exam_part_key
          and part.value->>'curriculum_root_node_id'
              =a.curriculum_root_node_id::text
      ) or not exists (
        select 1 from public.curriculum_nodes cn
        where cn.id=a.curriculum_root_node_id
          and cn.target_version_id=a.target_version_id
      ) then
    raise exception 'No published matching target/version/part curriculum'
      using errcode='42501';
  end if;

  -- Validate against manifest covering the assignment's actual administration date
  select * into v_manifest from public.exam_reference_manifest_revisions
    where id=a.manifest_revision_id;
  if not found or v_manifest.target_version_id <> a.target_version_id
     or v_manifest.exam_part_key <> a.exam_part_key
     or v_manifest.publication_status <> 'published'
     or v_manifest.review_status <> 'approved'
     or a.administration_date < v_manifest.effective_from
     or (v_manifest.effective_until is not null
         and a.administration_date > v_manifest.effective_until) then
    raise exception 'No current approved source manifest for this part on the administration date'
      using errcode='42501';
  end if;

  v_questions := jsonb_array_length(a.assigned_items);
  if v_questions not between 6 and 50 or
     (select count(*) from jsonb_object_keys(p_responses)) <> v_questions
     or pg_column_size(p_responses)>65536 then
    raise exception 'Complete bounded assigned responses required'
      using errcode='22023';
  end if;

  for v_entry in select value from jsonb_array_elements(a.assigned_items)
      as assigned(value)
  loop
    if jsonb_typeof(v_entry) is distinct from 'object'
       or (select count(*) from jsonb_object_keys(v_entry)) <> 2
       or coalesce(v_entry->>'id','') !~
          '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'
       or coalesce(v_entry->>'sha256','') !~ '^[a-f0-9]{64}$' then
      raise exception 'Malformed immutable practice assignment'
        using errcode='22023';
    end if;
    v_item_id := (v_entry->>'id')::uuid;
    if v_item_id=any(v_ids) then
      raise exception 'Assigned questions may not repeat'
        using errcode='22023';
    end if;
    v_ids := array_append(v_ids,v_item_id);

    select * into v_item from public.assessment_items
      where id=v_item_id and origin_target_version_id=a.target_version_id;
    v_hash := public.exam_reference_item_fingerprint(v_item_id);
    if not found or v_hash is distinct from (v_entry->>'sha256')
       or v_item.interaction_type <> 'single_choice'
       or not exists (
         select 1 from public.assessment_item_reference_validity b
         where b.assessment_item_id=v_item_id
           and b.manifest_revision_id=a.manifest_revision_id
           and b.publication_status='published'
           and b.review_status='approved'
           and b.rights_review_status='approved'
           and b.usage_role='practice_pool'
           and b.item_content_sha256=v_hash
       ) then
      raise exception 'Assigned item was modified or lost valid approval'
        using errcode='42501';
    end if;

    v_actual := trim(coalesce(p_responses->>v_item_id::text,''));
    v_expected := trim(v_item.scoring_spec->>'correct_index');
    if v_actual !~ '^[0-9]+$' or
       v_actual::integer >= jsonb_array_length(v_item.response_spec->'options') then
      raise exception 'Response index out of range for question'
        using errcode='22023';
    end if;
    if v_actual=v_expected then
      v_correct := v_correct+1;
    end if;
  end loop;

  -- At least three separate core concepts, not six copies of one item.
  with recursive subtree(id) as (
    select id from public.curriculum_nodes
      where id=a.curriculum_root_node_id
        and target_version_id=a.target_version_id
    union
    select n.id from public.curriculum_nodes n
      join subtree p on n.parent_id=p.id
      where n.target_version_id=a.target_version_id
  )
  select count(distinct ic.concept_id) into v_distinct_concepts
  from public.assessment_item_concepts ic
    join public.curriculum_node_concepts nc
      on nc.concept_id=ic.concept_id and nc.relevance='core'
  where ic.assessment_item_id=any(v_ids)
    and nc.curriculum_node_id in (select id from subtree);
  if v_distinct_concepts < 3 then
    raise exception 'Practice requires three distinct reviewed concepts'
      using errcode='42501';
  end if;

  v_edition := encode(sha256(convert_to(
    a.manifest_revision_id::text || ':' || a.assigned_items::text,
    'UTF8')),'hex');

  insert into public.exam_part_practice_attempts (
    owner_id,target_id,target_version_id,exam_part_key,
    curriculum_root_node_id,practice_kind,
    question_count,fully_correct_count,partial_count,
    practice_score,question_edition_fingerprint,assignment_id,response_sha256
  ) values (
    a.owner_id,a.target_id,a.target_version_id,a.exam_part_key,
    a.curriculum_root_node_id,a.practice_kind,
    v_questions,v_correct,0,
    round(v_correct::numeric/v_questions,6),v_edition,a.id,v_response_hash
  ) returning * into existing;

  return jsonb_build_object(
    'attempt_id',existing.id,
    'target_version_id',existing.target_version_id,
    'exam_part_key',existing.exam_part_key,
    'question_count',existing.question_count,
    'fully_correct_count',existing.fully_correct_count,
    'partial_count',existing.partial_count,
    'practice_score',existing.practice_score,
    'already_recorded',false,
    'official_exam_result',false
  );
end
$record$;

revoke all on function public.exm03_record_assigned_practice(uuid,jsonb)
  from public,anon,authenticated;
grant execute on function public.exm03_record_assigned_practice(uuid,jsonb)
  to service_role;

-- -----------------------------------------------------------------------------
-- 7. Update exm03_account_part_export_page to Include administration_date
-- -----------------------------------------------------------------------------
create or replace function public.exm03_account_part_export_page(
  p_limit integer default 250,
  p_before_issued_at timestamptz default null,
  p_before_assignment_id uuid default null
)
returns jsonb language plpgsql stable security definer
set search_path=pg_catalog,public,pg_temp
as $page$
declare
  v_owner uuid := public.exm03_portability_owner();
  v_rows jsonb;
  v_count integer;
begin
  if p_limit is null or p_limit<1 or p_limit>250
     or (p_before_issued_at is null) <> (p_before_assignment_id is null) then
    raise exception 'Invalid EXM assignment export page cursor'
      using errcode='22023';
  end if;

  select count(*)::integer,coalesce(jsonb_agg(jsonb_build_object(
    'assignment_id',a.id,
    'target_id',a.target_id,
    'target_version_id',a.target_version_id,
    'exam_part_key',a.exam_part_key,
    'curriculum_root_node_id',a.curriculum_root_node_id,
    'manifest_revision_id',a.manifest_revision_id,
    'practice_kind',a.practice_kind,
    'administration_date',a.administration_date,
    'issued_at',a.issued_at,
    'expires_at',a.expires_at,
    'attempt',case when t.id is null then null else jsonb_build_object(
      'attempt_id',t.id,
      'completed_at',t.completed_at,
      'question_count',t.question_count,
      'fully_correct_count',t.fully_correct_count,
      'partial_count',t.partial_count,
      'practice_score',t.practice_score,
      'question_edition_fingerprint',t.question_edition_fingerprint,
      'official_exam_result',false
    ) end
  ) order by a.issued_at desc,a.id desc),'[]'::jsonb)
  into v_count,v_rows
  from (
    select *
    from public.exam_part_practice_assignments x
    where x.owner_id=v_owner
      and (p_before_issued_at is null
        or (x.issued_at,x.id)<(p_before_issued_at,p_before_assignment_id))
    order by x.issued_at desc,x.id desc
    limit p_limit
  ) a
  left join public.exam_part_practice_attempts t
    on t.assignment_id=a.id and t.owner_id=a.owner_id;

  perform public.exm03_portability_owner();
  return jsonb_build_object(
    'scope','exm-educational-practice-all-editions-v1',
    'owner_id',v_owner,
    'row_count',v_count,
    'rows',v_rows
  );
end
$page$;

-- -----------------------------------------------------------------------------
-- 8. Update exm03_account_practice_export to Include administration_date
-- -----------------------------------------------------------------------------
create or replace function public.exm03_account_practice_export()
returns jsonb language plpgsql stable security definer
set search_path=pg_catalog,public,pg_temp
as $export$
declare
  v_owner uuid := public.exm03_portability_owner();
  v_inventory jsonb;
  v_reference jsonb;
  v_parts jsonb;
begin
  v_inventory := public.exm03_account_practice_inventory();
  v_reference := public.exam_reference_drill_account_export(5000);
  select coalesce(jsonb_agg(jsonb_build_object(
    'assignment_id',a.id,
    'target_id',a.target_id,
    'target_version_id',a.target_version_id,
    'exam_part_key',a.exam_part_key,
    'curriculum_root_node_id',a.curriculum_root_node_id,
    'manifest_revision_id',a.manifest_revision_id,
    'practice_kind',a.practice_kind,
    'administration_date',a.administration_date,
    'issued_at',a.issued_at,
    'expires_at',a.expires_at,
    'attempt',case when t.id is null then null else jsonb_build_object(
      'attempt_id',t.id,
      'completed_at',t.completed_at,
      'question_count',t.question_count,
      'fully_correct_count',t.fully_correct_count,
      'partial_count',t.partial_count,
      'practice_score',t.practice_score,
      'question_edition_fingerprint',t.question_edition_fingerprint,
      'official_exam_result',false
    ) end
  ) order by a.issued_at desc,a.id desc),'[]'::jsonb)
  into v_parts
  from public.exam_part_practice_assignments a
  left join public.exam_part_practice_attempts t
    on t.assignment_id=a.id and t.owner_id=a.owner_id
  where a.owner_id=v_owner;

  if jsonb_array_length(v_parts)<>(v_inventory->>'part_assignments')::integer
     or (v_reference->>'record_count')::integer<>(v_inventory->>'reference_events')::integer then
    raise exception 'EXM export read mismatch against verified inventory'
      using errcode='40001';
  end if;

  return jsonb_build_object(
    'format','learningapp-exm-combined-practice-v1',
    'scope','educational-practice-history-not-entire-account',
    'owner_id',v_owner,
    'generated_at',now(),
    'snapshot_consistency','single-stable-rpc-statement',
    'inventory',v_inventory,
    'reference_practice',v_reference,
    'part_practice',v_parts,
    'includes_unsubmitted_assignments',true,
    'official_exam_result',false
  );
end
$export$;

INSERT INTO supabase_migrations.schema_migrations (version, name) VALUES ('20261101180000', 'exm_03_release_hardening_and_date_eligibility') ON CONFLICT (version) DO NOTHING;

-- --------------------------------------------------------------------
-- [82/96] Migration: 20261101190000_eco_05_fix_user_xp_security.sql
-- --------------------------------------------------------------------
-- Migration 82: Secure User XP Progression & Definer Hardening
-- Closes FIX-2: Prohibits direct client tampering with user_xp balances and xp_events.
-- Implements single authenticated, idempotent server-side award operation (record_xp_award)
-- with strict semantic deduplication, daily rate ceiling, and restricts increment_user_xp to service_role.

-- 1. Drop old insecure function signature
DROP FUNCTION IF EXISTS public.increment_user_xp(UUID, INTEGER);

-- 2. Define hardened increment_user_xp function (service_role only for admin/batch awards)
CREATE OR REPLACE FUNCTION public.increment_user_xp(
  p_xp_amount INTEGER,
  p_user_id UUID DEFAULT NULL
)
RETURNS VOID AS $$
DECLARE
  v_auth_uid UUID := (SELECT auth.uid());
  v_target_user_id UUID;
BEGIN
  -- Determine target user: for authenticated callers, must be own uid; for service_role, p_user_id is required
  IF v_auth_uid IS NOT NULL THEN
    IF p_user_id IS NOT NULL AND p_user_id <> v_auth_uid THEN
      RAISE EXCEPTION 'Cannot modify XP for another user';
    END IF;
    v_target_user_id := v_auth_uid;
  ELSE
    IF p_user_id IS NULL THEN
      RAISE EXCEPTION 'Target user_id is required when calling increment_user_xp via service_role';
    END IF;
    v_target_user_id := p_user_id;
  END IF;

  IF p_xp_amount <= 0 OR p_xp_amount > 1000 THEN
    RAISE EXCEPTION 'Invalid XP increment amount (must be 1..1000)';
  END IF;

  INSERT INTO public.user_xp (user_id, total_xp, created_at, updated_at)
  VALUES (v_target_user_id, p_xp_amount, NOW(), NOW())
  ON CONFLICT (user_id)
  DO UPDATE SET
    total_xp = user_xp.total_xp + p_xp_amount,
    updated_at = NOW();
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- 3. Define transactional, idempotent record_xp_award RPC with semantic deduplication
CREATE OR REPLACE FUNCTION public.record_xp_award(
  p_event_id UUID,
  p_event_type TEXT,
  p_xp_amount INTEGER,
  p_source_id TEXT DEFAULT NULL,
  p_description TEXT DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
  v_auth_uid UUID := (SELECT auth.uid());
  v_canonical_event_type TEXT;
  v_capped_xp INTEGER;
  v_current_total INTEGER;
  v_new_total INTEGER;
  v_existing_event UUID;
  v_today_xp INTEGER;
BEGIN
  IF v_auth_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Advisory transaction lock to serialize concurrent calls per user
  PERFORM pg_advisory_xact_lock(hashtext(v_auth_uid::text));

  -- 1. Exact UUID Idempotency: if this exact event id was already processed, return current state
  SELECT id INTO v_existing_event
  FROM public.xp_events
  WHERE id = p_event_id AND user_id = v_auth_uid;

  IF v_existing_event IS NOT NULL THEN
    SELECT COALESCE(total_xp, 0) INTO v_current_total
    FROM public.user_xp
    WHERE user_id = v_auth_uid;

    RETURN jsonb_build_object(
      'status', 'already_processed',
      'event_id', p_event_id,
      'awarded_xp', 0,
      'total_xp', v_current_total
    );
  END IF;

  -- 2. Strict event type validation & canonicalization to snake_case (eliminates alias cooldown bypass)
  CASE p_event_type
    WHEN 'questionCorrect', 'question_correct' THEN v_canonical_event_type := 'question_correct';
    WHEN 'lessonComplete', 'lesson_complete' THEN v_canonical_event_type := 'lesson_complete';
    WHEN 'courseComplete', 'course_complete' THEN v_canonical_event_type := 'course_complete';
    WHEN 'reviewSession', 'review_session' THEN v_canonical_event_type := 'review_session';
    WHEN 'streakBonus', 'streak_bonus' THEN v_canonical_event_type := 'streak_bonus';
    WHEN 'achievement' THEN v_canonical_event_type := 'achievement';
    WHEN 'dailyGoal', 'daily_goal' THEN v_canonical_event_type := 'daily_goal';
    ELSE
      RAISE EXCEPTION 'Invalid XP event type: %', p_event_type;
  END CASE;

  IF p_xp_amount <= 0 THEN
    RAISE EXCEPTION 'XP amount must be positive';
  END IF;

  -- Require non-null source_id for event types that rely on source-based deduplication
  IF v_canonical_event_type IN ('achievement', 'lesson_complete', 'course_complete', 'question_correct', 'review_session') THEN
    IF p_source_id IS NULL OR TRIM(p_source_id) = '' THEN
      RAISE EXCEPTION 'source_id is required for event type: %', v_canonical_event_type;
    END IF;
  END IF;

  -- 3. Semantic deduplication:
  -- A. Permanent deduplication for achievements: an achievement can only be claimed once in a lifetime per source_id
  IF p_source_id IS NOT NULL AND v_canonical_event_type = 'achievement' THEN
    SELECT id INTO v_existing_event
    FROM public.xp_events
    WHERE user_id = v_auth_uid
      AND event_type = 'achievement'
      AND source_id = p_source_id;

    IF v_existing_event IS NOT NULL THEN
      SELECT COALESCE(total_xp, 0) INTO v_current_total
      FROM public.user_xp
      WHERE user_id = v_auth_uid;

      RETURN jsonb_build_object(
        'status', 'already_processed',
        'event_id', v_existing_event,
        'awarded_xp', 0,
        'total_xp', v_current_total
      );
    END IF;
  END IF;

  -- B. Lessons and courses: 24-hour cooldown on same source_id
  IF p_source_id IS NOT NULL AND v_canonical_event_type IN ('lesson_complete', 'course_complete') THEN
    SELECT id INTO v_existing_event
    FROM public.xp_events
    WHERE user_id = v_auth_uid
      AND event_type = v_canonical_event_type
      AND source_id = p_source_id
      AND earned_at > NOW() - INTERVAL '24 hours';

    IF v_existing_event IS NOT NULL THEN
      SELECT COALESCE(total_xp, 0) INTO v_current_total
      FROM public.user_xp
      WHERE user_id = v_auth_uid;

      RETURN jsonb_build_object(
        'status', 'already_processed',
        'event_id', v_existing_event,
        'awarded_xp', 0,
        'total_xp', v_current_total
      );
    END IF;
  END IF;

  -- C. Daily goals and streak bonuses: 20-hour cooldown
  IF v_canonical_event_type IN ('daily_goal', 'streak_bonus') THEN
    SELECT id INTO v_existing_event
    FROM public.xp_events
    WHERE user_id = v_auth_uid
      AND event_type = v_canonical_event_type
      AND earned_at > NOW() - INTERVAL '20 hours';

    IF v_existing_event IS NOT NULL THEN
      SELECT COALESCE(total_xp, 0) INTO v_current_total
      FROM public.user_xp
      WHERE user_id = v_auth_uid;

      RETURN jsonb_build_object(
        'status', 'already_processed',
        'event_id', v_existing_event,
        'awarded_xp', 0,
        'total_xp', v_current_total
      );
    END IF;
  END IF;

  -- D. Rapid question and review replay protection: 15-minute cooldown on same source_id
  IF p_source_id IS NOT NULL AND v_canonical_event_type IN ('question_correct', 'review_session') THEN
    SELECT id INTO v_existing_event
    FROM public.xp_events
    WHERE user_id = v_auth_uid
      AND event_type = v_canonical_event_type
      AND source_id = p_source_id
      AND earned_at > NOW() - INTERVAL '15 minutes';

    IF v_existing_event IS NOT NULL THEN
      SELECT COALESCE(total_xp, 0) INTO v_current_total
      FROM public.user_xp
      WHERE user_id = v_auth_uid;

      RETURN jsonb_build_object(
        'status', 'already_processed',
        'event_id', v_existing_event,
        'awarded_xp', 0,
        'total_xp', v_current_total
      );
    END IF;
  END IF;

  -- 4. Daily rate ceiling: max 2000 XP in any rolling 24-hour window
  SELECT COALESCE(SUM(xp_amount), 0) INTO v_today_xp
  FROM public.xp_events
  WHERE user_id = v_auth_uid AND earned_at > NOW() - INTERVAL '24 hours';

  IF v_today_xp >= 2000 THEN
    RAISE EXCEPTION 'Daily XP limit reached (maximum 2000 XP per 24 hours)';
  END IF;

  -- 5. Server-side capping per canonical event type
  CASE v_canonical_event_type
    WHEN 'question_correct' THEN
      v_capped_xp := LEAST(p_xp_amount, 25);
    WHEN 'lesson_complete' THEN
      v_capped_xp := LEAST(p_xp_amount, 100);
    WHEN 'course_complete' THEN
      v_capped_xp := LEAST(p_xp_amount, 500);
    WHEN 'review_session' THEN
      v_capped_xp := LEAST(p_xp_amount, 100);
    WHEN 'streak_bonus' THEN
      v_capped_xp := LEAST(p_xp_amount, 150);
    WHEN 'achievement' THEN
      v_capped_xp := LEAST(p_xp_amount, 250);
    WHEN 'daily_goal' THEN
      v_capped_xp := LEAST(p_xp_amount, 100);
    ELSE
      RAISE EXCEPTION 'Unhandled XP event type: %', v_canonical_event_type;
  END CASE;

  -- Ensure award doesn't breach the daily ceiling
  IF v_today_xp + v_capped_xp > 2000 THEN
    v_capped_xp := 2000 - v_today_xp;
  END IF;

  -- 6. Insert event atomically with canonicalized event type
  INSERT INTO public.xp_events (
    id,
    user_id,
    event_type,
    xp_amount,
    source_id,
    description,
    earned_at
  ) VALUES (
    p_event_id,
    v_auth_uid,
    v_canonical_event_type,
    v_capped_xp,
    p_source_id,
    p_description,
    NOW()
  );

  -- 7. Increment user total XP atomically
  INSERT INTO public.user_xp (user_id, total_xp, created_at, updated_at)
  VALUES (v_auth_uid, v_capped_xp, NOW(), NOW())
  ON CONFLICT (user_id)
  DO UPDATE SET
    total_xp = user_xp.total_xp + v_capped_xp,
    updated_at = NOW()
  RETURNING total_xp INTO v_new_total;

  RETURN jsonb_build_object(
    'status', 'awarded',
    'event_id', p_event_id,
    'awarded_xp', v_capped_xp,
    'total_xp', v_new_total
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- 4. Function execution permissions
-- increment_user_xp is strictly revoked from public, anon, AND authenticated (service_role only)
REVOKE EXECUTE ON FUNCTION public.increment_user_xp(INTEGER, UUID) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.increment_user_xp(INTEGER, UUID) FROM anon;
REVOKE EXECUTE ON FUNCTION public.increment_user_xp(INTEGER, UUID) FROM authenticated;
GRANT EXECUTE ON FUNCTION public.increment_user_xp(INTEGER, UUID) TO service_role;

-- record_xp_award is granted to authenticated users (asserts auth.uid())
REVOKE EXECUTE ON FUNCTION public.record_xp_award(UUID, TEXT, INTEGER, TEXT, TEXT) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.record_xp_award(UUID, TEXT, INTEGER, TEXT, TEXT) FROM anon;
GRANT EXECUTE ON FUNCTION public.record_xp_award(UUID, TEXT, INTEGER, TEXT, TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION public.record_xp_award(UUID, TEXT, INTEGER, TEXT, TEXT) TO service_role;

-- 5. Revoke ALL direct client write DML on user_xp and xp_events tables
-- Revoke table-level DML privileges from public, anon, and authenticated
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON TABLE public.user_xp FROM PUBLIC, anon, authenticated;
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON TABLE public.xp_events FROM PUBLIC, anon, authenticated;
GRANT SELECT ON TABLE public.user_xp TO authenticated;
GRANT SELECT ON TABLE public.xp_events TO authenticated;

-- Drop policies from Migration 20250101000002_create_user_xp.sql AND 20260528000000_secure_rls_with_anonymous_guests.sql
DROP POLICY IF EXISTS "user_xp_owner_all" ON public.user_xp;
DROP POLICY IF EXISTS "Users can insert own XP" ON public.user_xp;
DROP POLICY IF EXISTS "Users can update own XP" ON public.user_xp;
DROP POLICY IF EXISTS "Users can delete own XP" ON public.user_xp;

DROP POLICY IF EXISTS "xp_events_owner_all" ON public.xp_events;
DROP POLICY IF EXISTS "Users can insert own XP events" ON public.xp_events;
DROP POLICY IF EXISTS "Users can update own XP events" ON public.xp_events;
DROP POLICY IF EXISTS "Users can delete own XP events" ON public.xp_events;

-- Ensure SELECT policy uses optimized initplan (SELECT auth.uid())
DROP POLICY IF EXISTS "Users can view own XP" ON public.user_xp;
CREATE POLICY "Users can view own XP"
  ON public.user_xp FOR SELECT
  USING ((SELECT auth.uid()) = user_id);

DROP POLICY IF EXISTS "Users can view own XP events" ON public.xp_events;
CREATE POLICY "Users can view own XP events"
  ON public.xp_events FOR SELECT
  USING ((SELECT auth.uid()) = user_id);

-- 6. Backfill historical camelCase event types to canonical snake_case
UPDATE public.xp_events
SET event_type = CASE event_type
  WHEN 'questionCorrect' THEN 'question_correct'
  WHEN 'lessonComplete' THEN 'lesson_complete'
  WHEN 'courseComplete' THEN 'course_complete'
  WHEN 'reviewSession' THEN 'review_session'
  WHEN 'streakBonus' THEN 'streak_bonus'
  WHEN 'dailyGoal' THEN 'daily_goal'
  ELSE event_type
END
WHERE event_type IN ('questionCorrect', 'lessonComplete', 'courseComplete', 'reviewSession', 'streakBonus', 'dailyGoal');

INSERT INTO supabase_migrations.schema_migrations (version, name) VALUES ('20261101190000', 'eco_05_fix_user_xp_security') ON CONFLICT (version) DO NOTHING;

-- --------------------------------------------------------------------
-- [83/96] Migration: 20261101195000_reconcile_user_progress_study_time_seconds.sql
-- --------------------------------------------------------------------
-- Reconcile hosted drift: production's public.user_progress predates the
-- 20241228000000 baseline (created with IF NOT EXISTS) and never received
-- study_time_seconds, which 20261101200000's study_progress view and the app
-- require. No-op on databases built from the migration chain.
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM information_schema.columns
    WHERE table_schema = 'public'
      AND table_name = 'user_progress'
      AND column_name = 'study_time_seconds'
  ) THEN
    ALTER TABLE public.user_progress ADD COLUMN study_time_seconds integer DEFAULT 0;
    UPDATE public.user_progress
    SET study_time_seconds = COALESCE(study_time_minutes, 0) * 60;
  END IF;
END
$$;

