CREATE POLICY lesson_texts_read_visible ON public.lesson_texts
  FOR SELECT TO authenticated, anon
  USING (public.is_lesson_visible(lesson_id));

DROP POLICY IF EXISTS lesson_texts_write ON public.lesson_texts;
