-- --------------------------------------------------------------------
-- [85/96] Migration: 20261102140000_arch_01_learning_events_fsrs_and_server_scoring.sql
-- --------------------------------------------------------------------
-- ============================================================================
-- Architecture Phase 1: Learning Events, FSRS Projections & Server-Side Scoring
-- Migration: 20261102140000_arch_01_learning_events_fsrs_and_server_scoring.sql
-- ============================================================================

-- 1. LEARNING EVENTS TABLE (ARCH-1, ARCH-3, FIX-2)
-- Append-only event log for all learner interactions (reviews, questions, lessons).
CREATE TABLE IF NOT EXISTS public.learning_events (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  event_type TEXT NOT NULL,
  item_type TEXT NOT NULL,
  item_id TEXT NOT NULL,
  item_version TEXT,
  context_id TEXT,
  session_id TEXT,
  rating SMALLINT, -- 1=Again, 2=Hard, 3=Good, 4=Easy
  score REAL,      -- 0.0 to 1.0
  response JSONB,
  presented_order SMALLINT[],
  latency_ms INTEGER,
  hints_used SMALLINT DEFAULT 0,
  confidence SMALLINT, -- 1=low, 2=med, 3=high
  scheduler_state_before JSONB,
  scheduler_state_after JSONB,
  metadata JSONB DEFAULT '{}'::jsonb,
  app_version TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_learning_events_user_occurred ON public.learning_events(user_id, occurred_at DESC);
CREATE INDEX IF NOT EXISTS idx_learning_events_item ON public.learning_events(item_id, event_type);
CREATE INDEX IF NOT EXISTS idx_learning_events_context ON public.learning_events(user_id, context_id);

ALTER TABLE public.learning_events ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS learning_events_select_own ON public.learning_events;
CREATE POLICY learning_events_select_own ON public.learning_events
  FOR SELECT TO authenticated
  USING (user_id = (SELECT auth.uid()));

DROP POLICY IF EXISTS learning_events_insert_own ON public.learning_events;
CREATE POLICY learning_events_insert_own ON public.learning_events
  FOR INSERT TO authenticated
  WITH CHECK (user_id = (SELECT auth.uid()));

-- Revoke blanket privileges; grant strictly necessary PostgREST Data API access
REVOKE ALL ON public.learning_events FROM PUBLIC, anon;
GRANT SELECT, INSERT ON public.learning_events TO authenticated;
GRANT ALL ON public.learning_events TO service_role;

-- 2. FSRS ATTRIBUTES ON REVIEW ITEMS (ARCH-1)
ALTER TABLE public.review_items
  ADD COLUMN IF NOT EXISTS stability DOUBLE PRECISION,
  ADD COLUMN IF NOT EXISTS difficulty DOUBLE PRECISION,
  ADD COLUMN IF NOT EXISTS fsrs_state SMALLINT DEFAULT 1,
  ADD COLUMN IF NOT EXISTS retrievability DOUBLE PRECISION,
  ADD COLUMN IF NOT EXISTS step SMALLINT DEFAULT 0;

-- Revoke direct client UPDATE on review_items projection table (ARCH-1, ARCH-3)
-- All scheduler updates must flow through record_events or reset RPC
REVOKE UPDATE ON public.review_items FROM PUBLIC, anon, authenticated;
DROP POLICY IF EXISTS "Users can update own review items" ON public.review_items;

-- 3. CLOSE DIRECT READ OF PROTECTED ANSWER DATA (FIX-12)
-- A. assessment_items (scoring_spec contains answer keys and rubrics)
REVOKE ALL ON public.assessment_items FROM PUBLIC, anon, authenticated;
GRANT SELECT (
  id, lesson_id, stimulus_id, interaction_type, prompt, response_spec,
  difficulty, cognitive_level, metadata, user_id, origin_target_version_id,
  created_at, updated_at
) ON public.assessment_items TO anon, authenticated;
GRANT ALL ON public.assessment_items TO service_role;

-- B. assessment_questions (correct_answer and explanation contain answer keys)
REVOKE ALL ON public.assessment_questions FROM PUBLIC, anon, authenticated;
GRANT SELECT (
  id, assessment_id, question_text, options, order_index, created_at
) ON public.assessment_questions TO anon, authenticated;
GRANT ALL ON public.assessment_questions TO service_role;

-- 4. REVOKE DIRECT AUTHENTICATED EXECUTION OF RECORD_XP_AWARD (FIX-2)
-- Authoritative XP awards are strictly executed from trusted server functions.
REVOKE EXECUTE ON FUNCTION public.record_xp_award(UUID, TEXT, INTEGER, TEXT, TEXT) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.record_xp_award(UUID, TEXT, INTEGER, TEXT, TEXT) TO service_role;

-- 5. RECORD_EVENTS TRANSACTIONAL RPC (ARCH-1, ARCH-3, FIX-2, FIX-4)
-- Atomically logs append-only events, updates review projections idempotently,
-- and updates user_concept_state evidence projections.
-- NOTE: 'processed_count' in the returned payload denotes the count of accepted and
-- acknowledged events in the submitted batch (including idempotent replays), confirming
-- to the caller that the entire batch has been successfully received and handled.
CREATE OR REPLACE FUNCTION public.record_events(
  p_events JSONB[]
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_auth_uid UUID;
  v_event JSONB;
  v_event_id UUID;
  v_occurred_at TIMESTAMPTZ;
  v_event_type TEXT;
  v_item_type TEXT;
  v_item_id TEXT;
  v_item_version TEXT;
  v_context_id TEXT;
  v_session_id TEXT;
  v_rating SMALLINT;
  v_score REAL;
  v_response JSONB;
  v_presented_order SMALLINT[];
  v_latency_ms INTEGER;
  v_hints_used SMALLINT;
  v_confidence SMALLINT;
  v_sched_before JSONB;
  v_sched_after JSONB;
  v_metadata JSONB;
  v_app_version TEXT;
  v_inserted BOOLEAN;
  v_processed_count INTEGER := 0;
  v_concept_id_text TEXT;
BEGIN
  v_auth_uid := (SELECT auth.uid());
  IF v_auth_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required to record learning events'
      USING ERRCODE = '42501';
  END IF;

  FOREACH v_event IN ARRAY p_events LOOP
    v_event_id := COALESCE((v_event->>'id')::UUID, gen_random_uuid());
    v_occurred_at := COALESCE((v_event->>'occurred_at')::TIMESTAMPTZ, NOW());
    v_event_type := COALESCE(v_event->>'event_type', 'unknown');
    v_item_type := COALESCE(v_event->>'item_type', 'unknown');
    v_item_id := COALESCE(v_event->>'item_id', '');
    v_item_version := v_event->>'item_version';
    v_context_id := v_event->>'context_id';
    v_session_id := v_event->>'session_id';
    v_rating := (v_event->>'rating')::SMALLINT;
    IF v_rating IS NOT NULL AND (v_rating < 1 OR v_rating > 4) THEN
      v_rating := NULL;
    END IF;
    v_score := (v_event->>'score')::REAL;
    IF v_score IS NOT NULL THEN
      v_score := LEAST(1.0::REAL, GREATEST(0.0::REAL, v_score));
    END IF;
    v_response := v_event->'response';
    v_latency_ms := (v_event->>'latency_ms')::INTEGER;
    v_hints_used := COALESCE((v_event->>'hints_used')::SMALLINT, 0);
    v_confidence := (v_event->>'confidence')::SMALLINT;
    v_sched_before := v_event->'scheduler_state_before';
    v_sched_after := v_event->'scheduler_state_after';
    v_metadata := COALESCE(v_event->'metadata', '{}'::JSONB);
    v_app_version := v_event->>'app_version';

    -- Parse presented_order array safely if supplied
    v_presented_order := NULL;
    IF v_event ? 'presented_order' AND jsonb_typeof(v_event->'presented_order') = 'array' THEN
      v_presented_order := ARRAY(
        SELECT elem::SMALLINT
        FROM jsonb_array_elements_text(v_event->'presented_order') AS elem
      );
    END IF;

    -- 1. Insert into learning_events (idempotent via ON CONFLICT DO NOTHING)
    v_inserted := FALSE;
    INSERT INTO public.learning_events (
      id, user_id, occurred_at, event_type, item_type, item_id, item_version,
      context_id, session_id, rating, score, response, presented_order,
      latency_ms, hints_used, confidence, scheduler_state_before,
      scheduler_state_after, metadata, app_version
    ) VALUES (
      v_event_id, v_auth_uid, v_occurred_at, v_event_type, v_item_type, v_item_id, v_item_version,
      v_context_id, v_session_id, v_rating, v_score, v_response, v_presented_order,
      v_latency_ms, v_hints_used, v_confidence, v_sched_before,
      v_sched_after, v_metadata, v_app_version
    ) ON CONFLICT (id) DO NOTHING
    RETURNING TRUE INTO v_inserted;

    v_processed_count := v_processed_count + 1;

    -- 2. Update review_items projection ONLY if the event was newly inserted (prevent replay duplication)
    IF v_inserted IS TRUE AND v_event_type = 'review' AND v_sched_after IS NOT NULL THEN
      UPDATE public.review_items SET
        last_reviewed_at = v_occurred_at,
        next_review_date = COALESCE(
          (v_sched_after->>'due')::TIMESTAMPTZ,
          (v_sched_after->>'next_review_date')::TIMESTAMPTZ,
          NOW() + INTERVAL '1 day'
        ),
        stability = LEAST(36500.0, GREATEST(0.1, COALESCE((v_sched_after->>'stability')::DOUBLE PRECISION, stability))),
        difficulty = LEAST(10.0, GREATEST(1.0, COALESCE((v_sched_after->>'difficulty')::DOUBLE PRECISION, difficulty))),
        fsrs_state = LEAST(3, GREATEST(0, COALESCE((v_sched_after->>'state')::SMALLINT, fsrs_state))),
        step = GREATEST(0, COALESCE((v_sched_after->>'step')::SMALLINT, step)),
        repetition_level = GREATEST(0, COALESCE((v_sched_after->>'repetition_level')::INTEGER, repetition_level)),
        ease_factor = LEAST(2.50, GREATEST(1.30, COALESCE((v_sched_after->>'ease_factor')::DECIMAL(3,2), ease_factor))),
        total_reviews = review_items.total_reviews + 1,
        correct_reviews = CASE 
          WHEN COALESCE((v_sched_after->>'correct_reviews')::INTEGER, -1) >= 0 
            THEN (v_sched_after->>'correct_reviews')::INTEGER
          WHEN COALESCE(v_rating, 0) >= 3 OR COALESCE(v_score, 0.0) >= 0.6 
            THEN review_items.correct_reviews + 1 
          ELSE review_items.correct_reviews 
        END,
        updated_at = NOW()
      WHERE user_id = v_auth_uid AND (id::TEXT = v_item_id OR content_id = v_item_id);
    END IF;

    -- 3. Update user_concept_state projection when concept evidence is provided
    v_concept_id_text := COALESCE(v_event->>'concept_id', v_metadata->>'concept_id');
    IF v_inserted IS TRUE AND v_concept_id_text IS NOT NULL AND v_concept_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      DECLARE
        v_cid UUID := v_concept_id_text::UUID;
        v_ev_score NUMERIC := LEAST(1.0, GREATEST(0.0, COALESCE(v_score::NUMERIC, CASE WHEN COALESCE(v_rating, 0) >= 3 THEN 1.0 ELSE 0.0 END)));
      BEGIN
        INSERT INTO public.user_concept_state (
          user_id, concept_id, evidence_count, weighted_correct, weighted_total, last_evidence_at, updated_at
        ) VALUES (
          v_auth_uid, v_cid, 1, v_ev_score, 1.0, v_occurred_at, NOW()
        )
        ON CONFLICT (user_id, concept_id) DO UPDATE SET
          evidence_count = user_concept_state.evidence_count + 1,
          weighted_correct = user_concept_state.weighted_correct + EXCLUDED.weighted_correct,
          weighted_total = user_concept_state.weighted_total + 1.0,
          last_evidence_at = EXCLUDED.last_evidence_at,
          updated_at = NOW();
      EXCEPTION WHEN OTHERS THEN
        NULL;
      END;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'status', 'success',
    'processed_count', v_processed_count
  );
END;
$$;

REVOKE ALL ON FUNCTION public.record_events(JSONB[]) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.record_events(JSONB[]) TO authenticated;

-- 6. RESET REVIEW ITEM PROGRESS RPC (ARCH-1, ARCH-3)
CREATE OR REPLACE FUNCTION public.reset_review_item_progress(
  p_item_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_user_id UUID := (SELECT auth.uid());
  v_item RECORD;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required to reset review item' USING ERRCODE = '42501';
  END IF;

  UPDATE public.review_items SET
    repetition_level = 0,
    ease_factor = 2.5,
    next_review_date = NOW() + INTERVAL '1 day',
    total_reviews = 0,
    correct_reviews = 0,
    stability = 2.0,
    difficulty = 5.0,
    fsrs_state = 1,
    retrievability = 1.0,
    step = 0,
    updated_at = NOW()
  WHERE id = p_item_id AND user_id = v_user_id
  RETURNING * INTO v_item;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Review item not found: %', p_item_id USING ERRCODE = 'P0002';
  END IF;

  RETURN to_jsonb(v_item);
END;
$$;

REVOKE ALL ON FUNCTION public.reset_review_item_progress(UUID) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.reset_review_item_progress(UUID) TO authenticated;

-- 7. SANITIZED ASSESSMENT QUESTIONS RPC (ARCH-1, FIX-12)
-- Returns assessment questions WITHOUT exposing correct_answer or explanation
CREATE OR REPLACE FUNCTION public.get_assessment_questions_for_taking(
  p_assessment_id UUID
)
RETURNS TABLE (
  id UUID,
  assessment_id UUID,
  question_text TEXT,
  options JSONB,
  order_index INTEGER
)
LANGUAGE sql
SECURITY DEFINER
SET search_path = public, extensions
STABLE
AS $$
  SELECT
    q.id,
    q.assessment_id,
    q.question_text,
    q.options,
    q.order_index
  FROM public.assessment_questions q
  JOIN public.skill_assessments sa ON sa.id = q.assessment_id
  WHERE q.assessment_id = p_assessment_id
    AND sa.is_active = TRUE
  ORDER BY q.order_index ASC, q.created_at ASC;
$$;

REVOKE ALL ON FUNCTION public.get_assessment_questions_for_taking(UUID) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_assessment_questions_for_taking(UUID) TO anon, authenticated;

-- 8. SERVER-SIDE START ATTEMPT RPC (ARCH-1, FIX-12)
-- Authoritatively starts an assessment attempt with server-owned start timestamp.
CREATE OR REPLACE FUNCTION public.start_assessment_attempt(
  p_assessment_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_user_id UUID := (SELECT auth.uid());
  v_attempt_id UUID := gen_random_uuid();
  v_existing_attempt_id UUID;
  v_total_questions INTEGER := 0;
  v_attempt public.assessment_attempts%ROWTYPE;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required to start assessment' USING ERRCODE = '42501';
  END IF;

  -- Advisory transaction lock serializes start_assessment_attempt per user + assessment,
  -- preventing concurrent callers from creating redundant duplicate attempts.
  PERFORM pg_advisory_xact_lock(hashtext(v_user_id::text), hashtext(p_assessment_id::text));

  PERFORM 1
  FROM public.skill_assessments
  WHERE id = p_assessment_id AND is_active = TRUE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Active assessment not found: %', p_assessment_id;
  END IF;

  -- Anti-harvesting attempt reuse: return existing active uncompleted attempt if started within the last 2 hours
  SELECT id INTO v_existing_attempt_id
  FROM public.assessment_attempts
  WHERE user_id = v_user_id
    AND assessment_id = p_assessment_id
    AND completed_at IS NULL
    AND is_deleted = FALSE
    AND started_at > NOW() - INTERVAL '2 hours'
  ORDER BY started_at DESC
  LIMIT 1;

  IF v_existing_attempt_id IS NOT NULL THEN
    SELECT * INTO v_attempt FROM public.assessment_attempts WHERE id = v_existing_attempt_id;
    RETURN to_jsonb(v_attempt);
  END IF;

  SELECT count(id)::INTEGER INTO v_total_questions
  FROM public.assessment_questions
  WHERE assessment_id = p_assessment_id;

  INSERT INTO public.assessment_attempts (
    id, assessment_id, user_id, started_at, total_questions, is_verified, is_deleted
  ) VALUES (
    v_attempt_id, p_assessment_id, v_user_id, NOW(), v_total_questions, FALSE, FALSE
  )
  RETURNING * INTO v_attempt;

  RETURN to_jsonb(v_attempt);
END;
$$;

REVOKE ALL ON FUNCTION public.start_assessment_attempt(UUID) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.start_assessment_attempt(UUID) TO authenticated;

-- 9. SERVER-SIDE ASSESSMENT ATTEMPT SUBMISSION & GRADING RPC (ARCH-1, FIX-12)
-- Evaluates submitted answers against actual correct answers on the server,
-- requires a valid started attempt, locks it atomically against concurrent submissions,
-- enforces server timing, marks verified (if not overtime), and awards verified XP.
CREATE OR REPLACE FUNCTION public.submit_and_grade_assessment(
  p_assessment_id UUID,
  p_answers JSONB,
  p_attempt_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_user_id UUID;
  v_assessment public.skill_assessments%ROWTYPE;
  v_attempt public.assessment_attempts%ROWTYPE;
  v_started_at TIMESTAMPTZ;
  v_time_spent_seconds INTEGER := 0;
  v_is_overtime BOOLEAN := FALSE;
  v_is_verified BOOLEAN := FALSE;
  v_effective_answers JSONB;
  v_answered_count INTEGER := 0;
  v_q RECORD;
  v_user_answer INTEGER;
  v_is_correct BOOLEAN;
  v_correct_count INTEGER := 0;
  v_total_questions INTEGER := 0;
  v_score INTEGER := 0;
  v_passed BOOLEAN := FALSE;
  v_prev_level INTEGER := 0;
  v_new_level INTEGER := 0;
  v_question_results JSONB := '[]'::JSONB;
  v_xp_awarded INTEGER := 0;
  v_xp_res JSONB;
BEGIN
  v_user_id := (SELECT auth.uid());
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required to submit assessment' USING ERRCODE = '42501';
  END IF;

  IF p_attempt_id IS NULL THEN
    RAISE EXCEPTION 'A valid assessment attempt ID is required to submit and grade answers'
      USING ERRCODE = '42501';
  END IF;

  -- 1. Fetch and validate assessment
  SELECT * INTO v_assessment
  FROM public.skill_assessments
  WHERE id = p_assessment_id AND is_active = TRUE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Active assessment not found: %', p_assessment_id;
  END IF;

  -- 2. Atomically lock and validate the attempt against concurrent completion
  SELECT * INTO v_attempt
  FROM public.assessment_attempts
  WHERE id = p_attempt_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Assessment attempt not found: %', p_attempt_id USING ERRCODE = 'P0002';
  END IF;

  IF v_attempt.user_id <> v_user_id THEN
    RAISE EXCEPTION 'Attempt does not belong to authenticated user'
      USING ERRCODE = '42501';
  END IF;

  IF v_attempt.assessment_id <> p_assessment_id THEN
    RAISE EXCEPTION 'Attempt assessment ID mismatch: expected %, got %', p_assessment_id, v_attempt.assessment_id;
  END IF;

  IF v_attempt.completed_at IS NOT NULL THEN
    RAISE EXCEPTION 'Assessment attempt already completed: %', p_attempt_id;
  END IF;

  v_started_at := COALESCE(v_attempt.started_at, NOW());
  v_time_spent_seconds := GREATEST(0, EXTRACT(EPOCH FROM (NOW() - v_started_at))::INTEGER);

  -- Server-side time limit enforcement (with 30-second network latency grace window)
  IF v_assessment.time_limit_minutes IS NOT NULL AND v_assessment.time_limit_minutes > 0 THEN
    v_is_overtime := (v_time_spent_seconds > (v_assessment.time_limit_minutes * 60 + 30));
  ELSE
    v_is_overtime := FALSE;
  END IF;

  -- 3. Meaningful Assessment Completion & Anti-Harvesting Policy
  v_effective_answers := COALESCE(v_attempt.answers, '{}'::JSONB) || COALESCE(p_answers, '{}'::JSONB);

  SELECT count(*)::INTEGER INTO v_total_questions
  FROM public.assessment_questions
  WHERE assessment_id = p_assessment_id;

  SELECT count(DISTINCT q.id)::INTEGER INTO v_answered_count
  FROM public.assessment_questions q
  WHERE q.assessment_id = p_assessment_id
    AND v_effective_answers ? q.id::TEXT
    AND v_effective_answers->>q.id::TEXT IS NOT NULL;

  IF v_answered_count = 0 THEN
    RAISE EXCEPTION 'Cannot grade assessment attempt: no answers provided'
      USING ERRCODE = '22023';
  END IF;

  IF v_answered_count < v_total_questions THEN
    RAISE EXCEPTION 'Assessment completion policy requires all questions to be answered (% of % answered)',
      v_answered_count, v_total_questions
      USING ERRCODE = '22023';
  END IF;

  -- Anti-harvesting rapid submission check (requires >= 2 seconds elapsed time)
  IF v_time_spent_seconds < 2 THEN
    RAISE EXCEPTION 'Assessment submission rejected: duration (% seconds) too short for valid completion',
      v_time_spent_seconds
      USING ERRCODE = '22023';
  END IF;

  -- 4. Fetch previous level
  SELECT level INTO v_prev_level
  FROM public.user_skill_stats
  WHERE user_id = v_user_id AND skill_id = v_assessment.skill_id;
  IF v_prev_level IS NULL THEN
    v_prev_level := 0;
  END IF;

  -- 5. First pass: compute score and determine pass/fail
  FOR v_q IN
    SELECT id, correct_answer
    FROM public.assessment_questions
    WHERE assessment_id = p_assessment_id
  LOOP
    v_user_answer := (v_effective_answers->>v_q.id::TEXT)::INTEGER;
    IF v_user_answer IS NOT NULL AND v_user_answer = v_q.correct_answer THEN
      v_correct_count := v_correct_count + 1;
    END IF;
  END LOOP;

  IF v_total_questions > 0 THEN
    v_score := ROUND((v_correct_count::NUMERIC / v_total_questions::NUMERIC) * 100);
  ELSE
    v_score := 0;
  END IF;

  v_passed := (v_score >= v_assessment.passing_score) AND (NOT v_is_overtime);
  v_is_verified := (NOT v_is_overtime);

  -- 6. Second pass: construct result payload with answer withholding policy
  -- If passed: disclose full answers, explanations, and per-question correctness for educational review.
  -- If failed: withhold all correct answers, explanations, and per-question correctness (is_correct)
  -- across all questions to completely eliminate answer-key harvesting and oracle probing
  -- across repeated attempts. The user receives only their overall score and pass status.
  FOR v_q IN
    SELECT id, question_text, options, correct_answer, explanation, order_index
    FROM public.assessment_questions
    WHERE assessment_id = p_assessment_id
    ORDER BY order_index ASC, created_at ASC
  LOOP
    v_user_answer := (v_effective_answers->>v_q.id::TEXT)::INTEGER;
    v_is_correct := (v_user_answer IS NOT NULL AND v_user_answer = v_q.correct_answer);

    v_question_results := v_question_results || jsonb_build_object(
      'question_id', v_q.id,
      'question_text', v_q.question_text,
      'options', v_q.options,
      'user_answer', v_user_answer,
      'correct_answer', CASE WHEN v_passed THEN v_q.correct_answer ELSE NULL END,
      'is_correct', CASE WHEN v_passed THEN v_is_correct ELSE NULL END,
      'explanation', CASE WHEN v_passed THEN v_q.explanation ELSE NULL END
    );
  END LOOP;

  -- 7. Authoritatively complete attempt with conditional atomic update
  UPDATE public.assessment_attempts SET
    completed_at = NOW(),
    score = v_score,
    correct_count = v_correct_count,
    total_questions = v_total_questions,
    time_taken_seconds = v_time_spent_seconds,
    was_overtime = v_is_overtime,
    is_verified = v_is_verified,
    answers = v_effective_answers
  WHERE id = p_attempt_id AND completed_at IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Assessment attempt already completed: %', p_attempt_id;
  END IF;

  -- 6. Recompute skill statistics
  PERFORM public.recompute_user_skill_stat(v_user_id, v_assessment.skill_id);

  SELECT level INTO v_new_level
  FROM public.user_skill_stats
  WHERE user_id = v_user_id AND skill_id = v_assessment.skill_id;
  IF v_new_level IS NULL THEN
    v_new_level := 0;
  END IF;

  -- 7. Authoritative XP Award (issued exclusively for passed, non-overtime attempts)
  IF v_passed THEN
    BEGIN
      v_xp_res := public.record_xp_award(
        p_attempt_id,
        'course_complete',
        100,
        p_attempt_id::TEXT,
        'Passed verified skill assessment: ' || v_assessment.title
      );
      IF (v_xp_res->>'status') = 'awarded' THEN
        v_xp_awarded := COALESCE((v_xp_res->>'xp_awarded')::INTEGER, 100);
      END IF;
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END IF;

  RETURN jsonb_build_object(
    'attempt_id', p_attempt_id,
    'assessment_id', p_assessment_id,
    'skill_id', v_assessment.skill_id,
    'score', v_score,
    'correct_count', v_correct_count,
    'total_questions', v_total_questions,
    'passing_score', v_assessment.passing_score,
    'passed', v_passed,
    'is_verified', v_is_verified,
    'time_spent_seconds', v_time_spent_seconds,
    'is_overtime', v_is_overtime,
    'xp_awarded', v_xp_awarded,
    'previous_level', v_prev_level,
    'new_level', v_new_level,
    'question_results', v_question_results
  );
END;
$$;

REVOKE ALL ON FUNCTION public.submit_and_grade_assessment(UUID, JSONB, UUID) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.submit_and_grade_assessment(UUID, JSONB, UUID) TO authenticated;

-- 10. PREVENT DIRECT CLIENT TAMPERING WITH ASSESSMENT ATTEMPTS
CREATE OR REPLACE FUNCTION public.check_attempt_client_dml()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public, extensions
AS $$
BEGIN
  IF current_user IN ('authenticated', 'anon') THEN
    IF TG_OP = 'INSERT' THEN
      IF NEW.is_verified = TRUE THEN
        RAISE EXCEPTION 'Cannot self-certify assessment attempt: is_verified must be false'
          USING ERRCODE = '42501';
      END IF;
      IF NEW.completed_at IS NOT NULL OR NEW.score IS NOT NULL THEN
        RAISE EXCEPTION 'Direct insertion of completed assessment attempt is forbidden'
          USING ERRCODE = '42501';
      END IF;
      IF NEW.started_at IS NULL THEN
        NEW.started_at := NOW();
      END IF;
      NEW.was_overtime := FALSE;
      NEW.correct_count := 0;
      NEW.time_taken_seconds := NULL;
    ELSIF TG_OP = 'UPDATE' THEN
      IF NEW.started_at IS DISTINCT FROM OLD.started_at THEN
        RAISE EXCEPTION 'Cannot modify started_at of an assessment attempt'
          USING ERRCODE = '42501';
      END IF;
      IF OLD.completed_at IS NOT NULL THEN
        RAISE EXCEPTION 'Cannot modify already completed assessment attempt'
          USING ERRCODE = '42501';
      END IF;
      IF NEW.completed_at IS NOT NULL 
         OR NEW.score IS NOT NULL 
         OR NEW.correct_count IS DISTINCT FROM OLD.correct_count 
         OR NEW.total_questions IS DISTINCT FROM OLD.total_questions 
         OR NEW.time_taken_seconds IS NOT NULL 
         OR NEW.was_overtime IS DISTINCT FROM OLD.was_overtime 
         OR NEW.is_verified = TRUE THEN
        RAISE EXCEPTION 'Cannot directly modify completion or scoring fields of an assessment attempt'
          USING ERRCODE = '42501';
      END IF;
      IF NEW.assessment_id IS DISTINCT FROM OLD.assessment_id OR NEW.user_id IS DISTINCT FROM OLD.user_id THEN
        RAISE EXCEPTION 'Cannot reassign attempt identity'
          USING ERRCODE = '42501';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_check_attempt_verified_write ON public.assessment_attempts;
DROP TRIGGER IF EXISTS trg_check_attempt_client_dml ON public.assessment_attempts;
CREATE TRIGGER trg_check_attempt_client_dml
  BEFORE INSERT OR UPDATE ON public.assessment_attempts
  FOR EACH ROW
  EXECUTE FUNCTION public.check_attempt_client_dml();

-- 11. EXCLUDE OVERTIME ATTEMPTS FROM VERIFIED SKILL METRICS
CREATE OR REPLACE FUNCTION public.calculate_skill_level(p_user_id UUID, p_skill_id UUID) 
RETURNS INTEGER AS $$
DECLARE
  v_level INTEGER;
BEGIN
  SELECT COALESCE(AVG(score)::INTEGER, 0) INTO v_level
  FROM (
    SELECT aa.score
    FROM public.assessment_attempts aa
    JOIN public.skill_assessments sa ON sa.id = aa.assessment_id
    WHERE aa.user_id = p_user_id
      AND sa.skill_id = p_skill_id
      AND aa.is_verified = TRUE
      AND aa.was_overtime = FALSE
      AND aa.is_deleted = FALSE
      AND aa.score IS NOT NULL
    ORDER BY aa.score DESC
    LIMIT 3
  ) best_attempts;
  
  RETURN v_level;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

CREATE OR REPLACE FUNCTION public.recompute_user_skill_stat(p_user_id UUID, p_skill_id UUID) 
RETURNS VOID AS $$
DECLARE
  v_new_level INTEGER := 0;
  v_best_score INTEGER := 0;
  v_avg_score NUMERIC(5,2) := 0;
  v_total INTEGER := 0;
  v_has_verified BOOLEAN := FALSE;
BEGIN
  IF p_user_id IS NULL OR p_skill_id IS NULL THEN
    RETURN;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext(p_user_id::text), hashtext(p_skill_id::text));

  SELECT COUNT(*) INTO v_total
  FROM public.assessment_attempts aa
  JOIN public.skill_assessments sa ON sa.id = aa.assessment_id
  WHERE aa.user_id = p_user_id
    AND sa.skill_id = p_skill_id
    AND aa.is_deleted = FALSE
    AND aa.completed_at IS NOT NULL
    AND aa.score IS NOT NULL;

  IF v_total = 0 THEN
    DELETE FROM public.user_skill_stats
    WHERE user_id = p_user_id
      AND skill_id = p_skill_id;
    RETURN;
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.assessment_attempts aa
    JOIN public.skill_assessments sa ON sa.id = aa.assessment_id
    WHERE aa.user_id = p_user_id
      AND sa.skill_id = p_skill_id
      AND aa.is_verified = TRUE
      AND aa.was_overtime = FALSE
      AND aa.is_deleted = FALSE
      AND aa.completed_at IS NOT NULL
      AND aa.score IS NOT NULL
  ) INTO v_has_verified;

  IF v_has_verified THEN
    v_new_level := public.calculate_skill_level(p_user_id, p_skill_id);
    
    SELECT 
      MAX(score),
      AVG(score)::NUMERIC(5,2),
      COUNT(*)
    INTO v_best_score, v_avg_score, v_total
    FROM public.assessment_attempts aa
    JOIN public.skill_assessments sa ON sa.id = aa.assessment_id
    WHERE aa.user_id = p_user_id
      AND sa.skill_id = p_skill_id
      AND aa.is_verified = TRUE
      AND aa.was_overtime = FALSE
      AND aa.is_deleted = FALSE
      AND aa.completed_at IS NOT NULL
      AND aa.score IS NOT NULL;
  ELSE
    -- When no verified attempts exist, level is 0 and verified metrics remain 0
    v_new_level := 0;
    v_best_score := 0;
    v_avg_score := 0;
  END IF;

  INSERT INTO public.user_skill_stats (
    user_id, skill_id, level, best_score, average_score, total_assessments, is_verified, last_assessed_at, updated_at
  ) VALUES (
    p_user_id, p_skill_id, v_new_level, v_best_score, v_avg_score, v_total, v_has_verified, NOW(), NOW()
  )
  ON CONFLICT (user_id, skill_id) DO UPDATE SET
    level = EXCLUDED.level,
    best_score = EXCLUDED.best_score,
    average_score = EXCLUDED.average_score,
    total_assessments = EXCLUDED.total_assessments,
    is_verified = EXCLUDED.is_verified,
    last_assessed_at = EXCLUDED.last_assessed_at,
    updated_at = NOW();
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

INSERT INTO supabase_migrations.schema_migrations (version, name) VALUES ('20261102140000', 'arch_01_learning_events_fsrs_and_server_scoring') ON CONFLICT (version) DO NOTHING;

-- --------------------------------------------------------------------
-- [86/96] Migration: 20261106000000_arch_02_item_analytics_and_readiness_v2.sql
-- --------------------------------------------------------------------
-- ============================================================================
-- Architecture Phase 1 Deliverable: Item Analytics & Readiness v2
-- Migration: 20261106000000_arch_02_item_analytics_and_readiness_v2.sql
-- ============================================================================

-- -----------------------------------------------------------------------------
-- 1. ITEM ANALYTICS & PSYCHOMETRICS TABLE
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.item_analytics (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  item_id UUID NOT NULL,
  item_type TEXT NOT NULL DEFAULT 'question',
  response_count INTEGER NOT NULL DEFAULT 0,
  correct_count INTEGER NOT NULL DEFAULT 0,
  p_value REAL,                    -- Classical Test Theory difficulty/facility: correct / total
  point_biserial REAL,             -- Item discrimination: correlation between item score and total score
  distractor_rates JSONB DEFAULT '{}'::jsonb, -- e.g. {"0": 0.65, "1": 0.05, "2": 0.30}
  distractor_counts JSONB DEFAULT '{}'::jsonb,
  median_latency_ms INTEGER,       -- Median learner response time
  iqr_latency_ms INTEGER,          -- Interquartile range of response time
  flagged_reasons TEXT[] DEFAULT ARRAY[]::TEXT[], -- e.g. ['negative_discrimination', 'dead_distractor']
  auto_flagged BOOLEAN NOT NULL DEFAULT false,
  moderation_report_id UUID REFERENCES public.moderation_reports(id) ON DELETE SET NULL,
  last_calculated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT uq_item_analytics_item UNIQUE (item_id, item_type)
);

CREATE INDEX IF NOT EXISTS idx_item_analytics_flagged
  ON public.item_analytics(auto_flagged, last_calculated_at DESC);
CREATE INDEX IF NOT EXISTS idx_item_analytics_item_id
  ON public.item_analytics(item_id);

ALTER TABLE public.item_analytics ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS item_analytics_select_policy ON public.item_analytics;
CREATE POLICY item_analytics_select_policy ON public.item_analytics
  FOR SELECT TO authenticated, service_role
  USING (true);

-- Direct client DML denied: calculations must flow through compute_item_analytics or service_role
REVOKE ALL ON public.item_analytics FROM PUBLIC, anon;
GRANT SELECT ON public.item_analytics TO authenticated;
GRANT ALL ON public.item_analytics TO service_role;

-- -----------------------------------------------------------------------------
-- 2. COMPUTE ITEM ANALYTICS & AUTO-FLAG MODERATION RPC
-- -----------------------------------------------------------------------------
-- Analyzes empirical learner responses from learning_events and completed assessment_attempts,
-- computes CTT p-value, point-biserial discrimination (r_pbis), distractor selection rates,
-- and median latency. Items violating quality bounds (negative discrimination, extreme difficulty,
-- dead distractors, extreme latency) are auto-flagged into public.moderation_reports.
CREATE OR REPLACE FUNCTION public.compute_item_analytics(
  p_min_responses INTEGER DEFAULT 5
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_total_evaluated INTEGER := 0;
  v_flagged_count INTEGER := 0;
  v_reports_created INTEGER := 0;

  v_flags TEXT[];
  v_is_flagged BOOLEAN;
  v_open_report_id UUID;
  v_new_report_id UUID;
  v_report_desc TEXT;
  v_item RECORD;
BEGIN
  FOR v_item IN
    WITH event_responses AS (
      SELECT
        item_id::UUID AS q_id,
        COALESCE(item_type, 'question') AS q_type,
        user_id AS u_id,
        score::REAL AS score,
        CASE
          WHEN jsonb_typeof(response) = 'object' THEN response->>'selected'
          WHEN jsonb_typeof(response) = 'string' THEN trim(both '"' from response::text)
          WHEN response IS NOT NULL THEN response::text
          ELSE NULL
        END AS selected_opt,
        latency_ms
      FROM public.learning_events
      WHERE score IS NOT NULL
        AND item_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ),
    attempt_responses AS (
      SELECT
        kv.key::UUID AS q_id,
        'question'::TEXT AS q_type,
        a.user_id AS u_id,
        CASE WHEN (kv.value = q.correct_answer::TEXT) THEN 1.0::REAL ELSE 0.0::REAL END AS score,
        kv.value AS selected_opt,
        CASE
          WHEN a.time_taken_seconds IS NOT NULL AND a.time_taken_seconds > 0 THEN
            GREATEST(500, (a.time_taken_seconds * 1000) / GREATEST(1, (SELECT count(*) FROM jsonb_each_text(a.answers))))
          ELSE NULL
        END AS latency_ms
      FROM public.assessment_attempts a
      CROSS JOIN LATERAL jsonb_each_text(a.answers) kv
      JOIN public.assessment_questions q ON q.id = kv.key::UUID
      WHERE a.completed_at IS NOT NULL
    ),
    raw_responses AS (
      SELECT * FROM event_responses
      UNION ALL
      SELECT ar.* FROM attempt_responses ar
      WHERE NOT EXISTS (
        SELECT 1 FROM event_responses er
        WHERE er.q_id = ar.q_id AND er.u_id = ar.u_id
      )
    ),
    user_ability AS (
      SELECT u_id, AVG(score)::REAL AS mean_score
      FROM raw_responses
      GROUP BY u_id
    ),
    item_user_pairs AS (
      SELECT
        r.q_id,
        r.q_type,
        r.u_id,
        r.score,
        r.selected_opt,
        r.latency_ms,
        ua.mean_score AS user_mean_score
      FROM raw_responses r
      JOIN user_ability ua ON ua.u_id = r.u_id
    ),
    item_summaries AS (
      SELECT
        iup.q_id,
        iup.q_type,
        COUNT(*)::INTEGER AS resp_count,
        COUNT(CASE WHEN iup.score >= 0.5 THEN 1 END)::INTEGER AS corr_count,
        AVG(iup.score)::REAL AS mean_score,
        AVG(iup.user_mean_score)::REAL AS mean_total,
        AVG(CASE WHEN iup.score >= 0.5 THEN iup.user_mean_score END)::REAL AS mean_correct,
        NULLIF(stddev_samp(iup.user_mean_score), 0)::REAL AS stddev_total,
        percentile_cont(0.50) WITHIN GROUP (ORDER BY iup.latency_ms)::INTEGER AS median_latency_ms,
        percentile_cont(0.25) WITHIN GROUP (ORDER BY iup.latency_ms)::INTEGER AS q1_latency_ms,
        percentile_cont(0.75) WITHIN GROUP (ORDER BY iup.latency_ms)::INTEGER AS q3_latency_ms
      FROM item_user_pairs iup
      GROUP BY iup.q_id, iup.q_type
      HAVING COUNT(*) >= p_min_responses
    ),
    item_distractors AS (
      SELECT
        r.q_id,
        jsonb_object_agg(COALESCE(r.selected_opt, 'unanswered'), r.cnt) AS dist_counts,
        jsonb_object_agg(COALESCE(r.selected_opt, 'unanswered'), ROUND((r.cnt::NUMERIC / s.resp_count::NUMERIC), 4)) AS dist_rates
      FROM (
        SELECT q_id, selected_opt, COUNT(*)::INTEGER AS cnt
        FROM raw_responses
        GROUP BY q_id, selected_opt
      ) r
      JOIN item_summaries s ON s.q_id = r.q_id
      GROUP BY r.q_id
    )
    SELECT
      s.q_id,
      s.q_type,
      s.resp_count,
      s.corr_count,
      s.mean_score AS p_value,
      CASE
        WHEN s.stddev_total IS NOT NULL AND s.mean_score > 0.0 AND s.mean_score < 1.0 AND s.mean_correct IS NOT NULL THEN
          GREATEST(-1.0, LEAST(1.0, ((s.mean_correct - s.mean_total) / s.stddev_total) * sqrt(s.mean_score / (1.0 - s.mean_score))))
        ELSE 0.0
      END::REAL AS point_biserial,
      s.median_latency_ms,
      CASE
        WHEN s.q1_latency_ms IS NOT NULL AND s.q3_latency_ms IS NOT NULL THEN (s.q3_latency_ms - s.q1_latency_ms)
        ELSE NULL
      END AS iqr_latency_ms,
      COALESCE(d.dist_counts, '{}'::jsonb) AS dist_counts,
      COALESCE(d.dist_rates, '{}'::jsonb) AS dist_rates
    FROM item_summaries s
    LEFT JOIN item_distractors d ON d.q_id = s.q_id
  LOOP
    v_total_evaluated := v_total_evaluated + 1;
    v_flags := ARRAY[]::TEXT[];
    v_is_flagged := false;

    -- Flag Evaluation
    -- 1. Negative discrimination: higher ability learners miss it more often
    IF v_item.point_biserial < 0.0 AND v_item.resp_count >= 8 THEN
      v_flags := array_append(v_flags, 'negative_discrimination');
      v_is_flagged := true;
    END IF;

    -- 2. Extreme difficulty: p < 0.15 (below chance on 4-option MCQ)
    IF v_item.p_value < 0.15 AND v_item.resp_count >= 8 THEN
      v_flags := array_append(v_flags, 'extreme_difficulty');
      v_is_flagged := true;
    END IF;

    -- 3. Extreme ease: p > 0.95 (ceiling effect, poor discrimination)
    IF v_item.p_value > 0.95 AND v_item.resp_count >= 20 THEN
      v_flags := array_append(v_flags, 'extreme_ease');
    END IF;

    -- 4. Dead distractor: an option nobody chooses (< 3% rate when N >= 20)
    IF v_item.resp_count >= 20 AND EXISTS (
      SELECT 1 FROM jsonb_each_text(v_item.dist_rates)
      WHERE value::REAL < 0.03
    ) THEN
      v_flags := array_append(v_flags, 'dead_distractor');
      v_is_flagged := true;
    END IF;

    -- 5. Suspicious speed / latency outlier
    IF v_item.median_latency_ms IS NOT NULL AND v_item.median_latency_ms < 3000 AND v_item.resp_count >= 10 THEN
      v_flags := array_append(v_flags, 'suspicious_low_latency');
    END IF;
    IF v_item.median_latency_ms IS NOT NULL AND v_item.median_latency_ms > 180000 AND v_item.resp_count >= 10 THEN
      v_flags := array_append(v_flags, 'high_latency_outlier');
      v_is_flagged := true;
    END IF;

    -- Check for existing open moderation report
    SELECT id INTO v_open_report_id
    FROM public.moderation_reports
    WHERE target_type = 'question'
      AND target_id = v_item.q_id
      AND status IN ('pending', 'under_review')
    LIMIT 1;

    -- Auto-flag into moderation queue if critical defect identified and not already reported
    IF v_is_flagged THEN
      v_flagged_count := v_flagged_count + 1;

      IF v_open_report_id IS NULL THEN
        v_report_desc := '[Item Analytics Auto-Flag] Defects: ' || array_to_string(v_flags, ', ') ||
          '. p-value: ' || ROUND(v_item.p_value::NUMERIC, 3)::TEXT ||
          ', r_pbis: ' || ROUND(v_item.point_biserial::NUMERIC, 3)::TEXT ||
          ', N=' || v_item.resp_count::TEXT ||
          ', median latency: ' || COALESCE(v_item.median_latency_ms::TEXT, 'N/A') || 'ms. ' ||
          'Distractor rates: ' || v_item.dist_rates::TEXT ||
          '. Requires psychometric content review for miskeying or ambiguity.';

        INSERT INTO public.moderation_reports (
          reporter_id,
          target_type,
          target_id,
          reason,
          description,
          status
        ) VALUES (
          NULL,
          'question',
          v_item.q_id,
          'other',
          v_report_desc,
          'pending'
        ) RETURNING id INTO v_new_report_id;

        v_reports_created := v_reports_created + 1;
        v_open_report_id := v_new_report_id;
      END IF;
    END IF;

    -- Upsert into public.item_analytics
    INSERT INTO public.item_analytics (
      item_id,
      item_type,
      response_count,
      correct_count,
      p_value,
      point_biserial,
      distractor_rates,
      distractor_counts,
      median_latency_ms,
      iqr_latency_ms,
      flagged_reasons,
      auto_flagged,
      moderation_report_id,
      last_calculated_at
    ) VALUES (
      v_item.q_id,
      v_item.q_type,
      v_item.resp_count,
      v_item.corr_count,
      v_item.p_value,
      v_item.point_biserial,
      v_item.dist_rates,
      v_item.dist_counts,
      v_item.median_latency_ms,
      v_item.iqr_latency_ms,
      v_flags,
      v_is_flagged,
      v_open_report_id,
      NOW()
    )
    ON CONFLICT (item_id, item_type) DO UPDATE SET
      response_count = EXCLUDED.response_count,
      correct_count = EXCLUDED.correct_count,
      p_value = EXCLUDED.p_value,
      point_biserial = EXCLUDED.point_biserial,
      distractor_rates = EXCLUDED.distractor_rates,
      distractor_counts = EXCLUDED.distractor_counts,
      median_latency_ms = EXCLUDED.median_latency_ms,
      iqr_latency_ms = EXCLUDED.iqr_latency_ms,
      flagged_reasons = EXCLUDED.flagged_reasons,
      auto_flagged = EXCLUDED.auto_flagged,
      moderation_report_id = COALESCE(EXCLUDED.moderation_report_id, item_analytics.moderation_report_id),
      last_calculated_at = NOW();

  END LOOP;

  RETURN jsonb_build_object(
    'total_evaluated', v_total_evaluated,
    'flagged_items', v_flagged_count,
    'moderation_reports_created', v_reports_created
  );
END;
$$;

REVOKE ALL ON FUNCTION public.compute_item_analytics(INTEGER) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.compute_item_analytics(INTEGER) TO authenticated, service_role;

-- -----------------------------------------------------------------------------
-- 3. GET ITEM ANALYTICS RPC
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.get_item_analytics(
  p_item_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_rec RECORD;
BEGIN
  SELECT * INTO v_rec
  FROM public.item_analytics
  WHERE item_id = p_item_id
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  RETURN jsonb_build_object(
    'item_id', v_rec.item_id,
    'item_type', v_rec.item_type,
    'response_count', v_rec.response_count,
    'correct_count', v_rec.correct_count,
    'p_value', v_rec.p_value,
    'point_biserial', v_rec.point_biserial,
    'distractor_rates', v_rec.distractor_rates,
    'distractor_counts', v_rec.distractor_counts,
    'median_latency_ms', v_rec.median_latency_ms,
    'iqr_latency_ms', v_rec.iqr_latency_ms,
    'flagged_reasons', v_rec.flagged_reasons,
    'auto_flagged', v_rec.auto_flagged,
    'moderation_report_id', v_rec.moderation_report_id,
    'last_calculated_at', v_rec.last_calculated_at
  );
END;
$$;

REVOKE ALL ON FUNCTION public.get_item_analytics(UUID) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_item_analytics(UUID) TO authenticated, service_role;

-- -----------------------------------------------------------------------------
-- 4. SERVER-SIDE READINESS V2 WITH FSRS CALIBRATION RPC (FIX-9, ARCH-4)
-- -----------------------------------------------------------------------------
-- Evaluates learner exam readiness for a Learning Target Version without client inFilter
-- query truncation (FIX-9). Synthesizes:
--   1. Authoritative core concept curriculum blueprint coverage
--   2. Projected FSRS retrievability R(t) at target exam date
--   3. Empirical assessment evidence and confidence discounting
-- Returns structured readiness payload with qualitative bands.
CREATE OR REPLACE FUNCTION public.get_target_readiness_v2(
  p_target_version_id UUID,
  p_exam_date TIMESTAMPTZ DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_user_id UUID;
  v_target_date TIMESTAMPTZ;
  v_result JSONB;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required to evaluate readiness' USING ERRCODE = '42501';
  END IF;

  v_target_date := COALESCE(p_exam_date, NOW());

  WITH node_core_concepts AS (
    SELECT
      cnc.concept_id AS cid,
      MAX(COALESCE(cnc.weight, 1.0))::NUMERIC AS max_w
    FROM public.curriculum_nodes cn
    JOIN public.curriculum_node_concepts cnc ON cnc.curriculum_node_id = cn.id
    WHERE cn.target_version_id = p_target_version_id
      AND cnc.relevance = 'core'
    GROUP BY cnc.concept_id
  ),
  concept_details AS (
    SELECT
      ncc.cid AS concept_id,
      COALESCE(kc.name, kc.slug, 'Concept ' || SUBSTRING(ncc.cid::TEXT FROM 1 FOR 8)) AS concept_title,
      ncc.max_w AS weight,
      CASE
        WHEN ucs.weighted_total > 0 THEN (ucs.weighted_correct / ucs.weighted_total)::NUMERIC
        ELSE 0.0
      END AS accuracy,
      COALESCE(ucs.evidence_count, 0) AS evidence_count,
      COALESCE(ucs.retrieval_band, 'unassessed') AS retrieval_band,
      ri.stability,
      ri.last_reviewed_at,
      CASE
        WHEN ri.stability IS NOT NULL AND ri.stability > 0 THEN
          GREATEST(0.0, LEAST(1.0,
            POWER(
              1.0 + 19.0 * (
                GREATEST(0.0, EXTRACT(EPOCH FROM (v_target_date - COALESCE(ri.last_reviewed_at, NOW()))) / 86400.0)
                / (9.0 * ri.stability)
              ),
              -0.5
            )::NUMERIC
          ))
        ELSE NULL
      END AS projected_retrievability
    FROM node_core_concepts ncc
    LEFT JOIN public.knowledge_concepts kc ON kc.id = ncc.cid
    LEFT JOIN public.user_concept_state ucs ON ucs.concept_id = ncc.cid AND ucs.user_id = v_user_id
    LEFT JOIN LATERAL (
      SELECT r.stability, r.last_reviewed_at
      FROM public.review_items r
      WHERE r.user_id = v_user_id
        AND r.content_id = ncc.cid::TEXT
        AND r.stability IS NOT NULL
      ORDER BY r.last_reviewed_at DESC NULLS LAST
      LIMIT 1
    ) ri ON true
  ),
  scored_concepts AS (
    SELECT
      cd.*,
      CASE
        WHEN cd.evidence_count > 0 OR cd.projected_retrievability IS NOT NULL THEN
          CASE
            WHEN cd.projected_retrievability IS NOT NULL THEN
              (0.60 * cd.projected_retrievability) + (0.40 * cd.accuracy)
            ELSE
              cd.accuracy * LEAST(1.0, cd.evidence_count / 5.0)
          END
        ELSE 0.0
      END AS concept_score,
      CASE
        WHEN cd.evidence_count > 0 OR cd.projected_retrievability IS NOT NULL THEN 1
        ELSE 0
      END AS is_assessed
    FROM concept_details cd
  ),
  aggregates AS (
    SELECT
      COUNT(*)::INTEGER AS total_core,
      COALESCE(SUM(is_assessed), 0)::INTEGER AS assessed_count,
      COALESCE(SUM(weight), 0.0)::NUMERIC AS total_weight,
      CASE
        WHEN COALESCE(SUM(weight), 0.0) > 0 THEN
          COALESCE(SUM(concept_score * weight), 0.0) / SUM(weight)
        ELSE 0.0
      END::NUMERIC AS final_score,
      COALESCE(
        AVG(projected_retrievability) FILTER (WHERE projected_retrievability IS NOT NULL),
        0.0
      )::NUMERIC AS avg_retrievability,
      COUNT(*) FILTER (WHERE retrieval_band = 'well_established')::INTEGER AS dist_established,
      COUNT(*) FILTER (WHERE retrieval_band = 'well_retained')::INTEGER AS dist_retained,
      COUNT(*) FILTER (WHERE retrieval_band = 'developing')::INTEGER AS dist_developing,
      COUNT(*) FILTER (WHERE retrieval_band = 'needs_reinforcement')::INTEGER AS dist_reinforce,
      COUNT(*) FILTER (WHERE retrieval_band NOT IN ('well_established', 'well_retained', 'developing', 'needs_reinforcement'))::INTEGER AS dist_unassessed
    FROM scored_concepts
  ),
  weakest AS (
    SELECT COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'concept_id', sc.concept_id,
          'title', sc.concept_title,
          'score', ROUND(sc.concept_score, 3),
          'projected_retrievability', CASE WHEN sc.projected_retrievability IS NOT NULL THEN ROUND(sc.projected_retrievability, 3) ELSE NULL END,
          'evidence_count', sc.evidence_count
        )
      ),
      '[]'::jsonb
    ) AS weakest_concepts
    FROM (
      SELECT *
      FROM scored_concepts
      WHERE is_assessed = 1
      ORDER BY concept_score ASC, weight DESC
      LIMIT 5
    ) sc
  )
  SELECT
    jsonb_build_object(
      'target_version_id', p_target_version_id,
      'exam_date', v_target_date,
      'readiness_score', ROUND(agg.final_score, 4),
      'readiness_band', (
        CASE
          WHEN agg.total_core = 0 OR agg.assessed_count = 0 OR (agg.assessed_count::NUMERIC / GREATEST(1, agg.total_core)) < 0.20 THEN
            'notYetAssessed'
          WHEN agg.final_score >= 0.85 AND (agg.assessed_count::NUMERIC / agg.total_core) >= 0.80 THEN
            'strongCoverage'
          WHEN agg.final_score >= 0.60 AND (agg.assessed_count::NUMERIC / agg.total_core) >= 0.40 THEN
            'developing'
          ELSE
            'needsReinforcement'
        END
      ),
      'total_core_concepts', agg.total_core,
      'assessed_concepts_count', agg.assessed_count,
      'average_retrievability', ROUND(agg.avg_retrievability, 4),
      'retrieval_bands', jsonb_build_object(
        'well_established', agg.dist_established,
        'well_retained', agg.dist_retained,
        'developing', agg.dist_developing,
        'needs_reinforcement', agg.dist_reinforce,
        'unassessed', agg.dist_unassessed
      ),
      'weakest_concepts', w.weakest_concepts
    )
  INTO v_result
  FROM aggregates agg
  CROSS JOIN weakest w;

  RETURN v_result;
END;
$$;

REVOKE ALL ON FUNCTION public.get_target_readiness_v2(UUID, TIMESTAMPTZ) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_target_readiness_v2(UUID, TIMESTAMPTZ) TO authenticated, service_role;

INSERT INTO supabase_migrations.schema_migrations (version, name) VALUES ('20261106000000', 'arch_02_item_analytics_and_readiness_v2') ON CONFLICT (version) DO NOTHING;

-- --------------------------------------------------------------------
-- [87/96] Migration: 20261106010000_arch_03_versioned_api_schema_and_scope_resolver.sql
-- --------------------------------------------------------------------
-- ============================================================================
-- Architecture Phase 2 Deliverable: Versioned API Schema & Fast Scope Resolver
-- Migration: 20261106010000_arch_03_versioned_api_schema_and_scope_resolver.sql
-- ============================================================================

-- -----------------------------------------------------------------------------
-- 1. VERSIONED API SCHEMA CREATION (ARCH-2)
-- -----------------------------------------------------------------------------
CREATE SCHEMA IF NOT EXISTS api;
GRANT USAGE ON SCHEMA api TO anon, authenticated, service_role;

-- -----------------------------------------------------------------------------
-- 2. FAST SCOPE RESOLVER RPC: api.resolve_scope (ARCH-2, PERF-8)
-- -----------------------------------------------------------------------------
-- Resolves the bounded learning scope, curriculum hierarchy, and deterministic
-- activity sequence for any active learning context in a single server-side query.
-- Replaces client-side N+1 query cascades (35 round-trips with inFilter).
CREATE OR REPLACE FUNCTION api.resolve_scope(
  p_context JSONB
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, api
AS $$
DECLARE
  v_context_id TEXT;
  v_root_type TEXT;
  v_root_id TEXT;
  v_target_version_id UUID;
  v_config_hash TEXT;

  v_node_ids UUID[] := ARRAY[]::UUID[];
  v_core_concept_ids UUID[] := ARRAY[]::UUID[];
  v_supporting_concept_ids UUID[] := ARRAY[]::UUID[];
  v_related_concept_ids UUID[] := ARRAY[]::UUID[];

  v_activities JSONB := '[]'::JSONB;
  v_question_ids TEXT[] := ARRAY[]::TEXT[];
  v_term_ids TEXT[] := ARRAY[]::TEXT[];
  v_flashcard_ids TEXT[] := ARRAY[]::TEXT[];

  v_target_id UUID;
BEGIN
  v_context_id := COALESCE(p_context->>'id', p_context->>'context_id', 'ctx-default');
  v_root_type := COALESCE(p_context->>'root_type', 'target');
  v_root_id := p_context->>'root_id';
  v_config_hash := p_context->>'config_hash';

  -- Parse target_version_id if provided
  IF p_context ? 'target_version_id' AND p_context->>'target_version_id' IS NOT NULL AND (p_context->>'target_version_id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_target_version_id := (p_context->>'target_version_id')::UUID;
  END IF;

  -- ---------------------------------------------------------------------------
  -- RESOLUTION BY ROOT TYPE: TARGET
  -- ---------------------------------------------------------------------------
  IF v_root_type = 'target' THEN
    -- If no target_version_id supplied, resolve latest published version for target
    IF v_target_version_id IS NULL AND v_root_id IS NOT NULL THEN
      IF v_root_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        v_target_id := v_root_id::UUID;
        SELECT id INTO v_target_version_id
        FROM public.target_versions
        WHERE target_id = v_target_id AND status = 'published'
        ORDER BY created_at DESC
        LIMIT 1;
      ELSE
        -- Match slug if root_id is not a UUID
        SELECT tv.id INTO v_target_version_id
        FROM public.learning_targets lt
        JOIN public.target_versions tv ON tv.target_id = lt.id
        WHERE lt.slug = v_root_id AND tv.status = 'published'
        ORDER BY tv.created_at DESC
        LIMIT 1;
      END IF;
    END IF;

    -- When target version is located, resolve complete curriculum graph
    IF v_target_version_id IS NOT NULL THEN
      -- 1. Curriculum Node IDs
      SELECT ARRAY_AGG(id) INTO v_node_ids
      FROM public.curriculum_nodes
      WHERE target_version_id = v_target_version_id;
      v_node_ids := COALESCE(v_node_ids, ARRAY[]::UUID[]);

      -- 2. Core, Supporting, and Related Concepts
      SELECT ARRAY_AGG(DISTINCT cnc.concept_id) INTO v_core_concept_ids
      FROM public.curriculum_node_concepts cnc
      JOIN public.curriculum_nodes cn ON cn.id = cnc.curriculum_node_id
      WHERE cn.target_version_id = v_target_version_id AND cnc.relevance = 'core';
      v_core_concept_ids := COALESCE(v_core_concept_ids, ARRAY[]::UUID[]);

      SELECT ARRAY_AGG(DISTINCT cnc.concept_id) INTO v_supporting_concept_ids
      FROM public.curriculum_node_concepts cnc
      JOIN public.curriculum_nodes cn ON cn.id = cnc.curriculum_node_id
      WHERE cn.target_version_id = v_target_version_id AND cnc.relevance = 'supporting';
      v_supporting_concept_ids := COALESCE(v_supporting_concept_ids, ARRAY[]::UUID[]);

      SELECT ARRAY_AGG(DISTINCT cnc.concept_id) INTO v_related_concept_ids
      FROM public.curriculum_node_concepts cnc
      JOIN public.curriculum_nodes cn ON cn.id = cnc.curriculum_node_id
      WHERE cn.target_version_id = v_target_version_id AND cnc.relevance = 'related';
      v_related_concept_ids := COALESCE(v_related_concept_ids, ARRAY[]::UUID[]);

      -- 3. Ordered Activities from Nodes and Linked Public Lessons
      SELECT COALESCE(jsonb_agg(act), '[]'::JSONB) INTO v_activities
      FROM (
        SELECT
          cn.id::TEXT AS activity_id,
          'lesson'::TEXT AS kind,
          'official'::TEXT AS source,
          TRUE AS is_required,
          cn.id::TEXT AS curriculum_node_id,
          COALESCE(cn.sort_order, 0) AS curriculum_order,
          COALESCE(cn.sort_order, 0) AS activity_order,
          'core'::TEXT AS role,
          COALESCE(cn.title, 'Node ' || cn.code) AS title,
          COALESCE((cn.metadata->>'estimated_minutes')::INTEGER, 10) AS estimated_minutes,
          NULL::TEXT AS course_id,
          NULL::TEXT AS course_title,
          NULL::TEXT AS module_id,
          NULL::TEXT AS module_title
        FROM public.curriculum_nodes cn
        WHERE cn.target_version_id = v_target_version_id
        ORDER BY COALESCE(cn.sort_order, 0) ASC
      ) act;

      -- 4. Assessment Item and Question IDs
      SELECT ARRAY_AGG(DISTINCT ai.id::TEXT) INTO v_question_ids
      FROM public.assessment_items ai
      WHERE ai.origin_target_version_id = v_target_version_id;
      v_question_ids := COALESCE(v_question_ids, ARRAY[]::TEXT[]);

      -- Also collect question IDs from questions table if any
      IF array_length(v_node_ids, 1) > 0 THEN
        DECLARE
          v_extra_qids TEXT[];
        BEGIN
          SELECT ARRAY_AGG(DISTINCT q.id::TEXT) INTO v_extra_qids
          FROM public.assessment_questions q
          JOIN public.curriculum_node_lessons cnl ON cnl.lesson_id = q.assessment_id
          WHERE cnl.curriculum_node_id = ANY(v_node_ids);

          IF v_extra_qids IS NOT NULL THEN
            v_question_ids := ARRAY(
              SELECT DISTINCT unnest(v_question_ids || v_extra_qids)
            );
          END IF;
        END;
      END IF;

    END IF;

  -- ---------------------------------------------------------------------------
  -- RESOLUTION BY ROOT TYPE: LESSON
  -- ---------------------------------------------------------------------------
  ELSIF v_root_type = 'lesson' AND v_root_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    DECLARE
      v_lid UUID := v_root_id::UUID;
    BEGIN
      -- Questions linked to lesson
      SELECT ARRAY_AGG(id::TEXT) INTO v_question_ids
      FROM public.assessment_questions
      WHERE assessment_id = v_lid;
      v_question_ids := COALESCE(v_question_ids, ARRAY[]::TEXT[]);

      -- Single activity representing the lesson
      SELECT COALESCE(jsonb_agg(act), '[]'::JSONB) INTO v_activities
      FROM (
        SELECT
          l.id::TEXT AS activity_id,
          'lesson'::TEXT AS kind,
          'official'::TEXT AS source,
          TRUE AS is_required,
          cnl.curriculum_node_id::TEXT AS curriculum_node_id,
          0 AS curriculum_order,
          0 AS activity_order,
          'core'::TEXT AS role,
          COALESCE(l.title, 'Lesson') AS title,
          15 AS estimated_minutes,
          NULL::TEXT AS course_id,
          NULL::TEXT AS course_title,
          NULL::TEXT AS module_id,
          NULL::TEXT AS module_title
        FROM public.lessons l
        LEFT JOIN public.curriculum_node_lessons cnl ON cnl.lesson_id = l.id
        WHERE l.id = v_lid
      ) act;
    END;

  END IF;

  -- Return complete structured ResolvedScope JSON
  RETURN jsonb_build_object(
    'context_id', v_context_id,
    'core_concept_ids', COALESCE(to_jsonb(v_core_concept_ids), '[]'::JSONB),
    'supporting_concept_ids', COALESCE(to_jsonb(v_supporting_concept_ids), '[]'::JSONB),
    'related_concept_ids', COALESCE(to_jsonb(v_related_concept_ids), '[]'::JSONB),
    'curriculum_node_ids', COALESCE(to_jsonb(v_node_ids), '[]'::JSONB),
    'ordered_activities', v_activities,
    'question_ids', COALESCE(to_jsonb(v_question_ids), '[]'::JSONB),
    'term_ids', COALESCE(to_jsonb(v_term_ids), '[]'::JSONB),
    'flashcard_ids', COALESCE(to_jsonb(v_flashcard_ids), '[]'::JSONB),
    'resolved_at', NOW(),
    'config_hash', v_config_hash
  );
END;
$$;

-- Public schema alias for client compatibility
CREATE OR REPLACE FUNCTION public.resolve_scope(
  p_context JSONB
)
RETURNS JSONB
LANGUAGE sql
SECURITY DEFINER
SET search_path = public, extensions, api
AS $$
  SELECT api.resolve_scope(p_context);
$$;

REVOKE ALL ON FUNCTION api.resolve_scope(JSONB) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION api.resolve_scope(JSONB) TO anon, authenticated, service_role;
REVOKE ALL ON FUNCTION public.resolve_scope(JSONB) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.resolve_scope(JSONB) TO anon, authenticated, service_role;

-- -----------------------------------------------------------------------------
-- 3. LEARNER SUMMARY RPC: api.get_learner_summary (ARCH-2, ARCH-1)
-- -----------------------------------------------------------------------------
-- Computes the learner's active due counts, FSRS memory parameters, review backlog,
-- and recent study streak in a single consolidated RPC.
CREATE OR REPLACE FUNCTION api.get_learner_summary(
  p_context_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, api
AS $$
DECLARE
  v_uid UUID;
  v_due_count INTEGER := 0;
  v_total_reviewed INTEGER := 0;
  v_correct_reviewed INTEGER := 0;
  v_avg_stability DOUBLE PRECISION := 0.0;
  v_avg_difficulty DOUBLE PRECISION := 0.0;
  v_weakest_concepts JSONB := '[]'::JSONB;
  v_retention_rate REAL := 0.0;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required for learner summary' USING ERRCODE = '42501';
  END IF;

  -- 1. Spaced Repetition Due & Performance Aggregates
  SELECT
    COUNT(*) FILTER (WHERE next_review_date <= NOW()),
    COALESCE(SUM(total_reviews), 0),
    COALESCE(SUM(correct_reviews), 0),
    COALESCE(AVG(stability), 1.0),
    COALESCE(AVG(difficulty), 5.0)
  INTO
    v_due_count,
    v_total_reviewed,
    v_correct_reviewed,
    v_avg_stability,
    v_avg_difficulty
  FROM public.review_items
  WHERE user_id = v_uid;

  IF v_total_reviewed > 0 THEN
    v_retention_rate := (v_correct_reviewed::REAL / v_total_reviewed::REAL);
  END IF;

  -- 2. Weakest Concepts from Evidence Projection
  SELECT COALESCE(jsonb_agg(wc), '[]'::JSONB) INTO v_weakest_concepts
  FROM (
    SELECT
      ucs.concept_id::TEXT AS concept_id,
      COALESCE(kc.name, kc.slug, 'Concept ' || SUBSTRING(ucs.concept_id::TEXT FROM 1 FOR 8)) AS concept_title,
      CASE
        WHEN ucs.weighted_total > 0 THEN (ucs.weighted_correct / ucs.weighted_total)::NUMERIC(4,3)
        ELSE 0.0
      END AS accuracy,
      ucs.evidence_count,
      ucs.last_evidence_at
    FROM public.user_concept_state ucs
    LEFT JOIN public.knowledge_concepts kc ON kc.id = ucs.concept_id
    WHERE ucs.user_id = v_uid AND ucs.evidence_count >= 1
    ORDER BY (
      CASE WHEN ucs.weighted_total > 0 THEN (ucs.weighted_correct / ucs.weighted_total) ELSE 0.0 END
    ) ASC, ucs.evidence_count DESC
    LIMIT 5
  ) wc;

  RETURN jsonb_build_object(
    'user_id', v_uid,
    'context_id', p_context_id,
    'due_reviews_count', v_due_count,
    'total_reviews_count', v_total_reviewed,
    'correct_reviews_count', v_correct_reviewed,
    'retention_rate', ROUND(v_retention_rate::NUMERIC, 3),
    'average_stability', ROUND(v_avg_stability::NUMERIC, 2),
    'average_difficulty', ROUND(v_avg_difficulty::NUMERIC, 2),
    'weakest_concepts', v_weakest_concepts,
    'generated_at', NOW()
  );
END;
$$;

-- Public schema alias for client compatibility
CREATE OR REPLACE FUNCTION public.get_learner_summary(
  p_context_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE sql
SECURITY DEFINER
SET search_path = public, extensions, api
AS $$
  SELECT api.get_learner_summary(p_context_id);
$$;

REVOKE ALL ON FUNCTION api.get_learner_summary(UUID) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION api.get_learner_summary(UUID) TO authenticated, service_role;
REVOKE ALL ON FUNCTION public.get_learner_summary(UUID) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_learner_summary(UUID) TO authenticated, service_role;

-- -----------------------------------------------------------------------------
-- 4. UNIFIED CATALOG SEARCH RPC: api.search_catalog (ARCH-2, OPP-1)
-- -----------------------------------------------------------------------------
-- High-performance indexed catalog search across learning targets, certifications,
-- academic degrees, and licensure pathways with active version resolution.
CREATE OR REPLACE FUNCTION api.search_catalog(
  p_query TEXT DEFAULT NULL,
  p_category TEXT DEFAULT NULL,
  p_limit INTEGER DEFAULT 20
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, api
AS $$
DECLARE
  v_limit INTEGER;
  v_results JSONB := '[]'::JSONB;
BEGIN
  v_limit := LEAST(100, GREATEST(1, COALESCE(p_limit, 20)));

  SELECT COALESCE(jsonb_agg(cat), '[]'::JSONB) INTO v_results
  FROM (
    SELECT
      lt.id,
      lt.slug,
      lt.title,
      lt.description,
      lt.target_type AS category,
      COALESCE(lt.provider_name, lt.institution_name) AS issuer,
      tv.id AS active_version_id,
      tv.version_code,
      tv.title AS version_title,
      lt.created_at
    FROM public.learning_targets lt
    LEFT JOIN LATERAL (
      SELECT id, version_code, title
      FROM public.target_versions
      WHERE target_id = lt.id AND status = 'published'
      ORDER BY created_at DESC
      LIMIT 1
    ) tv ON TRUE
    WHERE (
      p_category IS NULL OR lt.target_type = p_category
    )
    AND (
      p_query IS NULL OR p_query = '' OR (
        lt.title ILIKE '%' || p_query || '%' OR
        lt.description ILIKE '%' || p_query || '%' OR
        lt.slug ILIKE '%' || p_query || '%' OR
        COALESCE(lt.provider_name, lt.institution_name, '') ILIKE '%' || p_query || '%'
      )
    )
    ORDER BY (
      CASE
        WHEN p_query IS NOT NULL AND lt.title ILIKE p_query || '%' THEN 1
        WHEN p_query IS NOT NULL AND lt.title ILIKE '%' || p_query || '%' THEN 2
        ELSE 3
      END
    ), lt.title ASC
    LIMIT v_limit
  ) cat;

  RETURN v_results;
END;
$$;

-- Public schema alias for client compatibility
CREATE OR REPLACE FUNCTION public.search_catalog(
  p_query TEXT DEFAULT NULL,
  p_category TEXT DEFAULT NULL,
  p_limit INTEGER DEFAULT 20
)
RETURNS JSONB
LANGUAGE sql
SECURITY DEFINER
SET search_path = public, extensions, api
AS $$
  SELECT api.search_catalog(p_query, p_category, p_limit);
$$;

REVOKE ALL ON FUNCTION api.search_catalog(TEXT, TEXT, INTEGER) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION api.search_catalog(TEXT, TEXT, INTEGER) TO anon, authenticated, service_role;
REVOKE ALL ON FUNCTION public.search_catalog(TEXT, TEXT, INTEGER) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.search_catalog(TEXT, TEXT, INTEGER) TO anon, authenticated, service_role;

